  local newGameRulesSnapshot = nil
  local newGameRulesCommitPending = false
  local newGameCommitPassesRemaining = 0

  -- 2.6.25 selective species-ban profile state. Persist National Dex numbers
  -- rather than registry keys so the same identity is stable across editions.
  -- R/B/Y expose #001-#151; Gold/Silver expose the complete Gen 2 National
  -- Dex #001-#251. Setup profiles are edition-scoped, so a Gen 2 list never
  -- leaks its Johto-only entries into an R/B/Y staged profile.
  -- Pure species-ban set normalization is owned by RuleCatalog.
  local normalizePkmnBanSet = RuleCatalog.normalizePkmnBanSet
  local pkmnBanCountFromSet = RuleCatalog.pkmnBanCountFromSet
  local pkmnBanSetsEqual = RuleCatalog.pkmnBanSetsEqual

  mod.exports.__beta26.nationalDexLimitForGame = function(game)
      return mod.exports.__beta26.runtimeIsGen2(game or currentGame or mod.game)
          and 251 or 151
  end

  mod.exports.__beta26.nationalDexIndexForSpecies = function(game, species)
      game = game or currentGame or mod.game
      local def = Identity.speciesDefinition(game, tostring(species or ""):upper())
      if type(def) ~= "table" then return nil end
      local index = math.floor(tonumber(def.dex or def.dexNumber
          or def.number or def.index) or 0)
      local limit = mod.exports.__beta26.nationalDexLimitForGame(game)
      if index >= 1 and index <= limit then return index end
      return nil
  end

  -- Retain the Gen 1 helper names for private compatibility with older
  -- diagnostics/tests while keeping their original 1..151 contract.
  mod.exports.__beta26.gen1DexIndexForSpecies = function(game, species)
      local def = Identity.speciesDefinition(game or currentGame or mod.game,
          tostring(species or ""):upper())
      if type(def) ~= "table" then return nil end
      local index = math.floor(tonumber(def.dex or def.dexNumber
          or def.number or def.index) or 0)
      if index >= 1 and index <= 151 then return index end
      return nil
  end

  mod.exports.__beta26.speciesBanRows = function(game)
      game = game or currentGame or mod.game
      local limit = mod.exports.__beta26.nationalDexLimitForGame(game)
      local byIndex = {}
      for key, def in pairs(game and game.data and game.data.pokemon or {}) do
          if type(def) == "table" then
              local index = math.floor(tonumber(def.dex or def.dexNumber
                  or def.number or def.index) or 0)
              if index >= 1 and index <= limit and byIndex[index] == nil then
                  byIndex[index] = {
                      index = index,
                      species = tostring(key or ""):upper(),
                      name = tostring(def.name or key or ("DEX " .. index)),
                  }
              end
          end
      end
      local out = {}
      for index = 1, limit do
          out[index] = byIndex[index] or {
              index = index, species = nil,
              name = ("DEX #%03d"):format(index), missing = true,
          }
      end
      return out
  end

  mod.exports.__beta26.gen1SpeciesBanRows = function(game)
      game = game or currentGame or mod.game
      local byIndex = {}
      for key, def in pairs(game and game.data and game.data.pokemon or {}) do
          if type(def) == "table" then
              local index = math.floor(tonumber(def.dex or def.dexNumber
                  or def.number or def.index) or 0)
              if index >= 1 and index <= 151 and byIndex[index] == nil then
                  byIndex[index] = {
                      index = index,
                      species = tostring(key or ""):upper(),
                      name = tostring(def.name or key or ("DEX " .. index)),
                  }
              end
          end
      end
      local out = {}
      for index = 1, 151 do
          out[index] = byIndex[index] or {
              index = index, species = nil,
              name = ("DEX #%03d"):format(index), missing = true,
          }
      end
      return out
  end

  mod.exports.__beta26.pkmnBanSetForConfig = function(preGame, game)
      local limit = mod.exports.__beta26.nationalDexLimitForGame(
          game or currentGame or mod.game)
      if preGame then
          return normalizePkmnBanSet(pendingNewGameRules
              and pendingNewGameRules.pkmn_ban_species or {}, limit)
      end
      return normalizePkmnBanSet(mod.save:get("pkmn_ban_species", {}), limit)
  end

  mod.exports.__beta26.pkmnBanCount = function(preGame, game)
      local limit = mod.exports.__beta26.nationalDexLimitForGame(
          game or currentGame or mod.game)
      return pkmnBanCountFromSet(
          mod.exports.__beta26.pkmnBanSetForConfig(preGame, game), limit)
  end

  mod.exports.__beta26.pkmnBanContains = function(game, species)
      if mod.save:get("pkmn_ban", false) ~= true then return false end
      game = game or currentGame or mod.game
      local index = mod.exports.__beta26.nationalDexIndexForSpecies(game, species)
      if not index then return false end
      local limit = mod.exports.__beta26.nationalDexLimitForGame(game)
      local set = normalizePkmnBanSet(mod.save:get("pkmn_ban_species", {}), limit)
      return set[tostring(index)] == true
  end

  function mod.exports.__beta26.selectSetupProfileScope(game)
      local scope = mod.exports.__beta26.profileScopeForGame(game)
      if mod.exports.__beta26.setupProfileScope ~= scope then
          mod.exports.__beta26.setupProfileScope = scope
          pendingNewGameRules = nil
          -- Live changes were written to mod.save above, so the synchronized
      -- title representation is intentionally clean. Pre-game edits are staged
      -- only and therefore set pendingRulesDirty=true in the other branch.
      pendingRulesDirty = false
          pendingNewGameRulesForNextSave = false
          newGameRulesSnapshot = nil
          newGameRulesCommitPending = false
          newGameCommitPassesRemaining = 0
      end
      return scope
  end

  -- These keys persist the staged setup independently of the active save-rule
  -- keys.  They are declared here and used after copyRuleProfile is defined.
  local STAGED_PROFILE_KEY = "__nuzlocke_staged_new_game_profile"
  local STAGED_INTENT_KEY = "__nuzlocke_staged_new_game_intent"

  local function stagedProfileKey()
      return STAGED_PROFILE_KEY .. ":" .. mod.exports.__beta26.setupProfileScope
  end

  local function stagedIntentKey()
      return STAGED_INTENT_KEY .. ":" .. mod.exports.__beta26.setupProfileScope
  end

  ---------------------------------------------------------------------
  -- NEW GAME STARTER SETTINGS
  -- These values are read only when a brand-new save is constructed.
  -- Existing saves are never rewritten by this hook.
  ---------------------------------------------------------------------
  -- Pure NEW GAME starting-resource resolution/audits are owned by RuleCatalog.
  mod.exports.__beta26.resolveNewGameStartingResources = RuleCatalog.resolveNewGameStartingResources
  mod.exports.__beta26.resolveGoldNewGameStartingResources = RuleCatalog.resolveGoldNewGameStartingResources
  mod.exports.__beta26.auditGoldStartingResourceProfiles = RuleCatalog.auditGoldStartingResourceProfiles
  mod.exports.__beta26.auditStartingResourceProfiles = RuleCatalog.auditStartingResourceProfiles

  mod.hooks:wrap("save.new_game", function(next, save)
      local result = next(save)
      local targetSave = result or save
      currentSave = targetSave or currentSave
      if currentGame and currentSave then currentGame.save = currentSave end

      -- Resolve NEW GAME resources through one narrow boundary. Missing/invalid
      -- values preserve the vanilla/default $3000 wallet; an explicit 0 remains
      -- a legitimate player choice. This helper is exported so regression tests
      -- can assert the exact same defaults the save hook consumes.
      local profile = newGameRulesSnapshot or pendingNewGameRules
      local resources = mod.exports.__beta26.resolveNewGameStartingResources(profile)
      local startingMoney = resources.money
      local startingBalls = resources.balls
      local startingCandies = resources.candies
      local goldResources = mod.exports.__beta26.resolveGoldNewGameStartingResources(profile)
      local goldStartingMoney = goldResources.money
      local goldStartingBalls = goldResources.balls
      local goldStartingCandies = goldResources.candies

      if targetSave then
          -- Gold's Route 29 tutorial occurs after title staging has been
          -- cleared. Carry this NEW GAME-only choice on the save, just as the
          -- delayed Gold Rival-name shortcut does, without inventing a story
          -- flag before the real Route 29 script reaches it.
          targetSave.nuzlockeSkipCatchTutorial =
              profile and profile.skip_catch_tutorial == true or nil

          -- Starting Money / Balls / Rare Candies use generation-specific
          -- Setup keys. R/B/Y keeps its historical fields; Gold reads only the
          -- dedicated gold_starting_* fields below, so stale values from one
          -- staged profile cannot silently rewrite the other generation.
          local version = getGameVersion and getGameVersion() or "RED"
          local saveVersion = tostring(targetSave.version
              or targetSave.gameVersion or ""):upper()
          local gen2Start = version == "GOLD" or version == "SILVER"
              or version == "CRYSTAL"
              or saveVersion:find("GOLD", 1, true) ~= nil
              or saveVersion:find("SILVER", 1, true) ~= nil
              or saveVersion:find("CRYSTAL", 1, true) ~= nil

          -- 2.2.21 Quick Nuzlocke Start is a NEW GAME transaction, not a
          -- persistent in-run toggle. Carry only the one-shot request and the
          -- resolved Ball amount onto the actual save so the world can apply it
          -- after native fresh-save initialization has completed. Five Balls is
          -- the minimum capture-ready checkpoint. R/B/Y can raise that direct
          -- Quick Start amount; Gold's configured extra Balls remain a separate
          -- post-Elm PC allotment and never replace the native 5-Ball milestone.
          local quickStart = profile and profile.quick_nuzlocke_start == true
          targetSave.nuzlockeQuickStartPending = quickStart and true or nil
          targetSave.nuzlockeQuickStartBallCount = quickStart
              and (gen2Start and 5 or math.max(5, startingBalls)) or nil

          -- QoL: a fresh-save-only vitamin kit. It is deliberately stored in
          -- the PC rather than the Bag and marked on the save so even an
          -- unusual repeated save.new_game wrapper cannot duplicate it. The
          -- items do not bypass No Stat EXP Gain or any other use restriction.
          local delegatedRule = mod.exports.__beta26.externalRuleDelegation
          local delegationGame = currentGame or mod.game
          local vitaminsDelegated = type(delegatedRule) == "function"
              and delegatedRule("pc_starting_vitamins", delegationGame) ~= nil
          local healItemsDelegated = type(delegatedRule) == "function"
              and delegatedRule("pc_starting_heal_items", delegationGame) ~= nil

          if profile and profile.pc_starting_vitamins == true
              and not vitaminsDelegated
              and targetSave.nuzlockePcVitaminsGranted ~= true then
              targetSave.pcItems = targetSave.pcItems or {}
              local vitamins = mod.exports.__beta26.nativeStatVitamins
              for _, itemId in ipairs(vitamins) do
                  targetSave.pcItems[itemId] = math.max(0,
                      math.floor(tonumber(targetSave.pcItems[itemId]) or 0)) + 10
              end
              targetSave.nuzlockePcVitaminsGranted = true
          end

          -- QoL: optional fresh-save PC medicine kit. Keep this independent
          -- from challenge item-use policy: it only seeds storage once.
          if profile and profile.pc_starting_heal_items == true
              and not healItemsDelegated
              and targetSave.nuzlockePcHealItemsGranted ~= true then
              targetSave.pcItems = targetSave.pcItems or {}
              local healItems = {
                  "POTION", "SUPER_POTION", "MAX_POTION",
                  "ANTIDOTE", "BURN_HEAL", "ICE_HEAL", "AWAKENING",
                  "PARLYZ_HEAL", "FULL_HEAL",
              }
              for _, itemId in ipairs(healItems) do
                  targetSave.pcItems[itemId] = math.max(0,
                      math.floor(tonumber(targetSave.pcItems[itemId]) or 0)) + 10
              end
              targetSave.nuzlockePcHealItemsGranted = true
          end

          if not gen2Start then
              targetSave.money = startingMoney
              targetSave.pcItems = targetSave.pcItems or {}

              -- Immutable run-start snapshot for the Nuzlocke side of the
              -- Trainer Card. These values describe the selected NEW GAME setup,
              -- not the player's current inventory/money, and are never rewritten
              -- by normal gameplay. Keeping them on the actual save object avoids
              -- depending on title-screen mod.save state during the NEW GAME seam.
              targetSave.nuzlockeRunStartMoney = startingMoney
              targetSave.nuzlockeRunStartBalls = startingBalls
              targetSave.nuzlockeRunStartCandies = startingCandies

              -- beta.26 Soft Start: configured starting Balls are intentionally
              -- held until Oak's Pokedex transition. This prevents the challenge
              -- from arming during the pre-Pokedex portion of a fresh R/B/Y run.
              targetSave.nuzlockeDeferredStartingBalls =
                  startingBalls > 0 and startingBalls or nil
              targetSave.pcItems.POKE_BALL = nil
              targetSave.pcItems.RARE_CANDY =
                  startingCandies > 0 and startingCandies or nil
          else
              -- Gold parity owns dedicated setup keys. Money follows Gold's
              -- native six-digit wallet. Rare Candies can live in the bedroom
              -- PC immediately, but configured extra Poke Balls are deferred
              -- until Elm's native post-Mystery-Egg capture unlock so Setup
              -- cannot arm the pre-Ball Route 29 opening early.
              targetSave.player = targetSave.player or {}
              targetSave.player.money = goldStartingMoney
              targetSave.pcItems = targetSave.pcItems or {}
              targetSave.pcItems.RARE_CANDY =
                  goldStartingCandies > 0 and goldStartingCandies or nil
              targetSave.nuzlockeGoldDeferredStartingBalls =
                  goldStartingBalls > 0 and goldStartingBalls or nil

              -- Keep the same immutable run-start snapshot names used by the
              -- R/B/Y status surface. These describe Setup choices, not the
              -- current wallet/inventory; Gold presentation providers may read
              -- them without knowing which generation authored the save.
              targetSave.nuzlockeRunStartMoney = goldStartingMoney
              targetSave.nuzlockeRunStartBalls = goldStartingBalls
              targetSave.nuzlockeRunStartCandies = goldStartingCandies

              -- Never carry the Gen 1 Oak/Pokedex deferral into Gold.
              targetSave.nuzlockeDeferredStartingBalls = nil
          end
      end

      return result or targetSave
  end)

  ---------------------------------------------------------------------
  -- LOCKE TYPE PRESETS
  --
  -- These presets only expose playstyles the current rule engine can already
  -- enforce without inventing a new subsystem. Optional clauses (Dupes/Shiny,
  -- gifts/trades, legendary bans), UI options, world-building, Gym Guide,
  -- and starting resources remain independent of the selected preset.
  --
  -- CUSTOM    = preserve the player's hand-built rules.
  -- NUZLOCKE  = classic core: permadeath, first encounter, failed encounter,
  --             and required nicknames.
  -- HARDCORE  = NUZLOCKE + caps through Champion + no healing/X items in battle
  --             + Blackout loss. Gym/Dungeon lock-ins remain optional because
  --             they are not part of the conventional Hardcore ruleset.
  --             Gen1Recomp's native Battle Style option remains authoritative;
  --             players who want full Hardcore should set it to SET.
  -- SOLO      = NUZLOCKE + Solo Only + Blackout, so exhausting the active
  --             solo slot ends the run even if reserves exist. PC swaps remain available because that is how the
  --             existing Solo Only rule is intentionally implemented.
  -- IRONMON   = an IronMON-style loadout using only rules this mod actually
  --             owns: Solo, Blackout, no healing/X items, no escape, no field
  --             healing/PP helpers, and no shops/Centers/Mom. It intentionally
  --             does not claim to reproduce every external IronMON rule.
  ---------------------------------------------------------------------
  -- Static loadout definitions are owned by RuleCatalog; live apply/classify
  -- methods continue to attach below in main.lua.
  local LockePreset = RuleCatalog.buildLockePreset()

  defaultRuleValue = function(key)
      -- Ordinary rules resolve from the same record used to register them in
      -- Setup/NUZ RULES. Only non-row profile metadata remains explicit here.
      local rule = mod.exports.__beta26.ruleDefinitionByKey
          and mod.exports.__beta26.ruleDefinitionByKey[tostring(key or "")]
      if rule and rule.default ~= nil then return rule.default end
      if key == "locke_type" then return 1 end
      if key == "rule_lock" or key == "rules_locked" then return false end
      return false
  end

  do
      local helpers = RuleCatalog.makeDescriptionHelpers({
          defaultRuleValue = function(key) return defaultRuleValue(key) end,
          getPendingNewGameRules = function() return pendingNewGameRules end,
          getCurrentGame = function() return currentGame or mod.game end,
          externalRuleDelegation = function(key, game)
              if type(externalRuleDelegation) == "function" then
                  return externalRuleDelegation(key, game)
              end
              return nil
          end,
      })
      ruleDescriptionAnnotation = helpers.annotation
      ruleDescriptionForDisplay = helpers.forDisplay
  end



  do -- compiler-budget scope: catalog-owned pure rule/value helpers
  local MOVEMENT_ASSIST_LABELS = RuleCatalog.MOVEMENT_ASSIST_LABELS
  local normalizeMovementAssistMode = RuleCatalog.normalizeMovementAssistMode

  mod.exports.__beta26.movementAssistLabels = MOVEMENT_ASSIST_LABELS
  mod.exports.__beta26.movementAssistMode = normalizeMovementAssistMode
  mod.exports.__beta26.movementAssistLabel = function(value)
      return MOVEMENT_ASSIST_LABELS[normalizeMovementAssistMode(value)]
          or MOVEMENT_ASSIST_LABELS[0]
  end
  mod.exports.__beta26.cycleIntegerRange = RuleCatalog.cycleIntegerRange
  mod.exports.__beta26.scalePercentFloor = RuleCatalog.scalePercentFloor
  mod.exports.__beta26.normalizeItemPolicyKey = RuleCatalog.normalizeItemPolicyKey
  mod.exports.__beta26.battleScopeLabel = RuleCatalog.battleScopeLabel
  mod.exports.__beta26.statusMoveChildKeys = RuleCatalog.statusMoveChildKeys
  mod.exports.__beta26.isStatusMoveChildKey = RuleCatalog.isStatusMoveChildKey
  mod.exports.__beta26.isBattleScopeRuleKey = RuleCatalog.isBattleScopeRuleKey
  end -- catalog-owned pure rule/value helper scope

  -- 2.9.41: preserve the established export/call surface while moving the
  -- pure coercion implementation beside the authoritative rule catalog. Pass
  -- the live definition index on every call; never capture a registration-time
  -- snapshot that could become stale or nil.
  mod.exports.__beta26.coerceRuleValue = function(key, value, mode)
      return RuleCatalog.coerceRuleValue(
          mod.exports.__beta26.ruleDefinitionByKey, key, value, mode)
  end

  ---------------------------------------------------------------------
  -- MACHINE-READABLE RULE + SAVE CONFIG DESCRIPTORS (2.5.17)
  --
  -- 2.5.55 makes each ordinary ruleCategories row the authoritative registration
  -- record for its default/type/range/generation/UI metadata. These descriptors
  -- now read those same rows instead of reconstructing defaults independently.
  -- This remains descriptive/read-only and does not bump Save Schema 4,
  -- Compatibility API 28, or Diagnostics API 1.
  ---------------------------------------------------------------------
  do
      local copyTable = RuleCatalog.copyDescriptorValue
      local rows, byKey, collisions = RuleCatalog.buildRuleDescriptorSnapshot(
          ruleCategories, defaultRuleValue, {
              { key="locke_type", value_type="number", default=defaultRuleValue("locke_type"), numeric=true, min=0, max=6 },
              { key="rule_lock", value_type="boolean", default=defaultRuleValue("rule_lock") },
              { key="run_settings_lock", value_type="boolean", default=false },
              { key="rules_locked", value_type="boolean", default=defaultRuleValue("rules_locked") },
              { key="rules_permanently_locked", value_type="boolean", default=false },
              { key="difficulty_provider_id", value_type="string", default="vanilla" },
          })

      -- 2.9.43: pure registry describe/get/structural audit now live beside
      -- descriptor construction. Live enum and stored-save audits are attached
      -- below and remain in main.lua because they depend on runtime owners.
      local RuleRegistry = RuleCatalog.buildRuleRegistry(rows, byKey, collisions)

      -- 2.9.37: authoritative enum/range completeness audit. Numeric rule
      -- descriptors must define finite ordered bounds, keep their default inside
      -- those bounds, and coerce both extremes through the same canonical path.
      -- This is structural/semantic certification only; it does not mutate saves.
      function RuleRegistry.auditEnumRanges()
          local failures, checked = {}, 0
          for _, row in ipairs(rows) do
              if row.value_type == "number" or row.numeric == true then
                  checked = checked + 1
                  local minv, maxv = tonumber(row.min), tonumber(row.max)
                  local def = tonumber(row.default)
                  if minv == nil or maxv == nil then
                      failures[#failures + 1] = row.key .. ":missing_bounds"
                  elseif minv ~= minv or maxv ~= maxv or minv > maxv then
                      failures[#failures + 1] = row.key .. ":invalid_bounds"
                  elseif def == nil or def < minv or def > maxv then
                      failures[#failures + 1] = row.key .. ":default_out_of_range"
                  elseif row.source ~= "profile_metadata" then
                      local low = mod.exports.__beta26.coerceRuleValue(row.key, minv - 1000000, "read")
                      local high = mod.exports.__beta26.coerceRuleValue(row.key, maxv + 1000000, "read")
                      if low ~= minv then failures[#failures + 1] = row.key .. ":min_clamp" end
                      if high ~= maxv then failures[#failures + 1] = row.key .. ":max_clamp" end
                  end
              end
          end
          return { ok=#failures == 0, checked=checked, failures=failures }
      end
      mod.exports.__beta26.ruleEnumRangeCompletenessAudit = RuleRegistry.auditEnumRanges

      -- 2.6.1: read-only validation of every persisted canonical rule/profile
      -- value. This reports stale/coercible legacy representations separately
      -- from genuinely invalid values and never rewrites the save.
      function RuleRegistry.validateStored(source)
          local report = {
              ok = true, checked = 0, present = 0, invalid_count = 0,
              stale_count = 0, errors = {}, warnings = {}, issues = {},
          }
          local getter
          if type(source) == "function" then
              getter = source
          elseif type(source) == "table" then
              getter = function(key) return source[key] end
          else
              getter = function(key) return mod.save:get(key, nil) end
          end
          local function issue(row, code, value, warning)
              local text = tostring(row.key) .. ":" .. tostring(code)
                  .. "=" .. tostring(value)
              report.issues[#report.issues + 1] = {
                  key = row.key, code = code, value = value,
                  severity = warning and "warning" or "error",
              }
              if warning then
                  report.stale_count = report.stale_count + 1
                  report.warnings[#report.warnings + 1] = text
              else
                  report.invalid_count = report.invalid_count + 1
                  report.errors[#report.errors + 1] = text
                  report.ok = false
              end
          end
          for _, row in ipairs(rows) do
              if row.persisted ~= false then
                  report.checked = report.checked + 1
                  local okValue, value = pcall(getter, row.key)
                  if not okValue then
                      issue(row, "read_error", value, false)
                  elseif value ~= nil then
                      report.present = report.present + 1
                      if row.value_type == "boolean" then
                          if type(value) ~= "boolean" then
                              issue(row, "type_" .. type(value), value, false)
                          end
                      elseif row.value_type == "string" then
                          if type(value) ~= "string" then
                              issue(row, "type_" .. type(value), value, false)
                          end
                      elseif row.value_type == "number" then
                          if type(value) == "boolean"
                              and (row.legacy_read_true ~= nil
                                  or row.legacy_read_false ~= nil) then
                              issue(row, "legacy_boolean", value, true)
                          elseif type(value) ~= "number" then
                              issue(row, "type_" .. type(value), value, false)
                          elseif value ~= value or value == math.huge
                              or value == -math.huge then
                              issue(row, "non_finite", value, false)
                          else
                              if row.numeric == true and value ~= math.floor(value) then
                                  issue(row, "non_integer", value, false)
                              end
                              if row.min ~= nil and value < tonumber(row.min) then
                                  issue(row, "below_min", value, false)
                              end
                              if row.max ~= nil and value > tonumber(row.max) then
                                  issue(row, "above_max", value, false)
                              end
                              if type(row.allowed_values) == "table" then
                                  local allowed = false
                                  for _, candidate in ipairs(row.allowed_values) do
                                      if value == candidate then allowed = true break end
                                  end
                                  if not allowed then issue(row, "not_allowed", value, false) end
                              end
                          end
                      end
                  end
              end
          end
          return report
      end
      mod.exports.__beta26.ruleRegistry = RuleRegistry

      local fields = RuleCatalog.buildSaveSchemaFields(rows, {
          schema_key = SAVE_SCHEMA_KEY,
          current_schema = CURRENT_SAVE_SCHEMA,
          migration_key = SAVE_MIGRATION_KEY,
          schema_transaction_key = mod.exports.__beta26.saveUpgrade.transactionKey,
          gameplay_transaction_key = mod.exports.__beta26.GameplayTransactions.storage_key,
          transaction_receipts_key = mod.exports.__beta26.GameplayTransactions.receipts_key,
      })

      -- 2.9.44: pure descriptor presentation/structural audit now lives beside
      -- save-field snapshot construction. All live schema/migration/transaction
      -- ownership remains in main.lua; only the already-built snapshot is passed.
      local SaveSchemaDescriptor = RuleCatalog.buildSaveSchemaDescriptor(
          fields, rows, CURRENT_SAVE_SCHEMA)
      mod.exports.__beta26.saveSchemaDescriptor = SaveSchemaDescriptor
  end

  -- Machine-readable lineage.  Filename/version labels are not authoritative
  -- on their own; CI and Dev Mode can bind this build to its exact immediate
  -- parent package hash before it is promoted as the next canonical child.
  mod.exports.__beta26.buildProvenance = function()
      return {
          descriptor_api = 1,
          version = mod.exports.__beta26.build,
          parent_version = mod.exports.__beta26.parentVersion,
          parent_sha256 = mod.exports.__beta26.parentSha256,
          save_schema = CURRENT_SAVE_SCHEMA,
          compatibility_api = mod.exports.__beta26.compatibilityApi,
          diagnostics_api = mod.exports.__beta26.diagnosticsApi,
          mod_api = 2,
          audited_recomp = mod.exports.__beta26.recompCompatAudited,
          player_package_files = 37,
      }
  end
  if mod.exports.nuzlocke_compat then
      mod.exports.nuzlocke_compat.build_provenance =
          mod.exports.__beta26.buildProvenance
  end

  -- 29.3.13 default audit: new restrictive systems default OFF, economy and
  -- difficulty remain vanilla, and the conventional Nuzlocke core remains the
  -- only challenge behavior enabled by default. Keep this pure for smoke tests.
  mod.exports.__beta26.auditNewRuleDefaults = function()
      local expected = {
          type_lock_mode = 0, no_day_care = false, shiny_clause = 0,
          gym_lock_in = false, dungeon_lock_in = false,
          travel_restrictions = 0, party_size_limit = 6, gym_team_size = false,
          route_forgiveness = 0, trainer_money_multiplier = 4,
          difficulty_profile = 0, randomizer_info_policy = 0,
          badge_boosts = true, no_catching = false,
          progression_pc_catches = false, no_held_items = false,
          player_start_stat_exp = 0, wild_start_stat_exp = 0,
          trainer_start_stat_exp = 0,
          pc_starting_vitamins = false, pc_starting_heal_items = false, random_starter = false,
          random_field_items = false, random_shops = false, random_shop_balance = 2,
          random_tms = false, random_tm_compatibility = 0, random_tm_locations = false, random_gift_items = false,
          skip_opening_intro = false, quick_nuzlocke_start = false,
          skip_cherrygrove_tour = false,
          encounter_ball_limit = 0,
          run_surf = 0, battle_menu_ui = false,
          unlimited_bag_space = false, trade_evolutions = false,
          gold_starting_money = 3000, gold_starting_pokeballs = 0,
          gold_starting_rare_candies = 0,
          dev_mode = false,
      }
      for key, value in pairs(expected) do
          if defaultRuleValue(key) ~= value then return false, key end
      end
      return true
  end

  -- Numeric setup/profile values can be supplied by old saves or external
  -- editing tools. Keep NaN/Inf from surviving normalization and later
  -- becoming invalid persisted Lua-source values. This boundary guard is
  -- intentionally narrow; ordinary gameplay math remains unchanged.
  mod.exports.__beta26.finiteNumber = RuleCatalog.finiteNumber

  local function normalizeRuleValue(rule, value)
      if type(rule) ~= "table" then return value end

      if rule.numeric then
          -- Old Dupes Clause saves used a boolean. Preserve ON as FAMILY,
          -- which matches the behavior those saves previously had.
          if rule.key == "dupes_mode" and type(value) == "boolean" then
              value = value and 2 or 0
          elseif rule.key == "shiny_clause" and type(value) == "boolean" then
              -- 2.4.20 migration: historical ON meant unlimited shiny exceptions.
              value = value and 4 or 0
          elseif (rule.key == "gold_egg_encounter_mode"
              or rule.key == "gold_bug_contest_mode")
              and type(value) == "boolean" then
              -- Older builds could collapse these enum rows through the
              -- shared boolean setter. Preserve true as the first enabled
              -- mode rather than silently resetting it OFF.
              value = value and 1 or 0
          elseif rule.key == "run_surf"
              and type(value) == "boolean" then
              -- Legacy movement-assist profiles may still carry booleans;
              -- ON means HOLD B.
              value = value and 1 or 0
          end

          local fallback = mod.exports.__beta26.finiteNumber(
              defaultRuleValue(rule.key), nil)
              or mod.exports.__beta26.finiteNumber(rule.min, 0)
          local number = math.floor(mod.exports.__beta26.finiteNumber(value, fallback))
          local minValue = mod.exports.__beta26.finiteNumber(rule.min, nil)
          local maxValue = mod.exports.__beta26.finiteNumber(rule.max, nil)
          if minValue then number = math.max(minValue, number) end
          if maxValue then number = math.min(maxValue, number) end
          return number
      end

      return value == true
  end

  local function legacyLevelCapScope()
      local hardcore = mod.save:get("hardcore_mode", false) == true
      if not hardcore then return 0 end
      return mod.save:get("elite_four_caps", false) == true and 2 or 1
  end

  -- 2.5.4: Solo Only is retired. Party Size Limit now owns Solo runs.
  -- Preserve old saves by converting Solo=true to a one-Pokemon cap.
  mod.exports.__beta26.registerSaveUpgradeStep("semantic",
      "solo_to_party_limit_254", function()
          local legacySolo = mod.save:get("solo_active", nil)
          if legacySolo == true then
              local limit = tonumber(mod.save:get("party_size_limit", 6)) or 6
              if limit > 1 then mod.save:set("party_size_limit", 1) end
          end
          return true
      end)

  -- 2.4.98 numeric selector setter repair. 2.4.97 and earlier could
  -- write booleans when Shiny Clause or Encounter Ball Limit was edited
  -- because those numeric keys fell through setConfigValue's boolean branch.
  -- The exact attempted selection is not recoverable from `false`, so use the
  -- conservative canonical OFF value and let the player reselect explicitly.
  -- `true` for Shiny Clause retains its historical UNLIMITED meaning; there
  -- was never a defined boolean-true Encounter Ball Limit, so it also becomes
  -- OFF rather than guessing a throw budget.
  mod.exports.__beta26.registerSaveUpgradeStep("semantic",
      "selector_boolean_repair_2498", function()
          local shiny = mod.save:get("shiny_clause", nil)
          if type(shiny) == "boolean" then
              mod.save:set("shiny_clause", shiny and 4 or 0)
          end
          local ballLimit = mod.save:get("encounter_ball_limit", nil)
          if type(ballLimit) == "boolean" then
              mod.save:set("encounter_ball_limit", 0)
          end
          return true
      end)

  mod.exports.__beta26.registerSaveUpgradeStep("semantic",
      "legacy_level_cap_scope", function()
          -- Older saves stored two booleans instead of the unified scope. Only
          -- materialize the new key when legacy evidence actually exists;
          -- fresh/vanilla saves keep their normal default path.
          local oldHardcore = mod.save:get("hardcore_mode", nil)
          local oldElite = mod.save:get("elite_four_caps", nil)
          if mod.save:get("level_cap_scope", nil) == nil
              and (oldHardcore ~= nil or oldElite ~= nil) then
              mod.save:set("level_cap_scope", legacyLevelCapScope())
          end
          return true
      end)

  -- 2.4.84 legacy enum canonicalization.
  --
  -- Several old rule rows were booleans before becoming numeric selectors.
  -- Runtime readers already understood those booleans, but leaving the raw
  -- value in storage meant an old save could repeatedly project back to its
  -- legacy state after an edit. Canonicalize the unambiguous legacy shapes
  -- once through the central semantic migration pipeline.
  mod.exports.__beta26.registerSaveUpgradeStep("semantic",
      "legacy_numeric_rule_shapes_2484", function()
          local conversions = {
              shiny_clause = function(v) return v and 4 or 0 end,
              dupes_mode = function(v) return v and 2 or 0 end,
              gold_egg_encounter_mode = function(v) return v and 1 or 0 end,
              gold_bug_contest_mode = function(v) return v and 1 or 0 end,
          }
          for key, convert in pairs(conversions) do
              local raw = mod.save:get(key, nil)
              if type(raw) == "boolean" then
                  mod.save:set(key, convert(raw))
              end
          end
          -- Historical starting Rare Candies was also boolean. It is a setup
          -- resource selector rather than an ordinary rule toggle, but its
          -- old shape is equally unambiguous and safe to canonicalize.
          local oldCandies = mod.save:get("starting_rare_candies", nil)
          if type(oldCandies) == "boolean" then
              mod.save:set("starting_rare_candies", oldCandies and 99 or 0)
          end
          return true
      end)

  -- 2.8.55: stable Nuzlocke-authored UI source catalog.
  -- These strings were already passed through Strings() at runtime, but were
  -- not discoverable through nuzlocke_translation.sources(). Keep the first
  -- catalog focused on high-value player-facing status/tracker/world-summary
  -- surfaces; future localization passes can extend it without changing rule
  -- semantics or introducing per-language branches.
  local TRANSLATION_UI_SOURCES = RuleCatalog.TRANSLATION_UI_SOURCES

  -- 2.3.20 translation-tooling seam:
  -- Rule/section source strings are already marked with Strings.source().
  -- Expose the live definitions so translation tooling can discover them
  -- without maintaining a duplicate catalog that drifts as rules evolve.
  mod.exports.nuzlocke_translation.sources = function()
      local seen, out = {}, {}
      local function add(value, kind, key)
          if type(value) ~= "string" or value == "" or seen[value] then return end
          seen[value] = true
          out[#out + 1] = { source = value, kind = kind, key = key }
      end
      for _, category in ipairs(ruleCategories) do
          add(category.title, "section", nil)
          add(category.shortTitle, "section_short", nil)
          for _, rule in ipairs(category.rules or {}) do
              add(rule.name, "rule_name", rule.key)
              add(rule.shortName, "rule_short_name", rule.key)
              add(rule.desc, "rule_description", rule.key)
          end
      end
      for _, row in ipairs(TRANSLATION_UI_SOURCES) do
          add(row.source, row.kind or "ui", row.key)
      end

      -- World Building's authored rule/flavor catalog is already resolved
      -- through Strings() when presented. Expose every authored variant so
      -- translation tooling can cover T1/T2 and Kanto/Johto flavor without
      -- duplicating or parsing world_building.lua.
      local worldCatalog = mod.exports.__beta26.worldRuleCatalog
      if type(worldCatalog) == "table" then
          for key, row in pairs(worldCatalog) do
              if type(row) == "table" then
                  for _, field in ipairs({ "t1", "t2", "kanto", "johto" }) do
                      local value = row[field]
                      if type(value) == "table" then
                          for _, text in ipairs(value) do
                              add(text, "world_building_" .. field, tostring(key))
                          end
                      else
                          add(value, "world_building_" .. field, tostring(key))
                      end
                  end
              end
          end
      end

      table.sort(out, function(a, b)
          if tostring(a.kind) == tostring(b.kind) then
              return tostring(a.source) < tostring(b.source)
          end
          return tostring(a.kind) < tostring(b.kind)
      end)
      return out
  end

  mod.exports.nuzlocke_translation.catalog = function()
      local out = {}
      for _, row in ipairs(mod.exports.nuzlocke_translation.sources()) do
          out[row.source] = Strings.lookup(row.source)
      end
      return out
  end

  local function makeDefaultPreGameRules()
      local values = {}
      for _, cat in ipairs(ruleCategories) do
          for _, rule in ipairs(cat.rules) do
              values[rule.key] = defaultRuleValue(rule.key)
          end
      end
      values.locke_type = defaultRuleValue("locke_type")
      values.run_settings_lock = false
      values.starting_money = defaultRuleValue("starting_money")
      values.starting_pokeballs = defaultRuleValue("starting_pokeballs")
      values.starting_rare_candies = defaultRuleValue("starting_rare_candies")
      values.infinite_rare_candies = defaultRuleValue("infinite_rare_candies")
      values.difficulty_provider_id = "vanilla"
      values.pkmn_ban_species = {}
      return values
  end

  local function makeRulesFromCurrentSave()
      local values = makeDefaultPreGameRules()
      local liveTypeDraft = mod.save:get("type_lock_draft", false) == true

      for _, cat in ipairs(ruleCategories) do
          for _, rule in ipairs(cat.rules) do
              local raw = mod.save:get(rule.key, nil)
              if rule.key == "level_cap_scope" and raw == nil then
                  raw = legacyLevelCapScope()
              elseif raw == nil and (rule.key == "route_2_split"
                  or rule.key == "route_10_split"
                  or rule.key == "route_20_split") then
                  -- Old setup/save data had one blanket Route Splits flag.
                  -- Preserve its intent for the three routes that remain
                  -- independently supported; every other old split collapses
                  -- safely to its parent during encounter reprojection.
                  raw = mod.save:get("route_splits", 0) == 1
              end
              if raw == nil and liveTypeDraft and mod.exports.__beta26.typeLockSlotIndex(rule.key) then
                  values[rule.key] = nil
              else
                  if raw == nil then raw = defaultRuleValue(rule.key) end
                  values[rule.key] = normalizeRuleValue(rule, raw)
              end
          end
      end

      values.locke_type = math.max(0, math.min(6,
          math.floor(mod.exports.__beta26.finiteNumber(
              mod.save:get("locke_type", defaultRuleValue("locke_type")),
              defaultRuleValue("locke_type")))))
      values.area_guide_enabled = H.loadAreaGuideState()
      values.rule_lock =
          mod.save:get("rule_lock", defaultRuleValue("rule_lock")) == true
      values.run_settings_lock = mod.save:get("run_settings_lock", false) == true
      values.rules_locked =
          mod.save:get("rules_locked", defaultRuleValue("rules_locked")) == true
      values.infinite_rare_candies =
          mod.save:get("infinite_rare_candies",
              defaultRuleValue("infinite_rare_candies")) == true
      local storedDifficultyId = mod.save:get("difficulty_provider_id", nil)
      values.difficulty_provider_id = type(storedDifficultyId) == "string"
          and storedDifficultyId ~= "" and storedDifficultyId or nil
      values.pkmn_ban_species = normalizePkmnBanSet(
          mod.save:get("pkmn_ban_species", {}))
      values.pkmn_ban = pkmnBanCountFromSet(values.pkmn_ban_species) > 0

      return values
  end

  H.routeListShowsAll = function()
      return areaGuideEnabled == true
  end

  ---------------------------------------------------------------------
  -- COMMIT STAGED NEW-GAME RULES
  --
  -- NEW GAME is identified by the explicit staging flag set by the title
  -- menu. Do not inspect whether mod.save already contains rule keys: the
  -- engine may populate defaults before save.loaded, which can otherwise
  -- make valid startup selections look like they were never chosen.
  --
  -- The helper runs from BOTH save.loaded and game.ready. Whichever lifecycle
  -- event sees the staged flag first commits it; the other event simply
  -- mirrors the now-authoritative save.
  ---------------------------------------------------------------------
  local function copyRuleProfile(source)
      local copy = {}
      for _, cat in ipairs(ruleCategories) do
          for _, rule in ipairs(cat.rules) do
              local v = source and source[rule.key]
              if v == nil and source and rule.key == "run_surf" then
                  local function legacyMovementMode(raw)
                      if type(raw) == "boolean" then return raw and 1 or 0 end
                      return math.max(0, math.min(2,
                          math.floor(tonumber(raw) or 0)))
                  end
                  if source.automatic_running_shoes ~= nil
                      or source.fast_surf ~= nil then
                      v = math.min(
                          legacyMovementMode(source.automatic_running_shoes),
                          legacyMovementMode(source.fast_surf))
                  end
              end
              if v == nil and source and (rule.key == "route_2_split"
                  or rule.key == "route_10_split"
                  or rule.key == "route_20_split") then
                  v = tonumber(source.route_splits) == 1
              end
              if v == nil and source and source.type_lock_draft == true
                  and mod.exports.__beta26.typeLockSlotIndex(rule.key) then
                  copy[rule.key] = nil
              else
                  if v == nil then v = defaultRuleValue(rule.key) end
                  copy[rule.key] = normalizeRuleValue(rule, v)
              end
          end
      end
      copy.locke_type = math.max(0, math.min(6,
          math.floor(mod.exports.__beta26.finiteNumber(
              source and source.locke_type, defaultRuleValue("locke_type")))))
      if source and source.area_guide_enabled ~= nil then
          copy.area_guide_enabled = source.area_guide_enabled == true
      else
          copy.area_guide_enabled = defaultRuleValue("area_guide_enabled")
      end
      copy.rule_lock = source and source.rule_lock == true or false
      copy.run_settings_lock = source and source.run_settings_lock == true or false
      copy.rules_locked = source and source.rules_locked == true or false
      copy.infinite_rare_candies = source and source.infinite_rare_candies == true
          or defaultRuleValue("infinite_rare_candies")
      local difficultyId = source and source.difficulty_provider_id
      copy.difficulty_provider_id = type(difficultyId) == "string"
          and difficultyId ~= "" and difficultyId or nil
      copy.pkmn_ban_species = normalizePkmnBanSet(
          source and source.pkmn_ban_species or {})
      copy.pkmn_ban = pkmnBanCountFromSet(copy.pkmn_ban_species) > 0
      copy.random_starter_reroll_index = math.max(0,
          math.floor(mod.exports.__beta26.finiteNumber(
              source and source.random_starter_reroll_index, 0)))
      copy.starting_money = math.max(0, math.min(9999,
          math.floor(mod.exports.__beta26.finiteNumber(
              source and source.starting_money, defaultRuleValue("starting_money")))))
      copy.starting_pokeballs = math.max(0, math.min(99,
          math.floor(mod.exports.__beta26.finiteNumber(
              source and source.starting_pokeballs, defaultRuleValue("starting_pokeballs")))))
      local rawCandies = source and source.starting_rare_candies
      if type(rawCandies) == "boolean" then rawCandies = rawCandies and 99 or 0 end
      copy.starting_rare_candies = math.max(0, math.min(99,
          math.floor(mod.exports.__beta26.finiteNumber(
              rawCandies, defaultRuleValue("starting_rare_candies")))))
      copy.gold_starting_money = math.max(0, math.min(999999,
          math.floor(mod.exports.__beta26.finiteNumber(
              source and source.gold_starting_money,
              defaultRuleValue("gold_starting_money")))))
      copy.gold_starting_pokeballs = math.max(0, math.min(99,
          math.floor(mod.exports.__beta26.finiteNumber(
              source and source.gold_starting_pokeballs,
              defaultRuleValue("gold_starting_pokeballs")))))
      copy.gold_starting_rare_candies = math.max(0, math.min(99,
          math.floor(mod.exports.__beta26.finiteNumber(
              source and source.gold_starting_rare_candies,
              defaultRuleValue("gold_starting_rare_candies")))))
      copy.hardcore_mode = (tonumber(copy.level_cap_scope) or 0) > 0
      copy.elite_four_caps = (tonumber(copy.level_cap_scope) or 0) >= 2
      return copy
  end

  H.serializeSetupValue = function(v)
      if type(v) == "boolean" then
          return v and "true" or "false"
      elseif type(v) == "number" then
          if mod.exports.__beta26.finiteNumber(v, nil) == nil then return "nil" end
          return tostring(v)
      elseif type(v) == "string" then
          return string.format("%q", v)
      end
      return "nil"
  end

  H.serializeSetupProfile = function(profile)
      local keys = {}
      for k, _ in pairs(profile or {}) do keys[#keys + 1] = k end
      table.sort(keys)
      local out = { "return {" }
      for _, k in ipairs(keys) do
          out[#out + 1] = "[" .. string.format("%q", k) .. "]="
              .. H.serializeSetupValue(profile[k]) .. ","
      end
      out[#out + 1] = "}"
      return table.concat(out, "\n")
  end

  -- beta.30.1.5: Gen1Recomp 0.1.86+ blocks the legacy direct
  -- filesystem facade in sandboxed mods. The old Setup profile loader touched
  -- that blocked facade before opening the configuration screen, so the title
  -- SETUP path could crash before any screen-level guard ran.
  --
  -- Compatibility bridge: keep per-generation Setup profile preferences only
  -- for the current process/session. This avoids creating/adopting a
  -- playthrough identity merely by browsing fresh-game Setup at title.
  mod.exports.__beta26.sessionSetupProfiles =
      mod.exports.__beta26.sessionSetupProfiles or {}

  local function saveSetupProfileToDisk(profile)
      local scope = tostring(mod.exports.__beta26.setupProfileScope or "gen1")
      local clean = copyRuleProfile(profile or {})
      clean.random_starter_reroll_index = 0
      mod.exports.__beta26.sessionSetupProfiles[scope] = clean
      return true
  end

  local function loadSetupProfileFromDisk()
      local scope = tostring(mod.exports.__beta26.setupProfileScope or "gen1")
      local profile = mod.exports.__beta26.sessionSetupProfiles[scope]
      if type(profile) ~= "table" then return nil end
      return copyRuleProfile(profile)
  end

  -- 2.6.61: installation-scoped Saved Setup Presets.  Gen1Recomp 0.2.19's
  -- public mod.cache facade is explicitly independent of Pokémon playthroughs,
  -- so presets survive app restarts without borrowing save identity.  Three
  -- bounded slots are kept per existing Setup profile scope (R/B/Y shared;
  -- Gold and Silver separate), matching the protected Setup behavior.  Only rule/setup profile
  -- data produced by copyRuleProfile is serialized; runtime progress never
  -- enters this store.
  local SETUP_PRESET_SLOTS = 3
  local selectedSetupPresetSlot = 0
  local function setupPresetPath(slot)
      slot = math.max(1, math.min(SETUP_PRESET_SLOTS,
          math.floor(tonumber(slot) or 1)))
      local scope = tostring(mod.exports.__beta26.setupProfileScope or "gen1")
      return "setup_presets/" .. scope .. "/slot" .. tostring(slot) .. ".lua"
  end

  H.saveSetupPreset = function(slot, profile)
      if not mod.cache or type(mod.cache.write) ~= "function" then
          return false, "CACHE UNAVAILABLE"
      end
      local clean = copyRuleProfile(profile or {})
      clean.random_starter_reroll_index = 0
      local bytes = H.serializeSetupProfile(clean)
      local ok, err = mod.cache:write(setupPresetPath(slot), bytes)
      return ok ~= nil and ok ~= false, err
  end

  H.loadSetupPreset = function(slot)
      if not mod.cache or type(mod.cache.read) ~= "function" then
          return nil, "CACHE UNAVAILABLE"
      end
      local bytes, err = mod.cache:read(setupPresetPath(slot))
      if type(bytes) ~= "string" or bytes == "" then return nil, err or "EMPTY" end
      local value, parsed = {}, 0
      for line in bytes:gmatch("[^\r\n]+") do
          local key, raw = line:match('^%["([^"]+)"%]=(.*),$')
          if key and raw then
              local decoded
              if raw == "true" then decoded = true
              elseif raw == "false" then decoded = false
              elseif raw == "nil" then decoded = nil
              elseif raw:match('^".*"$') then
                  local body = raw:sub(2, -2)
                  decoded = body:gsub('\\"', '"'):gsub("\\\\", "\\")
              else
                  decoded = tonumber(raw)
                  if decoded == nil then return nil, "INVALID PRESET VALUE" end
              end
              value[key] = decoded
              parsed = parsed + 1
          end
      end
      if parsed == 0 then return nil, "INVALID PRESET" end
      return copyRuleProfile(value)
  end

  H.setupPresetExists = function(slot)
      return mod.cache and type(mod.cache.exists) == "function"
          and mod.cache:exists(setupPresetPath(slot)) == true
  end

  H.setupPresetPreview = function(slot, current)
      local profile, err = H.loadSetupPreset(slot)
      if not profile then return nil, err end
      -- 2.9.62: compare canonical profile representations on both sides.
      -- The old warning compared a normalized saved preset against the raw
      -- setup table, exposing boolean/nil/numeric implementation values and
      -- reporting differences immediately after saving an unchanged preset.
      profile = copyRuleProfile(profile)
      local currentProfile = copyRuleProfile(current or {})
      local changes = {}
      local keys = {}
      for _, cat in ipairs(ruleCategories) do
          for _, rule in ipairs(cat.rules) do keys[#keys + 1] = rule.key end
      end
      table.sort(keys)
      for _, key in ipairs(keys) do
          local before = currentProfile[key]
          local after = profile[key]
          if mod.exports.__beta26.configValuesDiffer(before, after) then
              local spec = mod.exports.__beta26.ruleDefinitionByKey
                  and mod.exports.__beta26.ruleDefinitionByKey[key]
              local label = mod.exports.__beta26.lockeRuleValueLabel
              changes[#changes + 1] = {
                  key = key,
                  name = tostring(spec and (spec.shortName or spec.name) or key),
                  from = type(label) == "function" and tostring(label(key, before))
                      or tostring(before),
                  to = type(label) == "function" and tostring(label(key, after))
                      or tostring(after),
              }
          end
      end
      return profile, changes
  end

  H.persistStagedProfile = function(profile)
      if not profile then return end
      mod.save:set(stagedProfileKey(), copyRuleProfile(profile))
      mod.save:set(stagedIntentKey(), true)
  end

  H.loadPersistedStagedProfile = function()
      if mod.save:get(stagedIntentKey(), false) ~= true then
          return nil
      end
      local profile = mod.save:get(stagedProfileKey(), nil)
      if type(profile) ~= "table" then
          return nil
      end
      return copyRuleProfile(profile)
  end

  local function clearPersistedStagedProfile()
      mod.save:set(stagedIntentKey(), false)
      mod.save:set(stagedProfileKey(), nil)
  end

  local function saveCurrentSetupProfile()
      if not pendingNewGameRules then
          pendingNewGameRules = makeDefaultPreGameRules()
      end
      local profile = copyRuleProfile(pendingNewGameRules)
      return saveSetupProfileToDisk(profile)
  end

  H.saveCurrentInGameRules = function()
      if mod.save:get("run_settings_lock", false) == true then
          return false, "run_settings_locked"
      end
      if not pendingNewGameRules then
          pendingNewGameRules = makeRulesFromCurrentSave()
      end

      local profile = copyRuleProfile(pendingNewGameRules)
      for _, cat in ipairs(ruleCategories) do
          for _, rule in ipairs(cat.rules) do
              if profile.type_lock_draft == true and mod.exports.__beta26.typeLockSlotIndex(rule.key)
                  and profile[rule.key] == nil then
                  mod.save:set(rule.key, nil)
              else
                  mod.save:set(rule.key, normalizeRuleValue(rule, profile[rule.key]))
              end
          end
      end
      do
          local mode = mod.exports.__beta26.movementAssistMode(profile.run_surf)
          mod.save:set("automatic_running_shoes", mode)
          mod.save:set("fast_surf", mode)
      end
      mod.save:set("locke_type", math.max(0, math.min(6,
          math.floor(tonumber(profile.locke_type)
              or defaultRuleValue("locke_type")))))
      saveAreaGuideState(profile.area_guide_enabled == true)
      mod.save:set("rule_lock", profile.rule_lock == true)
      local permanentlyLocked = mod.save:get("rules_permanently_locked", false) == true
      if permanentlyLocked then profile.rules_locked = true end
      mod.save:set("rules_locked", profile.rules_locked == true)
      if profile.rules_locked == true then mod.save:set("rules_permanently_locked", true) end
      mod.save:set("infinite_rare_candies", profile.infinite_rare_candies == true)
      mod.save:set("pkmn_ban_species", normalizePkmnBanSet(profile.pkmn_ban_species))
      mod.save:set("pkmn_ban", pkmnBanCountFromSet(profile.pkmn_ban_species) > 0)

      pendingNewGameRules = copyRuleProfile(profile)
      pendingRulesDirty = false
      areaGuideEnabled = profile.area_guide_enabled == true
      return true
  end

  local function stageNewGameProfile()
      -- The durable profile is the preferred source at the NEW GAME boundary.
      -- If the player changed the screen and did not press SAVE, use the live
      -- profile they are looking at; otherwise recover the explicitly saved
      -- profile from disk.
      local saved = loadSetupProfileFromDisk()
      if saved and not pendingRulesDirty then
          pendingNewGameRules = saved
      end
      pendingNewGameRules = copyRuleProfile(pendingNewGameRules or makeDefaultPreGameRules())
      mod.exports.__beta26.resolveRandomTypeLockSelection(pendingNewGameRules)
      newGameRulesSnapshot = copyRuleProfile(pendingNewGameRules)
      H.persistStagedProfile(newGameRulesSnapshot)
      pendingNewGameRulesForNextSave = true
      newGameRulesCommitPending = true
      newGameCommitPassesRemaining = 12
  end

  local function applyNewGameSnapshot()
      if saveSchemaTooNew then
          return false
      end
      if not newGameRulesCommitPending or not newGameRulesSnapshot then
          return false
      end

      local profile = newGameRulesSnapshot
      local allVerified = true

      -- Explicitly write EVERY registered rule, including false values.
      -- This is the critical distinction from relying on missing save keys:
      -- an OFF selection is a real selection, not permission to use defaults.
      for _, cat in ipairs(ruleCategories) do
          for _, rule in ipairs(cat.rules) do
              local expected
              if profile.type_lock_draft == true and mod.exports.__beta26.typeLockSlotIndex(rule.key)
                  and profile[rule.key] == nil then
                  expected = nil
              else
                  expected = normalizeRuleValue(rule, profile[rule.key])
              end
              mod.save:set(rule.key, expected)
          end
      end
      do
          local mode = mod.exports.__beta26.movementAssistMode(profile.run_surf)
          mod.save:set("automatic_running_shoes", mode)
          mod.save:set("fast_surf", mode)
      end

      -- `locke_type` is profile metadata rather than a registered rule row,
      -- so the loop above does not persist it. Write it explicitly before the
      -- verification block below; otherwise a fresh setup can save every owned
      -- rule correctly while retaining an older loadout label (or repeatedly
      -- failing snapshot verification).
      mod.save:set("locke_type", math.max(0, math.min(6,
          math.floor(tonumber(profile.locke_type)
              or defaultRuleValue("locke_type")))))
      saveAreaGuideState(profile.area_guide_enabled == true)
      mod.save:set("rule_lock", profile.rule_lock == true)
      mod.save:set("run_settings_lock", profile.run_settings_lock == true)
      if mod.save:get("rules_permanently_locked", false) == true then profile.rules_locked = true end
      mod.save:set("rules_locked", profile.rules_locked == true)
      if profile.rules_locked == true then mod.save:set("rules_permanently_locked", true) end
      mod.save:set("infinite_rare_candies", profile.infinite_rare_candies == true)
      mod.save:set("pkmn_ban_species", normalizePkmnBanSet(profile.pkmn_ban_species))
      mod.save:set("pkmn_ban", pkmnBanCountFromSet(profile.pkmn_ban_species) > 0)
      if type(profile.difficulty_provider_id) == "string"
          and profile.difficulty_provider_id ~= "" then
          mod.save:set("difficulty_provider_id", profile.difficulty_provider_id)
      end

      -- 2.6.21: zero is a persistent AUTO configuration, not the generated
      -- seed itself. Resolve AUTO into a playthrough-local seed only after the
      -- fresh mod.save bucket owns this snapshot, then re-apply seeded registry
      -- transforms so consecutive NEW GAME runs cannot inherit the prior run's
      -- encounter/learnset layout. Nonzero legacy/manual seeds stay fixed.
      if type(mod.exports.__beta26.ensureRandomizerRunSeed) == "function" then
          pcall(mod.exports.__beta26.ensureRandomizerRunSeed, profile)
      end
      if mod.exports.__beta26.Randomizer
          and type(mod.exports.__beta26.Randomizer.applyAll) == "function" then
          pcall(mod.exports.__beta26.Randomizer.applyAll, currentGame or mod.game)
      end

      if mod.save:get("route_forgiveness_initialized", false) ~= true then
          local rf = math.floor(tonumber(profile.route_forgiveness) or 0)
          mod.save:set("route_forgiveness_tokens", rf == 2 and 1 or 0)
          mod.save:set("route_forgiveness_initialized", true)
          -- Reward identity and revival snapshots are per-run state.
          mod.save:set("route_forgiveness_gym_trainers", {}) -- legacy key
          mod.save:set("route_forgiveness_gym_leaders", {})
          mod.save:set("route_forgiveness_dead_archive", {})
      end
      -- The first profile commit can occur after game.ready. Materialize the
      -- selected starting count into the real inventory item immediately.
      local forgivenessRewards = mod.exports.__beta26.TrainerRewards
      if forgivenessRewards and type(forgivenessRewards.syncForgivenessTokenItem)
          == "function" then
          pcall(forgivenessRewards.syncForgivenessTokenItem, currentGame)
      end

      -- Verify against the active save.  Keep the snapshot alive if another
      -- engine initialization pass overwrites it; the next lifecycle pass
      -- will stamp the same snapshot again.
      for _, cat in ipairs(ruleCategories) do
          for _, rule in ipairs(cat.rules) do
              local expected
              if profile.type_lock_draft == true and mod.exports.__beta26.typeLockSlotIndex(rule.key)
                  and profile[rule.key] == nil then
                  expected = nil
              else
                  expected = normalizeRuleValue(rule, profile[rule.key])
              end
              local actual = mod.save:get(rule.key, nil)
              if actual ~= expected then
                  allVerified = false
              end
          end
      end
      local lockeTypeActual = math.max(0, math.min(6,
          math.floor(tonumber(mod.save:get("locke_type",
              defaultRuleValue("locke_type")))
              or defaultRuleValue("locke_type"))))
      if lockeTypeActual ~= math.max(0, math.min(6,
          math.floor(tonumber(profile.locke_type)
              or defaultRuleValue("locke_type")))) then
          allVerified = false
      end
      local guideActual = mod.save:get("area_guide_enabled", nil)
      if guideActual ~= (profile.area_guide_enabled == true) then
          allVerified = false
      end
      if mod.save:get("rule_lock", nil) ~= (profile.rule_lock == true) then
          allVerified = false
      end
      if mod.save:get("run_settings_lock", nil) ~= (profile.run_settings_lock == true) then
          allVerified = false
      end
      if mod.save:get("rules_locked", nil) ~= (profile.rules_locked == true) then
          allVerified = false
      end
      local rareCandyActual = mod.save:get("infinite_rare_candies", nil)
      if rareCandyActual ~= (profile.infinite_rare_candies == true) then
          allVerified = false
      end
      if not pkmnBanSetsEqual(mod.save:get("pkmn_ban_species", {}),
          profile.pkmn_ban_species) then
          allVerified = false
      end
      if mod.save:get("pkmn_ban", false)
          ~= (pkmnBanCountFromSet(profile.pkmn_ban_species) > 0) then
          allVerified = false
      end
      if type(profile.difficulty_provider_id) == "string"
          and profile.difficulty_provider_id ~= ""
          and mod.save:get("difficulty_provider_id", nil)
              ~= profile.difficulty_provider_id then
          allVerified = false
      end

      if allVerified then
          newGameRulesCommitPending = false
          pendingNewGameRulesForNextSave = false
          pendingRulesDirty = false
          pendingNewGameRules = copyRuleProfile(profile)
          areaGuideEnabled = profile.area_guide_enabled == true
          newGameRulesSnapshot = nil
          newGameCommitPassesRemaining = 0
          clearPersistedStagedProfile()
          return true
      end

      return false
  end

  local function refreshRuleMirrorFromSave()
      -- Do not replace a still-pending new-game profile with the save's
      -- defaults.  That was the source of setup choices such as Level Caps
      -- and No X Items being lost when a fresh save was first loaded.
      if pendingNewGameRulesForNextSave and pendingNewGameRules then
          return
      end
      pendingNewGameRules = makeRulesFromCurrentSave()
      areaGuideEnabled = pendingNewGameRules.area_guide_enabled ~= false
      pendingRulesDirty = false
  end

  local function recoverNewGameSnapshotIfNeeded()
      if newGameRulesCommitPending and newGameRulesSnapshot then
          return true
      end
      local persisted = H.loadPersistedStagedProfile()
      if persisted then
          newGameRulesSnapshot = persisted
          pendingNewGameRules = copyRuleProfile(persisted)
          pendingNewGameRulesForNextSave = true
          newGameRulesCommitPending = true
          newGameCommitPassesRemaining = math.max(newGameCommitPassesRemaining, 12)
          return true
      end
      return false
  end

  ---------------------------------------------------------------------
  -- DEFINITIVE NEW-GAME COMMIT
  --
  -- RBY exposes intro.oak_speech.finished after its introduction. It remains
  -- a useful RBY commit point. Gold uses the shared intro step-list hook below
  -- after its real post-game.ready save.created event identifies NEW GAME.
  ---------------------------------------------------------------------
  local function commitDurableSetupProfileToActiveSave()
      local profile = loadSetupProfileFromDisk()
      if not profile then return false end

      for _, cat in ipairs(ruleCategories) do
          for _, rule in ipairs(cat.rules) do
              mod.save:set(rule.key, normalizeRuleValue(rule, profile[rule.key]))
          end
      end
      do
          local mode = mod.exports.__beta26.movementAssistMode(profile.run_surf)
          mod.save:set("automatic_running_shoes", mode)
          mod.save:set("fast_surf", mode)
      end
      mod.save:set("locke_type", math.max(0, math.min(6,
          math.floor(tonumber(profile.locke_type)
              or defaultRuleValue("locke_type")))))
      saveAreaGuideState(profile.area_guide_enabled == true)
      mod.save:set("rule_lock", profile.rule_lock == true)
      mod.save:set("run_settings_lock", profile.run_settings_lock == true)
      mod.save:set("rules_locked", profile.rules_locked == true)
      mod.save:set("infinite_rare_candies", profile.infinite_rare_candies == true)
      mod.save:set("pkmn_ban_species", normalizePkmnBanSet(profile.pkmn_ban_species))
      mod.save:set("pkmn_ban", pkmnBanCountFromSet(profile.pkmn_ban_species) > 0)
      if type(profile.difficulty_provider_id) == "string"
          and profile.difficulty_provider_id ~= "" then
          mod.save:set("difficulty_provider_id", profile.difficulty_provider_id)
      end

      local verified = true
      for _, cat in ipairs(ruleCategories) do
          for _, rule in ipairs(cat.rules) do
              local expected = normalizeRuleValue(rule, profile[rule.key])
              if mod.save:get(rule.key, nil) ~= expected then
                  verified = false
                  break
              end
          end
          if not verified then break end
      end
      if not pkmnBanSetsEqual(mod.save:get("pkmn_ban_species", {}),
          profile.pkmn_ban_species) then
          verified = false
      end
      if mod.save:get("pkmn_ban", false)
          ~= (pkmnBanCountFromSet(profile.pkmn_ban_species) > 0) then
          verified = false
      end
      local durableLockeType = math.max(0, math.min(6,
          math.floor(tonumber(mod.save:get("locke_type",
              defaultRuleValue("locke_type")))
              or defaultRuleValue("locke_type"))))
      if durableLockeType ~= math.max(0, math.min(6,
          math.floor(tonumber(profile.locke_type)
              or defaultRuleValue("locke_type")))) then
          verified = false
      end
      if mod.save:get("area_guide_enabled", nil) ~= (profile.area_guide_enabled == true) then
          verified = false
      end
      if mod.save:get("rule_lock", nil) ~= (profile.rule_lock == true) then
          verified = false
      end
      if mod.save:get("run_settings_lock", nil) ~= (profile.run_settings_lock == true) then
          verified = false
      end
      if mod.save:get("rules_locked", nil) ~= (profile.rules_locked == true) then
          verified = false
      end
      if mod.save:get("infinite_rare_candies", nil) ~= (profile.infinite_rare_candies == true) then
          verified = false
      end
      if type(profile.difficulty_provider_id) == "string"
          and profile.difficulty_provider_id ~= ""
          and mod.save:get("difficulty_provider_id", nil)
              ~= profile.difficulty_provider_id then
          verified = false
      end

      if verified then
          pendingNewGameRules = copyRuleProfile(profile)
          pendingNewGameRulesForNextSave = false
          pendingRulesDirty = false
          areaGuideEnabled = profile.area_guide_enabled == true
          newGameRulesSnapshot = nil
          newGameRulesCommitPending = false
          newGameCommitPassesRemaining = 0
          clearPersistedStagedProfile()
      end
      return verified
  end

  mod.events:on("intro.oak_speech.finished", function()
      local ver = getGameVersion and getGameVersion() or "RED"
      if ver == "RED" or ver == "BLUE" or ver == "YELLOW" then
          commitDurableSetupProfileToActiveSave()
      end
  end)

  mod.events:on("save.loaded", function(ev)
      if ev and ev.save then currentSave = ev.save end
      if recoverNewGameSnapshotIfNeeded() then
          applyNewGameSnapshot()
      else
          refreshRuleMirrorFromSave()
      end
  end)

  mod.events:on("game.ready", function(ev)
      local game = type(ev) == "table" and ev.game or ev
      currentGame = game or currentGame
      currentSave = (game and game.save) or currentSave
      if recoverNewGameSnapshotIfNeeded() then
          applyNewGameSnapshot()
      else
          refreshRuleMirrorFromSave()
      end
  end)

  -- A few engine systems initialize save-backed data during the first frames
  -- after game.ready.  Re-apply the immutable NEW GAME snapshot during that
  -- short window.  This is intentionally finite and only runs for a staged
  -- brand-new game; existing saves are never touched.
  mod.events:on("world.stepped", function()
      if recoverNewGameSnapshotIfNeeded() and newGameCommitPassesRemaining > 0 then
          newGameCommitPassesRemaining = newGameCommitPassesRemaining - 1
          applyNewGameSnapshot()
      end
  end)

  ---------------------------------------------------------------------
  -- NEW-GAME DEFAULT NAMES
  --
  -- This deliberately patches the three story-owned naming seams instead of
  -- NamingScreen itself. The shared keyboard is also used for Pokemon, boxes,
  -- and other editable strings; a global shortcut would silently rename them.
  -- Each shortcut writes through the same save fields and continuation the
  -- vanilla screen uses, so Oak's confirmations and Gold's officer script keep
  -- their ordinary order.
  ---------------------------------------------------------------------
  mod.exports.__beta26.quickStartRequested = function(game)
      if saveSchemaTooNew then return false end
      local runtimeGame = game or currentGame or mod.game
      if externalRuleDelegation
          and externalRuleDelegation("quick_nuzlocke_start", runtimeGame) then
          return false
      end
      local save = runtimeGame and runtimeGame.save
      if save and save.nuzlockeQuickStartPending == true then return true end
      local profile = newGameRulesSnapshot or pendingNewGameRules
      if profile and profile.quick_nuzlocke_start ~= nil then
          return profile.quick_nuzlocke_start == true
      end
      return mod.save:get("quick_nuzlocke_start", false) == true
  end

  mod.exports.__beta26.skipOpeningIntroRequested = function(game)
      if saveSchemaTooNew then return false end
      -- NEW GAME presentation-only shortcut. A dedicated intro provider wins
      -- only this presentation seam; Quick Start may still apply its later
      -- capture-ready progression transaction after that provider finishes.
      if externalRuleDelegation
          and externalRuleDelegation("skip_opening_intro",
              game or currentGame or mod.game) then
          return false
      end
      if mod.exports.__beta26.quickStartRequested(game) then return true end
      local profile = newGameRulesSnapshot or pendingNewGameRules
      if profile and profile.skip_opening_intro ~= nil then
          return profile.skip_opening_intro == true
      end
      return mod.save:get("skip_opening_intro", false) == true
  end

  local function automaticDefaultNamesEnabled(game)
      if saveSchemaTooNew then return false end
      -- Provider ownership wins over both carried NEW GAME state and dormant
      -- local settings. This mirrors the other non-core delegation seams: the
      -- stored choice can return if the provider leaves, but never double-runs.
      if externalRuleDelegation
          and externalRuleDelegation("automatic_default_names", game or currentGame or mod.game) then
          return false
      end
      if mod.exports.__beta26.quickStartRequested(game) then return true end
      if mod.exports.__beta26.skipOpeningIntroRequested(game) then return true end
      local save = game and game.save
      if save and save.nuzlockeAutomaticDefaultNames == true then return true end

      local profile = newGameRulesSnapshot or pendingNewGameRules
      if profile and profile.automatic_default_names ~= nil then
          return profile.automatic_default_names == true
      end
      return mod.save:get("automatic_default_names", false) == true
  end

  local function rememberAutomaticDefaultNames(game)
      if game and game.save then
          -- Gold's Rival is named hours after Oak's speech. Carry the NEW GAME
          -- choice on the actual save so that later story special does not rely
          -- on title-menu staging state that has correctly been cleared.
          game.save.nuzlockeAutomaticDefaultNames = true
      end
  end

  local function configuredNamePreset(game, who, explicit, fallback)
      if type(explicit) == "table" and type(explicit[1]) == "string"
          and explicit[1] ~= "" then
          return explicit[1]
      end
      local boot = game and game.data and game.data.field
          and game.data.field.boot
      local presets = boot and boot.namePresets and boot.namePresets[who]
      if type(presets) == "table" and type(presets[1]) == "string"
          and presets[1] ~= "" then
          return presets[1]
      end
      return fallback
  end

  -- 2.7.80 reconstruction: setup-only host-clock authority for Gen 2.
  -- Read the staged NEW GAME profile before the fresh save exists, then carry
  -- the choice on the concrete save once creation swaps the mod.save backing.
  mod.exports.__beta26.systemDateTimeRequested = function(game)
      if saveSchemaTooNew then return false end
      game = game or currentGame or mod.game
      if not mod.exports.__beta26.runtimeIsGen2(game) then return false end
      local save = game and game.save
      if save and save.nuzlockeSystemDateTime == true then return true end
      local profile = newGameRulesSnapshot or pendingNewGameRules
      if profile and profile.system_date_time ~= nil then
          return profile.system_date_time == true
      end
      return mod.save:get("system_date_time", false) == true
  end

  -- 2.2.20: Skip Oak's presentation without replacing New Game itself.
  -- Named intro steps are an upstream mod seam. System Date/Time may remove
  -- only Gen 2's InitClock step; all unrelated Oak/player-name progression is
  -- preserved. Skip Opening Intro still keeps the minimum semantic steps.
  mod.hooks:wrap("intro.oak_speech.build", function(next, steps, speech)
      local downstream = next(steps, speech)
      if type(downstream) ~= "table" then return downstream end
      local game = speech and speech.game or currentGame or mod.game
      local gold = mod.exports.__beta26.runtimeIsGen2(game)
      local hostClock = gold and mod.exports.__beta26.systemDateTimeRequested(game)
      local skipIntro = mod.exports.__beta26.skipOpeningIntroRequested(game)
      if not skipIntro and not hostClock then return downstream end

      local keep = {}
      for _, step in ipairs(downstream) do
          local id = type(step) == "table" and step.id or nil
          local wanted
          if skipIntro then
              wanted = gold
                  and (id == "name_player" or (id == "init_clock" and not hostClock))
                  or (not gold and (id == "name_player" or id == "name_rival"))
          else
              wanted = not (gold and hostClock and id == "init_clock")
          end
          if wanted then keep[#keep + 1] = step end
      end
      return keep
  end)

  local function installAutomaticDefaultNameAdapters()
      if mod.exports.__beta26.isSaveEditorSession() then return false end

      local okRby, RbyOak = pcall(require, "src.ui.OakSpeech")
      if okRby and type(RbyOak) == "table"
          and type(RbyOak.runStep) == "function"
          and not (RbyOak.__nuzlockeDefaultNamesOwner == mod
              and RbyOak.runStep == RbyOak.__nuzlockeDefaultNamesFunction) then
          if RbyOak.runStep == RbyOak.__nuzlockeDefaultNamesFunction
              and type(RbyOak.__nuzlockeDefaultNamesPrevious) == "function" then
              RbyOak.runStep = RbyOak.__nuzlockeDefaultNamesPrevious
          end
          local previous = RbyOak.runStep
          local wrapper = function(self, step)
              local game = self and self.game
              if type(step) == "table" and step.kind == "name"
                  and automaticDefaultNamesEnabled(game) then
                  local who = step.who == "rival" and "rival" or "player"
                  local fallback = who == "rival" and "BLUE" or "RED"
                  local name = configuredNamePreset(game, who, step.presets,
                      fallback)
                  if game and game.save then
                      game.save.player = game.save.player or {}
                      if who == "rival" then
                          game.save.player.rival = name
                      else
                          game.save.player.name = name
                      end
                      rememberAutomaticDefaultNames(game)
                  end
                  if type(self.recordAnswer) == "function" then
                      self:recordAnswer(step, 1, name, name)
                  end
                  if type(self.advance) == "function" then self:advance() end
                  return
              end
              return previous(self, step)
          end
          RbyOak.runStep = wrapper
          RbyOak.__nuzlockeDefaultNamesOwner = mod
          RbyOak.__nuzlockeDefaultNamesPrevious = previous
          RbyOak.__nuzlockeDefaultNamesFunction = wrapper
      end

      local okGoldOak, GoldOak = pcall(require, "src.ui.gen2.OakSpeech")
      if okGoldOak and type(GoldOak) == "table"
          and type(GoldOak.openNamePick) == "function"
          and not (GoldOak.__nuzlockeDefaultNamesOwner == mod
              and GoldOak.openNamePick == GoldOak.__nuzlockeDefaultNamesFunction) then
          if GoldOak.openNamePick == GoldOak.__nuzlockeDefaultNamesFunction
              and type(GoldOak.__nuzlockeDefaultNamesPrevious) == "function" then
              GoldOak.openNamePick = GoldOak.__nuzlockeDefaultNamesPrevious
          end
          local previous = GoldOak.openNamePick
          local wrapper = function(self, step)
              local game = self and self.game
              if automaticDefaultNamesEnabled(game) then
                  local exact = getGameVersion()
                  local fallback = exact == "CRYSTAL" and "KRIS"
                      or exact == "SILVER" and "SILVER" or "GOLD"
                  local name = configuredNamePreset(game, "player",
                      step and step.presets, fallback)
                  if game and game.save then
                      game.save.player = game.save.player or {}
                      game.save.player.name = name
                      rememberAutomaticDefaultNames(game)
                  end
                  if type(self.recordAnswer) == "function" then
                      self:recordAnswer(step or {}, 1, name, name)
                  end
                  self.busy = false
                  if type(self.advance) == "function" then self:advance() end
                  return
              end
              return previous(self, step)
          end
          GoldOak.openNamePick = wrapper
          GoldOak.__nuzlockeDefaultNamesOwner = mod
          GoldOak.__nuzlockeDefaultNamesPrevious = previous
          GoldOak.__nuzlockeDefaultNamesFunction = wrapper
      end

      local okWorld, GoldWorld = pcall(require, "src.world.gen2.World")
      if okWorld and type(GoldWorld) == "table"
          and type(GoldWorld.nameRival) == "function"
          and not (GoldWorld.__nuzlockeDefaultNamesOwner == mod
              and GoldWorld.nameRival == GoldWorld.__nuzlockeDefaultNamesFunction) then
          if GoldWorld.nameRival == GoldWorld.__nuzlockeDefaultNamesFunction
              and type(GoldWorld.__nuzlockeDefaultNamesPrevious) == "function" then
              GoldWorld.nameRival = GoldWorld.__nuzlockeDefaultNamesPrevious
          end
          local previous = GoldWorld.nameRival
          local wrapper = function(self, onDone)
              local game = self and self.game
              if automaticDefaultNamesEnabled(game) then
                  local exact = getGameVersion()
                  local name = exact == "SILVER" and "GOLD" or "SILVER"
                  if game and game.save then
                      game.save.rival = game.save.rival or {}
                      game.save.rival.name = name
                      rememberAutomaticDefaultNames(game)
                  end
                  if onDone then onDone(name) end
                  return
              end
              return previous(self, onDone)
          end
          GoldWorld.nameRival = wrapper
          GoldWorld.__nuzlockeDefaultNamesOwner = mod
          GoldWorld.__nuzlockeDefaultNamesPrevious = previous
          GoldWorld.__nuzlockeDefaultNamesFunction = wrapper
      end
      return true
  end

  -- 2.3.10: do not import OakSpeech/Gold World modules merely to reach the
  -- title screen. Install on NEW GAME selection below, with game.ready as a
  -- reload/continuation repair point.
  mod.events:on("game.ready", function()
      pcall(installAutomaticDefaultNameAdapters)
  end)

  ---------------------------------------------------------------------
  -- WRITE / TRACKING / ENFORCEMENT POLICY
  ---------------------------------------------------------------------
  -- 2.5.20: these are deliberately separate questions. Passive progression
  -- (Gym/E4/Champion synchronization) is allowed while the player's Nuzlocke
  -- master switch is OFF, but no Nuzlocke-owned persistent state may be changed
  -- when an unsupported newer save schema has forced this build read-only.
  -- Rule consequences additionally require the challenge itself to be enabled.
  mod.exports.__beta26.canWriteNuzlockeSave = function(game)
      return mod.exports.__beta26.saveSchemaSupported()
          and game ~= nil and game.save ~= nil
  end

  mod.exports.__beta26.isNuzlockeEnabled = function()
      return mod.save:get("nuzlocke_enabled", true) ~= false
  end

  mod.exports.__beta26.shouldEnforceNuzlocke = function(game, battle)
      if not mod.exports.__beta26.canWriteNuzlockeSave(game) then
          return false
      end
      if not mod.exports.__beta26.isNuzlockeEnabled() then
          return false
      end
      if battle and (battle.demo or battle.ghost) then
          return false
      end
      return true
  end

  -- Historical/internal callers keep using active(); its meaning is now
  -- explicitly the RULE_ENFORCEMENT policy rather than generic persistence.
  active = function(game, battle)
      return mod.exports.__beta26.shouldEnforceNuzlocke(game, battle)
  end

  ---------------------------------------------------------------------
  -- 2.9.56 EVOLUTION POLICY MODULE
  -- Evolution Limits and Trade Evolution QoL share the evolution.check seam.
  -- Randomizer evolution mappings, UI/config, identity, and acquisition policy
  -- remain with their existing owners.
  ---------------------------------------------------------------------
  local EvolutionPolicy = loadRequiredModuleChunk("evolution_policy.lua")()(mod, {
      defaultRuleValue = defaultRuleValue,
      getCurrentGame = function() return currentGame or mod.game end,
      runtimeIsGen2 = function(game) return mod.exports.__beta26.runtimeIsGen2(game) end,
      shouldEnforce = function(game) return active(game) end,
  })



  mod.exports.__beta26.ruleActive = function(game, key, battle)
      local fallback = defaultRuleValue(key)
      if type(mod.exports.__beta26.ruleOperationalState) == "function" then
          local ok = mod.exports.__beta26.ruleOperationalState(
              key, false, game or currentGame or mod.game)
          if ok ~= true then return false end
      end
      return active(game or currentGame or mod.game, battle)
          and mod.save:get(key, fallback) == true
  end

  -- 2.6.50 capability-driven No Held Items. Gold/Silver expose every held-item
  -- check through held_item.trigger. Compatible Gen1 providers can advertise a
  -- held-item capability; their field GIVE rows are removed after downstream
  -- composition, while TAKE remains available. Existing Gen1 held-item values
  -- are suppressed only for the player's battle party and restored after battle.
  if mod.hooks and type(mod.hooks.wrap) == "function" then
      mod.hooks:wrap("ui.party.submenu", function(next, game, items, mon, ctx)
          local out = next(game, items, mon, ctx)
          if mod.exports.__beta26.runtimeIsGen2(game)
              or not mod.exports.__beta26.heldItemRuleAvailable(game)
              or not active(game, ctx and ctx.battle)
              or mod.save:get("no_held_items", false) ~= true
              or type(out) ~= "table" then return out end
          for i = #out, 1, -1 do
              local row = out[i]
              local label = tostring(type(row) == "table" and (row.label or row.name or row.value) or row or ""):upper()
              local value = tostring(type(row) == "table" and (row.value or row.id) or ""):upper()
              if label == "GIVE" or value == "GIVE" or value == "HELD_ITEM_GIVE" then
                  table.remove(out, i)
              end
          end
          return out
      end, 1000)
  end

  local suppressedHeldItems2650 = setmetatable({}, { __mode = "k" })
  mod.events:on("battle.started", function(payload)
      local battle = payload and (payload.battle or payload)
      local game = payload and payload.game or currentGame or mod.game
      if mod.exports.__beta26.runtimeIsGen2(game)
          or not mod.exports.__beta26.heldItemRuleAvailable(game)
          or not active(game, battle)
          or mod.save:get("no_held_items", false) ~= true then return end
      local party = game and game.save and game.save.party
      for _, mon in ipairs(type(party) == "table" and party or {}) do
          if type(mon) == "table" then
              local held, item = mon.heldItem, mon.item
              if held ~= nil or item ~= nil then
                  suppressedHeldItems2650[mon] = { heldItem = held, item = item }
                  mon.heldItem, mon.item = nil, nil
              end
          end
      end
  end)
  mod.events:on("battle.ended", function()
      for mon, saved in pairs(suppressedHeldItems2650) do
          if type(mon) == "table" and type(saved) == "table" then
              if mon.heldItem == nil then mon.heldItem = saved.heldItem end
              if mon.item == nil then mon.item = saved.item end
          end
          suppressedHeldItems2650[mon] = nil
      end
  end)

  -- Native Gen2 trigger suppression remains authoritative.
  -- Gold exposes every held-item check through held_item.trigger. Compose with
  -- downstream providers first, then suppress the final effect only for exact
  -- members of the player's battle.party. Enemy/trainer held items remain
  -- native, and the held item value itself is never deleted or rewritten.
  if mod.hooks and type(mod.hooks.wrap) == "function" then
      mod.hooks:wrap("held_item.trigger", function(next, ctx)
          local effect, parameter = next(ctx)
          local game = currentGame or mod.game
          if not mod.exports.__beta26.runtimeIsGen2(game)
              or not active(game, type(ctx) == "table" and ctx.battle or nil)
              or mod.save:get("no_held_items", false) ~= true
              or type(ctx) ~= "table" or type(ctx.battle) ~= "table"
              or type(ctx.mon) ~= "table" then
              return effect, parameter
          end

          local party = ctx.battle.party
          if type(party) ~= "table" then return effect, parameter end
          for _, mon in ipairs(party) do
              if mon == ctx.mon then
                  return nil, 0
              end
          end
          return effect, parameter
      end, 1000)
  end

  ---------------------------------------------------------------------
  -- SHARED THREE-STATE WALK / SURF SPEED ASSISTS
  -- Gen1Recomp exposes movement.speed for ordinary player-controlled steps in
  -- both generations. R/B/Y supplies onBike/surfing/input; Gold supplies the
  -- same keys plus playerState/downhill. Scripted Gold steps bypass this seam,
  -- so Surf start/Waterfall/cutscenes keep their authored timing.
  ---------------------------------------------------------------------
  mod.hooks:wrap("movement.speed", function(next, frames, ctx)
      local downstream = next(frames, ctx)
      local originalFrames = tonumber(frames)
      local baseFrames = tonumber(downstream) or originalFrames
      if not baseFrames or type(ctx) ~= "table" then return downstream end
      -- 2.6.40: movement providers compose monotonically. If a downstream
      -- owner already accelerated this player-controlled step, Nuzlocke must
      -- not halve it again. This prevents 2x+2x => 4x stacking with Running
      -- Shoes/content mods while still allowing downstream slowdowns to be
      -- accelerated by the player's selected Nuzlocke mode.
      local downstreamAlreadyAccelerated = originalFrames ~= nil
          and tonumber(downstream) ~= nil and tonumber(downstream) < originalFrames
      if ctx.scripted == true or ctx.playerControlled == false then
          return downstream
      end
      local game = ctx.game or currentGame or mod.game
      local input = game and game.input or ctx.input
      local bHeld = input and type(input.isDown) == "function"
          and input:isDown("b") == true or false
      local function modeActive(mode)
          mode = mod.exports.__beta26.movementAssistMode(mode)
          return mode == 2 or (mode == 1 and bHeld)
      end

      local runSurfMode = mod.exports.__beta26.movementAssistMode(
          mod.save:get("run_surf", 0))
      if ctx.surfing == true then
          if not modeActive(runSurfMode) then return downstream end
          if downstreamAlreadyAccelerated then return downstream end
          return math.max(1, math.floor(baseFrames / 2))
      end

      if ctx.onBike == true then return downstream end
      if not modeActive(runSurfMode) then return downstream end

      -- QoL Toggles' source-confirmed run_hold_b option composes on this same
      -- hook. If it already owns the currently-held B step, do not halve that
      -- downstream answer a second time. ALWAYS still accelerates non-B steps,
      -- so the three-state Nuzlocke control remains fully adjustable.
      local externalHoldB = mod.exports.__beta26.qolToggleValue
          and mod.exports.__beta26.qolToggleValue("run_hold_b", game) == true
      if externalHoldB and bHeld then return downstream end
      if downstreamAlreadyAccelerated then return downstream end
      return math.max(1, math.floor(baseFrames / 2))
  end)

  ---------------------------------------------------------------------
  -- OPTIONAL NUZLOCKE BATTLE COMMAND MENU UI (2.7.93)
  --
  -- Presentation only. Native battle update/input/menuIndex/action dispatch
  -- remain authoritative. Hide only the ordinary four-command bottom menu and
  -- redraw it as a centered Nuzlocke-owned 2x2 panel in the same row-major
  -- order. Safari, Bug Contest and tutorial/demo menus keep their native UI.
  ---------------------------------------------------------------------
  do
      -- 2.8.29: Battle Menu UI is a Gen I-only feature. On Gen II, do not
      -- register either presentation hook at all; native Crystal/Gold/Silver
      -- retain their exact FIGHT / <PK><MN> / PACK / RUN command renderer.
      local battleMenuUiGen2 = mod.exports.__beta26.runtimeIsGen2(currentGame or mod.game)
      if not battleMenuUiGen2 then
      local function battleMenuUiEligible(state)
          if mod.save:get("battle_menu_ui", false) ~= true
              or type(state) ~= "table" or state.phase ~= "menu" then
              return false
          end
          if state.demo or state.safari or state.contest or state.tutorial then
              return false
          end
          local index = tonumber(state.menuIndex)
          return index ~= nil and index >= 1 and index <= 4
      end
      mod.exports.__beta26.battleMenuUiEligible = battleMenuUiEligible

      mod.hooks:wrap("battle.bottom_ui_visible", function(next, state)
          local downstream = next(state)
          if battleMenuUiEligible(state) then return false end
          return downstream
      end)

      mod.hooks:wrap("battle.overlay", function(next, state)
          next(state)
          if not battleMenuUiEligible(state) then return end

          local okFont, Font = pcall(require, "src.render.Font")
          if not okFont or type(Font) ~= "table"
              or type(Font.draw) ~= "function" then return end
          local okTheme, Theme = pcall(require, "src.ui.Theme")

          local surfaceWidth = 160
          if type(state.uiSize) == "function" then
              local okSize, width = pcall(state.uiSize, state)
              if okSize and tonumber(width) and tonumber(width) >= 160 then
                  surfaceWidth = math.floor(tonumber(width))
              end
          end

          -- 2.7.95 visual restoration: use the game's pixel-box chrome and
          -- keep the command surface in the native bottom-right battle-owned
          -- region instead of the large translucent rounded rectangle added in
          -- 2.7.93. Input/action authority is still entirely native.
          local panelW, panelH = 104, 48
          local panelX = math.max(0, surfaceWidth - panelW)
          local panelY = 96
          local leftX, rightX = panelX + 16, panelX + 58
          local topY, bottomY = panelY + 12, panelY + 28
          local index = math.max(1, math.min(4,
              math.floor(tonumber(state.menuIndex) or 1)))
          local row = math.floor((index - 1) / 2)
          local col = (index - 1) % 2
          local cursorX = (col == 0 and leftX or rightX) - 10
          local cursorY = row == 0 and topY or bottomY

          love.graphics.setColor(1, 1, 1, 1)
          love.graphics.rectangle("fill", panelX, panelY, panelW, panelH)
          love.graphics.setColor(0, 0, 0, 1)
          if type(Font.drawBox) == "function" then
              Font.drawBox(math.floor(panelX / 8), math.floor(panelY / 8),
                  math.floor(panelW / 8), math.floor(panelH / 8))
          else
              love.graphics.rectangle("line", panelX, panelY, panelW, panelH)
          end
          Font.draw(Strings("FIGHT", "battle"), leftX, topY)
          Font.draw(Strings("POKEMON", "battle"), rightX, topY)
          Font.draw(Strings("BAG", "battle"), leftX, bottomY)
          Font.draw(Strings("RUN", "battle"), rightX, bottomY)
          if type(Font.drawCode) == "function" then
              Font.drawCode(okTheme and Theme.cursor or 0xED,
                  cursorX, cursorY)
          else
              Font.draw(">", cursorX, cursorY)
          end
          love.graphics.setColor(1, 1, 1, 1)
      end)
      else
          -- A saved Gen I toggle value is inert on Gen II by construction.
          mod.exports.__beta26.battleMenuUiEligible = function() return false end
      end
  end


  ---------------------------------------------------------------------
  -- INSTANT TEXT QOL
  -- Gen1Recomp TextBox:update owns the typewriter cadence, while page/CONT
  -- waits, scroll timing, sound waits, choices, and scripted auto/stay states
  -- are separate. Fill only the line that is actively typing, then delegate
  -- to the native update so every non-typewriter timing contract stays native.
  ---------------------------------------------------------------------
  mod.exports.__beta26.installInstantText = function()
      if mod.exports.__beta26.isSaveEditorSession() then return true end
      local okText, TextBox = pcall(require, "src.render.TextBox")
      if not okText or type(TextBox) ~= "table" or type(TextBox.update) ~= "function" then
          return false
      end

      local session = TextBox.__nuzlockeInstantTextSession
      if type(session) == "table" and session.owner == mod
          and TextBox.update == session.wrapper then
          return true
      end
      if type(session) == "table" and session.owner ~= mod
          and TextBox.update == session.wrapper
          and type(session.previous) == "function" then
          TextBox.update = session.previous
      end

      local previous = TextBox.update
      local wrapper = function(self, dt)
          local enabled = mod.save:get("instant_text", defaultRuleValue("instant_text")) == true
          if enabled and type(self) == "table"
              and self.done ~= true and self.waiting ~= true
              and (tonumber(self.holdFrames) or 0) <= 0
              and self.preSound == nil
              and type(self.codes) == "table" and type(self.shown) == "table"
              and type(self.charIndex) == "number" then
              local line = self.shown[#self.shown]
              if type(line) == "table" then
                  if self.charIndex < #self.codes then
                      for i = self.charIndex + 1, #self.codes do
                          line[#line + 1] = self.codes[i]
                      end
                      self.charIndex = #self.codes
                  end
                  -- Native text speed is constrained to 1/3/5 frames. Five
                  -- guarantees the original update reaches its line-finished
                  -- branch immediately, including an intentionally empty line,
                  -- without leaving a large timer surplus.
                  self.charTimer = 5
              end
          end
          return previous(self, dt)
      end
      TextBox.update = wrapper
      TextBox.__nuzlockeInstantTextSession = {
          owner = mod, previous = previous, wrapper = wrapper,
      }
      return true
  end

  -- 2.6.60: rollout-completeness audit for fail-soft installers.  Any
  -- exported installX invoked through a bare pcall is invisible to Install
  -- Health and Feature Health, so future additions must route through
  -- attemptInstall with a stable subsystem id.
  mod.exports.__beta26.bareInstallerPcallAudit = function(source)
      source = tostring(source or "")
      local count, samples = 0, {}
      for call in source:gmatch("pcall%s*%(%s*(mod%.exports%.__beta26%.install[%w_]+)") do
          count = count + 1
          if #samples < 8 then samples[#samples + 1] = call end
      end
      return {
          ok = count == 0,
          count = count,
          samples = samples,
          detail = count == 0 and "no bare exported installer pcalls"
              or ("bare installer pcalls=" .. tostring(count)
                  .. " " .. table.concat(samples, ",")),
      }
  end

  mod.events:on("mods.loaded", function()
      mod.exports.__beta26.attemptInstall("qol.instant_text", mod.exports.__beta26.installInstantText)
  end)
  mod.events:on("game.ready", function(ev)
      local game = type(ev) == "table" and ev.game or ev
      currentGame = game or currentGame
      mod.exports.__beta26.attemptInstall("qol.instant_text", mod.exports.__beta26.installInstantText)
  end)
  mod.events:on("save.loaded", function()
      mod.exports.__beta26.attemptInstall("qol.instant_text", mod.exports.__beta26.installInstantText)
  end)

  ---------------------------------------------------------------------
  -- UNLIMITED BAG SPACE QOL
  -- Bag.capacity is the single distinct-slot gate used by Bag.add. R/B/Y has
  -- one ordinary ITEM-style bag; Gold has independent ITEM/BALL/KEY_ITEM/TM_HM
  -- pockets. Expand only the capacity bottlenecks players normally manage:
  -- R/B/Y's bag and Gold's ITEM + BALL pockets. The native 99-per-item stack
  -- limit stays inside Bag.add, and Gold key/TM pockets + PC storage are not
  -- touched. OFF composes back to whichever live engine/provider capacity was
  -- underneath us instead of hard-coding a vanilla number.
  ---------------------------------------------------------------------
  mod.exports.__beta26.unlimitedBagCapacity = function(nativeCapacity, pocket, game, enabled)
      if enabled ~= true then return nativeCapacity end
      local gold = mod.exports.__beta26.runtimeIsGen2(game or currentGame or mod.game)
      local normalizedPocket = tostring(pocket or "ITEM"):upper()
      if gold and normalizedPocket ~= "ITEM" and normalizedPocket ~= "BALL" then
          return nativeCapacity
      end
      return math.max(tonumber(nativeCapacity) or 0, 0x7fffffff)
  end

  mod.exports.__beta26.installUnlimitedBagSpace = function()
      if mod.exports.__beta26.isSaveEditorSession() then return true end
      local okBag, Bag = pcall(require, "src.inventory.Bag")
      if not okBag or type(Bag) ~= "table" or type(Bag.capacity) ~= "function" then
          return false
      end

      local session = Bag.__nuzlockeUnlimitedBagSpaceSession
      if type(session) == "table" and session.owner == mod
          and Bag.capacity == session.wrapper then
          return true
      end
      -- A stale wrapper from another loader (notably the embedded Save Editor)
      -- must never retain that loader's mod.save closure into gameplay.
      if type(session) == "table" and session.owner ~= mod
          and Bag.capacity == session.wrapper
          and type(session.previous) == "function" then
          Bag.capacity = session.previous
      end

      local previous = Bag.capacity
      local wrapper = function(data, pocket)
          local native = previous(data, pocket)
          local enabled = mod.save:get(
              "unlimited_bag_space", defaultRuleValue("unlimited_bag_space")) == true
          return mod.exports.__beta26.unlimitedBagCapacity(
              native, pocket, currentGame or mod.game, enabled)
      end
      Bag.capacity = wrapper
      Bag.__nuzlockeUnlimitedBagSpaceSession = {
          owner = mod, previous = previous, wrapper = wrapper,
      }
      return true
  end

  mod.events:on("mods.loaded", function()
      mod.exports.__beta26.attemptInstall("qol.unlimited_bag_space", mod.exports.__beta26.installUnlimitedBagSpace)
  end)
  mod.events:on("game.ready", function(ev)
      local game = type(ev) == "table" and ev.game or ev
      currentGame = game or currentGame
      mod.exports.__beta26.attemptInstall("qol.unlimited_bag_space", mod.exports.__beta26.installUnlimitedBagSpace)
  end)
  mod.events:on("save.loaded", function()
      mod.exports.__beta26.attemptInstall("qol.unlimited_bag_space", mod.exports.__beta26.installUnlimitedBagSpace)
  end)

  ---------------------------------------------------------------------
  -- PUBLIC INTEROP / CAPABILITY API
  -- 2.5.82: behavior-preserving extraction from main.lua. Keep live game/save
  -- state behind getters so the module never captures a stale lifecycle value.
  ---------------------------------------------------------------------
  loadRequiredModuleChunk("public_interop.lua")()(mod, {
      currentGame = function() return currentGame end,
      currentSave = function() return currentSave end,
      defaultRuleValue = defaultRuleValue,
      registerArea = registerArea,
      externalRuleDelegation = externalRuleDelegation,
      NON_CORE_DELEGATION = NON_CORE_DELEGATION,
      -- 2.6.29: these policies are installed later in main.lua. Pass live
      -- wrappers/getters instead of freezing nil during this module load.
      specialAcquisitionDenied = function(...)
