  -- WORLD BUILDING / FLAVOR (2.6.18 MODULE)
  ---------------------------------------------------------------------
  local WorldBuilding = loadRequiredModuleChunk("world_building.lua")()(mod, {
      Strings = Strings, defaultRuleValue = defaultRuleValue,
