          label = "encounter randomizer",
      },
      random_field_items = {
          capabilities = { "field_item_randomizer_provider" },
          label = "visible field-item randomizer",
      },
      random_field_item_balance = {
          capabilities = { "field_item_randomizer_provider" },
          label = "visible field-item randomizer",
      },
      random_field_item_repetition = {
          capabilities = { "field_item_randomizer_provider" },
          label = "visible field-item randomizer",
      },
      random_learnsets = {
          capabilities = { "learnset_randomizer_provider" },
