  do -- compiler-budget scope: loadout preview labels
  local function lockeRuleDisplayName(key)
      for _, cat in ipairs(ruleCategories) do
          for _, rule in ipairs(cat.rules or {}) do
              if rule.key == key then
                  return tostring(Strings(rule.shortName or rule.name or key))
              end
          end
      end
      return tostring(key or "RULE"):gsub("_", " "):upper()
  end

  local function lockeRuleValueLabel(key, value)
      if key == "level_cap_scope" then
          return ({ [0]="NONE", [1]="GYMS", [2]="E4", [3]="CHAMP", [4]="POST" })[
              math.floor(tonumber(value) or 0)] or "NONE"
      end
      if mod.exports.__beta26.isBattleScopeRuleKey(key) then
          return tostring(Strings(mod.exports.__beta26.battleScopeLabel(value)))
      end
      return value == true and "ON" or "OFF"
  end

  mod.exports.__beta26.lockeRuleDisplayName = lockeRuleDisplayName
  mod.exports.__beta26.lockeRuleValueLabel = lockeRuleValueLabel

  mod.exports.__beta26.configValuesDiffer = function(actual, wanted)
      if type(wanted) == "number" then
          return tonumber(actual) ~= wanted
      end
      if type(wanted) == "boolean" then
          return (actual == true) ~= wanted
      end
      return actual ~= wanted
  end

  LockePreset.modeMatches = function(mode, preGame)
      local preset = LockePreset.presets[mode]
      if type(preset) ~= "table" then return false end
      for key, wanted in pairs(preset) do
          -- A currently delegated rule is owned by another provider. It must
          -- neither be rewritten by the loadout nor force the Nuzlocke label
          -- to CUSTOM merely because the external owner exposes a neutral row.
          local delegated = externalRuleDelegation
              and externalRuleDelegation(key, currentGame or mod.game)
          if not delegated then
              local actual = getConfigValue(key, preGame)
              if mod.exports.__beta26.configValuesDiffer(actual, wanted) then
                  return false
              end
          end
      end
      return true
  end

  LockePreset.classify = function(preGame)
      -- Prefer the exact named loadouts in visible order. CUSTOM is reserved
      -- for combinations that do not exactly match any preset footprint.
      for _, mode in ipairs({ 5, 6, 1, 2, 3, 4 }) do
          if LockePreset.modeMatches(mode, preGame) then return mode end
      end
      return 0
  end

  LockePreset.nextMode = function(current, step)
      local order = LockePreset.cycleOrder
      local pos = 1
      current = math.floor(tonumber(current) or 0)
      for i, mode in ipairs(order) do
          if mode == current then pos = i break end
      end
      step = (tonumber(step) or 1) >= 0 and 1 or -1
      pos = ((pos - 1 + step) % #order) + 1
      return order[pos]
  end

  LockePreset.preview = function(mode, preGame)
      local changes = {}
      local preset = LockePreset.presets[mode]
      if type(preset) ~= "table" then return changes end
      for key, wanted in pairs(preset) do
          local delegated = externalRuleDelegation
              and externalRuleDelegation(key, currentGame or mod.game)
          if not delegated then
              local actual = getConfigValue(key, preGame)
              local differs = mod.exports.__beta26.configValuesDiffer(actual, wanted)
              if differs then
                  changes[#changes + 1] = {
                      key = key,
                      name = lockeRuleDisplayName(key),
                      from = lockeRuleValueLabel(key, actual),
                      to = lockeRuleValueLabel(key, wanted),
                  }
              end
          end
      end
      table.sort(changes, function(a, b)
          return tostring(a.name) < tostring(b.name)
      end)
      return changes
  end


  LockePreset.nearest = function(preGame)
      local bestMode, bestCount = nil, math.huge
      for _, mode in ipairs({ 6, 1, 2, 3, 4, 5 }) do
          local count = #LockePreset.preview(mode, preGame)
          if count < bestCount then
              bestMode, bestCount = mode, count
          end
      end
      return bestMode, bestCount
  end

  LockePreset.displayLabel = function(mode, preGame)
      mode = math.max(0, math.min(6, math.floor(tonumber(mode) or 0)))
      if mode ~= 0 then return LockePreset.labels[mode] or "CUSTOM" end
      local nearest, count = LockePreset.nearest(preGame)
      if nearest and count and count > 0 then return "CUSTOM*" end
      return "CUSTOM"
  end

  LockePreset.customSummary = function(preGame)
      if LockePreset.classify(preGame) ~= 0 then return nil end
      local nearest, count = LockePreset.nearest(preGame)
      if not nearest then return Strings("CUSTOM LOADOUT") end
      return Strings("CUSTOM: %d change%s from %s", count, count == 1 and "" or "s",
          Strings(LockePreset.labels[nearest] or LockePreset.names[nearest] or "PRESET"))
  end

  LockePreset.description = function(mode)
      local descriptions = {
          [0] = Strings.source("Keep the current hand-built challenge rules unchanged."),
          [5] = Strings.source("Vanilla challenge-rule footprint only; independent QoL, Difficulty, Randomizer, UI, and World Building stay unchanged."),
          [6] = Strings.source("Classic Nuzlocke core plus Gym-level caps; a gentler recommended baseline."),
          [1] = Strings.source("Classic Nuzlocke core: permadeath, one encounter per area, failed encounters, and nicknames."),
          [2] = Strings.source("Nuzlocke plus Champion caps, battle healing/X-item bans, Gym team-size matching, and no rival mercy."),
          [3] = Strings.source("Nuzlocke with Party Size 1 and run-ending Blackout behavior."),
          [4] = Strings.source("IronMON-style solo/no-heal/no-shop challenge using only rules Nuzlocke owns."),
      }
      return Strings(descriptions[math.floor(tonumber(mode) or 0)]
