  local function setConfigValue(key, value, preGame, preserveDormant)
      if not preGame and mod.save:get("run_settings_lock", false) == true then return false end
      -- Use lifecycle-stable Type Locke slot tables throughout this update.
      -- Yellow 2.5.7 runtime testing showed Type Locke edits can still reach
      -- the generic error dialog even after unrelated-rule sync was hardened.
      local typeLockKeys = mod.exports.__beta26.typeLockSlotKeys()
      local typeLockDefaults = mod.exports.__beta26.typeLockSlotDefaults()
      if key == "rules_locked"
          and mod.exports.__beta26.permanentRuleSealWip then
          value = false
      end
      if not preserveDormant and externalRuleDelegation
          and externalRuleDelegation(key, currentGame or mod.game) then
          return false
      end
      if key == "locke_type" then
          -- Locke preset identity is profile metadata rather than an ordinary
          -- ruleCategories row, so it intentionally keeps its explicit clamp.
          value = math.max(0, math.min(6, math.floor(tonumber(value) or 0)))
      else
          value = mod.exports.__beta26.coerceRuleValue(key, value, "write")
      end
      local achievementPriorValue = nil
      if not preGame then
          achievementPriorValue = mod.save:get(key, defaultRuleValue(key))
      end

      if preGame then
          if not pendingNewGameRules then
              pendingNewGameRules = makeDefaultPreGameRules()
          end
          pendingNewGameRules[key] = value
          if key == "shop_restrictions" then
              local mode = math.max(0, math.min(3, math.floor(tonumber(value) or 0)))
              pendingNewGameRules.no_buying = (mode == 1 or mode == 3)
              pendingNewGameRules.no_selling = (mode == 2 or mode == 3)
          end
          if key == "run_surf" then
              local mode = mod.exports.__beta26.movementAssistMode(value)
              pendingNewGameRules.automatic_running_shoes = mode
              pendingNewGameRules.fast_surf = mode
          end
          if key == "no_buying" or key == "no_selling" then
              local noBuy = key == "no_buying" and value == true
                  or key ~= "no_buying" and pendingNewGameRules.no_buying == true
              local noSell = key == "no_selling" and value == true
                  or key ~= "no_selling" and pendingNewGameRules.no_selling == true
              pendingNewGameRules.shop_restrictions =
                  noBuy and (noSell and 3 or 1) or (noSell and 2 or 0)
          end
          if key == "pkmn_ban" and value ~= true then
              pendingNewGameRules.pkmn_ban_species = {}
          end
          if key == "status_move_scope" then
              for _, childKey in ipairs(mod.exports.__beta26.statusMoveChildKeys()) do
                  pendingNewGameRules[childKey] = value
              end
          end
          if key == "randomizer_seed" and tonumber(value) and tonumber(value) > 0 then
              pendingNewGameRules.__randomizer_legacy = nil
          end
          if key == "type_lock_draft" and value == true then
              for _, slotKey in ipairs(typeLockKeys) do pendingNewGameRules[slotKey] = nil end
          end
          if key == "type_lock_mode" then
              local mode = value
              if mode <= 0 then
                  for _, slotKey in ipairs(typeLockKeys) do pendingNewGameRules[slotKey] = nil end
              elseif pendingNewGameRules.type_lock_draft == true then
                  for i = mode + 1, #typeLockKeys do pendingNewGameRules[typeLockKeys[i]] = nil end
              else
                  for i = 1, mode do local sk=typeLockKeys[i]; if pendingNewGameRules[sk] == nil then pendingNewGameRules[sk]=defaultRuleValue(sk) end end
                  mod.exports.__beta26.resolveRandomTypeLockSelection(pendingNewGameRules)
              end
          elseif key == "type_lock_draft" and value == false then
              local mode = math.max(0, math.min(6, math.floor(tonumber(pendingNewGameRules.type_lock_mode) or 0)))
              for i=1,mode do local sk=typeLockKeys[i]; if pendingNewGameRules[sk]==nil then pendingNewGameRules[sk]=defaultRuleValue(sk) end end
              mod.exports.__beta26.resolveRandomTypeLockSelection(pendingNewGameRules)
          elseif key:match("^type_lock_") and key ~= "type_lock_mode" and key ~= "type_lock_draft" then
              mod.exports.__beta26.resolveRandomTypeLockSelection(pendingNewGameRules)
          end
          if key == "difficulty_profile" and not LockePreset.applying then
              local options = mod.exports.__beta26.difficultyOptions()
              local row = options[(tonumber(value) or 0) + 1]
              pendingNewGameRules.difficulty_provider_id = row and row.id or nil
          end
          if key == "randomizer_preset" and not RandomizerPreset.applying then
          local preset = RandomizerPreset.values[tonumber(value) or 0]
          if preset then
              RandomizerPreset.applying = true
              for _, childKey in ipairs(RandomizerPreset.order) do
                  setConfigValue(childKey, preset[childKey], preGame, false)
              end
              RandomizerPreset.applying = false
              if not preGame and mod.exports.__beta26.Randomizer then
                  pcall(mod.exports.__beta26.Randomizer.applyAll, currentGame or mod.game)
              end
          end
      elseif RandomizerPreset.managed[key] and not RandomizerPreset.applying then
          if preGame then
              if pendingNewGameRules then pendingNewGameRules.randomizer_preset = 0 end
          else
              mod.save:set("randomizer_preset", 0)
          end
      end

      if key ~= "locke_type" and LockePreset.managed[key]
              and not LockePreset.applying then
              pendingNewGameRules.locke_type = LockePreset.classify(true)
          end
          if key == "level_cap_scope" then
              pendingNewGameRules.hardcore_mode = value > 0
              pendingNewGameRules.elite_four_caps = value >= 2
          end
          pendingRulesDirty = true

          if key == "area_guide_enabled" then
              areaGuideEnabled = value
          end
          return
      end

      if key == "area_guide_enabled" then
          saveAreaGuideState(value)
      else
          mod.save:set(key, value)
          if key == "shop_restrictions" then
              local mode = math.max(0, math.min(3, math.floor(tonumber(value) or 0)))
              mod.save:set("no_buying", mode == 1 or mode == 3)
              mod.save:set("no_selling", mode == 2 or mode == 3)
          end
          if key == "run_surf" then
              local mode = mod.exports.__beta26.movementAssistMode(value)
              mod.save:set("automatic_running_shoes", mode)
              mod.save:set("fast_surf", mode)
          end
          if key == "no_buying" or key == "no_selling" then
              local noBuy = key == "no_buying" and value == true
                  or key ~= "no_buying" and mod.save:get("no_buying", false) == true
              local noSell = key == "no_selling" and value == true
                  or key ~= "no_selling" and mod.save:get("no_selling", false) == true
              mod.save:set("shop_restrictions",
                  noBuy and (noSell and 3 or 1) or (noSell and 2 or 0))
          end
          if key == "pkmn_ban" and value ~= true then
              mod.save:set("pkmn_ban_species", {})
          end
          if key == "status_move_scope" then
              for _, childKey in ipairs(mod.exports.__beta26.statusMoveChildKeys()) do
                  mod.save:set(childKey, value)
              end
          end
          if key == "randomizer_seed" then
              if type(mod.exports.__beta26.resetRandomizerRunSeed) == "function" then
                  mod.exports.__beta26.resetRandomizerRunSeed()
              end
              local anyRandomizer = mod.save:get("random_starter", false) == true
                  or mod.save:get("random_encounter_tables", false) == true
                  or mod.save:get("random_field_items", false) == true
                  or mod.save:get("random_learnsets", false) == true
                  or mod.save:get("random_trainers", false) == true
                  or mod.save:get("random_evolutions", false) == true
                  or mod.save:get("random_shops", false) == true
                  or mod.save:get("random_tms", false) == true
                  or mod.save:get("random_tm_locations", false) == true
                  or mod.save:get("random_gift_items", false) == true
              if anyRandomizer and type(mod.exports.__beta26.randomizerSeed) == "function" then
                  mod.exports.__beta26.randomizerSeed(nil, true)
              end
          end
          if key == "type_lock_draft" and value == true then
              for _, slotKey in ipairs(typeLockKeys) do mod.save:set(slotKey, nil) end
          end
          if key == "type_lock_mode" then
              local mode = value
              if mode <= 0 then
                  for _, slotKey in ipairs(typeLockKeys) do mod.save:set(slotKey, nil) end
              elseif mod.save:get("type_lock_draft", false) == true then
                  for i=mode+1,#typeLockKeys do mod.save:set(typeLockKeys[i], nil) end
              else
                  local live={type_lock_mode=mode,type_lock_draft=false}
                  for i=1,mode do local sk=typeLockKeys[i]; live[sk]=mod.save:get(sk,defaultRuleValue(sk)) end
                  mod.exports.__beta26.resolveRandomTypeLockSelection(live)
                  for i=1,#typeLockKeys do mod.save:set(typeLockKeys[i], live[typeLockKeys[i]]) end
              end
          elseif key == "type_lock_draft" and value == false then
              local mode=math.max(0,math.min(6,math.floor(tonumber(mod.save:get("type_lock_mode",0)) or 0)))
              local live={type_lock_mode=mode,type_lock_draft=false}
              for i=1,mode do local sk=typeLockKeys[i]; live[sk]=mod.save:get(sk,defaultRuleValue(sk)) end
              mod.exports.__beta26.resolveRandomTypeLockSelection(live)
              for i=1,#typeLockKeys do mod.save:set(typeLockKeys[i], live[typeLockKeys[i]]) end
          end
          if (key == "random_starter" or key == "random_encounter_tables"
              or key == "random_field_items" or key == "random_learnsets"
              or key == "random_trainers" or key == "random_evolutions" or key == "random_shops"
              or key == "random_tms" or key == "random_tm_locations"
              or key == "random_gift_items") and value == true
              and mod.exports.__beta26.randomizerSeed then
              mod.exports.__beta26.randomizerSeed(nil, true)
          end
          if (key == "random_encounter_tables" or key == "random_learnsets"
              or key == "randomizer_seed"
              or key == "random_learnset_generation" or key == "random_species_generation"
              or key == "random_encounter_balance"
              or key == "random_encounter_repetition"
              or key == "random_encounter_diversity_strength"
              or key == "random_field_item_balance"
              or key == "random_field_item_repetition"
              or key == "random_evolutions" or key == "random_shops"
              or key == "random_tms" or key == "random_tm_compatibility")
              and mod.exports.__beta26.Randomizer and not RandomizerPreset.applying then
              pcall(mod.exports.__beta26.Randomizer.applyAll,
                  currentGame or mod.game)
          end
          if (key == "type_lock_mode" or key == "type_lock_draft" or key == "type_lock_primary"
              or key == "type_lock_secondary" or key == "type_lock_tertiary"
              or key == "type_lock_quaternary" or key == "type_lock_quinary" or key == "type_lock_senary"
              or key == "ban_legendaries" or key == "ban_mythicals"
              or key == "ban_pseudos" or key == "maximum_bst"
              or key == "pkmn_ban")
              and mod.exports.__beta26.Randomizer
              and type(mod.exports.__beta26.Randomizer.applyEncounters) == "function" then
              pcall(mod.exports.__beta26.Randomizer.applyEncounters,
                  currentGame or mod.game)
          end
          if key == "no_catching" then
              mod.save:set("no_catching_legacy_ambiguous_29313", nil)
          end
          if key == "difficulty_profile" then
              local options = mod.exports.__beta26.difficultyOptions()
              local row = options[(tonumber(value) or 0) + 1]
              mod.save:set("difficulty_provider_id", row and row.id or nil)
          end
          if key == "level_cap_scope" then
              mod.save:set("hardcore_mode", value > 0)
              mod.save:set("elite_four_caps", value >= 2)
          end
          if key:match("^type_lock_") and key ~= "type_lock_mode" and key ~= "type_lock_draft" and mod.save:get("type_lock_draft", false) ~= true then
              local mode=math.max(0,math.min(6,math.floor(tonumber(mod.save:get("type_lock_mode",0)) or 0)))
              local live={type_lock_mode=mode,type_lock_draft=false}
              for i=1,mode do local sk=typeLockKeys[i]; live[sk]=mod.save:get(sk,defaultRuleValue(sk)) end
              mod.exports.__beta26.resolveRandomTypeLockSelection(live)
              for i=1,#typeLockKeys do mod.save:set(typeLockKeys[i], live[typeLockKeys[i]]) end
              value=live[key]
          end
      end

      if key == "randomizer_preset" and not RandomizerPreset.applying then
          local preset = RandomizerPreset.values[tonumber(value) or 0]
          if preset then
              RandomizerPreset.applying = true
              for _, childKey in ipairs(RandomizerPreset.order) do
                  setConfigValue(childKey, preset[childKey], false, false)
              end
              RandomizerPreset.applying = false
              if mod.exports.__beta26.Randomizer then
                  pcall(mod.exports.__beta26.Randomizer.applyAll, currentGame or mod.game)
              end
          end
      elseif RandomizerPreset.managed[key] and not RandomizerPreset.applying then
          mod.save:set("randomizer_preset", 0)
      end

      if key ~= "locke_type" and LockePreset.managed[key]
          and not LockePreset.applying then
          mod.save:set("locke_type", LockePreset.classify(false))
      end

      -- A dungeon lock is transient state, not a permanent route flag. Turning
      -- either the master switch or Dungeon Lock-In OFF must release it now so
      -- re-enabling the rule later cannot resurrect an entrance from an older
      -- ruleset state.
      if (key == "nuzlocke_enabled" and value ~= true)
          or (key == "dungeon_lock_in" and value ~= true) then
          mod.save:set("nuzlocke_dungeon_lock_state", nil)
      end

      if (key == "route_2_split" or key == "route_10_split"
          or key == "route_20_split" or key == "mt_moon_splits"
          or key == "safari_zone_splits" or key == "gold_time_split"
          or key == "gold_headbutt_split") then
          if type(mod.exports.__beta26.reprojectEncounterAreas) == "function" then
              pcall(mod.exports.__beta26.reprojectEncounterAreas)
          end
          if type(mod.exports.__beta26.randomizerEncounterSplitChanged)
              == "function" then
              pcall(mod.exports.__beta26.randomizerEncounterSplitChanged,
                  currentGame or mod.game, key)
          end
      end

      -- Preserve run-integrity evidence for future achievements. This only
      -- records after Run History already exists and never starts a run from
      -- title/setup configuration.
      if mod.exports.__beta26.RunHistory
          and type(mod.exports.__beta26.RunHistory.recordRuleConfigurationChange)
              == "function" then
          local achievementAfterValue = mod.save:get(key, value)
          pcall(mod.exports.__beta26.RunHistory.recordRuleConfigurationChange,
              currentGame or mod.game, key, achievementPriorValue,
              achievementAfterValue, "setConfigValue")
      end

      -- Trainer Card and other live UI consumers can use this revision as a
      -- cheap invalidation signal. The actual value remains mod.save's source
      -- of truth, so toggles take effect immediately without requiring a save.
      mod.save:set("nuzlocke_rule_revision", (tonumber(mod.save:get("nuzlocke_rule_revision", 0)) or 0) + 1)

      if key == "dev_mode" then
          pcall(mod.exports.__beta26.refreshGoldDevMenuRow,
              currentGame or mod.game, value == true)
      end

      -- Keep the title-screen representation synchronized with the active save.
      if not pendingNewGameRules then
          pendingNewGameRules = makeDefaultPreGameRules()
      end
      pendingNewGameRules[key] = value
      if key == "pkmn_ban" then
          pendingNewGameRules.pkmn_ban_species = normalizePkmnBanSet(
              mod.save:get("pkmn_ban_species", {}))
      end
      if key == "status_move_scope" then
          for _, childKey in ipairs(mod.exports.__beta26.statusMoveChildKeys()) do
              pendingNewGameRules[childKey] = value
          end
      end
      if key == "difficulty_profile" and not LockePreset.applying then
          -- Live changes are already persisted, but the staged/title model
          -- also carries the stable provider id. Keep both representations
          -- aligned so dynamic provider ordering cannot revive a stale id.
          pendingNewGameRules.difficulty_provider_id =
              mod.save:get("difficulty_provider_id", nil)
      end
      local syncedTypeMode = math.max(0, math.min(6, math.floor(tonumber(pendingNewGameRules.type_lock_mode) or 0)))
      pendingNewGameRules.type_lock_draft = mod.save:get("type_lock_draft", pendingNewGameRules.type_lock_draft == true) == true
      -- 2.5.6: ordinary NUZ RULES edits must never depend on a live Type Locke
      -- table reference just to mirror the active save back into title/setup state.
      -- Blue 2.5.5 runtime evidence showed this unconditional sync reaching
      -- ipairs(nil) after otherwise-valid rule writes. Preserve the canonical slot
      -- order as a local fallback so unrelated toggles remain usable even if a
      -- stale/reloaded closure does not retain the shared table reference.
      local syncTypeLockKeys = typeLockKeys
      local syncTypeLockDefaults = typeLockDefaults
      for i, slotKey in ipairs(syncTypeLockKeys) do
          if syncedTypeMode >= i then
              local raw=mod.save:get(slotKey,pendingNewGameRules[slotKey])
              local fallback = syncTypeLockDefaults[i]
              if fallback == nil then fallback = defaultRuleValue(slotKey) end
              if raw ~= nil then pendingNewGameRules[slotKey]=math.max(0,math.min(18,math.floor(tonumber(raw) or tonumber(fallback) or 0))) else pendingNewGameRules[slotKey]=nil end
          else pendingNewGameRules[slotKey]=nil end
      end
      if key ~= "locke_type" and LockePreset.managed[key]
          and not LockePreset.applying then
          pendingNewGameRules.locke_type = tonumber(mod.save:get(
              "locke_type", defaultRuleValue("locke_type")))
              or defaultRuleValue("locke_type")
      end
      if key == "level_cap_scope" then
          pendingNewGameRules.hardcore_mode = value > 0
          pendingNewGameRules.elite_four_caps = value >= 2
      end
      pendingRulesDirty = false
      if key == "infinite_rare_candies" and refreshGymGuideVisibility and currentGame then
          refreshGymGuideVisibility(currentGame)
      end
      if key == "dev_mode" and value == true
          and mod.exports.__beta26.Dev then
          mod.exports.__beta26.Dev.push("dev_mode", "enabled from NUZ RULES",
              currentGame or mod.game)
          pcall(mod.exports.__beta26.Dev.logSnapshot, "dev_mode_enabled",
              currentGame or mod.game)
      end
  end

  -- 2.9.18: narrow internal setter export for the Nuzlocke-owned lifecycle UI.
  -- Consumers must use this rather than writing rule state directly so ordinary
  -- lock release, integrity evidence, revisions, and title-state sync still run.
  mod.exports.__beta26.setConfigValue = setConfigValue

  LockePreset.apply = function(mode, preGame)
      mode = math.max(0, math.min(6, math.floor(tonumber(mode) or 0)))

      -- CUSTOM is intentionally non-destructive: it only drops the preset label
      -- and keeps the player's current rule combination intact.
      if mode == 0 then
          setConfigValue("locke_type", 0, preGame)
          return true
      end

      local preset = LockePreset.presets[mode]
      if type(preset) ~= "table" then return false end

      LockePreset.applying = true
      for key, value in pairs(preset) do
          setConfigValue(key, value, preGame, false)
      end
      setConfigValue("locke_type", mode, preGame, true)
      LockePreset.applying = false
      return true
  end

