  ---------------------------------------------------------------------
  -- DIRECT LOADOUT CHOOSER (2.7.83)
  ---------------------------------------------------------------------
  mod.content.screens:register("NuzlockeLoadoutChooser", {
      new = function(game, ctx)
          ctx = ctx or {}
          local order = { 5, 6, 1, 2, 3, 4, 0 }
          local currentMode = math.max(0, math.min(6, math.floor(tonumber(ctx.currentMode) or 0)))
          local index = 1
          for i, mode in ipairs(order) do if mode == currentMode then index = i break end end
          local self = { game=game, screenId="NuzlockeLoadoutChooser", isOpaque=true,
              order=order, index=index, preGame=ctx.preGame==true, onChoose=ctx.onChoose, elapsed=0 }
          mod.exports.__beta26.UiSystem.applyLayout(self, "centered")
          local function mode() return self.order[self.index] or 0 end
          function self:update(dt)
              self.elapsed = self.elapsed + (dt or 0)
              if game.input:wasPressed("up") then self.index=((self.index-2)%#self.order)+1
              elseif game.input:wasPressed("down") then self.index=(self.index%#self.order)+1
              elseif game.input:wasPressed("left") then self.index=((self.index-2)%#self.order)+1
              elseif game.input:wasPressed("right") then self.index=(self.index%#self.order)+1
              elseif game.input:wasPressed("b") then game.stack:pop()
              elseif game.input:wasPressed("a") then
                  local chosen=mode(); game.stack:pop()
                  if self.onChoose then self.onChoose(chosen) end
              end
          end
          function self:draw()
              local chosen=mode(); local changes=LockePreset.preview(chosen,self.preGame)
              local name=tostring(Strings(LockePreset.names[chosen] or "CUSTOM"))
              local desc=tostring(LockePreset.description(chosen))
              if mod.exports.__beta26.runtimeIsGen2(game) then
                  local Chrome=require("src.ui.gen2.Chrome"); local GoldFont=require("src.render.Font")
                  Chrome.clear(); Chrome.box(0,0,20,18)
                  mod.exports.__beta26.drawGen2NuzTitle(Chrome,GoldFont,"LOADOUT",name,{row=1,subtitleRow=3})
                  local y=5
                  for i,m in ipairs(self.order) do
                      if i==self.index then Chrome.cursor(1,y) end
                      Chrome.print(Strings(LockePreset.labels[m] or LockePreset.names[m]),3,y); y=y+1
                  end
                  Chrome.printWrapped(Strings("%d CHANGES: %s",#changes,desc),2,13,16,2)
                  Chrome.print(Strings("A:CHOOSE  B:BACK"),2,16); return
              end
              local Font=mod.ui.Font; love.graphics.setColor(1,1,1,1); love.graphics.rectangle("fill",0,0,160,144); Font.drawBox(0,0,20,18)
              Font.draw(Strings("LOADOUT"),58,8); Font.draw(name,14,20)
              local y=34
              for i,m in ipairs(self.order) do
                  if i==self.index then Font.draw(Strings(">"),10,y) end
                  Font.draw(Strings(LockePreset.labels[m] or LockePreset.names[m]),22,y); y=y+10
              end
              Font.draw(marqueeText(Strings("%d CHANGES %s",#changes,desc),18,self.elapsed,1.2),10,110)
              Font.draw(Strings("A:CHOOSE B:BACK"),28,130)
          end
          return self
      end,
  })

  ---------------------------------------------------------------------
  -- DIFFICULTY PROFILE REVIEW (2.7.67 / direct selector 2.7.83)
  -- Difficulty changes are previewed against VANILLA before mutation.
  -- Left/Right browse every available profile; A confirms the shown profile.
  -- Only after A does the existing interaction warning run when needed.
  ---------------------------------------------------------------------
  mod.content.screens:register("NuzlockeDifficultyReview", {
      new = function(game, ctx)
          ctx = ctx or {}
          local options = mod.exports.__beta26.difficultyOptions()
          local startId = tostring(ctx.proposedId or ctx.currentId or "vanilla")
          local _, startIndex = difficultyOptionById(options, startId)
          local self = { game=game, screenId="NuzlockeDifficultyReview", isOpaque=true,
              options=options, index=(tonumber(startIndex) or 0)+1, elapsed=0,
              summaryScroll=0, onConfirm=ctx.onConfirm }
          mod.exports.__beta26.UiSystem.applyLayout(self,"centered")
          local function current() return self.options[self.index] or self.options[1] end
          local function summary(row)
              local fn=mod.exports.__beta26.difficultyProfileSummary
              local text=type(fn)=="function" and fn(row and row.id or "vanilla") or ""
              return tostring(text or "")
          end
          function self:update(dt)
              self.elapsed=self.elapsed+(dt or 0)
              if #self.options <= 0 then
                  if game.input:wasPressed("b") then game.stack:pop() end
                  return
              end
              if game.input:wasPressed("up") or game.input:wasPressed("left") then
                  self.index=((self.index-2)%#self.options)+1
                  self.summaryScroll=0
              elseif game.input:wasPressed("down") or game.input:wasPressed("right") then
                  self.index=(self.index%#self.options)+1
                  self.summaryScroll=0
              elseif game.input:wasPressed("select") then
                  local detailLines=wrapText(summary(current()),16)
                  local maxScroll=math.max(0,#detailLines-3)
                  self.summaryScroll=maxScroll > 0
                      and (((tonumber(self.summaryScroll) or 0)+1)%(maxScroll+1)) or 0
              elseif game.input:wasPressed("b") then
                  game.stack:pop()
              elseif game.input:wasPressed("a") then
                  local row=current()
                  game.stack:pop()
                  if self.onConfirm and row then self.onConfirm(row) end
              end
          end
          function self:draw()
              local row=current()
              local name=tostring(Strings(row and row.name or "VANILLA"))
              local text=summary(row)
              local lines=wrapText(text,16)
              local maxSummaryScroll=math.max(0,#lines-3)
              self.summaryScroll=math.max(0,math.min(
                  tonumber(self.summaryScroll) or 0,maxSummaryScroll))
              local firstSummary=self.summaryScroll+1
              if mod.exports.__beta26.runtimeIsGen2(game) then
                  local Chrome=require("src.ui.gen2.Chrome")
                  local GoldFont=require("src.render.Font")
                  Chrome.clear()
                  Chrome.box(0,0,20,18)
                  mod.exports.__beta26.drawGen2NuzTitle(
                      Chrome,GoldFont,"DIFFICULTY",name,{row=1,subtitleRow=3})
                  local top=5
                  local visible=math.min(#self.options,5)
                  local base=math.max(1,math.min(
                      self.index-2,math.max(1,#self.options-visible+1)))
                  for i=base,math.min(#self.options,base+visible-1) do
                      if i==self.index then Chrome.cursor(1,top) end
                      Chrome.print(marqueeText(Strings(
                          self.options[i].name or self.options[i].id),
                          15,self.elapsed,1.2),3,top)
                      top=top+1
                  end
                  for i=0,2 do
                      local detail=lines[firstSummary+i]
                      if detail then Chrome.print(detail,2,11+i) end
                  end
                  if maxSummaryScroll>0 then
                      Chrome.print(Strings("SEL:MORE"),2,15)
                      Chrome.print(Strings("%d/%d",
                          self.summaryScroll+1,maxSummaryScroll+1),13,15)
                  end
                  Chrome.print(Strings("LR:PROFILE A:OK B:BACK"),2,16)
                  return
              end
              local Font=mod.ui.Font
              love.graphics.setColor(1,1,1,1)
              love.graphics.rectangle("fill",0,0,160,144)
              Font.drawBox(0,0,20,18)
              Font.draw(Strings("DIFFICULTY"),44,8)
              Font.draw(marqueeText(name,16,self.elapsed,1.2),14,20)
              local Theme=require("src.ui.Theme")
              local y=34
              local visible=math.min(#self.options,5)
              local base=math.max(1,math.min(
                  self.index-2,math.max(1,#self.options-visible+1)))
              for i=base,math.min(#self.options,base+visible-1) do
                  if i==self.index then Font.drawCode(Theme.cursor,10,y) end
                  Font.draw(marqueeText(Strings(
                      self.options[i].name or self.options[i].id),
                      18,self.elapsed,1.2),22,y)
                  y=y+10
              end
              for i=0,2 do
                  local detail=lines[firstSummary+i]
                  if detail then Font.draw(detail,12,88+i*12) end
              end
              if maxSummaryScroll>0 then
                  Font.draw(Strings("SEL:MORE %d/%d",
                      self.summaryScroll+1,maxSummaryScroll+1),12,124)
              end
              Font.draw(Strings("LR:PROFILE A:OK B:BACK"),12,134)
          end
          return self
      end,
  })

  ---------------------------------------------------------------------
  -- LOADOUT CHANGE CONFIRMATION (2.4.18)
  -- A preset is never applied until this modal has shown the player exactly
  -- how many loadout-owned rules will change. B cancels with zero mutation.
  ---------------------------------------------------------------------
  mod.content.screens:register("NuzlockeLoadoutConfirm", {
      new = function(game, ctx)
          ctx = ctx or {}
          local self = {
              game = game,
              screenId = "NuzlockeLoadoutConfirm",
              isOpaque = true,
              cursor = 2, -- safe default: NO
              elapsed = 0,
              scroll = 0,
              mode = math.max(0, math.min(6, math.floor(tonumber(ctx.mode) or 0))),
              modalTitle = ctx.title and tostring(ctx.title) or nil,
              modalName = ctx.name and tostring(ctx.name) or nil,
              modalMessage = ctx.message and tostring(ctx.message) or nil,
              changes = type(ctx.changes) == "table" and ctx.changes or {},
              onChoice = ctx.onChoice,
          }
          mod.exports.__beta26.UiSystem.applyLayout(self, "centered")

          function self:update(dt)
              self.elapsed = self.elapsed + (dt or 0)
              local maxScroll = math.max(0, #self.changes - 4)
              if game.input:wasPressed("up") then
                  self.scroll = math.max(0, (self.scroll or 0) - 1)
              elseif game.input:wasPressed("down") then
                  self.scroll = math.min(maxScroll, (self.scroll or 0) + 1)
              elseif game.input:wasPressed("left") or game.input:wasPressed("right") then
                  self.cursor = self.cursor == 1 and 2 or 1
              elseif game.input:wasPressed("b") then
                  game.stack:pop()
                  if self.onChoice then self.onChoice(false) end
              elseif game.input:wasPressed("a") then
                  local yes = self.cursor == 1
                  game.stack:pop()
                  if self.onChoice then self.onChoice(yes) end
              end
          end
          function self:draw()
              local name = self.modalName
                  or tostring(Strings(LockePreset.names[self.mode] or "CUSTOM"))
              local modalTitle = self.modalTitle or Strings("LOADOUT WARNING")
              local count = #self.changes
              if mod.exports.__beta26.runtimeIsGen2(game) then
                  local Chrome = require("src.ui.gen2.Chrome")
                  Chrome.clear()
                  Chrome.box(0, 0, 20, 18)
                  local GoldFont = require("src.render.Font")
                  mod.exports.__beta26.drawGen2NuzTitle(Chrome, GoldFont, modalTitle)
                  Chrome.printWrapped(self.modalMessage or Strings("%s will change %d loadout-owned rules.",
                      name, count), 2, 3, 16, 3)
                  local y = 7
                  local first = math.min(count + 1, (self.scroll or 0) + 1)
                  local last = math.min(count, first + 3)
                  for i = first, last do
                      local ch = self.changes[i]
                      Chrome.print(marqueeText(Strings("%s>%s %s",
                          ch.from, ch.to, ch.name), 16, self.elapsed, 1.2),
                          2, y)
                      y = y + 1
                  end
                  if count > 4 then
                      Chrome.print(Strings("%d-%d/%d UP/DN", first, last, count), 2, 11)
                  end
                  if self.cursor == 1 then Chrome.cursor(2, 14) end
                  if self.cursor == 2 then Chrome.cursor(10, 14) end
                  Chrome.print(Strings("APPLY"), 3, 14)
                  Chrome.print(Strings("CANCEL"), 11, 14)
                  return
              end

              local Font = mod.ui.Font
              -- 2.5.8 Yellow runtime repair: keep the confirmation fully on the
              -- native 160x144 surface. Each change row gets a fixed 16-glyph
              -- budget with the destination value first; long rule names
              -- marquee inside the remaining budget instead of crossing the box.
              love.graphics.setColor(1, 1, 1, 1)
              love.graphics.rectangle("fill", 0, 0, 160, 144)
              Font.drawBox(0, 0, 20, 18)
              Font.draw(marqueeText(Strings(modalTitle), 16, self.elapsed, 1.2), 14, 10)
              Font.draw(marqueeText(self.modalMessage or Strings("%s changes %d", name, count),
                  16, self.elapsed, 1.2), 14, 28)
              local y = 46
              local first = math.min(count + 1, (self.scroll or 0) + 1)
              local last = math.min(count, first + 3)
              for i = first, last do
                  local ch = self.changes[i]
                  local from = tostring(Strings(ch.from or ""))
                  local to = tostring(Strings(ch.to or ""))
                  local transition = from .. ">" .. to
                  local nameBudget = math.max(5, 15 - #transition)
                  local label = marqueeText(ch.name or ch.key or "RULE",
                      nameBudget, self.elapsed, 1.2)
                  Font.draw(Strings("%s %s", transition, label), 14, y)
                  y = y + 12
              end
              if count > 4 then
                  Font.draw(Strings("%d-%d/%d UP/DN", first, last, count), 14, 96)
              end
              local Theme=require("src.ui.Theme")
              if self.cursor==1 then Font.drawCode(Theme.cursor,10,116) end
              if self.cursor==2 then Font.drawCode(Theme.cursor,72,116) end
              Font.draw(Strings("APPLY"),22,116)
              Font.draw(Strings("CANCEL"),84,116)
          end
          return self
      end,
  })

  ---------------------------------------------------------------------
  -- PKMN BAN PICKER (2.6.25)
  -- R/B/Y use National Dex #001-#151; Gold/Silver use #001-#251. Persisted
  -- identity is always National Dex number. Both presenters use the engine's
  -- native filled cursor glyph for the hovered species; A toggles, B returns.
  ---------------------------------------------------------------------
  mod.content.screens:register("NuzlockePokemonBanScreen", {
      isModOptions = true,
      new = function(game, ctx)
          ctx = ctx or {}
          local preGame = ctx.preGame == true
          local gen2Mode = mod.exports.__beta26.runtimeIsGen2(game)
          local rows = mod.exports.__beta26.speciesBanRows(game)
          local self = {
              game = game,
              screenId = "NuzlockePokemonBanScreen",
              isOpaque = true,
              preGame = preGame,
              gen2Mode = gen2Mode,
              rows = rows,
              index = 1,
              scroll = 0,
              visibleRows = 5,
              elapsed = 0,
          }

          mod.exports.__beta26.UiSystem.applyLayout(self, "centered")

          local function currentSet()
              return mod.exports.__beta26.pkmnBanSetForConfig(preGame, game)
          end

          local function ensureVisible()
              local maxScroll = math.max(0, #rows - self.visibleRows)
              if self.index <= self.scroll then
                  self.scroll = self.index - 1
              elseif self.index > self.scroll + self.visibleRows then
                  self.scroll = self.index - self.visibleRows
              end
              self.scroll = math.max(0, math.min(maxScroll, self.scroll))
          end

          local function toggleCurrent()
              if mod.exports.__beta26.configRulesLocked(preGame) then return false end
              local row = rows[self.index]
              if not row then return false end
              local key = tostring(row.index)
              local limit = mod.exports.__beta26.nationalDexLimitForGame(game)
              local set = currentSet()
              if set[key] == true then set[key] = nil else set[key] = true end
              set = normalizePkmnBanSet(set, limit)

              if preGame then
                  if not pendingNewGameRules then
                      pendingNewGameRules = loadSetupProfileFromDisk()
                          or makeDefaultPreGameRules()
                  end
                  pendingNewGameRules.pkmn_ban_species = set
              else
                  mod.save:set("pkmn_ban_species", set)
                  if pendingNewGameRules then
                      pendingNewGameRules.pkmn_ban_species = normalizePkmnBanSet(set, limit)
                  end
              end
              setConfigValue("pkmn_ban", pkmnBanCountFromSet(set, limit) > 0, preGame)
              return true
          end

          function self:update(dt)
              self.elapsed = self.elapsed + (dt or 0)
              if game.input:wasPressed("up") then
                  self.index = math.max(1, self.index - 1)
                  ensureVisible()
              elseif game.input:wasPressed("down") then
                  self.index = math.min(#rows, self.index + 1)
                  ensureVisible()
              elseif game.input:wasPressed("left") then
                  self.index = math.max(1, self.index - self.visibleRows)
                  ensureVisible()
              elseif game.input:wasPressed("right") then
                  self.index = math.min(#rows, self.index + self.visibleRows)
                  ensureVisible()
              elseif game.input:wasPressed("b") then
                  game.stack:pop()
              elseif game.input:wasPressed("a") then
                  toggleCurrent()
              end
          end

          function self:draw()
              local set = currentSet()
              local first = self.scroll + 1
              local last = math.min(#rows, self.scroll + self.visibleRows)
              local limit = mod.exports.__beta26.nationalDexLimitForGame(game)
              local bannedCount = pkmnBanCountFromSet(set, limit)

              if self.gen2Mode then
                  local Chrome = require("src.ui.gen2.Chrome")
                  local Font = require("src.render.Font")
                  Chrome.clear()
                  Chrome.box(0, 0, 20, 18)
                  mod.exports.__beta26.drawGen2NuzTitle(Chrome, Font, "PKMN BAN")
                  for i = first, last do
                      local row = rows[i]
                      local y = 3 + (i - first) * 2
                      if i == self.index then Chrome.cursor(1, y) end
                      local label = ("%03d %s"):format(row.index,
                          tostring(row.name or row.species or ("DEX #" .. row.index)))
                      Chrome.print(marqueeText(label, 16, self.elapsed, 3.8), 2, y)
                      Chrome.print(set[tostring(row.index)] == true
                          and Strings("BANNED") or Strings("ALLOWED"), 3, y + 1)
                  end
                  local position = ("%d/%d"):format(self.index, #rows)
                  Chrome.print(position, 3, 14)
                  Chrome.print(Strings("BAN %d", bannedCount), 10, 14)
                  if self.scroll > 0 then Font.drawCode(0x61, 8, 14 * 8) end
                  if self.scroll + self.visibleRows < #rows then
                      Font.drawCode(Chrome.DOWN_ARROW, 144, 14 * 8)
                  end
                  Chrome.print(Strings("A:TOGGLE B:BACK"), 2, 16)
                  return
              end

              local Font = mod.ui.Font
              local Theme = require("src.ui.Theme")
              local function fitPkmnBanPixelText(text, budget)
                  text = Strings(tostring(text or ""))
                  budget = math.max(0, tonumber(budget) or 0)
                  if type(Font.width) ~= "function"
                      or type(Font.split) ~= "function"
                      or type(Font.spansFitting) ~= "function"
                      or Font.width(text) <= budget then
                      return text
                  end
                  local spans = Font.split(text)
                  local fit = Font.spansFitting(spans, budget)
                  if fit <= 0 then return "" end
                  return text:sub(1, spans[fit].to)
              end
              love.graphics.setColor(1, 1, 1, 1)
              love.graphics.rectangle("fill", 0, 0, 160, 144)
              Font.drawBox(0, 0, 20, 18)
              love.graphics.setColor(0, 0, 0, 1)
              Font.draw(Strings("PKMN BAN"), 16, 8)
              for i = first, last do
                  local row = rows[i]
                  local y = 24 + (i - first) * 16
                  if i == self.index then
                      Font.drawCode(Theme.cursor, 8, y)
                  end
                  local label = ("%03d %s"):format(row.index,
                      tostring(row.name or row.species or ("DEX #" .. row.index)))
                  Font.draw(fitPkmnBanPixelText(label, 132), 20, y)
                  Font.draw(set[tostring(row.index)] == true
                      and Strings("BANNED") or Strings("ALLOWED"), 28, y + 8)
              end
              local position = ("%d/%d"):format(self.index, #rows)
              Font.draw(position, 16, 112)
              Font.draw(Strings("BANNED %d", bannedCount), 76, 112)
              Font.draw(Strings("A:TOGGLE  B:BACK"), 16, 128)
              love.graphics.setColor(1, 1, 1, 1)
          end
          return self
      end,
  })

  ---------------------------------------------------------------------
  -- REGISTER CONFIG SCREEN
  ---------------------------------------------------------------------
  mod.content.screens:register("NuzlockeConfigScreen", {
      isModOptions = true,
      new = function(game, ctx)
          local preGame = ctx and ctx.preGame == true
          local autoNewGame = ctx and ctx.autoNewGame == true
          -- Gold and R/B/Y share this screen, but their supported rule
          -- surfaces are intentionally different. Resolve the mode from the
          -- explicit caller hint first, then from the live game. B9 left this
          -- lexical undefined, which made Gold render the R/B/Y setup surface.
          local goldMode = (ctx and ctx.goldMode == true)
              or mod.exports.__beta26.runtimeIsGen2(game)

          if preGame and not pendingNewGameRules then
              pendingNewGameRules = loadSetupProfileFromDisk()
                  or makeDefaultPreGameRules()
          elseif not preGame then
              discoverAllKnownAreas(game)
              -- The active save is authoritative when entering the in-game menu.
              if not pendingRulesDirty then
                  pendingNewGameRules = makeRulesFromCurrentSave()
              end
              areaGuideEnabled =
                  pendingNewGameRules.area_guide_enabled ~= false
          end

          local allItemList = H.buildFlatItemList(preGame, goldMode)
          if preGame and autoNewGame then
              table.insert(allItemList, 1, {
                  isHeader = false, isControl = true, alwaysVisible = true,
                  isStartNewGameControl = true,
                  rule = { key = "start_nuzlocke_game",
                      name = Strings.source("START NEW GAME"),
                      shortName = Strings.source("START GAME"),
                      desc = Strings.source("Commit this setup to a new save and begin the normal introduction. B cancels.")
                  }
              })
          end

          -- 2.8.22: one Randomizer hierarchy for BOTH Gen I and Gen II.
          -- Every true child is immediately below its owning parent; global
          -- Randomizer controls stay at the top. Existing dependency filtering
          -- below remains authoritative, so child rows disappear while their
          -- parent is OFF without losing their stored value.
          do
              local randomizerOrder = {
                  randomizer_preset=10,
                  randomizer_seed=20, reroll_randomizer_seed=21,
                  auto_randomizer_seed=22,
                  randomizer_info_policy=30,
                  random_species_generation=40,

                  random_starter=100, random_starter_style=101,
                  random_starter_balance=102, random_starter_trio_typing=103,
                  random_starter_rerolls=104, reroll_random_starter=105,

                  random_encounter_tables=200,
                  random_encounter_balance=201,
                  random_encounter_repetition=202,
                  random_encounter_diversity_strength=203,

                  random_field_items=300, random_field_item_balance=301,
                  random_field_item_repetition=302,

                  random_learnsets=400, random_learnset_generation=401,
                  random_learnset_stab=402,

                  random_trainers=500, random_trainer_balance=501,
                  random_trainer_diversity=502, random_trainer_theme=503,

                  random_evolutions=600, random_evolution_balance=601,

                  random_shops=700, random_shop_balance=701,

                  random_tms=800, random_tm_compatibility=801,
                  random_tm_locations=810,

                  random_gift_items=900,
              }
              local rebuilt = {}
              local i = 1
              while i <= #allItemList do
                  local row = allItemList[i]
                  if row and row.isHeader
                      and tostring(row.name or "") == "RANDOMIZER" then
                      rebuilt[#rebuilt + 1] = row
                      i = i + 1
                      local block = {}
                      while i <= #allItemList
                          and not (allItemList[i] and allItemList[i].isHeader) do
                          block[#block + 1] = allItemList[i]
                          i = i + 1
                      end
                      for order, candidate in ipairs(block) do
                          candidate.__nuzRandomizerOriginalOrder2809 = order
                      end
                      table.sort(block, function(a, b)
                          local ak = a and a.rule and a.rule.key
                          local bk = b and b.rule and b.rule.key
                          local ar = randomizerOrder[ak] or 10000
                          local br = randomizerOrder[bk] or 10000
                          if ar ~= br then return ar < br end
                          return (a.__nuzRandomizerOriginalOrder2809 or 0)
                              < (b.__nuzRandomizerOriginalOrder2809 or 0)
                      end)
                      for _, candidate in ipairs(block) do
                          candidate.__nuzRandomizerOriginalOrder2809 = nil
                          rebuilt[#rebuilt + 1] = candidate
                      end
                  else
                      rebuilt[#rebuilt + 1] = row
                      i = i + 1
                  end
              end
              allItemList = rebuilt
          end
          local collapseSurface = (preGame and "setup:" or "rules:")
              .. (goldMode and "gold" or "rby")
          collapsedConfigSections[collapseSurface] =
              collapsedConfigSections[collapseSurface] or {}
          local collapsedSections = collapsedConfigSections[collapseSurface]
          local flatItemList = {}

          local function sectionKey(item)
              return tostring(item and item.name or "")
          end

          -- 2.6.22: collapsed headers summarize configuration without adding
          -- another list row. Count only catalog-backed settings belonging to
          -- this exact surface; action rows such as Reroll Seed are controls,
          -- not settings. "CHANGED" means the effective displayed value differs
          -- from that rule's catalog default, so delegated/provider-owned rows
          -- summarize the same value the player actually sees.
          local function collapsedSectionSummary(header)
              if not (header and header.isHeader) then return nil, 0, 0 end
              local wanted = sectionKey(header)
              local collecting = false
              local changed, total = 0, 0
              for _, candidate in ipairs(allItemList) do
                  if candidate.isHeader then
                      local key = sectionKey(candidate)
                      if collecting then break end
                      collecting = key == wanted
                  elseif collecting and candidate.rule then
                      local key = candidate.rule.key
                      local spec = key and mod.exports.__beta26.ruleDefinitionByKey
                          and mod.exports.__beta26.ruleDefinitionByKey[key]
                      if spec then
                          total = total + 1
                          local actual = getConfigValue(key, preGame)
                          local wantedDefault = defaultRuleValue(key)
                          if mod.exports.__beta26.configValuesDiffer(
                              actual, wantedDefault) then
                              changed = changed + 1
                          end
                      end
                  end
              end
              local label = changed == 0 and Strings("DEFAULT")
                  or Strings("%d CHANGED", changed)
              return tostring(label), changed, total
          end

          -- 2.5.24: remember navigation by semantic row identity rather than by
          -- raw list index. Dependent rows and collapsed sections can change the
          -- visible list length, so rule/header keys are the stable anchor.
          local function itemPositionKey(item)
              if not item then return nil end
              if item.isHeader then
                  return "header:" .. sectionKey(item)
              end
              local key = item.rule and item.rule.key
              if key ~= nil then
                  return "rule:" .. tostring(key)
              end
              return nil
          end

          local function rebuildVisibleItems(preferred)
              local visible, currentSection = {}, nil
              for _, candidate in ipairs(allItemList) do
                  if candidate.isHeader then
                      currentSection = sectionKey(candidate)
                      candidate.sectionKey = currentSection
                      visible[#visible + 1] = candidate
                  else
                      local key = candidate.rule and candidate.rule.key
                      local typeLockMode = math.max(0, math.min(6, math.floor(tonumber(getConfigValue("type_lock_mode", preGame)) or 0)))
                      local typeLockDraft = getConfigValue("type_lock_draft", preGame) == true
                      local typeSlotIndex = ({ type_lock_primary=1, type_lock_secondary=2, type_lock_tertiary=3, type_lock_quaternary=4, type_lock_quinary=5, type_lock_senary=6 })[key]
                      local hiddenByTypeLock = (key == "type_lock_draft" and typeLockMode == 0) or (typeSlotIndex ~= nil and (typeLockMode < typeSlotIndex or typeLockDraft))

                      -- 2.3.29 dependent randomizer selectors:
                      -- keep the saved child value, but hide the row entirely
                      -- while its owning randomizer is OFF. This applies to
                      -- both staged Setup values and the live in-game Rules UI.
                      local hiddenByNoCatching =
                          (key == "encounter_ball_limit"
                              and getConfigValue("no_catching", preGame) == true)

                      local hiddenByRandomizerParent =
                          ((key == "random_starter_style"
                                  or key == "random_starter_balance"
                                  or key == "random_starter_trio_typing"
                                  or key == "random_starter_rerolls")
                              and getConfigValue("random_starter", preGame) ~= true)
                          or ((key == "random_field_item_balance"
                                  or key == "random_field_item_repetition")
                              and getConfigValue("random_field_items", preGame) ~= true)
                          or (key == "random_evolution_balance"
                              and getConfigValue("random_evolutions", preGame) ~= true)
                          or (key == "random_shop_balance"
                              and getConfigValue("random_shops", preGame) ~= true)
                          or (key == "random_tm_compatibility"
                              and getConfigValue("random_tms", preGame) ~= true)
                          or ((key == "random_trainer_balance"
                              or key == "random_trainer_diversity"
                              or key == "random_trainer_theme")
                              and getConfigValue("random_trainers", preGame) ~= true)
                          or ((key == "random_encounter_balance"
                                  or key == "random_encounter_repetition"
                                  or key == "random_encounter_diversity_strength")
                              and getConfigValue("random_encounter_tables", preGame) ~= true)
                          or (key == "random_species_generation"
                              and getConfigValue("random_encounter_tables", preGame) ~= true
                              and getConfigValue("random_trainers", preGame) ~= true
                              and getConfigValue("random_evolutions", preGame) ~= true)
                          or (key == "random_encounter_diversity_strength"
                              and tonumber(getConfigValue(
                                  "random_encounter_repetition", preGame) or 0) ~= 1)
                          or (key == "randomizer_info_policy"
                              and getConfigValue("random_encounter_tables", preGame) ~= true
                              and getConfigValue("random_starter", preGame) ~= true
                              and getConfigValue("random_field_items", preGame) ~= true
                              and getConfigValue("random_learnsets", preGame) ~= true
                              and getConfigValue("random_trainers", preGame) ~= true
                              and getConfigValue("random_evolutions", preGame) ~= true
                              and getConfigValue("random_shops", preGame) ~= true
                              and getConfigValue("random_tms", preGame) ~= true
                              and getConfigValue("random_tm_locations", preGame) ~= true
                              and getConfigValue("random_gift_items", preGame) ~= true)
                          or (candidate.isStarterRerollControl
                              and (getConfigValue("random_starter", preGame) ~= true
                                  or getConfigValue("random_starter_rerolls", preGame) ~= true
                                  or (not preGame
                                      and type(mod.exports.__beta26.randomizerCanRerollStarter) == "function"
                                      and not mod.exports.__beta26.randomizerCanRerollStarter(
                                          nil, currentGame or mod.game))))
                          or ((key == "random_learnset_generation" or key == "random_learnset_stab")
                              and getConfigValue("random_learnsets", preGame) ~= true)

                      -- 2.6.34: a non-OFF No Status Moves parent already gives
                      -- its six true status-ban children the same scope. Use the
                      -- authoritative child list so UI hiding and parent
                      -- synchronization cannot drift apart. Accuracy/other stat
                      -- drops and Sleep Clause remain independent and visible.
                      local statusChild =
                          mod.exports.__beta26.isStatusMoveChildKey(key)
                      local hiddenByStatusParent = statusChild
                          and (tonumber(getConfigValue(
                              "status_move_scope", preGame)) or 0) ~= 0
                      local operational = true
                      if key and type(mod.exports.__beta26.ruleOperationalState) == "function" then
                          operational = mod.exports.__beta26.ruleOperationalState(
                              key, preGame, currentGame or mod.game)
                      end
                      local hiddenByOperationalContract = operational ~= true

                      if not hiddenByTypeLock and not hiddenByNoCatching
                          and not hiddenByRandomizerParent
                          and not hiddenByStatusParent
                          and not hiddenByOperationalContract
                          and (candidate.alwaysVisible
                              or currentSection == nil
                              or collapsedSections[currentSection] ~= true) then
                          visible[#visible + 1] = candidate
                      end
                  end
              end
              flatItemList = visible
              local target = 1
              if preferred then
                  for i, candidate in ipairs(flatItemList) do
                      if candidate == preferred then target = i break end
                  end
              end
              return target
          end

          local initialCursor = rebuildVisibleItems(nil)
          local initialScroll = 0
          local rememberedPosition = configSurfacePositions[collapseSurface]
          if type(rememberedPosition) == "table" then
              local wantedCursor = rememberedPosition.cursorKey
              local wantedTop = rememberedPosition.scrollKey
              if wantedCursor ~= nil then
                  for i, candidate in ipairs(flatItemList) do
                      if itemPositionKey(candidate) == wantedCursor then
                          initialCursor = i
                          break
                      end
                  end
              end
              if wantedTop ~= nil then
                  for i, candidate in ipairs(flatItemList) do
                      if itemPositionKey(candidate) == wantedTop then
                          initialScroll = i - 1
                          break
                      end
                  end
              end
              initialScroll = math.max(0, math.min(initialScroll,
                  math.max(0, #flatItemList - 1)))
          end

          local self = {
              game = game,
              screenId = "NuzlockeConfigScreen",
              isOpaque = true,
              preGame = preGame,
              goldMode = goldMode,
              autoNewGame = autoNewGame,
              onDone = ctx and ctx.onDone,
              cursor = initialCursor,
              scroll = initialScroll,
              -- 2.6.31: classic R/B/Y reclaims the old dedicated position
              -- strip for a fourth visible config row. Gen 2 keeps its native
              -- three-row geometry unchanged.
              pageSize = 3,
              descScroll = 0,
              marqueeTime = 0,
              editingNumber = false,
              digitIndex = 1,
              inGameSaveFlash = 0,
              rerollSeedFlash = 0,
              autoSeedFlash = 0,
              rerollStarterFlash = 0,
              lockConfirmStage = 0,
              lockConfirmReadyAt = 0
          }

          -- 2.7.56: Nuzlocke owns the semantic layout policy while a
          -- provider adapter resolves the active logical surface. R/B/Y Rules
          -- and Setup have a real 38-column composition, so they may use a
          -- wide host surface; Gen 2 retains its native Chrome presentation.
          mod.exports.__beta26.UiSystem.applyLayout(self, "adaptive")
          self.nuzlockeUi = mod.exports.nuzlocke_ui.describeScreen(self)
          self.presentationRole = "rules"
          self.presentationStateOwner = "nuzlocke"
          self.presentationNativeFallback = true

          local function rememberConfigPosition()
              local count = #flatItemList
              if count <= 0 then return end
              local cursor = math.max(1, math.min(count,
                  math.floor(tonumber(self.cursor) or 1)))
              local scroll = math.max(0, math.min(math.max(0, count - 1),
                  math.floor(tonumber(self.scroll) or 0)))
              configSurfacePositions[collapseSurface] = {
                  cursorKey = itemPositionKey(flatItemList[cursor]),
                  scrollKey = itemPositionKey(flatItemList[scroll + 1]),
              }
          end

          -- 2.7.31: one authoritative description text path for
          -- both input paging and rendering. Gold previously rendered four
          -- Chrome.wrap() lines but Select paging counted three generic
          -- wrapText() lines, so the visible arrow and actual scroll range
          -- could disagree.
          local function configDescriptionText(item)
              if type(item) ~= "table" or type(item.rule) ~= "table" then
                  return ""
              end
              local displayedDescription =
                  ruleDescriptionForDisplay(item.rule, self.preGame)
              if item.rule.key == "locke_type" then
                  local mode = math.max(0, math.min(6, math.floor(tonumber(
                      getConfigValue("locke_type", self.preGame)) or 0)))
                  if mode == 0 then
                      local summary = LockePreset.customSummary(self.preGame)
                      if summary then
                          displayedDescription = tostring(summary) .. ". "
                              .. tostring(displayedDescription or "")
                      end
                  end
              end
              if item.rule.key == "rules_locked"
                  and not mod.exports.__beta26.permanentRuleSealWip then
                  if self.lockConfirmStage == 1 then
                      displayedDescription = Strings(
                          "WARNING 1/2: Permanent Rule Seal cannot be undone. Select SEAL again to continue, or move away/B to cancel.")
                  elseif self.lockConfirmStage == 2 then
                      displayedDescription = Strings(
                          "FINAL WARNING 2/2: One more SEAL activation permanently locks challenge rules. Move away/B to cancel.")
                  end
              end
              return displayedDescription
          end

          local function configDescriptionScrollMetrics(item)
              local displayedDescription = configDescriptionText(item)
              if self.goldMode then
                  local Chrome = require("src.ui.gen2.Chrome")
                  local lines = Chrome.wrap(displayedDescription, 16)
                  return lines, math.max(0, #lines - 4)
              end
              local lines = wrapText(displayedDescription, 16)
              return lines, math.max(0, #lines - 3)
          end

          function self:update(dt)
              -- The title-screen setup has no active save.  Do not query or
              -- mutate save-backed map state while editing the staged setup.
              if not self.preGame then
                  local currentKey = areaKey(self.game, nil)
                  if currentKey then
                      markVisited(currentKey)
                  end
              end

              self.marqueeTime = self.marqueeTime + (dt or 0)
              if self.setupSaveFlash and self.setupSaveFlash > 0 then
                  self.setupSaveFlash = math.max(0, self.setupSaveFlash - (dt or 0))
              elseif self.setupSaveFlash and self.setupSaveFlash < 0 then
                  self.setupSaveFlash = math.min(0, self.setupSaveFlash + (dt or 0))
              end

              if self.inGameSaveFlash and self.inGameSaveFlash > 0 then
                  self.inGameSaveFlash = math.max(0, self.inGameSaveFlash - (dt or 0))
              elseif self.inGameSaveFlash and self.inGameSaveFlash < 0 then
                  self.inGameSaveFlash = math.min(0, self.inGameSaveFlash + (dt or 0))
              end

              if self.rerollSeedFlash and self.rerollSeedFlash > 0 then
                  self.rerollSeedFlash = math.max(0, self.rerollSeedFlash - (dt or 0))
              elseif self.rerollSeedFlash and self.rerollSeedFlash < 0 then
                  self.rerollSeedFlash = math.min(0, self.rerollSeedFlash + (dt or 0))
              end
              if self.autoSeedFlash and self.autoSeedFlash > 0 then
                  self.autoSeedFlash = math.max(0, self.autoSeedFlash - (dt or 0))
              elseif self.autoSeedFlash and self.autoSeedFlash < 0 then
                  self.autoSeedFlash = math.min(0, self.autoSeedFlash + (dt or 0))
              end
              if self.rerollStarterFlash and self.rerollStarterFlash > 0 then
                  self.rerollStarterFlash = math.max(0, self.rerollStarterFlash - (dt or 0))
              elseif self.rerollStarterFlash and self.rerollStarterFlash < 0 then
                  self.rerollStarterFlash = math.min(0, self.rerollStarterFlash + (dt or 0))
              end

              if self.game.input:wasPressed("b") then
                  self.lockConfirmStage = 0
                  self.lockConfirmReadyAt = 0
                  if self.editingNumber then
                      self.editingNumber = false
                      self.digitIndex = 1
                      self.descScroll = 0
                  else
                      rememberConfigPosition()
                      self.game.stack:pop()
                      if type(self.onDone) == "function" then
                          local cb = self.onDone
                          self.onDone = nil
                          cb(false)
                      end
                  end
                  return
              end

              -- Declare this before moveCursor so the closure captures the local
              -- helper instead of resolving a nonexistent global on UP/DOWN.
              local function isSelectableItem(item)
                  if not item then return false end
                  if item.isHeader then return true end
                  if item.rule and (item.rule.key == "wonderlocke"
                      or (item.rule.key == "rules_locked"
                          and mod.exports.__beta26.permanentRuleSealWip)) then
                      return false
                  end
                  return true
              end

              local function moveCursor(dir)
                  local count = #flatItemList
                  if count <= 0 then return end

                  local target = self.cursor
                  local guard = 0
                  repeat
                      target = target + dir
                      if target < 1 then
                          target = count
                      elseif target > count then
                          target = 1
                      end
                      guard = guard + 1
                      if guard > count then
                          return
                      end
                  until isSelectableItem(flatItemList[target])

                  if target ~= self.cursor then
                      self.lockConfirmStage = 0
                      self.lockConfirmReadyAt = 0
                  end
                  self.cursor = target
                  self.descScroll = 0
              end

              local function jumpSection(dir)
                  local count = #flatItemList
                  if count <= 0 then return false end
                  dir = tonumber(dir) or 1

                  local target = nil
                  if dir > 0 then
                      for i = self.cursor + 1, count do
                          if flatItemList[i] and flatItemList[i].isHeader then
                              target = i
                              break
                          end
                      end
                      if not target then
                          for i = 1, math.min(self.cursor, count) do
                              if flatItemList[i] and flatItemList[i].isHeader then
                                  target = i
                                  break
                              end
                          end
                      end
                  else
                      for i = self.cursor - 1, 1, -1 do
                          if flatItemList[i] and flatItemList[i].isHeader then
                              target = i
                              break
                          end
                      end
                      if not target then
                          for i = count, math.max(1, self.cursor), -1 do
                              if flatItemList[i] and flatItemList[i].isHeader then
                                  target = i
                                  break
                              end
                          end
                      end
                  end

                  if not target then return false end
                  if target ~= self.cursor then
                      self.lockConfirmStage = 0
                      self.lockConfirmReadyAt = 0
                  end
                  self.cursor = target
                  self.descScroll = 0
                  self.editingNumber = false
                  return true
              end

              local function setAllSectionsCollapsed(value)
                  value = value == true
                  local preferred = flatItemList[self.cursor]
                  local seen = {}
                  for _, candidate in ipairs(allItemList) do
                      if candidate and candidate.isHeader then
                          local key = candidate.sectionKey or sectionKey(candidate)
                          if not seen[key] then
                              seen[key] = true
                              collapsedSections[key] = value
                          end
                      end
                  end
                  self.cursor = rebuildVisibleItems(preferred)
                  self.scroll = math.max(0,
                      math.min(self.scroll, math.max(0, #flatItemList - 1)))
                  self.descScroll = 0
                  self.editingNumber = false
                  self.lockConfirmStage = 0
                  self.lockConfirmReadyAt = 0
                  return true
              end

              local function selectedItem()
                  return flatItemList[self.cursor]
              end

              local function refreshDependentRows(changedKey, preferred)
                  -- 2.8.02: every parent used by rebuildVisibleItems must
                  -- invalidate the visible-row projection immediately. 2.8.01
                  -- restored the Gen II Trainer Randomizer rows to the catalog
                  -- allowlist, but changing Random Trainers did not rebuild the
                  -- already-open Setup/Rules list, so Balance/Diversity/Theme
                  -- stayed hidden until the screen was reconstructed. Keep this
                  -- trigger set aligned with hiddenByRandomizerParent above.
                  if changedKey ~= "random_starter"
                      and changedKey ~= "random_starter_rerolls"
                      and changedKey ~= "random_encounter_tables"
                      and changedKey ~= "random_encounter_repetition"
                      and changedKey ~= "random_field_items"
                      and changedKey ~= "random_learnsets"
                      and changedKey ~= "random_trainers"
                      and changedKey ~= "random_evolutions"
                      and changedKey ~= "random_shops"
                      and changedKey ~= "random_tms"
                      and changedKey ~= "random_tm_locations"
                      and changedKey ~= "random_gift_items"
                      and changedKey ~= "type_lock_mode"
                      and changedKey ~= "type_lock_draft"
                      and changedKey ~= "no_catching"
                      and changedKey ~= "status_move_scope" then
                      return
                  end
                  self.cursor = rebuildVisibleItems(preferred)
                  self.scroll = math.max(0,
                      math.min(self.scroll, math.max(0, #flatItemList - 1)))
                  self.descScroll = 0
              end

              local function setHeaderCollapsed(item, value)
                  if not (item and item.isHeader) then return false end
                  local key = item.sectionKey or sectionKey(item)
                  if value == nil then value = collapsedSections[key] ~= true end
                  collapsedSections[key] = value == true
                  self.cursor = rebuildVisibleItems(item)
                  self.scroll = math.max(0,
                      math.min(self.scroll, math.max(0, #flatItemList - 1)))
                  self.descScroll = 0
                  self.editingNumber = false
                  self.lockConfirmStage = 0
                  self.lockConfirmReadyAt = 0
                  return true
              end

              local function activateControl(item, delta)
                  if not item or not item.isControl then return false end
                  if item.rule and item.rule.key == "rules_locked"
                      and mod.exports.__beta26.permanentRuleSealWip then
                      -- DORMANT/WIP: preserve the full activation block below,
                      -- but never enter it while the feature is disabled.
                      self.lockConfirmStage = 0
                      self.lockConfirmReadyAt = 0
                      return false
                  end
                  local isPermanentSeal = item.rule
                      and item.rule.key == "rules_locked"
                  if not isPermanentSeal then
                      self.lockConfirmStage = 0
                      self.lockConfirmReadyAt = 0
                  end
                  if item.isStartNewGameControl then
                      saveCurrentSetupProfile()
                      stageNewGameProfile()
                      rememberConfigPosition()
                      self.game.stack:pop()
                      if type(self.onDone) == "function" then
                          local cb = self.onDone
                          self.onDone = nil
                          cb(true)
                      end
                      return true
                  end
                  if item.isRunSettingsLockControl then
                      if self.preGame then
                          setConfigValue("run_settings_lock",
                              not getConfigValue("run_settings_lock", true), true)
                      end
                      return true
                  end
                  if item.isLockeTypeControl then
                      if mod.exports.__beta26.configRulesLocked(self.preGame) then return true end
                      local current=tonumber(getConfigValue("locke_type",self.preGame)) or 0
                      mod.ui.push(self.game,"NuzlockeLoadoutChooser",{
                          currentMode=current, preGame=self.preGame,
                          onChoose=function(chosen)
                              if chosen==0 then LockePreset.apply(0,self.preGame); self.descScroll=0; return end
                              local changes=LockePreset.preview(chosen,self.preGame)
                              if #changes==0 then LockePreset.apply(chosen,self.preGame); self.descScroll=0; return end
                              mod.ui.push(self.game,"NuzlockeLoadoutConfirm",{mode=chosen,changes=changes,onChoice=function(yes) if yes then LockePreset.apply(chosen,self.preGame); self.descScroll=0 end end})
                          end,
                      })
                      return true
                  end
                  if item.isManualClockControl then
                      mod.ui.push(self.game, "NuzlockeManualClock", {})
                      self.descScroll = 0
                      return true
                  end
                  if item.isPkmnBanControl then
                      if mod.exports.__beta26.configRulesLocked(self.preGame) then
                          return true
                      end
                      mod.ui.push(self.game, "NuzlockePokemonBanScreen", {
                          preGame = self.preGame,
                      })
                      self.descScroll = 0
                      return true
                  end
                  if item.isStarterRerollControl then
                      if mod.exports.__beta26.configRulesLocked(self.preGame) then
                          return false
                      end
                      if self.preGame and not pendingNewGameRules then
                          pendingNewGameRules = loadSetupProfileFromDisk()
                              or makeDefaultPreGameRules()
                      end
                      local reroll = mod.exports.__beta26.randomizerRerollStarter
                      local index = type(reroll) == "function"
                          and reroll(self.preGame and pendingNewGameRules or nil,
                              self.game) or nil
                      if tonumber(index) and tonumber(index) > 0 then
                          if self.preGame then pendingRulesDirty = true end
                          self.rerollStarterFlash = 1.5
                      else
                          self.rerollStarterFlash = -1.5
                      end
                      self.descScroll = 0
                      return true
                  end
                  if item.isRandomizerRerollControl then
                      if mod.exports.__beta26.configRulesLocked(self.preGame) then
                          return false
                      end
                      if self.preGame and not pendingNewGameRules then
                          pendingNewGameRules = loadSetupProfileFromDisk()
                              or makeDefaultPreGameRules()
                      end
                      local reroll = mod.exports.__beta26.randomizerRerollSeed
                      if type(reroll) == "function" then
                          local seed = reroll(self.preGame and pendingNewGameRules or nil)
                          if tonumber(seed) and tonumber(seed) > 0 then
                              if self.preGame then
                                  pendingRulesDirty = true
                              elseif mod.exports.__beta26.Randomizer then
                                  pcall(mod.exports.__beta26.Randomizer.applyAll, self.game)
                              end
                              self.rerollSeedFlash = 1.5
                          else
                              self.rerollSeedFlash = -1.5
                          end
                      else
                          self.rerollSeedFlash = -1.5
                      end
                      self.descScroll = 0
                      return true
                  end
                  if item.isRandomizerAutoSeedControl then
                      if mod.exports.__beta26.configRulesLocked(self.preGame) then
                          return false
                      end
                      if self.preGame then
                          if not pendingNewGameRules then
                              pendingNewGameRules = loadSetupProfileFromDisk()
                                  or makeDefaultPreGameRules()
                          end
                          pendingNewGameRules.randomizer_seed = 0
                          pendingNewGameRules.random_starter_reroll_index = 0
                          pendingNewGameRules.__randomizer_legacy = nil
                          pendingRulesDirty = true
                      else
                          mod.save:set("randomizer_seed", 0)
                          mod.save:set("__nuzlocke_random_starter_reroll_index", 0)
                          if type(mod.exports.__beta26.resetRandomizerRunSeed) == "function" then
                              mod.exports.__beta26.resetRandomizerRunSeed()
                          end
                          if mod.exports.__beta26.Randomizer then
                              pcall(mod.exports.__beta26.Randomizer.applyAll, self.game)
                          end
                      end
                      self.autoSeedFlash = 1.5
                      self.descScroll = 0
                      return true
                  end
                  local function cycleSetupPresetTarget(step)
                      step = tonumber(step) or 1
                      if step == 0 then step = 1 end
                      local dir = step < 0 and -1 or 1
                      selectedSetupPresetSlot =
                          (selectedSetupPresetSlot + dir) % (SETUP_PRESET_SLOTS + 1)
                      self.setupPresetFlash = nil
                      self.descScroll = 0
                      return true
                  end
                  if item.isSetupPresetSlot then
                      return cycleSetupPresetTarget(delta)
                  end
                  if item.isSetupPresetSave then
                      -- 2.7.103: Save/Load are actions, not duplicate slot selectors.
                      -- LEFT/RIGHT are consumed here so they cannot accidentally
                      -- mutate the shared Profile Slot while this action row is focused.
                      if delta ~= nil then return true end
                      if selectedSetupPresetSlot <= 0 then
                          self.setupPresetFlash = nil
                          self.descScroll = 0
                          return true
                      end
                      local profile = copyRuleProfile(self.preGame
                          and (pendingNewGameRules or makeDefaultPreGameRules())
                          or makeRulesFromCurrentSave())
                      local ok = H.saveSetupPreset(selectedSetupPresetSlot, profile)
                      self.setupPresetFlash = ok and 1.5 or -1.5
                      return true
                  end
                  if item.isSetupPresetLoad then
                      if delta ~= nil then return true end
                      if selectedSetupPresetSlot <= 0 then
                          self.setupPresetFlash = nil
                          self.descScroll = 0
                          return true
                      end
                      local profile, changes = H.setupPresetPreview(
                          selectedSetupPresetSlot,
                          self.preGame and (pendingNewGameRules or makeDefaultPreGameRules())
                              or makeRulesFromCurrentSave())
                      if not profile then
                          self.setupPresetFlash = -1.5
                          return true
                      end
                      if #changes == 0 then
                          pendingNewGameRules = copyRuleProfile(profile)
                          if not self.preGame then H.saveCurrentInGameRules() end
                          self.setupPresetFlash = 1.5
                          return true
                      end
                      mod.ui.push(self.game, "NuzlockeLoadoutConfirm", {
                          mode = 0,
                          changes = changes,
                          onChoice = function(yes)
                              if yes then
                                  pendingNewGameRules = copyRuleProfile(profile)
                                  pendingRulesDirty = true
                                  if not self.preGame then
                                      H.saveCurrentInGameRules()
                                  end
                                  self.setupPresetFlash = 1.5
                              end
                          end,
                      })
                      return true
                  end
                  if item.isSetupSave and self.preGame then
                      local ok = saveCurrentSetupProfile()
                      self.setupSaveFlash = ok and 1.5 or -1.5
                      return true
                  end
                  if item.isInGameSave and not self.preGame then
                      local ok = H.saveCurrentInGameRules()
                      self.inGameSaveFlash = ok and 1.5 or -1.5
                      return true
                  end
                  if item.isRecoveryControl then
                      -- 2.7.101: Encounter Assignment is a TOOLS action in
                      -- both Setup and the live rule list.
                      mod.ui.push(self.game, "NuzlockeLegacyRecoveryScreen")
                      return true
                  end
                  if item.isRuleLockControl and item.rule
                      and item.rule.key == "rule_lock" then
                      setConfigValue("rule_lock",
                          not getConfigValue("rule_lock", self.preGame), self.preGame)
                      self.descScroll = 0
                      return true
                  end
                  if item.rule and item.rule.key == "rules_locked" then
                      local cur = getConfigValue("rules_locked", self.preGame)
                      if cur then return true end

                      -- Two explicit warnings are required before the third,
                      -- deliberate activation permanently seals challenge rules.
                      -- A short debounce prevents one keyboard/gamepad press from
                      -- accidentally advancing more than one stage.
                      if (self.marqueeTime or 0) < (self.lockConfirmReadyAt or 0) then
                          return true
                      end

                      if self.lockConfirmStage == 0 then
                          self.lockConfirmStage = 1
                          self.lockConfirmReadyAt = (self.marqueeTime or 0) + 0.35
                          if not self.preGame then
                              pcall(mod.exports.__beta26.pushWorldText, self.game,
                                  "PERMANENT RULE SEAL - WARNING 1/2\nThis cannot be undone on this save.\nSelect SEAL again only if you want to continue.")
                          end
                          self.descScroll = 0
                          return true
                      end

                      if self.lockConfirmStage == 1 then
                          self.lockConfirmStage = 2
                          self.lockConfirmReadyAt = (self.marqueeTime or 0) + 0.35
                          if not self.preGame then
                              pcall(mod.exports.__beta26.pushWorldText, self.game,
                                  "PERMANENT RULE SEAL - FINAL WARNING 2/2\nChallenge rules will be permanently locked.\nSelect SEAL one final time to seal them.")
                          end
                          self.descScroll = 0
                          return true
                      end

                      setConfigValue("rules_locked", true, self.preGame)
                      self.lockConfirmStage = 0
                      self.lockConfirmReadyAt = 0
                      if not self.preGame then
                          local ok = mod.exports.__beta26.persistPermanentRuleSeal(
                              self.game)
                          if ok ~= true then
                              -- mod.save still locks the current session; the
                              -- lifecycle retry below will mirror it once a
                              -- playthrough storage context becomes available.
                              mod.save:set("rules_permanently_locked", true)
                          end
                      end
                      return true
                  end
                  return false
              end

              local function canChangeSelected(item)
                  if not item or item.isHeader then
                      return false
                  end
                  if item.isStartNewGameControl then return true end
                  if item.isRunSettingsLockControl then return self.preGame end
                  if not self.preGame and mod.save:get("run_settings_lock", false) == true then
                      return false
                  end

                  -- Save/recovery controls remain usable while locked. Reroll Seed
                  -- changes challenge configuration, so it obeys the same permanent
                  -- seal as the numeric seed row rather than bypassing it as a utility.
                  if item.isRandomizerRerollControl or item.isRandomizerAutoSeedControl then
                      return not mod.exports.__beta26.configRulesLocked(self.preGame)
                  end
                  -- The permanent lock itself is monotonic: once true it cannot be
                  -- toggled off; save/recovery controls remain available.
                  if item.isControl and (item.isInGameSave or item.isSetupSave
                      or item.isSetupPresetSlot or item.isSetupPresetSave
                      or item.isSetupPresetLoad or item.isRecoveryControl) then
                      return true
                  end
                  if item.isRuleLockControl and item.rule.key == "rule_lock" then
                      return true
                  end
                  if item.isControl and item.rule.key == "rules_locked" then
                      if mod.exports.__beta26.permanentRuleSealWip then
                          return false
                      end
                      return not mod.exports.__beta26.configRulesLocked(self.preGame)
                  end
                  if item.isLockeTypeControl then
                      return not mod.exports.__beta26.configRulesLocked(self.preGame)
                  end

                  if item.rule and item.rule.key == "wonderlocke" then
                      return false
                  end
                  if item.rule and externalRuleDelegation
                      and externalRuleDelegation(item.rule.key, self.game) then
                      return false
                  end
                  if item.rule and (item.rule.key == "world_building_tier"
                      or item.rule.key == "gold_radio_world_building"
                      or item.rule.key == "difficulty_profile"
                      or item.rule.key == "run_surf"
                      or item.rule.key == "unlimited_bag_space"
                      or item.rule.key == "trade_evolutions"
                      or item.rule.key == "automatic_default_names"
                      or item.rule.key == "skip_opening_intro"
                      or item.rule.key == "quick_nuzlocke_start"
                      or item.rule.key == "skip_catch_tutorial"
                      or item.rule.key == "pc_starting_vitamins"
                      or item.rule.key == "pc_starting_heal_items"
                      or item.rule.key == "infinite_rare_candies"
                      or item.rule.key == "starting_money"
                      or item.rule.key == "starting_pokeballs"
                      or item.rule.key == "starting_rare_candies"
                      or item.rule.key == "gold_starting_money"
                      or item.rule.key == "gold_starting_pokeballs"
                      or item.rule.key == "gold_starting_rare_candies"
                      or item.rule.key == "skip_cherrygrove_tour"
                      or item.rule.key == "catch_info"
                      or item.rule.key == "stat_info"
                      or item.rule.key == "move_info"
                      or item.rule.key == "area_guide_enabled"
                      or item.rule.key == "battle_menu_ui"
                      or item.rule.key == "dev_mode") then
                      -- Permanent Rule Seal applies only to challenge rules.
                      -- Difficulty, World Building, QoL and presentation remain
                      -- independently adjustable after a seal.
                      return true
                  end
                  return not mod.exports.__beta26.configRulesLocked(self.preGame)
              end

              local function sectionResetPreview(header)
                  if not (header and header.isHeader) then return {}, nil end
                  local section = header.sectionKey or sectionKey(header)
                  local changes, collecting = {}, false
                  local mode = math.max(0, math.min(6, math.floor(tonumber(
                      getConfigValue("locke_type", self.preGame)) or 0)))
                  local preset = mode > 0 and LockePreset.presets[mode] or nil
                  for _, candidate in ipairs(allItemList) do
                      if candidate.isHeader then
                          local key = candidate.sectionKey or sectionKey(candidate)
                          if collecting then break end
                          if key == section then collecting = true end
                      elseif collecting and candidate.rule
                          and canChangeSelected(candidate) then
                          local key = candidate.rule.key
                          local wanted = preset and preset[key]
                          if wanted == nil then wanted = defaultRuleValue(key) end
                          local actual = getConfigValue(key, self.preGame)
                          local differs = mod.exports.__beta26.configValuesDiffer(
                              actual, wanted)
                          if differs then
                              changes[#changes + 1] = {
                                  key = key,
                                  name = mod.exports.__beta26.lockeRuleDisplayName(key),
                                  from = mod.exports.__beta26.lockeRuleValueLabel(key, actual),
                                  to = mod.exports.__beta26.lockeRuleValueLabel(key, wanted),
                                  value = wanted,
                              }
                          end
                      end
                  end
                  return changes, section
              end

              local function promptSectionReset(header)
                  local changes, section = sectionResetPreview(header)
                  if #changes == 0 then
                      self.descScroll = 0
                      return true
                  end
                  mod.ui.push(self.game, "NuzlockeLoadoutConfirm", {
                      title = "RESET SECTION?",
                      name = tostring(Strings(section or "SECTION")),
                      changes = changes,
                      onChoice = function(yes)
                          if not yes then return end
                          LockePreset.applying = true
                          for _, change in ipairs(changes) do
                              setConfigValue(change.key, change.value, self.preGame)
                          end
                          LockePreset.applying = false
                          local classified = LockePreset.classify(self.preGame)
                          setConfigValue("locke_type", classified, self.preGame)
                          self.cursor = rebuildVisibleItems(header)
                          self.scroll = math.max(0,
                              math.min(self.scroll, math.max(0, #flatItemList - 1)))
                          self.descScroll = 0
                      end,
                  })
                  return true
              end

              local function isStartingResourceRule(rule)
                  if not rule then return false end
                  return rule.key == "starting_money"
                      or rule.key == "starting_pokeballs"
                      or rule.key == "starting_rare_candies"
                      or rule.key == "gold_starting_money"
                      or rule.key == "gold_starting_pokeballs"
                      or rule.key == "gold_starting_rare_candies"
                      or rule.key == "randomizer_seed"
              end

              local function cycleNumericRule(rule, dir)
                  if not rule then return false end
                  if rule.key == "difficulty_profile" then
                      local options = mod.exports.__beta26.difficultyOptions()
                      local count = #options
                      if count <= 0 then return false end
                      local currentId = self.preGame
                          and pendingNewGameRules.difficulty_provider_id
                          or mod.save:get("difficulty_provider_id", "vanilla")
                      local _, currentIndex = difficultyOptionById(options, currentId)
                      local index = tonumber(currentIndex) or 0
                      local row = options[index + 1] or options[1]
                      local nextId = row and row.id or "vanilla"

                      local function applyDifficultyChange()
                          setConfigValue(rule.key, index, self.preGame)
                          if self.preGame then
                              pendingNewGameRules.difficulty_provider_id = nextId
                          else
                              mod.save:set("difficulty_provider_id", nextId)
                              -- Difficulty is explicitly changeable mid-game.
                              -- Observed trainer ace levels belong to the previous
                              -- composition and must not pin NEXT CAP after a change.
                              if mod.exports.__beta26.levelCapBosses then
                                  mod.exports.__beta26.levelCapBosses.observed = {}
                              end
                          end
                          self.descScroll = 0
                      end

                      local function afterReview(selectedRow)
                          if not selectedRow then return end
                          row = selectedRow
                          nextId = tostring(selectedRow.id or "vanilla")
                          local _, selectedIndex = difficultyOptionById(options, nextId)
                          index = tonumber(selectedIndex) or 0
                          local impactFn = mod.exports.__beta26.difficultyImpactChanges
                          local changes = type(impactFn) == "function"
                              and impactFn(currentId, nextId) or {}
                          local stackFn = mod.exports.__beta26.difficultyStackWarning
                          local stackWarning = type(stackFn) == "function"
                              and stackFn(nextId) or nil
                          if #changes > 0 or (type(stackWarning)=="string" and stackWarning~="") then
                              mod.ui.push(self.game, "NuzlockeLoadoutConfirm", {
                                  title = stackWarning and "DIFFICULTY STACK" or "DIFFICULTY WARNING",
                                  name = tostring(Strings(row and row.name or nextId)),
                                  message = stackWarning,
                                  changes = changes,
                                  onChoice = function(yes)
                                      if yes then applyDifficultyChange() end
                                  end,
                              })
                          else
                              applyDifficultyChange()
                          end
                      end
                      mod.ui.push(self.game, "NuzlockeDifficultyReview", {
                          currentId = currentId,
                          proposedId = nextId,
                          onConfirm = afterReview,
                      })
                      return true
                  end
                  if rule.key == "maximum_bst" then
                      local current = tonumber(getConfigValue(
                          rule.key, self.preGame)) or 0
                      local index = mod.exports.__beta26.maximumBstPresetIndex(
                          current)
                      local count = mod.exports.__beta26.maximumBstPresetMaxIndex + 1
                      index = mod.exports.__beta26.cycleIntegerRange(
                          index, 0, count - 1, dir)
                      setConfigValue(rule.key,
                          mod.exports.__beta26.maximumBstPresetValues[index],
                          self.preGame)
                      self.descScroll = 0
                      return true
                  end
                  local minValue = tonumber(rule.min) or 0
                  local maxValue = tonumber(rule.max) or minValue
                  local current = tonumber(getConfigValue(rule.key, self.preGame)) or minValue
                  local nextValue = mod.exports.__beta26.cycleIntegerRange(
                      current, minValue, maxValue, dir)
                  setConfigValue(rule.key, nextValue, self.preGame)
                  if rule.key == "type_lock_mode" or rule.key == "type_lock_draft"
                      or rule.key == "status_move_scope" then
                      refreshDependentRows(rule.key, selectedItem())
                  end
                  self.descScroll = 0
                  return true
              end

              -- 2.8.00: held list navigation keeps five progressive speed gates but
              -- ramps a little more slowly and tops out a little slower than 2.7.106.
              -- A tap remains one movement; SELECT retains section-jump priority;
              -- numeric digit-edit mode remains edge-only.
              local function repeatedListDirection()
                  local input = self.game.input
                  if type(input) ~= "table" then return nil end
                  local downPressed = input:wasPressed("down")
                  local upPressed = input:wasPressed("up")
                  local edge = downPressed and 1 or (upPressed and -1 or nil)
                  local downHeld = type(input.isDown) == "function"
                      and input:isDown("down") or false
                  local upHeld = type(input.isDown) == "function"
                      and input:isDown("up") or false
                  local held
                  if downHeld ~= upHeld then held = downHeld and 1 or -1 end
                  local elapsed = math.max(0, tonumber(dt) or 0)

                  local function reset(direction)
                      self.__nuzListHoldDir2800 = direction
                      self.__nuzListHoldAge2800 = 0
                      self.__nuzListHoldTimer2800 = 0.48
                  end

                  if edge then
                      reset(edge)
                      return edge
                  end
                  if held == nil then
                      self.__nuzListHoldDir2800 = nil
                      self.__nuzListHoldAge2800 = nil
                      self.__nuzListHoldTimer2800 = nil
                      return nil
                  end
                  if self.__nuzListHoldDir2800 ~= held then
                      reset(held)
                      return nil
                  end

                  local age = (tonumber(self.__nuzListHoldAge2800) or 0) + elapsed
                  self.__nuzListHoldAge2800 = age
                  local interval
                  if age < 1.10 then interval = 0.27       -- gate 1
                  elseif age < 2.00 then interval = 0.23  -- gate 2
                  elseif age < 3.10 then interval = 0.19  -- gate 3
                  elseif age < 4.40 then interval = 0.15  -- gate 4
                  else interval = 0.11 end                -- gate 5

                  local timer = (tonumber(self.__nuzListHoldTimer2800) or 0.48)
                      - elapsed
                  if timer <= 0 then
                      self.__nuzListHoldTimer2800 = interval
                      return held
                  end
                  self.__nuzListHoldTimer2800 = timer
                  return nil
              end

              local item = selectedItem()
              local editingAtStart = self.editingNumber
              local listDirection = nil
              if not self.editingNumber then
                  listDirection = repeatedListDirection()
              else
                  self.__nuzListHoldDir2800 = nil
                  self.__nuzListHoldAge2800 = nil
                  self.__nuzListHoldTimer2800 = nil
              end

              if self.editingNumber and item and item.rule.numeric
                  and isStartingResourceRule(item.rule) then
                  local rule = item.rule
                  local value = tonumber(getConfigValue(rule.key, self.preGame)) or rule.min
                  local digits = rule.digits or 1
                  local text = ("%0" .. tostring(digits) .. "d"):format(value)

                  if self.game.input:wasPressed("left") then
                      self.digitIndex = math.max(1, self.digitIndex - 1)
                  elseif self.game.input:wasPressed("right") then
                      self.digitIndex = math.min(digits, self.digitIndex + 1)
                  elseif self.game.input:wasPressed("up") or self.game.input:wasPressed("down") then
                      local step = self.game.input:wasPressed("up") and 1 or -1
                      local chars = {}
                      for i = 1, #text do chars[i] = tonumber(text:sub(i, i)) or 0 end
                      chars[self.digitIndex] = (chars[self.digitIndex] + step) % 10
                      local newValue = tonumber(table.concat(chars)) or 0
                      if newValue >= rule.min and newValue <= rule.max then
                          setConfigValue(rule.key, newValue, self.preGame)
                      end
                  elseif self.game.input:wasPressed("a") or self.game.input:wasPressed("select") then
                      if rule.key == "randomizer_seed" and mod.exports.__beta26.randomizerSeed then
                          local anyRandomizer = getConfigValue("random_starter", self.preGame) == true
                              or getConfigValue("random_encounter_tables", self.preGame) == true
                              or getConfigValue("random_field_items", self.preGame) == true
                              or getConfigValue("random_learnsets", self.preGame) == true
                          if anyRandomizer and not self.preGame then
                              mod.exports.__beta26.randomizerSeed(nil, true)
                              if mod.exports.__beta26.Randomizer then
                                  pcall(mod.exports.__beta26.Randomizer.applyAll, self.game)
                              end
                          end
                      end
                      self.editingNumber = false
                      self.digitIndex = 1
                      self.descScroll = 0
                  end

              elseif listDirection == 1 then
                  local selectHeld = type(self.game.input.isDown) == "function"
                      and self.game.input:isDown("select")
                  if selectHeld then
                      jumpSection(1)
                  else
                      moveCursor(1)
                  end
              elseif listDirection == -1 then
                  local selectHeld = type(self.game.input.isDown) == "function"
                      and self.game.input:isDown("select")
                  if selectHeld then
                      jumpSection(-1)
                  else
                      moveCursor(-1)
                  end
              elseif self.game.input:wasPressed("right") or self.game.input:wasPressed("left") then
                  local selectHeld = type(self.game.input.isDown) == "function"
                      and self.game.input:isDown("select")
                  if item and item.isHeader and selectHeld then
                      setAllSectionsCollapsed(
                          self.game.input:wasPressed("left"))
                  elseif item and item.isHeader then
                      setHeaderCollapsed(item,
                          self.game.input:wasPressed("left"))
                  elseif item and item.isLockeTypeControl and canChangeSelected(item) then
                      activateControl(item,
                          self.game.input:wasPressed("right") and 1 or -1)
                  elseif item and item.rule and item.rule.key ~= "wonderlocke"
                      and item.rule.numeric and canChangeSelected(item) then
                      if isStartingResourceRule(item.rule) then
                          self.editingNumber = true
                          self.digitIndex = 1
                          self.descScroll = 0
                      else
                          cycleNumericRule(item.rule,
                              self.game.input:wasPressed("right") and 1 or -1)
                      end
                  elseif item and item.isControl then
                      activateControl(item,
                          self.game.input:wasPressed("right") and 1 or -1)
                  elseif canChangeSelected(item) then
                      local key = item.rule.key
                      local preferred = item
                      local cur = getConfigValue(key, self.preGame)
                      setConfigValue(key, not cur, self.preGame)
                      refreshDependentRows(key, preferred)
                  end
              elseif self.game.input:wasPressed("select") then
                  if item and item.isHeader then
                      promptSectionReset(item)
                  elseif item and not item.isHeader then
                      local _, maxScroll =
                          configDescriptionScrollMetrics(item)
                      if maxScroll > 0 then
                          self.descScroll =
                              (self.descScroll + 1) % (maxScroll + 1)
                      end
                  end
              end

              if self.game.input:wasPressed("a") and not editingAtStart then
                  if item and item.isHeader then
                      setHeaderCollapsed(item)
                  elseif item and item.isLockeTypeControl then
                      if canChangeSelected(item) then activateControl(item, 1) end
                  elseif item and item.isControl then
                      activateControl(item)
                  elseif item and item.rule and item.rule.key ~= "wonderlocke"
                      and item.rule.numeric and canChangeSelected(item) then
                      if isStartingResourceRule(item.rule) then
                          self.editingNumber = true
                          self.digitIndex = 1
                          self.descScroll = 0
                      else
                          cycleNumericRule(item.rule, 1)
                      end
                  elseif canChangeSelected(item) then
                      local key = item.rule.key
                      local preferred = item
                      local cur = getConfigValue(key, self.preGame)
                      setConfigValue(key, not cur, self.preGame)
                      refreshDependentRows(key, preferred)
                  end
              end
          end

          function self:draw()
              -- Gold owns a different menu language from R/B/Y. In particular,
              -- src.ui.OptionRows is explicitly not a Gen2 compatibility facade:
              -- painting the Gen 1 option chrome over Gold is an upstream-documented
              -- trap. Keep all configuration state/update logic shared, but draw the
              -- Gold surface with src.ui.gen2.Chrome's native tile boxes, cursor and
              -- down-arrow. This is presentation-only and does not change rule
              -- semantics, save keys, presets, or the protected R/B/Y screen.
              if self.goldMode then
                  local Chrome = require("src.ui.gen2.Chrome")
                  local GoldFont = require("src.render.Font")
                  Chrome.clear()
                  Chrome.box(0, 0, 20, 11)
                  Chrome.box(0, 11, 20, 7)

                  local locked = mod.exports.__beta26.configRulesLocked(self.preGame)
                  local edition = mod.exports.__beta26.Dev.gameLabel(self.game)
                  local uiView = mod.exports.__beta26.UiSystem.view(
                      self.preGame and "SETUP" or "RULES", self.game, {
                          edition = edition,
                          mode = self.preGame and "NEW RUN" or "LIVE",
                          state = locked and "LOCKED" or nil,
                      })
                  mod.exports.__beta26.UiSystem.gen2Header(Chrome, GoldFont, uiView)

                  -- 2.7.92: normal Setup/Rules content uses one consistent
                  -- black treatment. The bold title remains the emphasized
                  -- chrome element; only WIP/delegated rows may dim.
                  love.graphics.setColor(0, 0, 0, 1)

                  if self.cursor > self.scroll + self.pageSize then
                      self.scroll = self.cursor - self.pageSize
                  end
                  if self.cursor <= self.scroll then
                      self.scroll = math.max(0, self.cursor - 1)
                  end

                  local function clipped(text, width)
                      return marqueeText(Strings(tostring(text or "")), width,
                          self.marqueeTime, 3.8)
                  end

                  -- 2.4.28: Gold now follows the same compact-label policy as
                  -- R/B/Y. Prefer the full translated label whenever it fits.
                  -- If it does not fit, use shortName/shortTitle only when the
                  -- shorthand is safe for the active translation; otherwise
                  -- keep the translated full label and let the native Gold
                  -- marquee expose it instead of injecting an English
                  -- abbreviation into a translated menu.
                  local function goldMenuLabel(fullSource, shortSource, width)
                      local fullRaw = tostring(fullSource or "")
                      local fullText = Strings(fullRaw)
                      width = math.max(1, math.floor(tonumber(width) or 1))
                      local pixelBudget = width * 8
                      local fullFits = type(GoldFont.width) ~= "function"
                          and #fullText <= width or GoldFont.width(fullText) <= pixelBudget
                      if fullFits then return fullText end

                      if shortSource ~= nil then
                          local shortRaw = tostring(shortSource)
                          local shortText = Strings(shortRaw)
                          local fullWasTranslated = tostring(fullText) ~= fullRaw
                          local shortWasTranslated = tostring(shortText) ~= shortRaw
                          if not fullWasTranslated or shortWasTranslated then
                              local shortFits = type(GoldFont.width) ~= "function"
                                  and #shortText <= width or GoldFont.width(shortText) <= pixelBudget
                              if shortFits then return shortText end
                              return marqueeText(shortText, width, self.marqueeTime, 3.8)
                          end
                      end

                      return marqueeText(fullText, width, self.marqueeTime, 3.8)
                  end

                  -- 2.7.91: the edition/run subtitle is gone, so move the
                  -- three rule rows upward and put the pager in the bottom-center
                  -- of the list panel. This keeps navigation visually grouped
                  -- without consuming the reclaimed header space.
                  do
                      local total = #flatItemList
                      local current = total > 0
                          and math.max(1, math.min(tonumber(self.cursor) or 1, total))
                          or 0
                      local position = ("%d/%d"):format(current, total)
                      local positionWidth = type(GoldFont.width) == "function"
                          and GoldFont.width(position) or (#position * 8)
                      local gap = 4
                      local arrowWidth = 8
                      local clusterWidth = arrowWidth + gap + positionWidth
                          + gap + arrowWidth
                      local clusterX = math.max(8,
                          math.floor((160 - clusterWidth) / 2))
                      local navY = 9 * 8
                      local positionX = clusterX + arrowWidth + gap
                      local downX = positionX + positionWidth + gap
                      GoldFont.draw(position, positionX, navY)
                      local canScrollUp = (self.scroll or 0) > 0
                      local canScrollDown = (self.scroll or 0) + self.pageSize < total
                      if canScrollUp then
                          GoldFont.drawCode(0x61, clusterX, navY)
                      end
                      if canScrollDown then
                          GoldFont.drawCode(Chrome.DOWN_ARROW, downX, navY)
                      end
                  end

                  local function goldValueText(item, val)
                      if item.isLockeTypeControl then
                          local mode = math.max(0, math.min(6,
                              math.floor(tonumber(val) or 0)))
                          return LockePreset.displayLabel(mode, preGame)
                      elseif item.isManualClockControl then
                          local okClock, Clock = pcall(require, "src.core.gen2.Clock")
                          local save = self.game and self.game.save
                          local hour = okClock and type(Clock.hour)=="function"
                              and Clock.hour(save) or nil
                          local minute = okClock and type(Clock.minute)=="function"
                              and Clock.minute(save) or nil
                          if hour ~= nil then
                              return string.format("%02d:%02d",
                                  math.floor(tonumber(hour) or 0) % 24,
                                  math.floor(tonumber(minute) or 0) % 60)
                          end
                          return "SET"
                      elseif item.isRecoveryControl then
                          local legacy = trackerLog().__LEGACY__
                          return tostring(type(legacy) == "table" and #legacy or 0)
                      elseif item.isRandomizerRerollControl then
                          if self.rerollSeedFlash and self.rerollSeedFlash > 0 then return "ROLLED" end
                          if self.rerollSeedFlash and self.rerollSeedFlash < 0 then return "ERROR" end
                          return "ROLL"
                      elseif item.isRandomizerAutoSeedControl then
                          if self.autoSeedFlash and self.autoSeedFlash < 0 then return "ERROR" end
                          return "AUTO"
                      elseif item.isPkmnBanControl then
                          local count = mod.exports.__beta26.pkmnBanCount(
                              self.preGame, self.game)
                          return count > 0 and (tostring(count) .. " BAN") or "NONE"
                      elseif item.isSetupPresetSlot then
                          if selectedSetupPresetSlot <= 0 then return "OFF" end
                          local exists = H.setupPresetExists(selectedSetupPresetSlot)
                          return tostring(selectedSetupPresetSlot) .. (exists and "*" or "")
                      elseif item.isSetupPresetSave then
                          if self.setupPresetFlash and self.setupPresetFlash > 0 then return "SAVED" end
                          if self.setupPresetFlash and self.setupPresetFlash < 0 then return "ERROR" end
                          return selectedSetupPresetSlot > 0 and "SAVE" or "OFF"
                      elseif item.isSetupPresetLoad then
                          if self.setupPresetFlash and self.setupPresetFlash < 0 then return "EMPTY" end
                          if self.setupPresetFlash and self.setupPresetFlash > 0
                              and selectedSetupPresetSlot > 0 then return "LOADED" end
                          if selectedSetupPresetSlot <= 0 then return "OFF" end
                          return H.setupPresetExists(selectedSetupPresetSlot) and "LOAD" or "EMPTY"
                      elseif item.isSetupSave then
                          if self.setupSaveFlash and self.setupSaveFlash > 0 then return "SAVED" end
                          if self.setupSaveFlash and self.setupSaveFlash < 0 then return "ERROR" end
                          return "SAVE"
                      elseif item.isInGameSave then
                          if self.inGameSaveFlash and self.inGameSaveFlash > 0 then return "SAVED" end
                          if self.inGameSaveFlash and self.inGameSaveFlash < 0 then return "ERROR" end
                          return "SAVE"
                      end

                      local key = item.rule and item.rule.key
                      if not item.rule then return "" end
                      if item.isStartNewGameControl then return "START" end
                      if key == "wonderlocke"
                          or (key == "rules_locked"
                              and mod.exports.__beta26.permanentRuleSealWip) then
                          return "WIP"
                      end
                      if mod.exports.__beta26.isBattleScopeRuleKey(key) then
                          return Strings(mod.exports.__beta26.battleScopeLabel(val))
                      end
                      if not item.rule.numeric then
                          if key == "dev_self_test_export" then return "RUN" end
                          return val and "ON" or "OFF"
                      end
                      if key == "difficulty_profile" then
                          local options = mod.exports.__beta26.difficultyOptions()
                          local row = options[(tonumber(val) or 0) + 1]
                          return row and tostring(row.name or "VANILLA"):upper() or "VANILLA"
                      elseif key == "starting_money" or key == "gold_starting_money" then
                          return Chrome.money(tonumber(val) or 0)
                      elseif key == "world_building_tier" then
                          return ({ [0]="OFF", [1]="T1", [2]="T2", [3]="T3" })[tonumber(val) or 0] or "OFF"
                      elseif key == "level_cap_scope" then
                          return ({ [0]="NONE", [1]="GYMS", [2]="E4", [3]="CHAMP", [4]="POST" })[tonumber(val) or 0] or "NONE"
                      elseif key == "dupes_mode" then
                          return ({ [0]="OFF", [1]="SPEC", [2]="FAM", [3]="SPLIT" })[tonumber(val) or 0] or "OFF"
                      elseif key == "evolution_limit" then
                          return ({ [0]="NORMAL", [1]="NO FINAL", [2]="NO EVO" })[tonumber(val) or 0] or "NORMAL"
                      elseif key == "gift_slot_policy" or key == "trade_slot_policy" then
                          return ({ [0]="AREA", [1]="BONUS" })[tonumber(val) or 0] or "AREA"
                      elseif key == "travel_restrictions" then
                          return ({ [0]="NORMAL", [1]="NO FLY", [2]="NO FLY+TP" })[tonumber(val) or 0] or "NORMAL"
                      elseif key == "shop_restrictions" then
                          return ({ [0]="OFF", [1]="NO BUY", [2]="NO SELL", [3]="NEITHER" })[tonumber(val) or 0] or "OFF"
                      elseif key == "run_surf" then
                          return Strings(mod.exports.__beta26.movementAssistLabel(val))
                      elseif key == "shiny_clause" then
                          return ({ [0]="OFF", [1]="1", [2]="2", [3]="3", [4]="UNLIMITED" })[tonumber(val) or 4] or "UNLIMITED"
                      elseif key == "shiny_rate_mode" then
                          if mod.exports.__beta26.shinyExternalProvider(currentGame or mod.game) then
                              return "EXTERNAL"
                          end
                          return Strings(mod.exports.__beta26.shinyRateLabel(val))
                      elseif key == "encounter_ball_limit" then
                          return ({ [0]="OFF", [1]="1", [2]="2", [3]="3", [4]="5", [5]="10" })[tonumber(val) or 0] or "OFF"
                      elseif key == "colorlocke_mode" or key == "alphabetlocke_mode" then
                          return ({ [0]="OFF", [1]="RANDOM", [2]="CHOOSE" })[tonumber(val) or 0] or "OFF"
                      elseif key == "colorlocke_color" then
                          return mod.exports.__beta26.colorlockeColorLabel(val)
                      elseif key == "alphabetlocke_letter" then
                          return mod.exports.__beta26.alphabetlockeLetterLabel(val)
                      elseif key == "type_lock_mode" then
                          return mod.exports.__beta26.typeLockModeLabel(val)
                      elseif key == "type_lock_primary" or key == "type_lock_secondary" or key == "type_lock_tertiary" or key == "type_lock_quaternary" or key == "type_lock_quinary" or key == "type_lock_senary" then
                          return mod.exports.__beta26.typeLockTypeLabel(val)
                      elseif key == "randomizer_preset" then
                          return ({ [0]="CUSTOM", [1]="CHAOS", [2]="BALANCED" })[tonumber(val) or 0] or "CUSTOM"
                      elseif key == "randomizer_seed" then
                          local seed = tonumber(val) or 0
                          return seed > 0 and ("%08d"):format(seed) or "AUTO"
                      elseif key == "random_starter_style" then
                          return ({ [0]="ANY", [1]="3-STAGE", [2]="BASE", [3]="SIM BST" })[tonumber(val) or 0] or "ANY"
                      elseif key == "random_starter_balance" then
                          return ({ [0]="INDEPENDENT", [1]="BALANCED" })[tonumber(val) or 0] or "INDEPENDENT"
                      elseif key == "random_starter_trio_typing" then
                          return ({ [0]="OFF", [1]="AUTO" })[tonumber(val) or 0] or "OFF"
                      elseif key == "random_field_item_balance" then
                          return ({ [0]="CHAOS", [1]="CATEGORY", [2]="BALANCED" })[tonumber(val) or 0] or "CHAOS"
                      elseif key == "random_field_item_repetition" then
                          return ({ [0]="ALLOW", [1]="DIVERSE", [2]="UNIQUE" })[tonumber(val) or 0] or "ALLOW"
                      elseif key == "random_encounter_balance" then
                          return ({ [0]="CHAOS", [1]="SIM BST", [2]="EVO", [3]="BALANCED" })[tonumber(val) or 0] or "CHAOS"
                      elseif key == "random_encounter_repetition" then
                          return ({ [0]="ALLOW", [1]="DIVERSE", [2]="UNIQUE" })[tonumber(val) or 0] or "ALLOW"
                      elseif key == "random_encounter_diversity_strength" then
                          return ({ [0]="LIGHT", [1]="STANDARD", [2]="STRONG" })[tonumber(val) or 1] or "STANDARD"
                      elseif key == "random_evolution_balance" then
                          return ({ [0]="CHAOS", [1]="DEPTH", [2]="SIM BST", [3]="BALANCED" })[tonumber(val) or 0] or "CHAOS"
                      elseif key == "random_trainer_balance" then
                          return ({ [0]="CHAOS", [1]="EVO", [2]="SIM BST", [3]="BALANCED" })[tonumber(val) or 0] or "CHAOS"
                      elseif key == "random_trainer_diversity" then
                          return ({ [0]="OFF", [1]="DIVERSE", [2]="UNIQUE" })[tonumber(val) or 0] or "OFF"
                      elseif key == "random_trainer_theme" then
                          return ({ [0]="OFF", [1]="TYPE" })[tonumber(val) or 0] or "OFF"
                      elseif key == "randomizer_info_policy" then
                          return ({ [0]="OPEN INFO", [1]="BLIND INFO" })[tonumber(val) or 0] or "OPEN INFO"
                      elseif key == "gold_egg_encounter_mode" then
                          return ({ [0]="OFF", [1]="RECEIVED", [2]="HATCHED", [3]="GIFT" })[tonumber(val) or 0] or "OFF"
                      elseif key == "gold_bug_contest_mode" then
                          return ({ [0]="NORMAL", [1]="EXEMPT", [2]="SLOT" })[tonumber(val) or 0] or "NORMAL"
                      elseif key == "random_learnset_generation" then
                          return ({ [0]="AUTO", [1]="GEN1", [2]="GEN2" })[tonumber(val) or 0] or "AUTO"
                      elseif key == "random_learnset_stab" then
                          return ({ [0]="OFF", [1]="PREFER", [2]="STRONG" })[tonumber(val) or 1] or "PREFER"
                      elseif key == "random_species_generation" then
                          return ({ [0]="AUTO", [1]="GEN1", [2]="GEN2", [3]="BOTH" })[tonumber(val) or 0] or "AUTO"
                      elseif key == "route_forgiveness" then
                          return ({ [0]="OFF", [1]="0", [2]="1" })[tonumber(val) or 0] or "OFF"
                      elseif key == "trainer_money_multiplier" then
                          return mod.exports.__beta26.trainerMoneyPresetLabels[
                              tonumber(val) or 4] or Strings.source("100%")
                      elseif key == "mt_moon_splits" then
                          return ({ [0]="OFF", [1]="COMMON" })[tonumber(val) or 0] or "OFF"
                      elseif key == "safari_zone_splits" then
                          return ({ [0]="STANDARD", [1]="PER AREA", [2]="UNTIL CATCH", [3]="AREA+CATCH" })[tonumber(val) or 0] or "STANDARD"
                      elseif key == "player_start_stat_exp" or key == "wild_start_stat_exp"
                          or key == "trainer_start_stat_exp" then
                          return mod.exports.__beta26.statExpPresetLabels[tonumber(val) or 0] or "0%"
                      elseif key == "maximum_bst" then
                          return mod.exports.__beta26.maximumBstDisplayLabel(val)
                      end
                      return tostring(math.floor(tonumber(val) or item.rule.min or 0))
                  end

                  for slot = 1, self.pageSize do
                      local i = self.scroll + slot
                      local item = flatItemList[i]
                      if not item then break end
                      local rowY = 3 + (slot - 1) * 2
                      local selected = i == self.cursor
                      local rowWip = item.rule and (
                          item.rule.key == "wonderlocke"
                          or (item.rule.key == "rules_locked"
                              and mod.exports.__beta26.permanentRuleSealWip))
                      if selected and not rowWip then
                          Chrome.cursor(1, rowY)
                      end
                      if item.isHeader then
                          local headerText = goldMenuLabel(item.name, item.shortName, 14)
                          local headerWidth = type(GoldFont.width) == "function"
                              and GoldFont.width(headerText) or (#headerText * 8)
                          -- +1px tracking keeps the one-pixel bold echo from
                          -- visually welding adjacent glyphs together.
                          local trackedWidth = headerWidth + math.max(0, #headerText - 1)
                          local headerX = math.max(16, math.floor((144 - trackedWidth) / 2))
                          local glyphX = headerX
                          for ci = 1, #headerText do
                              local ch = headerText:sub(ci, ci)
                              GoldFont.draw(ch, glyphX, rowY * 8)
                              GoldFont.draw(ch, glyphX + 1, rowY * 8)
                              glyphX = glyphX + (type(GoldFont.width) == "function"
                                  and GoldFont.width(ch) or 8) + 1
                          end
                          local key = item.sectionKey or sectionKey(item)
                          if collapsedSections[key] then
                              Chrome.cursor(18, rowY, true)
                          else
                              GoldFont.drawCode(Chrome.DOWN_ARROW, 18 * 8, rowY * 8)
                          end
                      else
                          local delegated = externalRuleDelegation
                              and externalRuleDelegation(item.rule.key, self.game)
                          local rowIsWip = item.rule.key == "wonderlocke"
                              or (item.rule.key == "rules_locked"
                                  and mod.exports.__beta26.permanentRuleSealWip)
                          if rowIsWip or delegated then
                              love.graphics.setColor(0.55, 0.55, 0.55, 1)
                          end
                          -- 2.2.1: keep the wider Gold rule-label field from
                          -- 2.1.23, but pull the right-aligned value/toggle column one
                          -- native tile back from the frame. Runtime 2.1.24 testing
                          -- showed the previous edge anchor could crowd/clip the border.
                          -- Long money/type values still receive up to seven tiles.
                          Chrome.print(goldMenuLabel(item.rule.name, item.rule.shortName, 10), 2, rowY)
                          local shownValue = goldValueText(item,
                              getConfigValue(item.rule.key, self.preGame))
                          local valueText = (item.rule.key == "starting_money"
                                  or item.rule.key == "gold_starting_money")
                              and shownValue or clipped(shownValue, 7)
                          local valuePixels = type(GoldFont.width) == "function"
                              and GoldFont.width(valueText) or (#tostring(valueText) * 8)
                          local valueTiles = math.max(1, math.min(7,
                              math.ceil((tonumber(valuePixels) or 8) / 8)))
                          Chrome.print(valueText, math.max(12, 19 - valueTiles), rowY)
                          if rowIsWip or delegated then
                              love.graphics.setColor(0, 0, 0, 1)
                          end
                      end
                  end

                  local selItem = flatItemList[self.cursor]
                  if selItem and selItem.isHeader then
                      local key = selItem.sectionKey or sectionKey(selItem)
                      local summary = collapsedSectionSummary(selItem)
                      if summary then
                          Chrome.print(goldMenuLabel(summary, nil, 16), 2, 12)
                      end
                      Chrome.print(Strings("SEL:RESET"), 2, 13)
                      Chrome.print(Strings("SEL+UD:JUMP"), 2, 14)
                      Chrome.print(Strings("A/LR:FOLD"), 2, 15)
                  elseif selItem and selItem.rule then
                      local descLines, maxScroll =
                          configDescriptionScrollMetrics(selItem)
                      self.descScroll = math.max(0, math.min(self.descScroll or 0, maxScroll))
                      for row = 1, 4 do
                          local line = descLines[self.descScroll + row]
                          if not line then break end
                          Chrome.print(line, 2, 11 + row)
                      end
                      -- 2.7.32: Gold long-help now communicates both
                      -- directions and the exact line-scroll position. Chrome
                      -- exposes the native down-arrow but no matching up-arrow,
                      -- so use a compact caret in the same reserved right gutter
                      -- rather than inventing an undocumented Gen2 glyph code.
                      if self.descScroll > 0 then
                          Chrome.print(Strings("^"), 18, 12)
                      end
                      if self.descScroll < maxScroll then
                          GoldFont.drawCode(Chrome.DOWN_ARROW, 18 * 8, 15 * 8)
                      end
                      if self.editingNumber then
                          Chrome.print(Strings("A:OK B:BACK"), 7, 16)
                      elseif maxScroll > 0 then
                          local pagingHint = self.descScroll < maxScroll
                              and "SEL:MORE" or "SEL:TOP"
                          local position = tostring(self.descScroll + 1)
                              .. "/" .. tostring(maxScroll + 1)
                          Chrome.print(Strings(pagingHint), 2, 16)
                          local positionCols = math.max(1, #position)
                          Chrome.print(Strings(position),
                              math.max(11, 19 - positionCols), 16)
                      elseif locked then
                          Chrome.print(Strings("RULES SEALED"), 7, 16)
                      end
                  end
                  love.graphics.setColor(1, 1, 1, 1)
                  return
              end

              local function drawGen1Surface()
              local Font = mod.ui.Font
              local wideMode = self.uiModLayout == "wide"
              local menuCols = wideMode and 38 or 20
              local valueShift = wideMode and 144 or 0

              -- 2.1.4: now that the Gen1 variable-width Font path is active,
              -- measure Nuzlocke-owned text in pixels instead of character
              -- counts. Marquee scrolling is no longer the normal R/B/Y
              -- presentation; labels truncate only when they genuinely cannot
              -- fit, and descriptions wrap to the full pixel width.
              local function fitPixelText(text, budget)
                  text = Strings(tostring(text or ""))
                  budget = math.max(0, tonumber(budget) or 0)
                  if type(Font.width) ~= "function"
                      or type(Font.split) ~= "function"
                      or type(Font.spansFitting) ~= "function" then
                      return text
                  end
                  if Font.width(text) <= budget then return text end
                  local spans = Font.split(text)
                  local fit = Font.spansFitting(spans, budget)
                  if fit <= 0 then return "" end
                  return text:sub(1, spans[fit].to)
              end

              local function marqueePixelText(text, budget, elapsed, secondsPerStep)
                  text = Strings(tostring(text or ""))
                  budget = math.max(0, tonumber(budget) or 0)
                  if type(Font.width) ~= "function"
                      or type(Font.split) ~= "function"
                      or type(Font.spansFitting) ~= "function"
                      or Font.width(text) <= budget then
                      return text
                  end

                  local spans = Font.split(text)
                  if #spans == 0 then return "" end
                  local visible = math.max(1, Font.spansFitting(spans, budget))
                  if visible >= #spans then return text end

                  -- Long labels stay still briefly, then bounce by whole glyph
                  -- spans. Text that fits never enters this path at all.
                  elapsed = tonumber(elapsed) or 0
                  if elapsed < 3.0 then
                      return text:sub(1, spans[visible].to)
                  end

                  secondsPerStep = secondsPerStep or 2.4
                  local maxOffset = #spans - visible
                  local cycle = math.max(1, maxOffset * 2)
                  local step = math.floor((elapsed - 3.0) / secondsPerStep)
                  local phase = step % cycle
                  local offset = phase <= maxOffset and phase
                      or (cycle - phase)

                  local first = offset + 1
                  local last = math.min(#spans, first + visible - 1)

                  -- Because advances vary, a fixed glyph count can still run
                  -- a few pixels long after the window moves. Shrink the end
                  -- until this exact substring fits the pixel budget.
                  while last > first
                      and Font.width(text:sub(spans[first].from,
                          spans[last].to)) > budget do
                      last = last - 1
                  end
                  return text:sub(spans[first].from, spans[last].to)
              end

              local function menuLabelText(fullSource, shortSource,
                  budget, elapsed)
                  local fullRaw = tostring(fullSource or "")
                  local fullText = Strings(fullRaw)
                  if type(Font.width) ~= "function"
                      or Font.width(fullText) <= budget then
                      return fullText
                  end

                  if shortSource ~= nil then
                      local shortRaw = tostring(shortSource)
                      local shortText = Strings(shortRaw)
                      local fullWasTranslated = tostring(fullText) ~= fullRaw
                      local shortWasTranslated = tostring(shortText) ~= shortRaw

                      -- Never substitute an English shorthand into a translated
                      -- label unless that shorthand was translated too. Existing
                      -- translation packs can continue to translate the natural
                      -- canonical label and get a slow marquee if needed.
                      if not fullWasTranslated or shortWasTranslated then
                          if type(Font.width) ~= "function"
                              or Font.width(shortText) <= budget then
                              return shortText
                          end
                          return marqueePixelText(shortRaw, budget, elapsed)
                      end
                  end

                  return marqueePixelText(fullRaw, budget, elapsed)
              end

              local function wrapPixelText(text, budget)
                  text = Strings(tostring(text or ""))
                  budget = math.max(1, tonumber(budget) or 1)
                  if type(Font.width) ~= "function" then
                      return wrapText(text, math.max(1,
                          math.floor(budget / 8)))
                  end
                  local lines, line = {}, ""
                  for word in text:gmatch("%S+") do
                      local candidate = line == "" and word
                          or (line .. " " .. word)
                      if line == "" or Font.width(candidate) <= budget then
                          line = candidate
                          if Font.width(line) > budget then
                              line = fitPixelText(line, budget)
                          end
                      else
                          lines[#lines + 1] = line
                          line = word
                          -- Pathological translated single words should never
                          -- draw through the frame. Keep the UI safe rather
                          -- than reintroducing horizontal marquee behavior.
                          if Font.width(line) > budget then
                              line = fitPixelText(line, budget)
                          end
                      end
                  end
                  if line ~= "" then lines[#lines + 1] = line end
                  if #lines == 0 then lines[1] = "" end
                  return lines
              end

              -- 2.6.31: classic config uses a 12/6 split instead of 11/7.
              -- The recovered 8px belongs to the list, not smaller typography.
              -- 2.7.95: pre-game Setup is drawn over edition-colored title
              -- presentation. Clear that inherited tint first so Setup uses the
              -- same monochrome black-on-white contract as live NUZLOCKE RULES.
              if self.preGame then
                  love.graphics.setColor(1, 1, 1, 1)
                  love.graphics.rectangle("fill", 0, 0, (menuCols * 8), 144)
                  love.graphics.setColor(0, 0, 0, 1)
              end
              Font.drawBox(0, 0, menuCols, 12)
              Font.drawBox(0, 12, menuCols, 6)

              if self.cursor > self.scroll + self.pageSize then
                  self.scroll = self.cursor - self.pageSize
              end

              if self.cursor <= self.scroll then
                  self.scroll = math.max(0, self.cursor - 1)
              end

              -- 2.7.91: Setup/Rules owns a single title row now. Move the
              -- visible rules upward into the reclaimed space and center the
              -- compact pager at the bottom of the list panel.
              local surfaceWidth = menuCols * 8
              local totalItems = #flatItemList
              local currentItem = totalItems > 0
                  and math.max(1, math.min(tonumber(self.cursor) or 1, totalItems))
                  or 0
              local positionText = ("%d/%d"):format(currentItem, totalItems)
              local positionWidth = type(Font.width) == "function"
                  and Font.width(positionText) or (#positionText * 6)
              local Theme = require("src.ui.Theme")
              local canScrollUp = (self.scroll or 0) > 0
              local canScrollDown = (self.scroll or 0) + self.pageSize < totalItems
              local navY = 82
              local arrowGap = 4
              local arrowWidth = 8
              local clusterWidth = arrowWidth + arrowGap + positionWidth
                  + arrowGap + arrowWidth
              local upX = math.max(8,
                  math.floor((surfaceWidth - clusterWidth) / 2))
              local positionX = upX + arrowWidth + arrowGap
              local downX = positionX + positionWidth + arrowGap

              -- Title: centred in the 160px canvas (inner X=8..152=144px wide).
              -- "NUZLOCKE RULES" = 14 chars * ~10px = 140px => start at X=10.
              -- "NZLCKE SETUP"  = 12 chars * ~10px = 120px => start at X=20.
              local locked = mod.exports.__beta26.configRulesLocked(self.preGame)
              local edition = mod.exports.__beta26.Dev.gameLabel(self.game)
              local uiView = mod.exports.__beta26.UiSystem.view(
                  self.preGame and "SETUP" or "RULES", self.game, {
                      edition = edition,
                      mode = self.preGame and "NEW RUN" or "LIVE",
                      state = locked and "LOCKED" or nil,
                  })
              mod.exports.__beta26.UiSystem.gen1Header(Font, uiView, surfaceWidth)
              -- 2.7.92: normal rule names, values, cursor/navigation glyphs,
              -- pager, and help copy use the same black text treatment.
              love.graphics.setColor(0, 0, 0, 1)
              Font.draw(positionText, positionX, navY)
              if canScrollUp then
                  -- R/B/Y has one native list-more tile (▼). Rotate that exact
                  -- tile rather than substituting an unsupported Unicode glyph.
                  love.graphics.push()
                  love.graphics.translate(upX + 4, navY + 4)
                  love.graphics.rotate(math.pi)
                  love.graphics.translate(-(upX + 4), -(navY + 4))
                  Font.drawCode(Theme.moreArrow or 0xEE, upX, navY)
                  love.graphics.pop()
              end
              if canScrollDown then
                  Font.drawCode(Theme.moreArrow or 0xEE, downX, navY)
              end

              -- 2.7.91: with the redundant context subtitle removed,
              -- start the three 16px rule rows one full row higher. The pager
              -- occupies the centered footer strip above the y=96 detail divider.
              local startY = 32

              for i = self.scroll + 1,
                  math.min(self.scroll + self.pageSize, #flatItemList) do

                  local item = flatItemList[i]
                  local drawY =
                      startY + ((i - (self.scroll + 1)) * 16)

                  if item.isHeader then
                      local isSelected = (i == self.cursor)
                      local key = item.sectionKey or sectionKey(item)
                      local Theme = require("src.ui.Theme")

                      -- Use the engine-native cursor glyph: it is proven
                      -- readable across Yellow's palette path. Position it at
                      -- the far-left edge and start text at X=22, reclaiming
                      -- eight pixels versus the historical X=30 layout.
                      if isSelected then
                          Font.drawCode(Theme.cursor, 8, drawY)
                      end

                      local headerText = menuLabelText(item.name, item.shortName,
                          wideMode and 256 or 116, self.marqueeTime)
                      local headerWidth = type(Font.width) == "function"
                          and Font.width(headerText) or (#headerText * 6)
                      local trackedWidth = headerWidth + math.max(0, #headerText - 1)
                      local headerAreaRight = 132 + valueShift
                      local headerX = math.max(16, math.floor((8 + headerAreaRight - trackedWidth) / 2))
                      local glyphX = headerX
                      for ci = 1, #headerText do
                          local ch = headerText:sub(ci, ci)
                          Font.draw(ch, glyphX, drawY)
                          Font.draw(ch, glyphX + 1, drawY)
                          glyphX = glyphX + (type(Font.width) == "function"
                              and Font.width(ch) or 6) + 1
                      end

                      Font.drawCode(collapsedSections[key]
                          and Theme.cursor or (Theme.moreArrow or 0xEE),
                          138 + valueShift, drawY)
                  else
                      local isSelected = (i == self.cursor)
                      local key = item.rule.key
                      local val = getConfigValue(key, self.preGame)

                      local isWip = (key == "wonderlocke")
                          or (key == "rules_locked"
                              and mod.exports.__beta26.permanentRuleSealWip)
                      local delegated = externalRuleDelegation
                          and externalRuleDelegation(key, self.game)
                      if isWip or delegated then
                          love.graphics.setColor(0.55, 0.55, 0.55, 1)
                      else
                          love.graphics.setColor(0, 0, 0, 1)
                      end

                      -- Delegated rows remain selectable for hover/help text,
                      -- but canChangeSelected() prevents mutation. Use the
                      -- native cursor at X=10 and start the label at X=22:
                      -- reliable selection visibility with a smaller gutter
                      -- than the old X=30 layout.
                      if isSelected and not isWip then
                          local Theme = require("src.ui.Theme")
                          Font.drawCode(Theme.cursor, 8, drawY)
                      end

                      -- 2.4.41: the label budget must follow the ACTUAL
                      -- value-column geometry. Several wide-value rows begin
                      -- left of the generic x=112 column; the old fixed 90px
                      -- budget let a label pass the width test even though its
                      -- rendered value started underneath it (Shiny Clause was
                      -- the visible failure). Keep a small gutter between the
                      -- label and whichever value column this row uses.
                      local valueStartX = 112 + valueShift
                      if item.isLockeTypeControl then
                          valueStartX = wideMode and 244 or 108
                      elseif item.isRecoveryControl then
                          valueStartX = 118 + valueShift
                      elseif item.isRandomizerRerollControl or item.isRandomizerAutoSeedControl or item.isStarterRerollControl then
                          valueStartX = 112 + valueShift
                      elseif item.isSetupSave or item.isInGameSave
                          or item.isSetupPresetSlot or item.isSetupPresetSave
                          or item.isSetupPresetLoad then
                          valueStartX = 112 + valueShift
                      elseif item.rule.numeric then
                          if mod.exports.__beta26.isBattleScopeRuleKey(key) then
                              valueStartX = 104 + valueShift
                          elseif key == "difficulty_profile" or key == "level_cap_scope"
                              or key == "randomizer_seed"
                              or key == "random_starter_style"
                              or key == "random_starter_balance"
                              or key == "random_starter_trio_typing"
                              or key == "random_encounter_balance"
                              or key == "randomizer_info_policy"
                              or key == "evolution_limit"
                              or key == "gift_slot_policy" or key == "trade_slot_policy" then
                              valueStartX = 104 + valueShift
                          elseif key == "travel_restrictions"
                              or key == "shiny_clause" then
                              valueStartX = 96 + valueShift
                          elseif key == "run_surf" then
                              valueStartX = 104 + valueShift
                          elseif key == "encounter_ball_limit" then
                              valueStartX = 112 + valueShift
                          elseif key == "starting_money"
                              or key == "difficulty_profile" then
                              valueStartX = 110 + valueShift
                          elseif key == "world_building_tier"
                              or key == "route_forgiveness" then
                              valueStartX = 118 + valueShift
                          end
                      end
                      local nameBudget = wideMode and 228
                          or math.max(42, valueStartX - 16 - 6)
                      local labelElapsed = isSelected and self.marqueeTime or 0
                      local labelText = menuLabelText(item.rule.name,
                          item.rule.shortName, nameBudget, labelElapsed)
                      if not isSelected then
                          labelText = fitPixelText(labelText, nameBudget)
                      end
                      Font.draw(labelText, 16, drawY)

                      if item.isLockeTypeControl then
                          local mode = math.max(0, math.min(6,
                              math.floor(tonumber(val) or 0)))
                          Font.draw(marqueePixelText(LockePreset.displayLabel(mode, preGame),
                              wideMode and 68 or 44, self.marqueeTime), 108, drawY)
                      elseif item.isRecoveryControl then
                          local legacy = trackerLog().__LEGACY__
                          local count = type(legacy) == "table" and #legacy or 0
                          Font.draw(tostring(count), 118 + valueShift, drawY)
                      elseif item.isRandomizerRerollControl then
                          local label = "ROLL"
                          if self.rerollSeedFlash and self.rerollSeedFlash > 0 then
                              label = "ROLLED"
                          elseif self.rerollSeedFlash and self.rerollSeedFlash < 0 then
                              label = "ERROR"
                          end
                          Font.draw(marqueePixelText(label, 42, self.marqueeTime), 112 + valueShift, drawY)
                      elseif item.isRandomizerAutoSeedControl then
                          local label = (self.autoSeedFlash and self.autoSeedFlash < 0) and "ERROR" or "AUTO"
                          Font.draw(marqueePixelText(label, 42, self.marqueeTime), 112 + valueShift, drawY)
                      elseif item.isStarterRerollControl then
                          local idx = type(mod.exports.__beta26.randomizerStarterRerollIndex) == "function"
                              and mod.exports.__beta26.randomizerStarterRerollIndex(
                                  self.preGame and pendingNewGameRules or nil) or 0
                          local label = "R" .. tostring(idx)
                          if self.rerollStarterFlash and self.rerollStarterFlash < 0 then
                              label = "ERROR"
                          end
                          Font.draw(marqueePixelText(label, 42, self.marqueeTime), 112 + valueShift, drawY)
                      elseif item.isSetupSave then
                          local label = "SAVE"
                          if self.setupSaveFlash and self.setupSaveFlash > 0 then
                              label = "SAVED"
                          elseif self.setupSaveFlash and self.setupSaveFlash < 0 then
                              label = "ERROR"
                          end
                          Font.draw(marqueePixelText(label, 42, self.marqueeTime), 112 + valueShift, drawY)
                      elseif item.isInGameSave then
                          local label = "SAVE"
                          if self.inGameSaveFlash and self.inGameSaveFlash > 0 then
                              label = "SAVED"
                          elseif self.inGameSaveFlash and self.inGameSaveFlash < 0 then
                              label = "ERROR"
                          end
                          Font.draw(marqueePixelText(label, 42, self.marqueeTime), 112 + valueShift, drawY)
                      elseif item.isSetupPresetSlot then
                          local label = "OFF"
                          if selectedSetupPresetSlot > 0 then
                              local exists = H.setupPresetExists(selectedSetupPresetSlot)
                              label = tostring(selectedSetupPresetSlot)
                                  .. (exists and "*" or "")
                          end
                          Font.draw(marqueePixelText(label, 42, self.marqueeTime),
                              112 + valueShift, drawY)
                      elseif item.isSetupPresetSave then
                          local label = selectedSetupPresetSlot > 0 and "SAVE" or "OFF"
                          if self.setupPresetFlash and self.setupPresetFlash > 0 then
                              label = "SAVED"
                          elseif self.setupPresetFlash and self.setupPresetFlash < 0 then
                              label = "ERROR"
                          end
                          Font.draw(marqueePixelText(label, 42, self.marqueeTime),
                              112 + valueShift, drawY)
                      elseif item.isSetupPresetLoad then
                          local label = "OFF"
                          if selectedSetupPresetSlot > 0 then
                              label = H.setupPresetExists(selectedSetupPresetSlot)
                                  and "LOAD" or "EMPTY"
                          end
                          if self.setupPresetFlash and self.setupPresetFlash < 0 then
                              label = "EMPTY"
                          elseif self.setupPresetFlash and self.setupPresetFlash > 0
                              and selectedSetupPresetSlot > 0 then
                              label = "LOADED"
                          end
                          Font.draw(marqueePixelText(label, 42, self.marqueeTime),
                              112 + valueShift, drawY)
                      elseif item.isPkmnBanControl then
                          local count = mod.exports.__beta26.pkmnBanCount(self.preGame, self.game)
                          local label = count > 0 and (tostring(count) .. " BAN") or "NONE"
                          Font.draw(marqueePixelText(label, 42, self.marqueeTime), 112 + valueShift, drawY)
                      elseif item.rule.numeric then
                          local digits = item.rule.digits or 1
                          local numberText = ("%0" .. tostring(digits) .. "d"):format(tonumber(val) or item.rule.min or 0)
                          if mod.exports.__beta26.isBattleScopeRuleKey(key) then
                              Font.draw(marqueePixelText(Strings(
                                  mod.exports.__beta26.battleScopeLabel(val)),
                                  50, self.marqueeTime), 104 + valueShift, drawY)
                          elseif key == "difficulty_profile" then
                              local options = mod.exports.__beta26.difficultyOptions()
                              local row = options[(tonumber(val) or 0) + 1]
                              local label = row and row.name or "VANILLA"
                              Font.draw(marqueePixelText(tostring(label):upper(), 44, self.marqueeTime), 110 + valueShift, drawY)
                          elseif key == "starting_money" or key == "gold_starting_money" then
                              Font.draw(Strings("¥%s", numberText), 110 + valueShift, drawY)
                          elseif key == "world_building_tier" then
                              local labels = { [0] = "OFF", [1] = "T1", [2] = "T2", [3] = "T3" }
                              Font.draw(Strings(labels[tonumber(val) or 0] or "OFF"), 118 + valueShift, drawY)
                          elseif key == "level_cap_scope" then
                              local labels = { [0] = "NONE", [1] = "GYMS", [2] = "E4", [3] = "CHAMP", [4] = "POST" }
                              Font.draw(marqueePixelText(labels[tonumber(val) or 0]
                                  or "NONE", 44, self.marqueeTime), 110 + valueShift, drawY)
                          elseif key == "dupes_mode" then
                              local labels = { [0] = "OFF", [1] = "SPEC", [2] = "FAM", [3] = "SPLIT" }
                              Font.draw(marqueePixelText(labels[tonumber(val) or 0]
                                  or "OFF", 42, self.marqueeTime), 112 + valueShift, drawY)
                          elseif key == "evolution_limit" then
                              local labels = { [0] = "NORMAL", [1] = "NO FINAL", [2] = "NO EVO" }
                              Font.draw(marqueePixelText(labels[tonumber(val) or 0]
                                  or "NORMAL", 50, self.marqueeTime), 104 + valueShift, drawY)
                          elseif key == "gift_slot_policy" or key == "trade_slot_policy" then
                              local labels = { [0] = "AREA", [1] = "BONUS" }
                              Font.draw(marqueePixelText(labels[tonumber(val) or 0]
                                  or "AREA", 50, self.marqueeTime), 104 + valueShift, drawY)
                          elseif key == "travel_restrictions" then
                              local labels = { [0] = "NORMAL", [1] = "NO FLY", [2] = "NO FLY+TP" }
                              Font.draw(marqueePixelText(labels[tonumber(val) or 0]
                                  or "NORMAL", 58, self.marqueeTime), 96 + valueShift, drawY)
                          elseif key == "shop_restrictions" then
                              local labels = { [0] = "OFF", [1] = "NO BUY", [2] = "NO SELL", [3] = "NEITHER" }
                              Font.draw(marqueePixelText(labels[tonumber(val) or 0]
                                  or "OFF", 58, self.marqueeTime), 96 + valueShift, drawY)
                          elseif key == "shiny_clause" then
                              local labels = { [0] = "OFF", [1] = "1", [2] = "2", [3] = "3", [4] = "UNLIMITED" }
                              Font.draw(marqueePixelText(labels[tonumber(val) or 0]
                                  or "OFF", 58, self.marqueeTime), 96 + valueShift, drawY)
                          elseif key == "shiny_rate_mode" then
                              local text = mod.exports.__beta26.shinyExternalProvider(currentGame or mod.game)
                                  and "EXTERNAL" or mod.exports.__beta26.shinyRateLabel(val)
                              Font.draw(marqueePixelText(Strings(text),
                                  58, self.marqueeTime), 96 + valueShift, drawY)
                          elseif key == "encounter_ball_limit" then
                              local labels = { [0] = "OFF", [1] = "1", [2] = "2", [3] = "3", [4] = "5", [5] = "10" }
                              Font.draw(marqueePixelText(labels[tonumber(val) or 0]
                                  or "OFF", 42, self.marqueeTime), 112 + valueShift, drawY)
                          elseif key == "colorlocke_mode" or key == "alphabetlocke_mode" then
                              local labels = { [0]="OFF", [1]="RANDOM", [2]="CHOOSE" }
                              Font.draw(marqueePixelText(labels[tonumber(val) or 0] or "OFF", 50, self.marqueeTime), 104 + valueShift, drawY)
                          elseif key == "colorlocke_color" then
                              Font.draw(marqueePixelText(mod.exports.__beta26.colorlockeColorLabel(val), 50, self.marqueeTime), 104 + valueShift, drawY)
                          elseif key == "alphabetlocke_letter" then
                              Font.draw(mod.exports.__beta26.alphabetlockeLetterLabel(val), 118 + valueShift, drawY)
                          elseif key == "type_lock_mode" then
                              Font.draw(marqueePixelText(mod.exports.__beta26.typeLockModeLabel(val), 42, self.marqueeTime), 112 + valueShift, drawY)
                          elseif key == "type_lock_primary" or key == "type_lock_secondary" or key == "type_lock_tertiary" or key == "type_lock_quaternary" or key == "type_lock_quinary" or key == "type_lock_senary" then
                              Font.draw(marqueePixelText(
                                  mod.exports.__beta26.typeLockTypeLabel(val),
                                  42, self.marqueeTime), 112 + valueShift, drawY)
                          elseif key == "randomizer_preset" then
                              local labels = { [0]="CUSTOM", [1]="CHAOS", [2]="BALANCED" }
                              Font.draw(marqueePixelText(labels[tonumber(val) or 0]
                                  or "CUSTOM", 50, self.marqueeTime), 104 + valueShift, drawY)
                          elseif key == "randomizer_seed" then
                              local seed = tonumber(val) or 0
                              local label = seed > 0 and ("%08d"):format(seed) or "AUTO"
                              Font.draw(marqueePixelText(label, 50, self.marqueeTime), 104 + valueShift, drawY)
                          elseif key == "random_starter_style" then
                              local labels = { [0]="ANY", [1]="3-STAGE", [2]="BASE", [3]="SIM BST" }
                              Font.draw(marqueePixelText(labels[tonumber(val) or 0]
                                  or "ANY", 50, self.marqueeTime), 104 + valueShift, drawY)
                          elseif key == "random_starter_balance" then
                              local labels = { [0]="INDEPENDENT", [1]="BALANCED" }
                              Font.draw(marqueePixelText(labels[tonumber(val) or 0]
                                  or "INDEPENDENT", 50, self.marqueeTime), 104 + valueShift, drawY)
                          elseif key == "random_starter_trio_typing" then
                              local labels = { [0]="OFF", [1]="AUTO" }
                              Font.draw(marqueePixelText(labels[tonumber(val) or 0]
                                  or "OFF", 50, self.marqueeTime), 104 + valueShift, drawY)
                          elseif key == "random_field_item_balance" then
                              local labels = { [0]="CHAOS", [1]="CATEGORY", [2]="BALANCED" }
                              Font.draw(marqueePixelText(labels[tonumber(val) or 0]
                                  or "CHAOS", 50, self.marqueeTime), 104 + valueShift, drawY)
                          elseif key == "random_field_item_repetition" then
                              local labels = { [0]="ALLOW", [1]="DIVERSE", [2]="UNIQUE" }
                              Font.draw(marqueePixelText(labels[tonumber(val) or 0]
                                  or "ALLOW", 50, self.marqueeTime), 104 + valueShift, drawY)
                          elseif key == "random_encounter_balance" then
                              local labels = { [0]="CHAOS", [1]="SIM BST", [2]="EVO", [3]="BALANCED" }
                              Font.draw(marqueePixelText(labels[tonumber(val) or 0]
                                  or "CHAOS", 50, self.marqueeTime), 104 + valueShift, drawY)
                          elseif key == "random_encounter_repetition" then
                              local labels = { [0]="ALLOW", [1]="DIVERSE", [2]="UNIQUE" }
                              Font.draw(marqueePixelText(labels[tonumber(val) or 0]
                                  or "ALLOW", 50, self.marqueeTime), 104 + valueShift, drawY)
                          elseif key == "random_encounter_diversity_strength" then
                              local labels = { [0]="LIGHT", [1]="STANDARD", [2]="STRONG" }
                              Font.draw(marqueePixelText(labels[tonumber(val) or 1]
                                  or "STANDARD", 50, self.marqueeTime), 104 + valueShift, drawY)
                          elseif key == "randomizer_info_policy" then
                              local labels = { [0]="OPEN INFO", [1]="BLIND INFO" }
                              Font.draw(marqueePixelText(labels[tonumber(val) or 0]
                                  or "OPEN INFO", 50, self.marqueeTime), 104 + valueShift, drawY)
                          elseif key == "random_learnset_generation" then
                              local labels = { [0]="AUTO", [1]="GEN1", [2]="GEN2" }
                              Font.draw(marqueePixelText(labels[tonumber(val) or 0]
                                  or "AUTO", 42, self.marqueeTime), 112 + valueShift, drawY)
                          elseif key == "random_learnset_stab" then
                              local labels = { [0]="OFF", [1]="PREFER", [2]="STRONG" }
                              Font.draw(marqueePixelText(labels[tonumber(val) or 1]
                                  or "PREFER", 42, self.marqueeTime), 112 + valueShift, drawY)
                          elseif key == "random_species_generation" then
                              local labels = { [0]="AUTO", [1]="GEN1", [2]="GEN2", [3]="BOTH" }
                              Font.draw(marqueePixelText(labels[tonumber(val) or 0]
                                  or "AUTO", 42, self.marqueeTime), 112 + valueShift, drawY)
                          elseif key == "run_surf" then
                              Font.draw(marqueePixelText(Strings(
                                  mod.exports.__beta26.movementAssistLabel(val)),
                                  50, self.marqueeTime), 104 + valueShift, drawY)
                          elseif key == "route_forgiveness" then
                              local labels = { [0] = "OFF", [1] = "0", [2] = "1" }
                              Font.draw(Strings(labels[tonumber(val) or 0] or "OFF"), 118 + valueShift, drawY)
                          elseif key == "trainer_money_multiplier" then
                              local label = mod.exports.__beta26.trainerMoneyPresetLabels[
                                  tonumber(val) or 4] or Strings.source("100%")
                              Font.draw(marqueePixelText(label, 44, self.marqueeTime), 110 + valueShift, drawY)
                          elseif key == "mt_moon_splits" then
                              local labels = { [0] = "OFF", [1] = "COMMON" }
                              Font.draw(marqueePixelText(labels[tonumber(val) or 0]
                                  or "OFF", 50, self.marqueeTime), 104 + valueShift, drawY)
                          elseif key == "safari_zone_splits" then
                              local labels = { [0] = "STANDARD", [1] = "PER AREA",
                                  [2] = "UNTIL CATCH", [3] = "AREA+CATCH" }
                              Font.draw(marqueePixelText(labels[tonumber(val) or 0]
                                  or "STANDARD", 50, self.marqueeTime), 104 + valueShift, drawY)
                          elseif key == "player_start_stat_exp" or key == "wild_start_stat_exp"
                              or key == "trainer_start_stat_exp" then
                              Font.draw(marqueePixelText(
                                  mod.exports.__beta26.statExpPresetLabels[tonumber(val) or 0]
                                      or "0%", 42, self.marqueeTime), 112 + valueShift, drawY)
                          elseif key == "maximum_bst" then
                              Font.draw(marqueePixelText(
                                  mod.exports.__beta26.maximumBstDisplayLabel(val),
                                  42, self.marqueeTime), 112 + valueShift, drawY)
                          elseif key == "random_evolution_balance" then
                              Font.draw(marqueePixelText(
                                  ({ [0]="CHAOS", [1]="DEPTH", [2]="SIM BST", [3]="BALANCED" })[tonumber(val) or 0] or "CHAOS",
                                  50, self.marqueeTime), 104 + valueShift, drawY)
                          elseif key == "random_trainer_balance" then
                              Font.draw(marqueePixelText(
                                  ({ [0]="CHAOS", [1]="EVO", [2]="SIM BST", [3]="BALANCED" })[tonumber(val) or 0] or "CHAOS",
                                  50, self.marqueeTime), 104 + valueShift, drawY)
                          elseif key == "random_trainer_diversity" then
                              Font.draw(marqueePixelText(
                                  ({ [0]="OFF", [1]="DIVERSE", [2]="UNIQUE" })[tonumber(val) or 0] or "OFF",
                                  50, self.marqueeTime), 104 + valueShift, drawY)
                          elseif key == "random_trainer_theme" then
                              Font.draw(marqueePixelText(
                                  ({ [0]="OFF", [1]="TYPE" })[tonumber(val) or 0] or "OFF",
                                  50, self.marqueeTime), 104 + valueShift, drawY)
                          elseif key == "random_shop_balance" then
                              Font.draw(marqueePixelText(
                                  ({ [0]="CHAOS", [1]="PRICE", [2]="BALANCED" })[tonumber(val) or 2] or "BALANCED",
                                  50, self.marqueeTime), 104 + valueShift, drawY)
                          elseif key == "random_tm_compatibility" then
                              Font.draw(marqueePixelText(
                                  ({ [0]="MOVE", [1]="SLOT", [2]="FULL" })[tonumber(val) or 0] or "MOVE",
                                  50, self.marqueeTime), 104 + valueShift, drawY)
                          else
                              Font.draw(numberText, 118 + valueShift, drawY)
                          end
                          if isSelected and self.editingNumber then
                              local prefix = (key == "starting_money"
                                  or key == "gold_starting_money") and 1 or 0
                              local editX = key == "randomizer_seed" and 104 or 118
                              Font.draw(Strings("^"), editX + valueShift + ((self.digitIndex - 1) + prefix) * 6, drawY - 8)
                          end
                      else
                          local status = item.isStartNewGameControl and "START"
                              or (key == "dev_self_test_export" and "RUN"
                              or (isWip and "WIP" or (val and "ON" or "OFF")))
                          Font.draw(Strings(status), 118 + valueShift, drawY)
                      end

                      love.graphics.setColor(0, 0, 0, 1)
                  end
              end

              local selItem = flatItemList[self.cursor]

              if selItem and not selItem.isHeader then
                  -- 2.4.16: editingNumber can only be entered from a real numeric
                  -- rule row, so its instructions must live in this selected-row
                  -- branch. The old placement in the outer else was unreachable.
                  if self.editingNumber then
                      Font.draw(Strings("LR:Digit  UD:Value"), 14, 104)
                      Font.draw(Strings("A:Confirm  B:Back"), 14, 120)
                  else
                      local displayedDescription = ruleDescriptionForDisplay(selItem.rule, self.preGame)
                      if selItem.rule.key == "locke_type" then
                          local mode = math.max(0, math.min(6, math.floor(tonumber(
                              getConfigValue("locke_type", self.preGame)) or 0)))
                          if mode == 0 then
                              local summary = LockePreset.customSummary(self.preGame)
                              if summary then
                                  displayedDescription = tostring(summary) .. ". "
                                      .. tostring(displayedDescription or "")
                              end
                          end
                      end
                      if selItem.rule.key == "rules_locked"
                          and not mod.exports.__beta26.permanentRuleSealWip then
                          if self.lockConfirmStage == 1 then
                              displayedDescription = Strings(
                                  "WARNING 1/2: Permanent Rule Seal cannot be undone. Select SEAL again to continue, or move away/B to cancel.")
                          elseif self.lockConfirmStage == 2 then
                              displayedDescription = Strings(
                                  "FINAL WARNING 2/2: One more SEAL activation permanently locks challenge rules. Move away/B to cancel.")
                          end
                      end
                      -- Reserve a right gutter for the lower-pane scroll
                      -- marker so the glyph never covers description text.
                      local descWrapBudget = math.max(88, surfaceWidth - 40)
                      local descLines = wrapPixelText(displayedDescription,
                          descWrapBudget)
                      local maxScroll = math.max(0, #descLines - 3)

                      if self.descScroll > maxScroll then
                          self.descScroll = maxScroll
                      end

                      local startLine = self.descScroll + 1
                      -- Show up to 3 lines; third line stays clear for the
                      -- scroll arrow so it never overlaps text.
                      local endLine = math.min(#descLines, startLine + 2)

                      -- 2.6.36: keep all lower-pane text fully inside the
                      -- 6-tile help frame. Use the safe 104/116/128 cadence and
                      -- keep the more-text arrow on the same final baseline.
                      local descY = 104
                      for li = startLine, endLine do
                          Font.draw(descLines[li], 14, descY)
                          descY = descY + 12
                      end

                      -- Blink only when another description page exists,
                      -- in the reserved lower-right gutter.
                      if self.descScroll < maxScroll then
                          local blinkOn = math.floor(self.marqueeTime / 0.8) % 2 == 0
                          if blinkOn then
                              local Theme = require("src.ui.Theme")
                              Font.drawCode(Theme.moreArrow or 0xEE,
                                  surfaceWidth - 16, 128)
                          end
                      end
                  end
              else
                  -- Help text when no rule is focused (e.g. on a header row,
                  -- which shouldn't happen with the cursor skip logic, but
                  -- show sensible hints anyway).
                  if selItem and selItem.isHeader then
                      local key = selItem.sectionKey or sectionKey(selItem)
                      local summary = collapsedSectionSummary(selItem)
                      if summary then
                          Font.draw(fitPixelText(summary, surfaceWidth - 28), 14, 104)
                      end
                      Font.draw(Strings("SEL: RESET"), 14, 116)
                      Font.draw(Strings("A/LR:FOLD SEL+UD:JUMP"), 14, 128)
                  elseif locked then
                      Font.draw(Strings("Rules are LOCKED."), 14, 104)
                      Font.draw(Strings("A on Lock to open."), 14, 120)
                  else
                      Font.draw(Strings("A or LR: Toggle"), 14, 104)
                      Font.draw(Strings("SEL: More text"), 14, 116)
                      Font.draw(Strings("B: Back"), 14, 128)
                  end
              end
              love.graphics.setColor(1, 1, 1, 1)
              end
              return drawGen1Surface()
          end

          -- 2.1.20: protect first runtime frames without mutating the
          -- StateStack from inside draw(). 2.1.19 could catch a draw exception
          -- and then pop the screen while StateStack/Renderer was iterating it,
          -- turning a recoverable custom-screen failure into a hard crash.
          -- Record draw failures and surface them on the next update tick.
          do
              local function queueRuntimeFail(phase, err)
                  if self.__nuzRuntimeError then return end
                  local msg = tostring(err or "unknown config-screen runtime error")
                  self.__nuzRuntimeError = {
                      phase = tostring(phase or "runtime"),
                      message = msg,
                  }
                  mod.exports.__beta26.lastConfigScreenError =
                      self.__nuzRuntimeError.phase .. ": " .. msg
                  -- 2.4.60: preserve the full xpcall/debug.traceback payload in
                  -- Dev Mode before the player-facing dialog shortens it.
                  local Dev = mod.exports.__beta26.Dev
                  if Dev and type(Dev.recordError) == "function" then
                      pcall(Dev.recordError,
                          "config_screen_" .. self.__nuzRuntimeError.phase,
                          msg, self.game)
                  end
              end

              local function presentRuntimeFail()
                  local failure = self.__nuzRuntimeError
                  if not failure or self.__nuzRuntimeErrorPresented then return false end
                  self.__nuzRuntimeErrorPresented = true
                  local game = self.game
                  if not (game and game.stack) then return true end
                  pcall(function()
                      if type(game.stack.pop) == "function" then game.stack:pop() end
                  end)
                  local short = tostring(failure.message):gsub("^.-:%s*", "")
                  if #short > 180 then short = short:sub(1, 180) .. "..." end
                  local surface = self.preGame and "SETUP" or "RULES"
                  local body = mod.exports.__beta26.manualPagedErrorText(
                      "NUZ " .. surface .. " "
                          .. tostring(failure.phase):upper() .. " ERROR",
                      short)
                  local okText, TextBox = pcall(require, "src.render.TextBox")
                  if okText and TextBox then
                      pcall(function() game.stack:push(TextBox.new(game, body)) end)
                  end
                  return true
              end

              local rawUpdate = self.update
              if type(rawUpdate) == "function" then
                  self.update = function(...)
                      if presentRuntimeFail() then return end
                      local args = { ... }
                      local ok, result = xpcall(function()
                          return rawUpdate(unpackValues(args))
                      end, debug and debug.traceback or tostring)
                      if not ok then
                          queueRuntimeFail("update", result)
                          presentRuntimeFail()
                          return
                      end
                      return result
                  end
              end

              local rawDraw = self.draw
              if type(rawDraw) == "function" then
                  self.draw = function(...)
                      if self.__nuzRuntimeError then return end
                      local args = { ... }
                      local ok, result = xpcall(function()
                          return rawDraw(unpackValues(args))
                      end, debug and debug.traceback or tostring)
                      if not ok then
                          queueRuntimeFail("draw", result)
                          return
                      end
                      return result
                  end
              end
          end

          return self
      end
  })

