  -- 0.1.86+ CUSTOM-SCREEN CRASH GUARD
  --
  -- Screens.push() isolates a failing mod-owned screen factory, then tries a
  -- built-in fallback. NuzlockeConfigScreen is custom-only, so a failed
  -- construction can turn into a second missing-builtin failure and CTD.
  --
  -- Deliberately stored on exports rather than as another top-level local:
  -- this monolithic chunk is already at Lua's 200-local ceiling.
  ---------------------------------------------------------------------
  mod.exports.__beta26.lastConfigScreenError = nil
  mod.exports.__beta26.pushNuzlockeConfigScreen = function(game, opts)
      local ok, result = pcall(mod.ui.push, game, "NuzlockeConfigScreen",
          opts or {})
      if ok and result then
          mod.exports.__beta26.lastConfigScreenError = nil
          return result
      end

      local err = tostring(result or "unknown setup-screen construction error")
      mod.exports.__beta26.lastConfigScreenError = err
      local short = err:gsub("^.-:%s*", "")
      if #short > 180 then short = short:sub(1, 180) .. "..." end
      local body = mod.exports.__beta26.manualPagedErrorText(
          "NUZLOCKE SETUP ERROR", short)

      local okText, TextBox = pcall(require, "src.render.TextBox")
      if okText and TextBox and game and game.stack then
          local shown = pcall(function()
              game.stack:push(TextBox.new(game, body))
          end)
          if shown then return false end
      end
      return false
  end

  ---------------------------------------------------------------------
  -- TITLE MENU HOOK
  --
  -- SETUP is a NEW-GAME-only entry. The engine's own final title menu is
  -- authoritative: if it contains CONTINUE, a valid save exists for the
  -- currently selected version/slot and SETUP must stay hidden.
  ---------------------------------------------------------------------
  mod.hooks:wrap("ui.title_menu.items", function(next, game, items)
      local result = next(game, items)
      if type(result) ~= "table" then
          result = items
      end

      -- Fresh-game SETUP and NEW GAME/CONTINUE staging belong only to a real
      -- title session. The embedded Save Editor may expose title-like rows but
      -- must remain untouched so it cannot stage a gameplay setup profile.
      if mod.exports.__beta26.isSaveEditorSession() then
          return result
      end

      local goldMode = mod.exports.__beta26.runtimeIsGen2(game)
      if goldMode and type(mod.exports.__beta26.installGoldTitleSetupAdapter) == "function" then
          mod.exports.__beta26.attemptInstall("setup.gen2_title_adapter", mod.exports.__beta26.installGoldTitleSetupAdapter)
      end
      local function titleLabel(item)
          if type(item) ~= "table" then return nil end
          local label = item.label
          if type(label) == "table" then
              label = label.source or label.text or label.label
          end
          return type(label) == "string" and label:upper() or nil
      end
      local function isContinueItem(item)
          if type(item) ~= "table" then return false end
          if item.value == "continue" then return true end
          local label = titleLabel(item)
          return label == "CONTINUE" or label == tostring(Strings("CONTINUE")):upper()
      end
      local function isNewGameItem(item)
          if type(item) ~= "table" then return false end
          if item.value == "new" then return true end
          local label = titleLabel(item)
          return label == "NEW GAME" or label == tostring(Strings("NEW GAME")):upper()
      end
      local function insertSetupBeforeNewGame(setup)
          for index, item in ipairs(result) do
              if isNewGameItem(item) then
                  table.insert(result, index, setup)
                  return true
              end
          end
          return false
      end

      for _, item in ipairs(result) do
          -- NEW GAME: stage the pending rules for the upcoming save.
          -- This is the established R/B/Y callback path used by beta.20 and
          -- earlier. Gen 2 uses its native value-dispatch adapter below.
          if isNewGameItem(item) and type(item.onSelect) == "function"
              and item.nuzlockeNewGameWrapped ~= true then
              local originalNewGame = item.onSelect
              item.nuzlockeNewGameWrapped = true
              item.onSelect = function()
                  pcall(installAutomaticDefaultNameAdapters)
                  mod.exports.__beta26.selectSetupProfileScope(game)
                  if not pendingNewGameRules or not pendingRulesDirty then
                      pendingNewGameRules = loadSetupProfileFromDisk()
                          or makeDefaultPreGameRules()
                      pendingRulesDirty = false
                  end
                  -- Unlike the standalone SETUP row, NEW GAME enters
                  -- configuration with an explicit START/CANCEL result.
                  mod.exports.__beta26.pushNuzlockeConfigScreen(game, {
                      preGame = true, goldMode = false, autoNewGame = true,
                      onDone = function(accepted)
                          if accepted then originalNewGame() end
                      end,
                  })
              end
          end

          -- CONTINUE: discard any staged setup so it can never override
          -- the existing save's rules.
          if isContinueItem(item) and type(item.onSelect) == "function"
              and item.nuzlockeContinueWrapped ~= true then
              local originalContinue = item.onSelect
              item.nuzlockeContinueWrapped = true
              item.onSelect = function()
                  pendingNewGameRulesForNextSave = false
                  pendingRulesDirty = false
                  newGameRulesSnapshot = nil
                  newGameRulesCommitPending = false
                  newGameCommitPassesRemaining = 0
                  clearPersistedStagedProfile()
                  originalContinue()
              end
          end
      end

      -- Beta.20's R/B/Y rule: trust the FINAL vanilla menu only for whether
      -- CONTINUE exists, then insert SETUP before NEW GAME. Do not require a
      -- particular NEW GAME row shape before inserting the R/B/Y entry.
      local hasContinue = false
      local hasSetup = false
      for _, item in ipairs(result) do
          if isContinueItem(item) then hasContinue = true end
          if type(item) == "table" and (item.nuzlockeSetup == true
              or item.value == "nuzlocke_setup") then hasSetup = true end
      end

      if not goldMode then
          if not hasContinue and not hasSetup then
              insertSetupBeforeNewGame({
                  label = Strings("SETUP"),
                  nuzlockeSetup = true,
                  onSelect = function()
                      mod.exports.__beta26.selectSetupProfileScope(game)
                      if not pendingNewGameRules or not pendingRulesDirty then
                          pendingNewGameRules = loadSetupProfileFromDisk()
                              or makeDefaultPreGameRules()
                          pendingRulesDirty = false
                      end
                      mod.exports.__beta26.pushNuzlockeConfigScreen(game,
                          { preGame = true, goldMode = false })
                  end
              })
          end
      else
          -- Preserve Gen 2's dedicated row/value path, but obey the same
          -- NEW-GAME-only contract as R/B/Y. Gold exposes both CONTINUE and
          -- NEW GAME when a save exists, so checking only the NEW GAME value
          -- incorrectly left SETUP visible beside CONTINUE.
          local newGameRow
          for _, item in ipairs(result) do
              if isNewGameItem(item) then
                  newGameRow = item
                  break
              end
          end
          if not hasContinue and not hasSetup and newGameRow
              and newGameRow.value == "new" then
              insertSetupBeforeNewGame({
                  label = Strings("SETUP"),
                  value = "nuzlocke_setup",
                  nuzlockeSetup = true,
              })
          end
      end

      return result
  end)

  ---------------------------------------------------------------------
  -- 0.1.86 TITLE-SETUP COMPATIBILITY FALLBACK
  --
  -- The public ui.title_menu.items seam remains the primary path. Runtime
  -- testing on 0.1.86 showed that a genuinely fresh Blue AND Gold boot could
  -- nevertheless reach the vanilla title list without our SETUP row. Because
  -- this mod already requests engine_internals, install a conservative
  -- belt-and-suspenders adapter around each generation's title-list builder.
  --
  -- The fallback runs AFTER vanilla/public-hook construction and changes
  -- nothing when SETUP is already present. It therefore cannot double-insert.
  ---------------------------------------------------------------------
  -- 2.3.10 / Yellow 0.1.98 boot safety: the public
  -- ui.title_menu.items path is runtime-confirmed working in 2.3.9. Keep the
  -- historical compatibility file in the unchanged package tree, but do not
  -- execute its engine-internal TitleState fallback during startup.
  mod.exports.__beta26.legacyTitleSetupFallbackDeferred = true

  -- 2.9.49: active Gen-II title SETUP wrapping/list ownership now lives in
  -- title_setup_compat.lua. Setup-profile lifecycle remains in this composition
  -- root and crosses the boundary only through explicit callbacks.
  loadRequiredModuleChunk("title_setup_compat.lua")().installGen2(mod, {
      Strings = Strings,
      runtimeIsGen2 = mod.exports.__beta26.runtimeIsGen2,
      isSaveEditorSession = mod.exports.__beta26.isSaveEditorSession,
      openSetup = function(game, onDone)
          mod.exports.__beta26.selectSetupProfileScope(game)
          if not pendingNewGameRules or not pendingRulesDirty then
              pendingNewGameRules = loadSetupProfileFromDisk()
                  or makeDefaultPreGameRules()
              pendingRulesDirty = false
          end
          mod.exports.__beta26.pushNuzlockeConfigScreen(game, {
              preGame = true, goldMode = true,
              autoNewGame = type(onDone) == "function",
              onDone = onDone,
          })
      end,
      stageNewGame = function(game)
          pcall(installAutomaticDefaultNameAdapters)
          mod.exports.__beta26.selectSetupProfileScope(game)
          if not pendingNewGameRules then
              pendingNewGameRules = loadSetupProfileFromDisk()
                  or makeDefaultPreGameRules()
          end
          saveSetupProfileToDisk(pendingNewGameRules)
          stageNewGameProfile()
      end,
      clearContinue = function()
          pendingNewGameRulesForNextSave = false
          pendingRulesDirty = false
          newGameRulesSnapshot = nil
          newGameRulesCommitPending = false
          newGameCommitPassesRemaining = 0
          clearPersistedStagedProfile()
      end,
  })


  ---------------------------------------------------------------------
  -- NUZ MENU
  -- 2.7.101: every Nuzlocke-owned ordinary START-menu destination is
  -- consolidated behind one stable entry. Party/stat-page NUZ INFO is
  -- deliberately not part of this surface and remains where the host owns it.
  ---------------------------------------------------------------------
  mod.content.screens:register("NuzlockeMenuScreen", {
      isModOptions = true,
      new = function(game)
          local gen2 = mod.exports.__beta26.runtimeIsGen2(game)
          local rows = {
              {
                  label = "NUZ RULES",
                  open = function()
                      mod.exports.__beta26.pushNuzlockeConfigScreen(game)
                  end,
              },
              {
                  label = "ENC TRACKER",
                  open = function()
                      mod.ui.push(game, "NuzlockeTrackerScreen")
                  end,
              },
              {
                  label = "NUZ STATUS",
                  open = function()
                      if gen2 then
                          mod.ui.push(game, "NuzlockeGoldStatusScreen")
                      else
                          mod.ui.push(game, "NuzlockeTrainerCardScreen",
                              { statusOnly = true })
                      end
                  end,
              },
              {
                  label = "GRAVEYARD",
                  open = function()
                      if type(mod.exports.__beta26.pushGraveyardViewer) == "function" then
                          mod.exports.__beta26.pushGraveyardViewer(game)
                      end
                  end,
              },
              {
                  label = "ALMANAC",
                  open = function()
                      if type(mod.exports.__beta26.pushAlmanac) == "function" then
                          mod.exports.__beta26.pushAlmanac(game)
                      end
                  end,
              },
              {
                  label = "MOD COMPAT",
                  open = function()
                      mod.ui.push(game, "NuzlockeModCompatScreen")
                  end,
              },
          }
          if mod.exports.__beta26.Dev.enabled() then
              rows[#rows + 1] = {
                  label = "DEV TOOLS",
                  open = function()
                      mod.ui.push(game, "NuzlockeDevToolsScreen")
                  end,
              }
          end
          -- Destructive run lifecycle action is always the final menu row.
          rows[#rows + 1] = {
              label = "END RUN",
              open = function()
                  if type(mod.exports.__beta26.pushEndRun) == "function" then
                      mod.exports.__beta26.pushEndRun(game)
                  end
              end,
          }

          local self = {
              game = game, screenId = "NuzlockeMenuScreen",
              isOpaque = true, rows = rows, index = 1, scroll = 0,
              visibleRows = 6,
          }
          mod.exports.__beta26.UiSystem.applyLayout(self, "centered")

          local function syncMenuScroll()
              local visible = self.visibleRows or 6
              if self.index <= self.scroll then self.scroll = self.index - 1 end
              if self.index > self.scroll + visible then
                  self.scroll = self.index - visible
              end
              self.scroll = math.max(0, math.min(
                  math.max(0, #self.rows - visible), self.scroll or 0))
          end

          function self:update(_dt)
              if game.input:wasPressed("up") then
                  self.index = math.max(1, self.index - 1)
                  syncMenuScroll()
              elseif game.input:wasPressed("down") then
                  self.index = math.min(#self.rows, self.index + 1)
                  syncMenuScroll()
              elseif game.input:wasPressed("b") then
                  game.stack:pop()
              elseif game.input:wasPressed("a") then
                  local row = self.rows[self.index]
                  if row and type(row.open) == "function" then row.open() end
              end
          end

          function self:draw()
              if gen2 then
                  local Chrome = require("src.ui.gen2.Chrome")
                  local Font = require("src.render.Font")
                  Chrome.clear()
                  Chrome.box(0, 0, 20, 18)
                  mod.exports.__beta26.drawGen2NuzTitle(
                      Chrome, Font, "NUZ MENU", nil, { row = 1 })
                  local first = (self.scroll or 0) + 1
                  local last = math.min(#self.rows, first + (self.visibleRows or 6) - 1)
                  local slot = 0
                  for i = first, last do
                      local row = self.rows[i]
                      local y = 4 + slot * 2
                      if i == self.index then Chrome.cursor(1, y) end
                      Chrome.print(Strings(row.label), 3, y)
                      slot = slot + 1
                  end
                  if first > 1 then Chrome.cursor(18, 3, true) end
                  if last < #self.rows then Chrome.cursor(18, 15, true) end
                  Chrome.print(Strings("A:OPEN  B:BACK"), 2, 16)
                  return
              end

              local Font = require("src.render.Font")
              local Theme = require("src.ui.Theme")
              local function trackedWidth(value, tracking)
                  local label = Strings(tostring(value or ""))
                  tracking = tracking or 1
                  local spans = type(Font.split) == "function"
                      and Font.split(label) or nil
                  if type(spans) ~= "table" or #spans == 0 then
                      return type(Font.width) == "function"
                          and Font.width(label) or (#label * 8)
                  end
                  local width = 0
                  for i, span in ipairs(spans) do
                      local glyph = label:sub(span.from, span.to)
                      width = width + (type(Font.width) == "function"
                          and Font.width(glyph) or 8)
                      if i < #spans then width = width + tracking end
                  end
                  return width
              end
              local function centeredTrackedBold(value, y)
                  local label = Strings(tostring(value or ""))
                  local spans = type(Font.split) == "function"
                      and Font.split(label) or nil
                  local x = math.max(8, math.floor(
                      (160 - trackedWidth(label, 1)) / 2))
                  if type(spans) ~= "table" or #spans == 0 then
                      Font.draw(label, x, y); Font.draw(label, x + 1, y)
                      return
                  end
                  for i, span in ipairs(spans) do
                      local glyph = label:sub(span.from, span.to)
                      Font.draw(glyph, x, y); Font.draw(glyph, x + 1, y)
                      x = x + (type(Font.width) == "function"
                          and Font.width(glyph) or 8)
                      if i < #spans then x = x + 1 end
                  end
              end

              love.graphics.setColor(1, 1, 1, 1)
              love.graphics.rectangle("fill", 0, 0, 160, 144)
              Font.drawBox(0, 0, 20, 18)
              love.graphics.setColor(0, 0, 0, 1)
              centeredTrackedBold("NUZ MENU", 8)
              local first = (self.scroll or 0) + 1
              local last = math.min(#self.rows, first + (self.visibleRows or 6) - 1)
              local slot = 0
              for i = first, last do
                  local row = self.rows[i]
                  local y = 32 + slot * 16
                  if i == self.index then
                      Font.drawCode(Theme.cursor, 8, y)
                  end
                  Font.draw(Strings(row.label), 24, y)
                  slot = slot + 1
              end
              if first > 1 then Font.draw(Strings("^"), 144, 24) end
              if last < #self.rows then Font.draw(Strings("v"), 144, 112) end
              Font.draw(Strings("A:OPEN  B:BACK"), 16, 128)
              love.graphics.setColor(1, 1, 1, 1)
          end
          return self
      end,
  })

  ---------------------------------------------------------------------
  -- START MENU HOOKS
  --
  -- IMPORTANT: build from the VANILLA result first, then modify that
  -- returned list.  Calling insertBefore() on the incoming `items` and
  -- then calling next() causes the vanilla hook to rebuild the list and
  -- silently discard our inserted entries.  That was why RULES/TRACKER
  -- disappeared in the previous build.
  ---------------------------------------------------------------------
  mod.hooks:wrap("ui.start_menu.items", function(next, game, items)
      local result = next(game, items)
      if type(result) ~= "table" then
          result = items
      end

      -- The hook already supplies the game whose menu is being built.
      -- Do not consult the global/current-game version here: during Gold menu
      -- construction that can lag behind and select the wider R/B/Y labels,
      -- which draw through Gold's narrow native START-menu border.
      local goldMenu = mod.exports.__beta26.runtimeIsGen2(game)
      -- Gen 1 localizes this row before the hook; Gold currently exposes a
      -- raw label plus a stable id. Resolve the actual rendered label so both
      -- implementations and translation mods remain valid insertion anchors.
      -- 2.2.9: a full Permadeath wipe can leave an empty party before
      -- vanilla recovery. Runtime testing confirmed entering the native POKEMON
      -- screen in that state can CTD. Preserve the native row but reject its
      -- action until the party contains a Pokemon again.
      for _, item in ipairs(result) do
          if type(item) == "table" then
              local id = tostring(item.id or item.action or item.value or ""):upper()
              local label = tostring(item.label or ""):upper()
              if id == "POKEMON" or label == "POKEMON" then
                  local nativeSelect = item.onSelect
                  if type(nativeSelect) == "function"
                      and item.__nuzlockeEmptyPartyGuard ~= true then
                      item.onSelect = function(...)
                          local party = game and game.save and game.save.party
                          if mod.save:get("nuzlocke_enabled", true) == true
                              and mod.save:get("permadeath", true) == true
                              and type(party) == "table" and #party == 0 then
                              mod.exports.__beta26.pushWorldText(game,
                                  "Your party is empty. Use the PC before opening POKEMON.")
                              return
                          end
                          return nativeSelect(...)
                      end
                      item.__nuzlockeEmptyPartyGuard = true
                  end
              end
          end
      end

      local optionAnchor = "OPTION"
      for _, item in ipairs(result) do
          if type(item) == "table" and (
              tostring(item.id or ""):upper() == "OPTION"
              or tostring(item.action or ""):upper() == "OPTION"
              or tostring(item.value or ""):upper() == "OPTION"
              or tostring(item.label or ""):upper() == "OPTION"
              or item.label == Strings("OPTION")) then
              optionAnchor = item.label or optionAnchor
              break
          end
      end

      -- 2.7.101: expose exactly one Nuzlocke-owned row in the ordinary
      -- START menu. All former Nuzlocke START destinations now live inside
      -- NUZ MENU. Native rows and Pokemon/stat-page NUZ INFO are untouched.
      mod.ui.insertBefore(result, optionAnchor, {
          -- 2.9.29: stable semantic identity is presentation/localization neutral.
          -- Modern START renderers may key icons/preferences from this id while
          -- preserving the callback and without recognizing the translated label.
          id = "nuzlocke.menu",
          label = goldMenu and Strings("NUZ MENU") or Strings("NUZ MENU"),
          desc = goldMenu and { Strings("Nuzlocke"), Strings("menus") }
              or { Strings("Nuzlocke menus") },
          __nuzlockeMenuRow = true,
          onSelect = function()
              mod.ui.push(game, "NuzlockeMenuScreen")
          end,
      })

      return result
  end)

  ---------------------------------------------------------------------
  -- R/B/Y NATIVE NUZ INFO
  -- 2.2.0: NUZ ST. and MOD COMPAT became stable after moving off custom
  -- hand-drawn states in 2.1.22. Party NUZ INFO was the remaining R/B/Y
  -- outlier and still opened NuzlockeCatchInfoScreen. Build the same API-27
  -- read-only Pokemon data into Gen1Recomp's host-owned ListMenu instead.
  -- Gold retains the native-styled custom page implementation below.
  ---------------------------------------------------------------------
  mod.exports.__beta26.pushRbyNuzInfoNative = function(game, mon)
      local api = mod.exports.nuzlocke_compat
      local info, infoError
      if api and type(api.getPokemonNuzInfo) == "function" then
          local ok, value = pcall(api.getPokemonNuzInfo, game, mon)
          if ok and type(value) == "table" then
              info = value
          elseif not ok then
              infoError = tostring(value)
          end
      end

      -- Preserve the player's page toggles exactly. A previous safety fallback
      -- silently collapsed an empty/failed page list back to CATCH only, which
      -- made NUZ INFO look incomplete. If the API page helper fails, read the
      -- same three save-backed toggles directly instead.
      local pages
      if api and type(api.getNuzInfoPages) == "function" then
          local ok, value = pcall(api.getNuzInfoPages)
          if ok and type(value) == "table" then pages = value end
      end
      if type(pages) ~= "table" then
          pages = {}
          if mod.save:get("catch_info", true) == true then pages[#pages + 1] = "catch" end
          if mod.save:get("stat_info", true) == true then pages[#pages + 1] = "stat" end
          if mod.save:get("move_info", true) == true then pages[#pages + 1] = "move" end
      end
      local enabled = {}
      for _, page in ipairs(pages) do enabled[tostring(page)] = true end

      -- If the richer API model ever fails, build a complete read-only model
      -- directly from the selected Pokemon instead of degrading to four CATCH
      -- rows. This keeps the crash-safe host ListMenu while retaining Catch,
      -- Stats, and Moves information.
      if not info then
          local directMoves = {}
          for i, move in ipairs(type(mon and mon.moves) == "table" and mon.moves or {}) do
              local id = type(move) == "table" and move.id or move
              local def = game and game.data and game.data.moves
                  and game.data.moves[id] or nil
              directMoves[i] = {
                  id = id,
                  name = def and def.name or tostring(id or "?"),
                  type = def and def.type or nil,
                  power = def and def.power or nil,
                  accuracy = def and def.accuracy or nil,
                  pp = type(move) == "table" and move.pp or nil,
                  maxPp = (type(move) == "table" and move.maxPp)
                      or (def and def.pp) or nil,
              }
          end
          info = {
              catch = {
                  location = mon and mon.catchLocation,
                  encounterType = mon and (mon.encounterType or mon.nuzlockeEncounterType),
                  origin = mon and mon.nuzlockeOrigin,
                  dead = mon and mon.nuzlockeDead == true,
                  cause = mon and (mon.deathCauseText or mon.deathCause),
              },
              stats = {
                  level = mon and mon.level,
                  hp = mon and mon.hp,
                  maxHp = mon and (mon.maxHp or (mon.stats and mon.stats.hp)),
                  values = type(mon and mon.stats) == "table" and mon.stats or {},
                  dvs = type(mon and mon.dvs) == "table" and mon.dvs or {},
                  statExp = type(mon and mon.statExp) == "table" and mon.statExp or {},
              },
              moves = directMoves,
              safeMode = true,
          }
      end

      local items = {}
      local activeNuzInfoPage = nil
      local function text(v, fallback)
          if v == nil or v == "" then return fallback or "--" end
          return tostring(v)
      end
      local function numberText(v)
          v = tonumber(v)
          return v and tostring(math.floor(v)) or "--"
      end
      local function nuzInfoRight(value, glyphBudget)
          if value == nil then return nil end
          local raw = tostring(value)
          local Font = mod.exports.__beta26.getFontModule
              and mod.exports.__beta26.getFontModule() or nil
          if Font and type(Font.split) == "function" then
              local ok, spans = pcall(Font.split, raw)
              if ok and type(spans) == "table" and #spans > (glyphBudget or 9) then
                  local last = spans[glyphBudget or 9]
                  if type(last) == "table" and tonumber(last.to) then
                      return raw:sub(1, tonumber(last.to))
                  end
              end
          end
          return raw
      end

      local function add(label, right, opts)
          -- STAT rows have far more unused space on the left than CATCH rows.
          -- Preserve the full worst-case Gen I value string (e.g.
          -- "999 D15 E65535") instead of clipping it to the generic 9-glyph
          -- right-column budget before draw-time layout can use that space.
          local rightBudget = activeNuzInfoPage == "stat" and 14
              or (activeNuzInfoPage == "catch" and 10 or 9)
          items[#items + 1] = {
              label = Strings(tostring(label or "")),
              right = right ~= nil and Strings(nuzInfoRight(right, rightBudget)) or nil,
              nuzInfoPage = activeNuzInfoPage,
              nuzInfoWideStat = opts and opts.wideStat == true or nil,
          }
      end
      local function section(label, page)
          activeNuzInfoPage = page
      end
      local function pageOff(label)
          local page = tostring(label):lower():match("catch") and "catch"
              or tostring(label):lower():match("stat") and "stat"
              or "move"
          section(label, page)
          add("PAGE", "OFF")
      end

      if enabled.catch then
          section("CATCH INFO", "catch")
          local catch = type(info.catch) == "table" and info.catch or {}
          -- 2.6.33: use the cartridge's native PKMN ligature and a compact
          -- encounter label so the value column can start farther left without
          -- crowding the row labels on the 160px classic surface.
          add("<PK><MN>", mod.exports.__beta26.safeSpeciesLabel(game, mon and mon.species))
          local location = catch.location or (mon and mon.catchLocation) or "UNKNOWN"
          local okRoute, routeLabel = pcall(routeName, location)
          add("LOC.", okRoute and routeLabel or tostring(location))
          add("ENC.", text(catch.encounterType, "UNKNOWN"):upper())
          add("ORIGIN", text(catch.origin, "NORMAL"):upper())
          add("STATUS", catch.dead and "LOST" or "ALIVE")
          if catch.shiny ~= nil then add("SHINY", catch.shiny and "YES" or "NO") end
          if catch.cause ~= nil and tostring(catch.cause) ~= "" then
              add("CAUSE", tostring(catch.cause))
          end
          local legal = catch.legality
          if type(legal) == "table" then
              add("LEGALITY", text(legal.status, legal.legal == false and "RESTRICTED" or "LEGAL"))
              if type(legal.reasons) == "table" and #legal.reasons > 0 then
                  add("RULE", table.concat(legal.reasons, "/"))
              end
              if legal.bst ~= nil then add("BST", numberText(legal.bst)) end
              if legal.maximumBST and tonumber(legal.maximumBST) and tonumber(legal.maximumBST) > 0 then
                  add("BST LIMIT", numberText(legal.maximumBST))
              end
          else
              add("LEGALITY", "UNKNOWN")
          end
          local provenance = catch.provenance
          if type(provenance) == "table" then
              if provenance.provider then add("PROVIDER", tostring(provenance.provider)) end
              if provenance.source then add("SOURCE", tostring(provenance.source)) end
              if provenance.identityProvider
                  and provenance.identityProvider ~= provenance.provider then
                  add("IDENTITY", tostring(provenance.identityProvider))
              end
              if provenance.externalIdentity ~= nil then
                  add("EXTERNAL", provenance.externalIdentity and "YES" or "NO")
              end
          end
          if info.safeMode or infoError then add("DETAIL", "SAFE MODE") end
      else
          pageOff("CATCH INFO")
      end

      if enabled.stat then
          section("STAT INFO", "stat")
          local stats = type(info.stats) == "table" and info.stats or {}
          add("LEVEL", numberText(stats.level))
          add("HP", ("%s/%s"):format(numberText(stats.hp), numberText(stats.maxHp)))
          local values = type(stats.values) == "table" and stats.values or {}
          local dvs = type(stats.dvs) == "table" and stats.dvs or {}
          local exp = type(stats.statExp) == "table" and stats.statExp or {}
          local function statRow(label, value, dv, statExp)
              add(label, ("%s D%s E%s"):format(
                  numberText(value), numberText(dv), numberText(statExp)),
                  { wideStat = true })
          end
          statRow("ATK", values.attack, dvs.attack, exp.attack)
          statRow("DEF", values.defense, dvs.defense, exp.defense)
          statRow("SPE", values.speed, dvs.speed, exp.speed)
          statRow("SPC", values.special or values.spAttack,
              dvs.special or dvs.spAttack, exp.special or exp.spAttack)
      else
          pageOff("STAT INFO")
      end

      if enabled.move then
          section("MOVE INFO", "move")
          local moves = type(info.moves) == "table" and info.moves or {}
          for slot = 1, 4 do
              local move = moves[slot]
              if move then
                  local name = text(move.name or move.id, "?")
                  local typeName = text(move.type, "?"):upper():gsub("_TYPE$", "")
                  items[#items + 1] = {
                      label = Strings(tostring(slot) .. " " .. name),
                      right = Strings(typeName),
                      nuzInfoPage = "move",
                      nuzInfoMove = {
                          slot = slot,
                          name = name,
                          type = typeName,
                          power = numberText(move.power),
                          accuracy = numberText(move.accuracy),
                          pp = numberText(move.pp),
                          maxPp = numberText(move.maxPp),
                      },
                  }
              else
                  items[#items + 1] = {
                      label = Strings(tostring(slot) .. " --"),
                      right = "",
                      nuzInfoPage = "move",
                      nuzInfoMove = {
                          slot = slot,
                          name = "--",
                          type = "--",
                          power = "--",
                          accuracy = "--",
                          pp = "--",
                          maxPp = "--",
                      },
                  }
              end
          end
      else
          pageOff("MOVE INFO")
      end

      if #items == 0 then
          add("NO PAGES", "ENABLE IN RULES")
      end

      local pageOrder = {}
      if enabled.catch then pageOrder[#pageOrder + 1] = "catch" end
      if enabled.stat then pageOrder[#pageOrder + 1] = "stat" end
      if enabled.move then pageOrder[#pageOrder + 1] = "move" end
      if #pageOrder == 0 then pageOrder[1] = "catch" end

      local pageTitles = {
          catch = Strings("CATCH INFO"),
          stat = Strings("STAT INFO"),
          move = Strings("MOVE INFO"),
      }
      local pageBuckets = { catch = {}, stat = {}, move = {} }
      for _, item in ipairs(items) do
          local key = item.nuzInfoPage
          if key and pageBuckets[key] then
              pageBuckets[key][#pageBuckets[key] + 1] = item
          end
      end

      local okMenu, menu = pcall(mod.ui.ListMenu.new, game, Strings("NUZ INFO"),
          pageBuckets[pageOrder[1]] or {}, {
              keyRepeat = true,
              wrap = false,
              rows = 6,
              kind = "nuzlocke_nuz_info",
          })
      if not okMenu or type(menu) ~= "table" then
          local TextBox = require("src.render.TextBox")
          local box = TextBox.new(game, Strings("NUZ INFO could not open.\nYour Pokemon is safe."))
          game.stack:push(box)
          return box
      end

      menu.nuzInfoPageOrder = pageOrder
      menu.nuzInfoPageIndex = 1
      menu.nuzInfoPageBuckets = pageBuckets
      menu.rows = pageOrder[1] == "move" and 2 or 6
      menu.marqueeTime = 0

      local function setNuzInfoPage(self, index)
          local count = #self.nuzInfoPageOrder
          if count <= 0 then return end
          self.nuzInfoPageIndex = ((index - 1) % count) + 1
          local key = self.nuzInfoPageOrder[self.nuzInfoPageIndex]
          self.items = self.nuzInfoPageBuckets[key] or {}
          self.rows = key == "move" and 2 or 6
          self.index = 1
          self.scroll = 0
          self.marqueeTime = 0
      end

      local baseUpdate = menu.update
      menu.update = function(self, dt)
          self.marqueeTime = (self.marqueeTime or 0) + (dt or 0)
          local count = #self.nuzInfoPageOrder
          if count > 1 and (self.game.input:wasPressed("right")
              or self.game.input:wasPressed("a")) then
              setNuzInfoPage(self, self.nuzInfoPageIndex + 1)
              return
          elseif count > 1 and self.game.input:wasPressed("left") then
              setNuzInfoPage(self, self.nuzInfoPageIndex - 1)
              return
          end
          return baseUpdate(self, dt)
      end

      menu.draw = function(self)
          local Font = require("src.render.Font")
          local Theme = require("src.ui.Theme")
          Font.drawBox(0, 0, 20, 18)

          -- Slight tracking between glyphs without inserting literal spaces.
          -- This keeps translated strings semantically intact while making
          -- the two title lines breathe a little more on the native surface.
          local function trackedWidth(label, tracking)
              local spans = type(Font.split) == "function" and Font.split(label) or nil
              if type(spans) ~= "table" or #spans == 0 then
                  return (type(Font.width) == "function" and Font.width(label)
                      or #tostring(label) * 8)
              end
              local width = 0
              for i, span in ipairs(spans) do
                  local glyph = label:sub(span.from, span.to)
                  width = width + (type(Font.width) == "function"
                      and Font.width(glyph) or 8)
                  if i < #spans then width = width + tracking end
              end
              return width
          end

          local function centeredTrackedBold(value, y, tracking)
              local label = Strings(value)
              tracking = tracking or 1
              local spans = type(Font.split) == "function" and Font.split(label) or nil
              if type(spans) ~= "table" or #spans == 0 then
                  local width = trackedWidth(label, tracking)
                  local x = math.max(8, math.floor((160 - width) / 2))
                  Font.draw(label, x, y)
                  Font.draw(label, x + 1, y)
                  return
              end
              local x = math.max(8,
                  math.floor((160 - trackedWidth(label, tracking)) / 2))
              for i, span in ipairs(spans) do
                  local glyph = label:sub(span.from, span.to)
                  Font.draw(glyph, x, y)
                  Font.draw(glyph, x + 1, y)
                  x = x + (type(Font.width) == "function"
                      and Font.width(glyph) or 8)
                  if i < #spans then x = x + tracking end
              end
          end

          centeredTrackedBold("NUZ INFO", 6, 1)
          local pageKey = self.nuzInfoPageOrder[self.nuzInfoPageIndex] or "catch"
          centeredTrackedBold(pageTitles[pageKey] or "CATCH INFO", 22, 1)

          if pageKey == "move" then
              -- Two compact move cards fit cleanly on the native 160x144
              -- surface. Long move names get the full row and marquee;
              -- type/power and accuracy/PP are moved onto their own lines.
              for row = 1, self.rows do
                  local i = (self.scroll or 0) + row
                  local item = self.items[i]
                  if not item then break end
                  local move = item.nuzInfoMove or {}
                  local baseY = 38 + (row - 1) * 42
                  local name = tostring(move.name or "--")
                  local title = tostring(move.slot or i) .. " "
                      .. marqueeText(name, 14, self.marqueeTime, 2.8)
                  Font.draw(title, 12, baseY)

                  -- 2.3.35: keep each move card single-column. The previous
                  -- TYPE/PWR and ACC/PP split columns still collided on the
                  -- native 160px surface with long type names and 3-digit
                  -- values. Give TYPE its own full row, then compress numeric
                  -- combat data into stable short labels on the third row.
                  local typeLine = Strings("TYPE %s",
                      tostring(move.type or "--"))
                  Font.draw(marqueeText(typeLine, 17,
                      self.marqueeTime, 2.8), 20, baseY + 13)

                  local statsLine = Strings("P%s A%s PP%s/%s",
                      tostring(move.power or "--"),
                      tostring(move.accuracy or "--"),
                      tostring(move.pp or "--"),
                      tostring(move.maxPp or "--"))
                  Font.draw(marqueeText(statsLine, 17,
                      self.marqueeTime, 2.8), 20, baseY + 26)
              end
          else
              -- Catch/Stat rows use normal weight. Only the two title lines
              -- above are bold.
              for row = 1, self.rows do
                  local i = (self.scroll or 0) + row
                  local item = self.items[i]
                  if not item then break end
                  local y = 34 + (row - 1) * 14
                  local label = tostring(item.label or "")
                  local right = tostring(item.right or "")
                  Font.draw(label, 12, y)
                  if right ~= "" then
                      if pageKey == "stat" then
                          -- STAT INFO's labels are only LEVEL/HP/ATK/DEF/SPE/SPC.
                          -- The battle-stat rows therefore leave most of the left
                          -- half empty. Move their value column into that space and
                          -- give it the full 14-glyph inner-width budget, enough for
                          -- the largest native value/DV/Stat EXP combination without
                          -- marquee scrolling. LEVEL/HP keep a little more separation
                          -- from their longer labels but still gain width.
                          -- Use the semantic row marker rather than comparing
                          -- translated labels, so localization cannot move a wide
                          -- stat row back into the narrow column.
                          local wideStat = item.nuzInfoWideStat == true
                          local rightX = wideStat and 40 or 64
                          local rightWidth = wideStat and 14 or 11
                          Font.draw(marqueeText(right, rightWidth,
                              self.marqueeTime, 2.8), rightX, y)
                      else
                          -- 2.6.33: CATCH INFO uses compact row labels (native
                          -- <PK><MN>, LOC., ENC.) and a label-aware value column.
                          -- Start at x=72 for the common short rows, then move
                          -- right only when a longer label needs the room. This
                          -- keeps columns readable while gaining up to two
                          -- extra value glyphs versus the old fixed x=88/8-glyph
                          -- layout.
                          local labelWidth = type(Font.width) == "function"
                              and Font.width(label) or (#label * 8)
                          local rightX = math.max(72, 12 + labelWidth + 8)
                          local rightWidth = math.max(4,
                              math.floor((152 - rightX) / 8))
                          Font.draw(marqueeText(right, rightWidth,
                              self.marqueeTime, 2.8), rightX, y)
                      end
                  end
              end
          end

          if pageKey == "stat" then
              Font.draw(Strings("D=DV E=STAT EXP"), 12, 116)
          end

          local maxScroll = math.max(0, #self.items - (self.rows or 1))
          local canUp = (self.scroll or 0) > 0
          local canDown = (self.scroll or 0) < maxScroll
          if canUp then
              local x, y = 148, 30
              love.graphics.push()
              love.graphics.translate(x + 4, y + 4)
              love.graphics.rotate(math.pi)
              love.graphics.translate(-(x + 4), -(y + 4))
              Font.drawCode(Theme.moreArrow or 0xEE, x, y)
              love.graphics.pop()
          end
          if canDown then
              -- Below the move-card numeric line and above the footer.
              Font.drawCode(Theme.moreArrow or 0xEE, 148, 118)
          end

          if #self.nuzInfoPageOrder > 1 then
              Font.draw(Strings("A/<>:PG"), 8, 128)
              Font.draw(Strings("%d/%d", self.nuzInfoPageIndex,
                  #self.nuzInfoPageOrder), 76, 128)
          end
          Font.draw(Strings("B:BACK"), 104, 128)
      end

      menu.nuzlockeModernUiModel = function(self)
          local key = self.nuzInfoPageOrder[self.nuzInfoPageIndex] or "catch"
          local rows = {}
          for _, item in ipairs(self.items or {}) do
              rows[#rows + 1] = {
                  label = tostring(item.label or ""),
                  right = tostring(item.right or ""),
              }
          end
          return {
              title = Strings("NUZ INFO"),
              subtitle = pageTitles[key],
              rows = rows,
              index = self.index or 1,
              scroll = self.scroll or 0,
              details = { Strings("PAGE %d/%d",
                  self.nuzInfoPageIndex, #self.nuzInfoPageOrder) },
              footer = #self.nuzInfoPageOrder > 1
                  and { Strings("A/LEFT/RIGHT: PAGE"), Strings("B: BACK") }
                  or { Strings("B: BACK") },
          }
      end

      game.stack:push(menu)
      return menu
  end

  ---------------------------------------------------------------------
  -- PARTY SUBMENU HOOK
  ---------------------------------------------------------------------
  mod.hooks:wrap("ui.party.submenu", function(next, game, items, mon, ctx)
      -- Compose from the predecessor result first. Other mods may filter,
      -- replace, or rebuild the party submenu.
      local result = next(game, items, mon, ctx)
      if type(result) ~= "table" then result = items end
      if type(result) ~= "table" then return result end
      -- 2.8.27: Gen2 BattleState owns its battle-party lifecycle and supplies
      -- ctx.battle=true for the native SWITCH/STATS/CANCEL submenu. NUZ INFO is
      -- field-only and must not modify that list or its cancel callbacks.
      if mod.exports.__beta26.runtimeIsGen2(game)
          and ctx and ctx.battle == true then return result end
      if mod.exports.__beta26.runtimeIsGen2(game) then
          pcall(mod.exports.__beta26.noteGen2AdapterReach,
              "party_shared_hook", { rows=#result })
      end

      local anyNuzInfo = mod.save:get("catch_info", true) == true
          or mod.save:get("stat_info", true) == true
          or mod.save:get("move_info", true) == true
      if anyNuzInfo and mon then
          for _, item in ipairs(result) do
              if type(item) == "table" and (item.nuzlockeCatchInfo == true
                  or item.nuzlockeNuzInfo == true
                  or item.id == "nuzlocke_catch_info"
                  or item.id == "nuzlocke_nuz_info") then
                  -- Upgrade a preserved older row instead of inserting a
                  -- duplicate when another compatibility layer re-enters.
                  item.id = "nuzlocke_nuz_info"
                  item.nuzlockeNuzInfo = true
                  item.label = Strings("NUZ INFO")
                  item.onSelect = function()
                      if mod.exports.__beta26.runtimeIsGen2(game) then
                          mod.ui.push(game, "NuzlockeCatchInfoScreen", { mon = mon })
                      else
                          mod.exports.__beta26.pushRbyNuzInfoNative(game, mon)
                      end
                  end
                  if mod.exports.__beta26.runtimeIsGen2(game) then
                      pcall(mod.exports.__beta26.noteGen2AdapterReach,
                          "party_shared_row_present", true)
                  end
                  return result
              end
          end

          local cancelAnchor = "CANCEL"
          for _, item in ipairs(result) do
              if type(item) == "table" and (item.label == "CANCEL"
                  or item.label == Strings("CANCEL")
                  or item.id == "CANCEL" or item.id == "cancel"
                  or item.action == "cancel" or item.cancel == true) then
                  cancelAnchor = item.label or cancelAnchor
                  break
              end
          end
          mod.ui.insertBefore(result, cancelAnchor, {
              id = "nuzlocke_nuz_info",
              nuzlockeNuzInfo = true,
              label = Strings("NUZ INFO"),
              onSelect = function()
                  if mod.exports.__beta26.runtimeIsGen2(game) then
                      mod.ui.push(game, "NuzlockeCatchInfoScreen", { mon = mon })
                  else
                      mod.exports.__beta26.pushRbyNuzInfoNative(game, mon)
                  end
              end
          })
          if mod.exports.__beta26.runtimeIsGen2(game) then
              pcall(mod.exports.__beta26.noteGen2AdapterReach,
                  "party_shared_row_inserted", true)
          end
      end

      return result
  end)

  ---------------------------------------------------------------------
  -- BATTLE CATCH ENFORCEMENT
  --
  -- The recomp's BagMenu calls BattleState:throwBall after consuming the
  -- selected ball. Bryan's original Nuzlocke implementation intercepts
  -- this exact method, refunds the ball, displays the rejection message,
  -- and returns before vanilla capture processing.
  --
  -- We use that same engine seam for the actual first-catch / No Dupes
  -- decision. The important difference from Bryan's strict mode is that
  -- duplicate encounters NEVER consume the area's encounter in this mod.
  -- Shinies always bypass No Dupes, and bypass 1st Catch when Shiny Clause
  -- is enabled.
  ---------------------------------------------------------------------
  mod.events:on("game.ready", function(game)
      local ok, BattleState = pcall(require, "src.battle.BattleState")
      local okBag, Bag = pcall(require, "src.inventory.Bag")
      if not ok or type(BattleState) ~= "table"
          or type(BattleState.throwBall) ~= "function"
          or not okBag or type(Bag) ~= "table"
          or type(Bag.add) ~= "function" then
          return
      end

      -- 2.5.14: these direct engine wrappers must survive a second ModLoader
      -- session in the same Lua process.  A bare boolean marker can outlive the
      -- mod instance and leave a wrapper closing over an obsolete mod.save.
      local function ownedMethodSession(key, method)
          local session = BattleState[key]
          if type(session) == "table" and session.owner ~= mod
              and BattleState[method] == session.wrapper
              and type(session.previous) == "function" then
              BattleState[method] = session.previous
              session = nil
          end
          local healthy = type(session) == "table" and session.owner == mod
              and BattleState[method] == session.wrapper
          return healthy, session
      end
      BattleState.__nuzlockeFinal23Patched = true -- historical marker only

      -- Current Gen1Recomp emits the public battle.ended event from finish().
      -- Older builds were less consistent, so keep a private fallback for our
      -- own bookkeeping only. Never synthesize a second public engine event:
      -- unrelated mods may treat battle.ended as a transactional boundary.
      if type(BattleState.finish) == "function" then
          local healthy = ownedMethodSession(
              "__nuzlockeCatchFinishSession", "finish")
          if not healthy then
              local vanillaCatchFinish = BattleState.finish
              local finishWrapper
              finishWrapper = function(self, ...)
                  local result = vanillaCatchFinish(self, ...)
                  if type(finalizeNuzlockeBattle) == "function" then
                      pcall(finalizeNuzlockeBattle, self, self and self.result)
                  end
                  return result
              end
              BattleState.finish = finishWrapper
              BattleState.__nuzlockeCatchFinishSession = {
                  owner = mod, previous = vanillaCatchFinish,
                  wrapper = finishWrapper,
              }
          end
          BattleState.__nuzlockeCatchFinishPatched = true -- historical marker
      end

      -- Gen1Recomp 0.2.27 added the public catch.nickname decision seam.
      -- Nickname Rule uses that hook as the preferred R/B/Y catch-policy
      -- surface; this askNicknameUI wrapper remains as the enforcement layer
      -- that prevents an empty/declined name and as compatibility for older
      -- 0.2.24-0.2.26 engines that never call catch.nickname.
      do
          local healthy = ownedMethodSession(
              "__nuzlockeNicknameScreenSession", "askNicknameUI")
          local vanillaAskNicknameUI = BattleState.askNicknameUI
          local okStrings, Strings = pcall(require, "src.core.Strings")

          if not healthy and type(vanillaAskNicknameUI) == "function" then
              local nicknameWrapper
              nicknameWrapper = function(self, mon, displayName)
                  if active(self and self.game, self)
                      and mod.save:get("nickname_rule", defaultRuleValue("nickname_rule"))
                      and okStrings and Strings then
                      self.lockedBall, self.blankForAskName = nil, false

                      local namingOpts
                      namingOpts = {
                          title = Strings("NICKNAME?"),
                          maxLen = 10,
                          onDone = function(name)
                              name = tostring(name or "")
                              if name ~= "" then
                                  mon.nickname = name
                                  mon.nuzlockeNeedsNickname = nil
                                  mon.nuzlockeNicknameRequired = nil
                                  return
                              end

                              -- NamingScreen intentionally permits an empty
                              -- confirm for vanilla's "decline nickname" flow.
                              -- Under Nickname Rule, immediately reopen it.
                              local okScreens, Screens =
                                  pcall(require, "src.ui.Screens")
                              if okScreens and Screens
                                  and type(Screens.push) == "function" then
                                  pcall(Screens.push, self.game,
                                      "NamingScreen", namingOpts)
                              end
                          end,
                      }
                      return self:buildScreen("NamingScreen", namingOpts)
                  end
                  return vanillaAskNicknameUI(self, mon, displayName)
              end
              BattleState.askNicknameUI = nicknameWrapper
              BattleState.__nuzlockeNicknameScreenSession = {
                  owner = mod, previous = vanillaAskNicknameUI,
                  wrapper = nicknameWrapper,
              }
          end
          BattleState.__nuzlockeNicknameScreenPatched = true -- historical marker
      end

      -- BattleState's message queue does not soft-wrap mod-authored text on
      -- every supported recomp build. Keep Nuzlocke battle messages inside the
      -- native 18-column window and use CONT markers after the first two lines
      -- so longer messages wait for A/B instead of scrolling past automatically.
      mod.exports.__beta26.formatBattleText = function(text)
          local lines = wrapText(mod.exports.__beta26.cleanWorldText(text), 18)
          if #lines == 0 then return "" end
          if #lines == 1 then return lines[1] end
          local out = lines[1] .. "\n" .. lines[2]
          for i = 3, #lines do
              out = out .. "\v" .. lines[i]
          end
          return out
      end

      -- 2.8.76: native R/B/Y Ball use is an enforcement boundary. Policy
      -- evaluator exceptions must fail closed exactly like the public item-use
      -- compatibility seam; an exception can never become permission.
      local function safeRbyBallUsePolicy(evaluator, gameRef, battle, ball)
          if type(evaluator) ~= "function" then return true, nil end
          local okUse, allowed, decision = pcall(evaluator,
              gameRef, gameRef and gameRef.data, gameRef and gameRef.save,
              ball, nil, { battle = battle, inBattle = true, isBall = true })
          if not okUse then
              mod.exports.__beta26.lastItemPolicyError =
                  "rby_ball_use:" .. tostring(allowed)
              return false, {
                  code = "policy_error",
                  key = "policy_error",
                  rule = "policy_error",
                  message = Strings(
                      "Nuzlocke item policy error. Ball use blocked safely."),
              }
          end
          if allowed == false then return false, decision end
          return true, decision
      end

      mod.exports.__beta26.rbyBallPolicyErrorSelfTest = function()
          local allowed, decision = safeRbyBallUsePolicy(
              function() error("selftest_policy_fault") end,
              { data = {}, save = {} }, {}, "POKE_BALL")
          local ok = allowed == false and type(decision) == "table"
              and decision.code == "policy_error"
              and decision.rule == "policy_error"
          return {
              ok = ok,
              failures = ok and {} or { "policy_exception_did_not_fail_closed" },
          }
      end

      local throwHealthy = ownedMethodSession(
          "__nuzlockeCatchGateSession", "throwBall")
      if not throwHealthy then
          local vanillaThrowBall = BattleState.throwBall
          local throwWrapper
          throwWrapper = function(self, ball)
          local gameRef = self and self.game

          -- BagMenu has already consumed the selected Ball at this seam. Check
          -- the use-only Ball rule before Soft Start can arm, and refund on denial.
          local useAllowed, useDecision = safeRbyBallUsePolicy(
              evaluateItemUsePolicy, gameRef, self, ball)
          if not useAllowed and useDecision
              and (useDecision.key == "no_catching"
                  or useDecision.code == "no_catching"
                  or useDecision.rule == "no_catching") then
              local override = mod.exports.__beta26.tryProgressionCatchOverride
              if type(override) == "function" then
                  local okOverride, allowed, refusal = pcall(override,
                      gameRef, self, "no_catching", self)
                  if okOverride and allowed == true then
                      useAllowed = true
                  elseif okOverride and refusal == "progression_pc_full" then
                      useDecision = useDecision or {}
                      useDecision.message = mod.exports.__beta26.worldRuleText(
                          gameRef, "progression_pc_full")
                      useDecision.tier2 = useDecision.message
                      useDecision.tier3 = useDecision.message
                  end
              end
          end
          if not useAllowed then
              pcall(function()
                  Bag.add(gameRef.save, ball, 1, gameRef.data)
              end)
              local message = useDecision and useDecision.message
                  or Strings("No Catching is ON!")
              local tier = worldTier(gameRef)
              if tier >= 3 and useDecision and useDecision.tier3 then
                  message = useDecision.tier3
              elseif tier >= 2 and useDecision and useDecision.tier2 then
                  message = useDecision.tier2
              end
              if type(self.say) == "function" then
                  self:say(mod.exports.__beta26.formatBattleText(message))
              elseif type(self.sayNext) == "function" then
                  self:sayNext(mod.exports.__beta26.formatBattleText(message))
              end
              return
          end

          -- Possessing/using the first usable Ball permanently arms encounter
          -- bookkeeping for this run. The flag never disarms at zero Balls.
          if gameRef and mod.exports.__beta26.armEncounterRulesNow then
              mod.exports.__beta26.armEncounterRulesNow(gameRef)
          end
          local species = self and self.enemy and self.enemy.mon
              and self.enemy.mon.species

          local reason
          local reasonOk, reasonValue = pcall(function()
              return catchDeniedReason(gameRef, self, species)
          end)
          if reasonOk then
              reason = reasonValue
          else
              mod.exports.__beta26.lastAcquisitionPolicyError =
                  "rby_capture: " .. tostring(reasonValue)
              reason = "policy_error"
          end

          if reason then
              -- BagMenu has already removed the ball. Use Bryan's exact
              -- refund mechanism and original messages.
              pcall(function()
                  Bag.add(gameRef.save, ball, 1, gameRef.data)
              end)

              local message = mod.exports.__beta26.catchRejectionMessage(gameRef, reason, species)

              -- Use the same message entry point as Bryan's implementation.
              -- If a stripped/older build does not expose say(), fall back
              -- to the queue-based API rather than touching phase/queue state.
              if message then
                  if type(self.say) == "function" then
                      self:say(mod.exports.__beta26.formatBattleText(message))
                  elseif type(self.sayNext) == "function" then
                      self:sayNext(mod.exports.__beta26.formatBattleText(message))
                  end
              end

              return
          end

          local ballAllowed, ballLimit =
              mod.exports.__beta26.encounterBallThrowAvailable(gameRef, self)
          if not ballAllowed then
              -- R/B/Y BagMenu consumed the selected Ball before throwBall.
              -- An exhausted budget is a refusal, not an attempted throw.
              pcall(function()
                  Bag.add(gameRef.save, ball, 1, gameRef.data)
              end)
              local message =
                  mod.exports.__beta26.encounterBallLimitMessage(ballLimit)
              if type(self.say) == "function" then
                  self:say(mod.exports.__beta26.formatBattleText(message))
              elseif type(self.sayNext) == "function" then
                  self:sayNext(mod.exports.__beta26.formatBattleText(message))
              end
              return
          end
          mod.exports.__beta26.consumeEncounterBallThrow(gameRef, self)

          return vanillaThrowBall(self, ball)
          end
          BattleState.throwBall = throwWrapper
          BattleState.__nuzlockeCatchGateSession = {
              owner = mod, previous = vanillaThrowBall, wrapper = throwWrapper,
          }
      end
  end)

  ---------------------------------------------------------------------
  -- NICKNAME ENFORCEMENT
  --
  -- Gen1Recomp 0.2.27+: preferred public catch nickname policy seam.
  -- Returning true tells the engine to offer naming at the exact cart
  -- decision point. The askNicknameUI enforcement above then prevents a
  -- required nickname from being declined or confirmed empty.
  ---------------------------------------------------------------------
  mod.hooks:wrap("catch.nickname", function(next, mon, ctx)
      local battle = ctx and ctx.battle
      local gameRef = (ctx and ctx.game) or (battle and battle.game)
      if active(gameRef, battle)
          and not mod.exports.__beta26.runtimeIsGen2(gameRef)
          and mod.save:get("nickname_rule", defaultRuleValue("nickname_rule")) then
          if mon then
              mon.nuzlockeNicknameRequired = true
              mon.nuzlockeNeedsNickname = true
          end
          mod.exports.__beta26.catchNicknameHookObserved = true
          return true
      end
      return next(mon, ctx)
  end)

  -- 0.2.24-0.2.26 compatibility fallback. Those engines do not call
  -- catch.nickname, so retain the historical battle.nickname seam. On
  -- 0.2.27+ catch.nickname above is the authoritative decision surface.
  mod.hooks:wrap("battle.nickname", function(next, battle, mon)
      if active(battle and battle.game, battle)
          and not mod.exports.__beta26.runtimeIsGen2(battle and battle.game)
          and mod.save:get("nickname_rule", defaultRuleValue("nickname_rule")) then
          return true
      end
      return next(battle, mon)
  end)

  -- Fallback for engine builds where battle.nickname is only a notification
  -- hook. If a caught Pokemon reaches the tracker without a custom nickname,
  -- mark it for the engine's nickname flow rather than silently accepting the
  -- species name. This does not invent a nickname; the player must supply it.
  mod.events:on("pokemon.caught", function(ev)
      if not (ev and ev.mon and ev.game) then return end
      if not active(ev.game, ev.battle) then return end
      if mod.exports.__beta26.runtimeIsGen2(ev.game) then return end
      if not mod.save:get("nickname_rule", defaultRuleValue("nickname_rule")) then return end
      local mon = ev.mon
      if mon.nickname == nil or mon.nickname == "" or mon.nickname == mon.species then
          mon.nuzlockeNeedsNickname = true
          mon.nuzlockeNicknameRequired = true
          -- The mandatory NamingScreen is the feedback for this rule. Do not
          -- stack another World Building box on the catch message or naming
          -- flow from this post-catch compatibility listener.
      end
  end)

  ---------------------------------------------------------------------
  -- ITEM USE ENFORCEMENT / SHARED POLICY
  --
  -- One pure legality decision feeds our engine gate and cooperative mods that
  -- want to ask BEFORE mutating inventory. Presentation stays outside policy.
  ---------------------------------------------------------------------
  ---------------------------------------------------------------------
  -- 2.9.55 ITEM POLICY MODULE
  -- Shared item-use legality and engine/field-action guard ownership now live
  -- in item_policy.lua. Economy policy and battle orchestration remain here.
  ---------------------------------------------------------------------
  local ItemPolicyRuntime = loadRequiredModuleChunk("item_policy.lua")()(mod, {
      Strings = Strings,
      getCurrentGame = function() return currentGame or mod.game end,
      getCurrentSave = function() return currentSave or ((currentGame or mod.game) and (currentGame or mod.game).save) end,
      worldTier = worldTier,
      levelCapScope = levelCapScope,
      nextLevelCap = nextLevelCap,
      refreshPublicCompatSnapshots = refreshPublicCompatSnapshots,
  })
  ItemPolicy = ItemPolicyRuntime.ItemPolicy
  evaluateItemUsePolicy = ItemPolicyRuntime.evaluateItemUsePolicy


  if mod.exports.nuzlocke_compat then
      mod.exports.nuzlocke_compat.canUseItem = function(game, itemId, context)
          context = type(context) == "table" and context or {}
          local allowed, decision = evaluateItemUsePolicy(
              game, context.data or (game and game.data),
              context.save or (game and game.save), itemId, context.target, context)
          return allowed, decision and decision.code or nil, decision
      end
      mod.exports.nuzlocke_compat.canPurchase = function(game, context)
          context = type(context) == "table" and context or {}
          if mod.save:get("nuzlocke_enabled", true) == false
              or not (game and game.save) then return true end
          local kind = tostring(context.kind or ""):lower()
          if (kind == "item_shop" or kind == "shop_item")
              and mod.save:get("no_buying", false) == true then
              local Dev = mod.exports.__beta26.Dev
              if Dev and type(Dev.recordDecision) == "function" then
                  pcall(Dev.recordDecision, "economy", "no_buying", "BLOCK",
                      "item_shop", game)
              end
              return false, "no_buying"
          end
          return true
      end
      mod.exports.nuzlocke_compat.canSell = function(game, context)
          context = type(context) == "table" and context or {}
          if mod.save:get("nuzlocke_enabled", true) == false
              or not (game and game.save) then return true end
          local kind = tostring(context.kind or ""):lower()
          if (kind == "item_shop" or kind == "shop_item")
              and mod.save:get("no_selling", false) == true then
              local Dev = mod.exports.__beta26.Dev
              if Dev and type(Dev.recordDecision) == "function" then
                  pcall(Dev.recordDecision, "economy", "no_selling", "BLOCK",
                      "item_shop", game)
              end
              return false, "no_selling"
          end
          return true
      end
  end

  -- Gen1Recomp 0.1.98 exposes contextual field actions through mod.world.
  -- Those helpers deliberately call the active overworld directly instead of
  -- re-opening the Pack, so Pack-only policy hooks are not an authoritative
  -- veto. Guard the underlying fishing/Gold field-item seams as a backstop;
  -- normal Pack use still gets the richer ItemPolicy presentation above.
  -- 2.7.101: Gen2 party-target consumable metadata is repaired at the
  -- Pack-use seam in late_runtime.lua, where the merged Pack item view is live.


  -- 2.3.10: item/field engine adapters install only after lifecycle events.
  -- Re-check only at coarse lifecycle boundaries. This repairs a live function
  -- replaced during startup/mod composition without introducing battle-frame work.
  mod.events:on("game.ready", function()
      pcall(ItemPolicy.install); pcall(ItemPolicy.installFieldActionGuards)
  end)
  mod.events:on("save.loaded", function()
      pcall(ItemPolicy.install); pcall(ItemPolicy.installFieldActionGuards)
  end)
  mod.events:on("mods.loaded", function()
      pcall(ItemPolicy.install); pcall(ItemPolicy.installFieldActionGuards)
  end)
  mod.events:on("map.entered", function()
      pcall(ItemPolicy.install); pcall(ItemPolicy.installFieldActionGuards)
  end)
  mod.events:on("battle.started", function()
      pcall(ItemPolicy.install); pcall(ItemPolicy.installFieldActionGuards)
  end)

  ---------------------------------------------------------------------
  -- BATTLE ITEM FALLBACK HOOK
  ---------------------------------------------------------------------
  mod.hooks:wrap("battle.use_item", function(next, battle, item)
      local game = battle and battle.game or currentGame
      if not active(game, battle) then return next(battle, item) end
      local okEffects, ItemEffects = pcall(require, "src.inventory.ItemEffects")
      local allowed, decision = evaluateItemUsePolicy(
          game, game and game.data, game and game.save, item,
          type(item) == "table" and item.target or nil,
          { battle = battle, inBattle = true,
            itemEffects = okEffects and ItemEffects or nil })
      if not allowed then
          local _, messages = ItemPolicy.present(game, decision, {
              battle = battle, inBattle = true, itemId = item,
          })
          return false, messages and messages[1] or "Item use is blocked!"
      end
      return next(battle, item)
  end)

  ---------------------------------------------------------------------
  -- NO ESCAPE
  --
  -- BattleState exposes the Gen 1 escape calculation through the public
  -- battle.run hook. Returning false from this hook makes both the RUN
  -- command and the faint-screen "Use next POKeMON? -> NO" escape attempt
  -- fail normally, which means the player gets the vanilla "Can't escape!"
  -- result and the turn is consumed. Trainer battles never reach this hook
  -- because the engine rejects RUN before attempting the escape roll.
  ---------------------------------------------------------------------
  mod.hooks:wrap("battle.run", function(next, ctx)
      local battle = ctx and ctx.battle
      -- Gold's pure Battle model carries save/data but no `battle.game`; the
      -- shared battle.run hook still passes that Battle as ctx.battle. Resolve
      -- the live game generation-neutrally so No Escape is not silently inert
      -- on Gold while retaining R/B/Y's direct battle.game when available.
      local game = battle and battle.game or currentGame or mod.game
      if active(game, battle)
          and mod.save:get("no_escape", false) == true then
          local provider = activeCompatProvider("escape", game, battle)
          local relationship = provider and
              mod.exports.__beta26.compat.Mods.relationshipFor(provider.id, "escape")
          if provider and (relationship == "delegate" or relationship == "exclusive") then
              return next(ctx)
          end
          -- Returning false already produces the engine's native
          -- "Can't escape!" result and consumes the turn. Do not stack a
          -- second World Building TextBox into the battle flow.
          return false
      end
      return next(ctx)
  end, 100000)

  ---------------------------------------------------------------------
  -- MAP ENTRY
  --
  -- map.entered gives the actual engine map ID.
  -- via="boot" is important: an old save loaded in Pallet Town is
  -- immediately recorded without requiring the player to walk.
  ---------------------------------------------------------------------
  mod.events:on("map.entered", function(ev)
      if not ev or not ev.mapId then
          return
      end

      local map = ev.map
      local x, y = mod.exports.__beta26.encounterPosition(currentGame)
      local physical = mod.exports.__beta26.cardinalPhysicalArea(ev.mapId, x, y,
          map and map.widthCells, map and map.heightCells)
      local key = registerArea(mod.exports.__beta26.projectEncounterArea(physical))

      if not isTrackedArea(key) then
          return
      end

      markVisited(physical)
  end)

  ---------------------------------------------------------------------
  -- WORLD STEP
  -- Keep the tracker synchronized with the actual map the player is on.
  -- This is intentionally redundant with map.entered: world.stepped is a
  -- cheap, reliable fallback for connections/transitions and old saves.
  ---------------------------------------------------------------------
  mod.events:on("world.stepped", function(ev)
      if not ev or not ev.mapId then
          return
      end

      local map = currentGame and currentGame.overworld
          and currentGame.overworld.map
      local physical = mod.exports.__beta26.cardinalPhysicalArea(
          ev.mapId, ev.x, ev.y,
          map and map.widthCells, map and map.heightCells)
      local key = registerArea(mod.exports.__beta26.projectEncounterArea(physical))
      if key then
          markVisited(physical)
      end
  end)

  ---------------------------------------------------------------------
  -- OVERWORLD ENCOUNTER DETECTION
  --
  -- Different overworld-spawn mods may annotate the catch event/battle in
  -- different ways. Accept the common explicit flags first, then treat a
  -- catch with no battle object as an overworld capture. Normal wild battles
  -- remain eligible regardless of this setting.
  ---------------------------------------------------------------------
  mod.exports.__beta26.isOverworldEncounter = function(ev)
      if not ev then
          return false
      end

      if ev.overworldEncounter == true
          or ev.overworld == true
          or ev.isOverworld == true
          or ev.encounterType == "overworld"
          or ev.source == "overworld" then
          return true
      end

      local battle = ev.battle
      if battle then
          if battle.overworldEncounter == true
              or battle.overworld == true
              or battle.isOverworld == true
              or battle.encounterType == "overworld"
              or battle.source == "overworld" then
              return true
          end
      else
          -- A capture event without a battle is treated as an overworld
          -- capture. This is useful for mods that spawn/capture Pokemon
          -- directly without constructing the vanilla wild-battle state.
          return true
      end

      return false
  end

  ---------------------------------------------------------------------
  -- VERSION DETECTION
  --
  -- Detects RBY and GSC-family version ids exposed by the live engine.
  -- Falls back to RED only when the engine exposes no recognizable version.
  ---------------------------------------------------------------------
  getGameVersion = function()
      local candidates = {}
      local ok, GameVersion = pcall(require, "src.core.GameVersion")
      if ok and GameVersion then
          if type(GameVersion.get) == "function" then
              local okGet, detected = pcall(GameVersion.get)
              if okGet then candidates[#candidates+1] = detected end
          end
          candidates[#candidates+1] = GameVersion.version
      end
      if currentGame then
          candidates[#candidates+1] = currentGame.version
          candidates[#candidates+1] = currentGame.gameVersion
          candidates[#candidates+1] = currentGame.data and currentGame.data.version
          candidates[#candidates+1] = currentGame.data and currentGame.data.gameVersion
      end
      for _, v in ipairs(candidates) do
          local upper = tostring(v or ""):upper()
          if upper:find("CRYSTAL",1,true) or upper:find("CRY",1,true) then return "CRYSTAL" end
          if upper:find("SILVER",1,true) or upper:find("SLV",1,true) then return "SILVER" end
          if upper:find("GOLD",1,true) or upper == "G" then return "GOLD" end
          if upper:find("YELLOW",1,true) or upper:find("YLW",1,true) then return "YELLOW" end
          if upper:find("BLUE",1,true) or upper:find("BLU",1,true) then return "BLUE" end
          if upper:find("RED",1,true) then return "RED" end
      end
      return "RED"
  end

  mod.exports.__beta26.getGameProfile = function()
      local version = getGameVersion()
      return VersionCompat.profiles[version] or {family="UNKNOWN",region="UNKNOWN",status="unknown"}
  end

  ---------------------------------------------------------------------
  -- GOLD PRE-NEW-GAME SETUP
  --
  -- Gen 2 Setup is handled at the title menu above through the native
  -- {label,value} row shape and MainMenu:choose() dispatch. Previous
  -- post-NEW-GAME intro insertion experiments are intentionally removed.
  ---------------------------------------------------------------------


  ---------------------------------------------------------------------
  -- VERSION-AWARE VANILLA ACQUISITION SOURCE CATALOG
  -- 2.5.90: behavior-preserving extraction of static gift/trade source data
  -- and deterministic fallback lookup helpers. Transaction enforcement stays
  -- in main.lua; only the read-only source catalog is modularized here.
  ---------------------------------------------------------------------
  loadRequiredModuleChunk("acquisition_catalog.lua")()(mod, {
      getGameVersion = getGameVersion,
  })

  if mod.exports.nuzlocke_compat then
      mod.exports.nuzlocke_compat.giftLocationFor = function(species)
          return mod.exports.__beta26.buildGiftLookup()[tostring(species or ""):upper()]
      end
      mod.exports.nuzlocke_compat.tradeLocationFor = function(species)
          return mod.exports.__beta26.buildTradeLookup()[tostring(species or ""):upper()]
      end
      mod.exports.nuzlocke_compat.isDeterministicGiftSource = function(species)
          return mod.exports.__beta26.deterministicSourceFallback("gift", species)
      end
      mod.exports.nuzlocke_compat.isDeterministicTradeSource = function(species)
          return mod.exports.__beta26.deterministicSourceFallback("trade", species)
      end
  end


  -- Gifts and in-game trades are transactions, not battles. Any rule that
  -- rejects one must do so BEFORE the engine removes/gives Pokemon or sets the
  -- NPC's completed-trade/gift state. Post-acquisition deletion can permanently
  -- destroy the player's offered Pokemon or burn a one-time gift.
  --
  -- 2.4.36: one shared slot-conflict predicate now owns CAUGHT/FAILED semantics
  -- for wild catches and special acquisitions. FAILED only blocks while the
  -- Failed Encounter rule is actually enabled; stale FAILED rows must not keep
  -- blocking gifts/trades/eggs after that rule is turned OFF.
  mod.exports.__beta26.encounterSlotConflict = function(game, area, requireArmed)
      area = routeKey(area) or area
      if not area or area == "UNKNOWN" or area == "__LEGACY__" then
          return nil
      end
      if mod.save:get("encounter_limit", defaultRuleValue("encounter_limit")) ~= true then
          return nil
      end
      if requireArmed == true
          and not mod.exports.__beta26.encounterRulesArmed(game) then
          return nil
      end
      syncCaughtAreasFromLog()
      if caughtAreas()[area] ~= nil then return "caught" end
      local state = getEncounterState and getEncounterState(area) or nil
      if type(state) == "table" and state.status == "CAUGHT" then
          return "caught"
      end
      if mod.save:get("failed_encounter", true) == true
          and type(state) == "table" and state.status == "FAILED" then
          return "failed"
      end
      return nil
  end

  mod.exports.__beta26.specialAreaUnavailable = function(area)
      return mod.exports.__beta26.encounterSlotConflict(
          currentGame or mod.game, area, false) ~= nil
  end


  -- Compatibility-facing acquisition-source classifier. Explicit provider
  -- provenance wins; source-less inference requires the reported/current area
  -- to agree with the version-aware vanilla source. UNKNOWN may still use a
  -- deterministic vanilla source as a last-resort compatibility fallback.
  if mod.exports.nuzlocke_compat then
      mod.exports.nuzlocke_compat.classifyAcquisition = function(game, species, source, location)
          local key = tostring(species or ""):upper()
          local src = tostring(source or ""):lower()
          local locKey = routeKey(location) or (location and tostring(location):upper()) or "UNKNOWN"
          if src == "gift" or src == "fossil" or src == "prize" then
              local area = locKey ~= "UNKNOWN" and locKey
                  or mod.exports.__beta26.buildGiftLookup()[key] or "UNKNOWN"
              return { kind = "gift", area = area, explicit = true }
          end
          if src == "trade" then
              local area = locKey ~= "UNKNOWN" and locKey
                  or mod.exports.__beta26.buildTradeLookup()[key] or "UNKNOWN"
              return { kind = "trade", area = area, explicit = true }
          end
          if src ~= "" then return { kind = src, area = locKey, explicit = true } end
          local gift = mod.exports.__beta26.buildGiftLookup()[key]
          if gift and ((routeKey(gift) or gift) == locKey
              or (locKey == "UNKNOWN" and mod.exports.__beta26.deterministicSourceFallback("gift", key))) then
              return { kind = "gift", area = gift, inferred = true }
          end
          local trade = mod.exports.__beta26.buildTradeLookup()[key]
          if trade and ((routeKey(trade) or trade) == locKey
              or (locKey == "UNKNOWN" and mod.exports.__beta26.deterministicSourceFallback("trade", key))) then
              return { kind = "trade", area = trade, inferred = true }
          end
          return { kind = "unknown", area = locKey, inferred = false }
      end
  end

  mod.exports.__beta26.currentSpecialArea = function(game, species, kind)
      species = tostring(species or ""):upper()
      -- The live map is stronger provenance than a species table and lets
      -- third-party gifts/trades reuse vanilla species in new locations.
      local current = areaKey(game, nil)
      current = routeKey(current) or current
      if current and current ~= "UNKNOWN" then return current end
      local lookup = kind == "trade" and mod.exports.__beta26.buildTradeLookup() or mod.exports.__beta26.buildGiftLookup()
      local known = lookup[species]
      return routeKey(known) or known or "UNKNOWN"
  end

  mod.exports.__beta26.configuredPartySizeLimit = function()
      return math.max(1, math.min(6, math.floor(tonumber(
          mod.save:get("party_size_limit", defaultRuleValue("party_size_limit"))) or 6)))
  end

  mod.exports.__beta26.partyAtConfiguredLimit = function(save)
      local limit = mod.exports.__beta26.configuredPartySizeLimit()
      -- 6 is the native party capacity, so preserve vanilla auto-box behavior.
      return limit < 6 and active(currentGame or mod.game, nil)
          and #(save and save.party or {}) >= limit
  end

  mod.exports.__beta26.specialAcquisitionConsumesArea = function(kind)
      kind = tostring(kind or ""):lower()
      local key = kind == "trade" and "trade_slot_policy" or "gift_slot_policy"
      local mode = math.max(0, math.min(1, math.floor(tonumber(
          mod.save:get(key, defaultRuleValue(key))) or 0)))
      return mode == 0
  end

  specialAcquisitionDenied = function(game, species, area, kind, mon, policy)
      if not active(game, nil) then return nil end
      -- Legacy direct callers predate semantic kind policy and are exclusively
      -- gift/trade paths. Preserve their full historical behavior while public
      -- Acquisition.evaluate can supply a dimensioned policy for newer kinds.
      policy = type(policy) == "table" and policy or {
          sourceRule = (kind == "gift" or kind == "trade"),
          speciesLegality = true,
          areaLegality = true,
          partyAdmission = (kind == "gift" or kind == "trade"),
      }
      local glitch = mod.exports.__beta26.getGlitchSpeciesInfo(game, species)
      species = glitch.key

      if policy.sourceRule == true then
          if kind == "gift" and mod.save:get("allow_gifts", defaultRuleValue("allow_gifts")) ~= true then
              return "disabled"
          end
          if kind == "trade" and mod.save:get("allow_trades", defaultRuleValue("allow_trades")) ~= true then
              return "disabled"
          end
      end
      if policy.speciesLegality == true then
          if glitch.isGlitch and not mod.exports.__beta26.glitchCatchesAllowed() then
              return "glitch"
          end
          local typeAllowed = type(mon) == "table"
              and mod.exports.__beta26.typeLockAllowsPokemon(game, mon)
              or mod.exports.__beta26.typeLockAllowsSpecies(game, species)
          if not typeAllowed then return "type_lock" end
          local challengeAllowed, challengeReason = mod.exports.__beta26.challengeSpeciesAllows(game, species)
          if not challengeAllowed then return challengeReason end

          if Identity.isLegendarySpecies(game, species)
              and mod.save:get("ban_legendaries", false) == true then
              return "legendary"
          end
          if Identity.isMythicalSpecies(game, species)
              and mod.save:get("ban_mythicals", false) == true then
              return "mythical"
          end
          if Identity.isPseudoSpecies(game, species)
              and mod.save:get("ban_pseudos", false) == true then
              return "pseudo"
          end
          if mod.exports.__beta26.pkmnBanContains(game, species) then
              return "pkmn_ban"
          end
          local bstLimit = mod.exports.__beta26.getMaximumBST()
          local bst = bstLimit > 0
              and mod.exports.__beta26.getSpeciesBST(game, species) or nil
          if bst and bst > bstLimit then
              return "bst"
          end
      end
      if policy.areaLegality == true
          and mod.exports.__beta26.specialAcquisitionConsumesArea(kind)
          and mod.exports.__beta26.specialAreaUnavailable(area) then
          return "area"
      end
      if policy.partyAdmission == true
          and mod.exports.__beta26.partyAtConfiguredLimit(game and game.save) then
          return "party_size"
      end
      return nil
  end

  ---------------------------------------------------------------------
  -- STARTER SPECIES LOOKUP  (version-aware)
  ---------------------------------------------------------------------
  local STARTERS_BY_VERSION = {
      RED    = { BULBASAUR = true, CHARMANDER = true, SQUIRTLE = true },
      BLUE   = { BULBASAUR = true, CHARMANDER = true, SQUIRTLE = true },
      YELLOW = { PIKACHU   = true },
  }

  mod.exports.__beta26.isStarterSpecies = function(species)
      local ver = getGameVersion()
      local starters = STARTERS_BY_VERSION[ver] or STARTERS_BY_VERSION["RED"]
      return starters[tostring(species or ""):upper()] == true
  end

  -- 2.4.96: Random Starter can turn the opening Pokemon into any legal
  -- species, so species-family heuristics alone cannot identify it afterward.
  -- Use the committed accepted random-starter scalar plus first-party/opening
  -- location provenance. Preview rolls are intentionally ignored.
  mod.exports.__beta26.isOpeningStarterAcquisition = function(
      game, species, source, location, mon)
      game = game or currentGame or mod.game
      species = tostring(species or ""):upper()
      source = tostring(source or ""):lower()
      local loc = tostring(location or ""):upper()
      local openingLoc = loc == "" or loc == "UNKNOWN"
          or loc == "PALLET_TOWN"
          or loc:find("OAK", 1, true) ~= nil
          or loc:find("LAB", 1, true) ~= nil

      if source == "starter" then return true end
      if source ~= "" then return false end
      if mod.exports.__beta26.isStarterSpecies(species) and openingLoc then
          return true
      end

      if mod.exports.__beta26.runtimeIsGen2(game) then return false end
      if mod.save:get("random_starter", false) ~= true then return false end
      if externalRuleDelegation
          and externalRuleDelegation("random_starter", game) then
          return false
      end

      local accepted = tostring(
          mod.save:get("__nuzlocke_random_starter_choice", "") or ""):upper()
      if accepted == "" or accepted ~= species or not openingLoc then
          return false
      end

      local save = game and game.save
      local party = save and save.party or {}
      if #party > 1 then return false end
      if mon and type(party[1]) == "table" then
          if party[1] == mon then return true end
          local a = Identity.pokemonIdentity(party[1])
          local b = Identity.pokemonIdentity(mon)
          if a ~= nil and b ~= nil and tostring(a) == tostring(b) then
              return true
          end
      end
      return #party <= 1
  end

  ---------------------------------------------------------------------
  -- REGISTER STARTER IN THE EXACT EDITION HOMETOWN
  -- R/B/Y retain PALLET_TOWN; shared Gold/Silver use NEW_BARK_TOWN.
  -- This is provenance authority, not merely Tracker presentation.
  ---------------------------------------------------------------------
  mod.exports.__beta26.registerStarterCatch = function(species, mon, opts)
      if not species then return end
      species = tostring(species):upper()
      local game = currentGame or mod.game
      local area = mod.exports.__beta26.runtimeIsGen2(game)
          and "NEW_BARK_TOWN" or "PALLET_TOWN"
      if mod.exports.__beta26.runtimeIsGen2(game) then
          pcall(mod.exports.__beta26.noteGen2AdapterReach,
              "starter_registration", { species=species, area=area })
      end
      registerArea(area)
      markVisited(area)

      local monId = mon and Identity.ensurePokemonIdentity(mon, currentSave, "NORMAL") or nil
      local fingerprint = mon and Identity.fingerprint(mon) or nil
      local log = trackerLog()
      local areas = caughtAreas()
      local canonicalRow = nil
      opts = type(opts) == "table" and opts or {}

      -- 2.7.79 reconstruction: very old saves may contain one identity-less,
      -- fingerprint-less LEGACY row for a starter that is now concretely proven.
      -- Species is permitted only inside this explicit repair mode, and only
      -- when both sides are unique. Fresh registration never enables it.
      if opts.allowUniqueLegacyStarterCleanup == true and mon then
          local sameSpeciesLive = 0
          for _, liveMon in ipairs(Identity.allCurrentMons(currentSave or (game and game.save))) do
              if tostring(liveMon and liveMon.species or ""):upper() == species then
                  sameSpeciesLive = sameSpeciesLive + 1
              end
          end
          local legacy = log.__LEGACY__
          local legacyIndex, legacyCount = nil, 0
          if sameSpeciesLive == 1 and type(legacy) == "table" then
              for i, row in ipairs(legacy) do
                  if type(row) == "table"
                      and row.pokemonId == nil and row.fingerprint == nil
                      and tostring(row.species or ""):upper() == species then
                      legacyCount = legacyCount + 1
                      legacyIndex = i
                  end
              end
          end
          if sameSpeciesLive == 1 and legacyCount == 1 and legacyIndex then
              canonicalRow = legacy[legacyIndex]
              table.remove(legacy, legacyIndex)
              if #legacy > 0 then log.__LEGACY__ = legacy else log.__LEGACY__ = nil end
              pcall(mod.exports.__beta26.noteGen2AdapterReach,
                  "starter_legacy_unique_cleanup", species)
          end
      end

      -- 2.7.78 reconstruction: one physical starter identity owns exactly one
      -- active Tracker row. Persistent ID is authoritative; fingerprint is only
      -- a compatibility fallback for old rows that predate stored Pokemon IDs.
      -- Species is deliberately never identity evidence here.
      for logArea, rows in pairs(log) do
          if type(rows) == "table" then
              local kept = {}
              for _, row in ipairs(rows) do
                  local same = false
                  if type(row) == "table" then
                      if monId ~= nil and row.pokemonId ~= nil then
                          same = tostring(row.pokemonId) == tostring(monId)
                      elseif row.pokemonId == nil and fingerprint ~= nil
                          and row.fingerprint ~= nil then
                          same = tostring(row.fingerprint) == tostring(fingerprint)
                      end
                  end
                  if same then
                      canonicalRow = canonicalRow or row
                  else
                      kept[#kept + 1] = row
                  end
              end
              if #kept > 0 then
                  log[logArea] = kept
              else
                  log[logArea] = nil
              end
              if logArea ~= "__LEGACY__" then
                  if #kept > 0 and type(kept[1]) == "table" then
                      areas[logArea] = kept[1].species or areas[logArea]
                  elseif logArea ~= area then
                      areas[logArea] = nil
                  end
              end
          end
      end

      canonicalRow = canonicalRow or {}
      canonicalRow.species = species
      canonicalRow.pokemonId = monId or canonicalRow.pokemonId
      canonicalRow.fingerprint = fingerprint or canonicalRow.fingerprint
      canonicalRow.isShiny = mon and Identity.isShiny(mon) or canonicalRow.isShiny
      canonicalRow.encounterType = "gift"
      canonicalRow.encounterSource = canonicalRow.encounterSource or "starter"
      log[area] = type(log[area]) == "table" and log[area] or {}
      log[area][#log[area] + 1] = canonicalRow
      areas[area] = species
      mod.save:set("tracker_log", log)
      mod.save:set("caught_areas", areas)

      if mon then
          mon.catchLocation = area
          mon.encounterType = "gift"
          mon.nuzlockeDead  = false
          mon.nuzlockeTrackerRegistered = true
          Identity.setPokemonOrigin(mon, "NORMAL")
          Identity.baselineAdd(mon, "NORMAL")
      end

      local history = mod.save:get("nuzlocke_history", {})
      if type(history) ~= "table" then history = {} end
      local normalizedHistory = {}
      local historyRow = nil
      if monId ~= nil then
          for _, row in ipairs(history) do
              if type(row) == "table" and row.pokemonId ~= nil
                  and tostring(row.pokemonId) == tostring(monId) then
                  historyRow = historyRow or row
              else
                  normalizedHistory[#normalizedHistory + 1] = row
              end
          end
      else
          for _, row in ipairs(history) do normalizedHistory[#normalizedHistory + 1] = row end
      end
      historyRow = historyRow or {}
      historyRow.name = (mon and (mon.nickname or mon.species)) or species
      historyRow.species = species
      historyRow.pokemonId = monId or historyRow.pokemonId
      historyRow.catchLocation = area
      historyRow.encounterType = "starter"
      historyRow.status = historyRow.status or "ALIVE"
      normalizedHistory[#normalizedHistory + 1] = historyRow
      mod.save:set("nuzlocke_history", normalizedHistory)

      pcall(mod.exports.__beta26.RunHistory.recordCatch, currentGame or mod.game, mon, {
          species = species, pokemonId = monId, area = area,
          encounterType = "starter", provenance = "NORMAL", source = "starter",
      })
      if mon and mod.exports.__beta26.runtimeIsGen2(game)
          and type(mod.exports.__beta26.reconcileGen2ElmStarterStory) == "function" then
          pcall(mod.exports.__beta26.reconcileGen2ElmStarterStory, game, mon)
      end
      return true
  end

  -- 2.7.79 reconstruction: once a concrete Gold/Silver Pokemon is already
  -- proven as the New Bark starter, reconcile Elm's native story authority.
  -- This never guesses starter identity; callers must pass the proven mon.
  mod.exports.__beta26.reconcileGen2ElmStarterStory = function(game, mon)
      game = game or currentGame or mod.game
      if not mod.exports.__beta26.runtimeIsGen2(game) or type(mon) ~= "table" then
          return false
      end
      if mon.nuzlockeTrackerRegistered ~= true
          or tostring(mon.catchLocation or ""):upper() ~= "NEW_BARK_TOWN" then
          return false
      end
      local encounterType = tostring(mon.encounterType or ""):lower()
      if encounterType ~= "gift" and encounterType ~= "starter" then return false end
      local world = game and game.world
      if not (world and world.events and type(world.events.set) == "function") then
          return false
      end
      local okFlags, FlagNames = pcall(require, "src.core.gen2.FlagNames")
      if not okFlags or type(FlagNames) ~= "table"
          or type(FlagNames.events) ~= "table" then return false end
      local changed = false
      local function setEvent(name)
          local id = FlagNames.events[name]
          if not id then return false end
          local already = false
          if type(world.events.get) == "function" then
              local okGet, value = pcall(world.events.get, world.events, id)
              already = okGet and value == true
          end
          if not already then
              local okSet = pcall(world.events.set, world.events, id, true)
              changed = okSet or changed
              return okSet
          end
          return true
      end
      setEvent("EVENT_GOT_A_POKEMON_FROM_ELM")
      local original = tostring(mod.save:get(
          "__nuzlocke_random_starter_original", "") or ""):upper()
      if original == "CHIKORITA" or original == "CYNDAQUIL"
          or original == "TOTODILE" then
          setEvent("EVENT_GOT_" .. original .. "_FROM_ELM")
          setEvent("EVENT_" .. original .. "_POKEBALL_IN_ELMS_LAB")
      end
      pcall(mod.exports.__beta26.noteGen2AdapterReach,
          "elm_story_reconciliation", {
              species = tostring(mon.species or ""):upper(),
              original = original ~= "" and original or nil,
          })
      return true
  end

  -- 2.7.76 reconstruction: repair only the provable early-Gen2 Pallet starter
  -- corruption shape produced by older shared-path failures. This is deliberately
  -- narrower than general Recover Catches and is idempotent.
  mod.exports.__beta26.repairGen2StarterHometown = function(game)
      game = game or currentGame or mod.game
      if not mod.exports.__beta26.runtimeIsGen2(game) then return false end
      if type(mod.exports.__beta26.saveWritePauseReason) == "function"
          and mod.exports.__beta26.saveWritePauseReason() ~= nil then return false end
      local save = game and game.save
      if type(save) ~= "table" or currentBadgeCount(save) ~= 0 then return false end
      local mons = Identity.allCurrentMons(save)
      if #mons ~= 1 then return false end
      local mon = mons[1]
      if type(mon) ~= "table" or mon.nuzlockeTrackerRegistered ~= true
          or tostring(mon.catchLocation or ""):upper() ~= "PALLET_TOWN" then return false end
      local encounterType = tostring(mon.encounterType or ""):lower()
      if encounterType ~= "gift" and encounterType ~= "starter" then return false end
      local species = tostring(mon.species or ""):upper()
      local log = trackerLog()
      local pallet = log.PALLET_TOWN
      if type(pallet) ~= "table" or #pallet ~= 1 then return false end
      local row = pallet[1]
      if type(row) ~= "table" or tostring(row.species or ""):upper() ~= species then
          return false
      end
      local rowType = tostring(row.encounterType or ""):lower()
      if rowType ~= "gift" and rowType ~= "starter" then return false end
      local monId = Identity.pokemonIdentity(mon)
      local monFingerprint = Identity.fingerprint(mon)
      local identityProven = (monId ~= nil and row.pokemonId ~= nil
              and tostring(row.pokemonId) == tostring(monId))
          or (row.pokemonId == nil and monFingerprint ~= nil and row.fingerprint ~= nil
              and tostring(row.fingerprint) == tostring(monFingerprint))
      if not identityProven then return false end
      local areas = caughtAreas()
      if tostring(areas.PALLET_TOWN or ""):upper() ~= species
          or areas.NEW_BARK_TOWN ~= nil then return false end

      registerArea("NEW_BARK_TOWN", "New Bark Town")
      row.encounterType = row.encounterType or "gift"
      log.NEW_BARK_TOWN = { row }
      log.PALLET_TOWN = nil
      areas.NEW_BARK_TOWN = species
      areas.PALLET_TOWN = nil
      local seen = visitedAreas()
      seen.NEW_BARK_TOWN = true
      seen.PALLET_TOWN = nil
      mon.catchLocation = "NEW_BARK_TOWN"
      mod.save:set("tracker_log", log)
      mod.save:set("caught_areas", areas)
      mod.save:set("visited_areas", seen)

      local states = mod.save:get("encounter_states", {})
      if type(states) == "table" and type(states.PALLET_TOWN) == "table"
          and tostring(states.PALLET_TOWN.species or ""):upper() == species then
          states.NEW_BARK_TOWN = states.PALLET_TOWN
          states.PALLET_TOWN = nil
          mod.save:set("encounter_states", states)
      end
      local history = mod.save:get("nuzlocke_history", {})
      if type(history) == "table" and monId ~= nil then
          for _, h in ipairs(history) do
              if type(h) == "table" and tostring(h.catchLocation or ""):upper() == "PALLET_TOWN"
                  and h.pokemonId ~= nil
                  and tostring(h.pokemonId) == tostring(monId) then
                  h.catchLocation = "NEW_BARK_TOWN"
              end
          end
          mod.save:set("nuzlocke_history", history)
      end
      pcall(mod.exports.__beta26.noteGen2AdapterReach, "starter_migration",
          { species=species, area="NEW_BARK_TOWN" })
      return true
  end
  for _, eventName in ipairs({ "game.ready", "save.loaded", "save.created" }) do
      mod.events:on(eventName, function(game)
          pcall(mod.exports.__beta26.repairGen2StarterHometown, game)
      end)
  end

  -- 2.7.78 reconstruction: existing-save identity repair. Only concrete mons
  -- already proven as tracker-registered starter/gift acquisitions in the
  -- exact-edition hometown are eligible; no species-based guessing is allowed.
  mod.exports.__beta26.repairStarterIdentityDuplicates = function(game)
      game = game or currentGame or mod.game
      if type(mod.exports.__beta26.saveWritePauseReason) == "function"
          and mod.exports.__beta26.saveWritePauseReason() ~= nil then return false end
      local save = game and game.save
      if type(save) ~= "table" then return false end
      local area = mod.exports.__beta26.runtimeIsGen2(game)
          and "NEW_BARK_TOWN" or "PALLET_TOWN"
      local repaired = false
      for _, mon in ipairs(Identity.allCurrentMons(save)) do
          if type(mon) == "table" and mon.nuzlockeTrackerRegistered == true
              and tostring(mon.catchLocation or ""):upper() == area then
              local encounterType = tostring(mon.encounterType or ""):lower()
              if encounterType == "gift" or encounterType == "starter" then
                  local species = tostring(mon.species or ""):upper()
                  if species ~= "" then
                      local ok = mod.exports.__beta26.registerStarterCatch(species, mon, {
                          allowUniqueLegacyStarterCleanup =
                              mod.exports.__beta26.runtimeIsGen2(game),
                      })
                      repaired = ok == true or repaired
                  end
              end
          end
      end
      return repaired
  end
  for _, eventName in ipairs({ "game.ready", "save.loaded" }) do
      mod.events:on(eventName, function(game)
          pcall(mod.exports.__beta26.repairStarterIdentityDuplicates, game)
      end)
  end

  -- 2.5.23: repair the exact fresh-R/B/Y regression where the native starter
  -- transaction completed while the command resolver wrapper was missing.
  -- Stay conservative: use the committed random choice when present, otherwise
  -- only the vanilla starter-choice event flags. Never guess from an arbitrary
  -- one-Pokemon party later in the run.
  mod.exports.__beta26.repairOpeningStarterTrackerLocation = function(game)
      if saveSchemaTooNew then return false end
      game = game or currentGame or mod.game
      if mod.exports.__beta26.runtimeIsGen2(game) then return false end
      local save = game and game.save
      local flags = save and save.flags or {}
      if not save or not (flags.EVENT_GOT_STARTER == true
          or tonumber(flags.EVENT_GOT_STARTER) == 1) then
          return false
      end

      local accepted = tostring(mod.save:get(
          "__nuzlocke_random_starter_choice", "") or ""):upper()
      if accepted == "" then
          if flags.EVENT_CHOSE_PIKACHU == true or tonumber(flags.EVENT_CHOSE_PIKACHU) == 1 then
              accepted = "PIKACHU"
          elseif flags.EVENT_CHOSE_CHARMANDER == true or tonumber(flags.EVENT_CHOSE_CHARMANDER) == 1 then
              accepted = "CHARMANDER"
          elseif flags.EVENT_CHOSE_SQUIRTLE == true or tonumber(flags.EVENT_CHOSE_SQUIRTLE) == 1 then
              accepted = "SQUIRTLE"
          elseif flags.EVENT_CHOSE_BULBASAUR == true or tonumber(flags.EVENT_CHOSE_BULBASAUR) == 1 then
              accepted = "BULBASAUR"
          end
      end
      if accepted == "" then return false end

      local mon
      for _, candidate in ipairs(save.party or {}) do
          if tostring(candidate and candidate.species or ""):upper() == accepted then
              mon = candidate; break
          end
      end
      if not mon then
          mod.exports.__beta26.forEachExistingSaveBox(save, function(box)
              for _, candidate in ipairs(box or {}) do
                  if tostring(candidate and candidate.species or ""):upper() == accepted then
                      mon = candidate
                      return false
                  end
              end
          end)
      end
      if type(mon) ~= "table" then return false end

      local monId = Identity.pokemonIdentity(mon)
      local log = trackerLog()
      local changed = false
      for area, rows in pairs(log) do
          local areaText = tostring(area or ""):upper()
          if area ~= "PALLET_TOWN" and type(rows) == "table"
              and (areaText == "UNKNOWN" or areaText:find("OAK", 1, true)
                  or areaText:find("LAB", 1, true)) then
              for i = #rows, 1, -1 do
                  local row = rows[i]
                  local same = false
                  if type(row) == "table" and monId ~= nil and row.pokemonId ~= nil then
                      same = tostring(row.pokemonId) == tostring(monId)
                  elseif type(row) == "table" then
                      same = tostring(row.species or ""):upper() == accepted
                  end
                  if same then table.remove(rows, i); changed = true end
              end
              if #rows == 0 then log[area] = nil end
          end
      end

      local areas = caughtAreas()
      for area, value in pairs(areas) do
          local areaText = tostring(area or ""):upper()
          if area ~= "PALLET_TOWN"
              and (areaText == "UNKNOWN" or areaText:find("OAK", 1, true)
                  or areaText:find("LAB", 1, true))
              and tostring(value or ""):upper() == accepted then
              areas[area] = nil
              changed = true
          end
      end
      if changed then
          mod.save:set("tracker_log", log)
          mod.save:set("caught_areas", areas)
      end
      mod.exports.__beta26.registerStarterCatch(accepted, mon)
      return true
  end

  mod.events:on("game.ready", function(ev)
      local game = type(ev) == "table" and ev.game or ev or currentGame or mod.game
      pcall(mod.exports.__beta26.repairOpeningStarterTrackerLocation, game)
  end)
  mod.events:on("save.loaded", function(ev)
      local game = type(ev) == "table" and ev.game or currentGame or mod.game
      pcall(mod.exports.__beta26.repairOpeningStarterTrackerLocation, game)
  end)

  -- Repair a randomized opening starter that an older build logged under
  -- Oak's Lab/UNKNOWN instead of PALLET_TOWN. Identity wins; species-only is
  -- used only while the save still has exactly one Pokemon and the committed
  -- accepted starter matches it.
  mod.exports.__beta26.repairRandomStarterTrackerLocation = function(game)
      if saveSchemaTooNew then return false end
      game = game or currentGame or mod.game
      if mod.exports.__beta26.runtimeIsGen2(game)
          or mod.save:get("random_starter", false) ~= true then
          return false
      end
      local accepted = tostring(
          mod.save:get("__nuzlocke_random_starter_choice", "") or ""):upper()
      if accepted == "" then return false end
      local save = game and game.save
      local party = save and save.party or {}
      local mon = party[1]
      if type(mon) ~= "table" or tostring(mon.species or ""):upper() ~= accepted then
          return false
      end
      local monId = Identity.pokemonIdentity(mon)
      local log = trackerLog()
      local foundWrong = false
      for area, rows in pairs(log) do
          local areaText = tostring(area or ""):upper()
          if area ~= "PALLET_TOWN" and type(rows) == "table"
              and (areaText == "UNKNOWN"
                  or areaText:find("OAK", 1, true)
                  or areaText:find("LAB", 1, true)) then
              for i = #rows, 1, -1 do
                  local row = rows[i]
                  local same = false
                  if type(row) == "table" and monId ~= nil
                      and row.pokemonId ~= nil then
                      same = tostring(row.pokemonId) == tostring(monId)
                  elseif type(row) == "table" and #party == 1 then
                      same = tostring(row.species or ""):upper() == accepted
                  end
                  if same then
                      table.remove(rows, i)
                      foundWrong = true
                  end
              end
              if #rows == 0 then log[area] = nil end
          end
      end
      if not foundWrong and mon.catchLocation == "PALLET_TOWN"
          and type(log.PALLET_TOWN) == "table" then
          return false
      end

      -- Clear only a wrong opening-area ledger entry matching this starter.
      local areas = caughtAreas()
      for area, value in pairs(areas) do
          local areaText = tostring(area or ""):upper()
          if area ~= "PALLET_TOWN"
              and (areaText == "UNKNOWN"
                  or areaText:find("OAK", 1, true)
                  or areaText:find("LAB", 1, true))
              and tostring(value or ""):upper() == accepted then
              areas[area] = nil
          end
      end
      mod.save:set("caught_areas", areas)
      mod.save:set("tracker_log", log)

      -- registerStarterCatch is idempotent and hydrates the concrete Pokemon.
      mod.exports.__beta26.registerStarterCatch(accepted, mon)
      return true
  end

  mod.events:on("game.ready", function(ev)
      local game = type(ev) == "table" and ev.game or ev or currentGame or mod.game
      pcall(mod.exports.__beta26.repairRandomStarterTrackerLocation, game)
  end)
  mod.events:on("save.loaded", function(ev)
      local game = type(ev) == "table" and ev.game or currentGame or mod.game
      pcall(mod.exports.__beta26.repairRandomStarterTrackerLocation, game)
  end)

  ---------------------------------------------------------------------
  -- REGISTER GIFT / TRADE CATCH IN ITS PROPER AREA
  ---------------------------------------------------------------------
  mod.exports.__beta26.registerSpecialCatch = function(species, area, encounterType, mon, opts)
      if not species or not area then return false end
      opts = type(opts) == "table" and opts or {}
      local consume = opts.consume ~= false
      local origin = tostring(opts.origin or "NORMAL")
      local glitch = mod.exports.__beta26.getGlitchSpeciesInfo(currentGame, species)
      local rawSpecies = species
      species = glitch.key
      area = routeKey(area) or area
      registerArea(area)
      markVisited(area)

      local log = trackerLog()
      log[area] = log[area] or {}
      local monId = mon and Identity.ensurePokemonIdentity(mon, currentSave, origin) or nil

      local function hydrateRegisteredMon(existing)
          if not mon then return end
          mon.catchLocation = area
          mon.encounterType = (type(existing) == "table" and existing.encounterType)
              or encounterType
          mon.nuzlockeDead = false
          mon.nuzlockeTrackerRegistered = true
          mon.nuzlockeGlitch = glitch.isGlitch or nil
          mon.nuzlockeMissingNo = glitch.missingNo or nil
          mon.nuzlockeRawSpecies = glitch.isGlitch and rawSpecies or nil
          Identity.setPokemonOrigin(mon, origin)
          Identity.baselineAdd(mon, origin)
      end

      -- A current/future engine path may report the same acquisition through
      -- both the script command wrapper and pokemon.received. Persistent ID is
      -- authoritative; fingerprint is the pre-ID compatibility fallback.
      -- Dedupe must still hydrate the concrete mon: Catch Info reads its
      -- provenance fields while Tracker/count reads this persistent log.
      for _, existing in ipairs(log[area]) do
          if type(existing) == "table" then
              if monId and existing.pokemonId
                  and tostring(existing.pokemonId) == tostring(monId) then
                  hydrateRegisteredMon(existing)
                  return true
              end
              if not monId and mon and existing.fingerprint
                  and existing.fingerprint == Identity.fingerprint(mon) then
                  hydrateRegisteredMon(existing)
                  return true
              end
          end
      end

      table.insert(log[area], {
          species       = species,
          rawSpecies    = glitch.isGlitch and rawSpecies or nil,
          glitch        = glitch.isGlitch or nil,
          missingNo     = glitch.missingNo or nil,
          pokemonId     = monId,
          fingerprint   = mon and Identity.fingerprint(mon) or nil,
          isShiny       = mon and Identity.isShiny(mon),
          encounterType = encounterType,
          consumedArea = consume,
          encounterMethod = opts.encounterMethod,
          encounterTime = opts.encounterTime,
          roamerSpecies = opts.roamerSpecies,
          eggCreatedLocation = opts.eggCreatedLocation,
          eggHatchLocation = opts.eggHatchLocation,
          provenance = origin,
      })
      mod.save:set("tracker_log", log)
      if consume then markCaught(area, species) end
      if mon then
          mon.catchLocation = area
          mon.encounterType = encounterType
          mon.nuzlockeEncounterMethod = opts.encounterMethod
          mon.nuzlockeEncounterTime = opts.encounterTime
          mon.nuzlockeRoamerSpecies = opts.roamerSpecies
          mon.eggCreatedLocation = opts.eggCreatedLocation or mon.eggCreatedLocation
          mon.eggHatchLocation = opts.eggHatchLocation or mon.eggHatchLocation
          mon.nuzlockeDead  = false
          mon.nuzlockeTrackerRegistered = true
          mon.nuzlockeGlitch = glitch.isGlitch or nil
          mon.nuzlockeMissingNo = glitch.missingNo or nil
          mon.nuzlockeRawSpecies = glitch.isGlitch and rawSpecies or nil
          Identity.setPokemonOrigin(mon, origin)
          Identity.baselineAdd(mon, origin)
      end

      local history = mod.save:get("nuzlocke_history", {})
      if type(history) ~= "table" then history = {} end
      table.insert(history, {
          name          = (mon and mon.nickname) or glitch.label or species,
          species       = species,
          rawSpecies    = glitch.isGlitch and rawSpecies or nil,
          glitch        = glitch.isGlitch or nil,
          missingNo     = glitch.missingNo or nil,
          pokemonId     = monId,
          catchLocation = area,
          encounterType = encounterType,
          encounterMethod = opts.encounterMethod,
          encounterTime = opts.encounterTime,
          roamerSpecies = opts.roamerSpecies,
          eggCreatedLocation = opts.eggCreatedLocation,
          eggHatchLocation = opts.eggHatchLocation,
          provenance = origin,
          consumedArea = consume,
          status        = "ALIVE",
      })
      mod.save:set("nuzlocke_history", history)
      pcall(mod.exports.__beta26.RunHistory.recordCatch, currentGame or mod.game, mon, {
          species = species, rawSpecies = glitch.isGlitch and rawSpecies or nil,
          pokemonId = monId, area = area, encounterType = encounterType,
          encounterMethod = opts.encounterMethod, provenance = origin,
          consumedArea = consume, source = "encounter_registration",
      })
      return true
  end

  -- REVIEWED: acquisition registration intentionally stays at its proven
  -- transaction point. Mandatory naming may finish afterward, so synchronize
  -- only the matching history snapshot by persistent Pokemon identity rather
  -- than moving tracker/area registration across a naming-screen yield.
  mod.exports.__beta26.syncHistoryNickname = function(mon)
      if type(mon) ~= "table" then return false end
      local nickname = tostring(mon.nickname or "")
      if not nickname:find("%S") then return false end
      local monId = Identity.pokemonIdentity(mon)
          or Identity.ensurePokemonIdentity(mon, currentSave,
              mon.nuzlockeOrigin or "NORMAL")
      if monId == nil then return false end

      local history = mod.save:get("nuzlocke_history", {})
      if type(history) ~= "table" then return false end
      local changed = false
      for _, record in ipairs(history) do
          if type(record) == "table" and record.pokemonId ~= nil
              and tostring(record.pokemonId) == tostring(monId)
              and (record.status == "ALIVE" or record.status == "PC_LOCKED")
              and record.name ~= nickname then
              record.name = nickname
              changed = true
          end
      end
      if changed then mod.save:set("nuzlocke_history", history) end
      return changed
  end

  ---------------------------------------------------------------------
  -- POKEMON.RECEIVED  —  starters, gifts, trades
  --
  -- ev fields (varies by engine build):
  --   ev.mon / ev.species   — the Pokemon received
  --   ev.source             — "starter" | "gift" | "trade" | "fossil" | "prize"
  --   ev.location / ev.mapId / ev.area — where it was received
  --   ev.game               — game reference
  --
  -- Priority:
  --   1. Starter        → always PALLET_TOWN, bypasses town_catches.
  --   2. Gift (allowed) → area from GIFT_LOCATIONS or current map.
  --   3. Gift (blocked) → native transaction is rejected before mutation.
  --   4. Trade (allowed)→ area from TRADE_DATA or current map.
  --   5. Trade (blocked)→ native transaction is rejected before exchange.
  ---------------------------------------------------------------------
  mod.exports.__beta26.isWonderTradeEvent = function(ev, source)
      if type(ev) ~= "table" then return false end
      if ev.wonderTrade == true or ev.isWonderTrade == true or ev.wonder_trade == true then return true end
      source = tostring(source or ""):lower():gsub("[%s%-]", "_")
      return source == "wonder_trade" or source == "wondertrade" or source == "wt"
  end

  -- Wonderlocke is intentionally dormant. Keep the public adapter so Wonder
  -- Trade mods can probe the compatibility surface safely, but never mutate a
  -- Pokemon or transaction until the feature is completed and re-enabled.
  if mod.exports.nuzlocke_compat then
      mod.exports.nuzlocke_compat.handleWonderTrade = function(game, mon, area, providerId)
          return false
      end
  end

  mod.events:on("pokemon.received", function(ev)
      if not ev then return end
      local game    = ev.game or currentGame
      local mon     = ev.mon
      local rawSpecies = ev.species or (mon and mon.species)
      if rawSpecies == nil or rawSpecies == "" then return end
      local glitch = mod.exports.__beta26.getGlitchSpeciesInfo(game, rawSpecies)
      local species = glitch.key

      -- Post-transaction events may be emitted by external mods. Preserve the
      -- received object and annotate it; native command wrappers perform any
      -- configured rejection before mutation.
      if mon and glitch.isGlitch then
          mon.nuzlockeGlitch = true
          mon.nuzlockeMissingNo = glitch.missingNo or nil
          mon.nuzlockeRawSpecies = rawSpecies
      end

      local source = tostring(ev.source or ""):lower()

      -- Strong Pokémon-level provenance always beats source-less species
      -- heuristics. A Pokémon already marked as a real Stadium import must
      -- never be reclassified as a vanilla gift/trade merely because its
      -- species is deterministic in the base game.
      local existingStadium = type(mon) == "table"
          and (mon.nuzlockeAcquisitionSource == "stadium_prize"
              or mon.nuzlockeEncounterSource == "STADIUM_PRIZE"
              or mon.nuzlockeOrigin == "STADIUM_PRIZE")
      if existingStadium then
          return
      end

      -- 2.7.90: Gen-2 native givePoke emits pokemon.received while the
      -- Elm wrapper is still inside the physical transaction. Honor the shared
      -- one-shot mandatory-starter receipt window before generic source/gift
      -- inference can reclassify the starter and run legality a second time.
      local mandatoryReceipt = mod.exports.__beta26.__mandatoryStarterReceipt
      if type(mandatoryReceipt) == "table"
          and mandatoryReceipt.game == game
          and mandatoryReceipt.save == (game and game.save) then
          mod.exports.__beta26.registerStarterCatch(species, mon)
          return
      end

      local rawLoc = ev.location or ev.mapId or ev.area
          or (game and game.overworld and game.overworld.map
              and game.overworld.map.id)
          or (game and game.save and game.save.player
              and game.save.player.map)
      local loc = routeKey(rawLoc) or "UNKNOWN"

      -- Gold's starter may be randomized to any valid species, so species-family
      -- heuristics cannot identify it after acquisition. The Gen 2 transaction
      -- wrapper normally registers it synchronously; this event fallback covers
      -- engine/provider paths that emit only pokemon.received. A first owned mon
      -- explicitly reported as a starter is always New Bark Town.
      if (getGameVersion() == "GOLD" or getGameVersion() == "SILVER"
          or getGameVersion() == "CRYSTAL") and source == "starter" then
          local party = game and game.save and game.save.party or {}
          if #party <= 1 then
              mod.exports.__beta26.registerStarterCatch(species, mon)
              return
          end
      end

      -- 1. Starter (explicit flag or species+location heuristic). Some
      -- current R/B/Y event paths report Oak's Lab rather than PALLET_TOWN,
      -- and may omit source="starter". Canonicalize those opening acquisitions
      -- immediately so they cannot create a second non-Pallet encounter row.
      local locText = tostring(loc or rawLoc or ""):upper()
      local isStarter = mod.exports.__beta26.isOpeningStarterAcquisition(
          game, species, source, locText, mon)
      -- Yellow's vanilla Pikachu fallback is retained for historical/provider
      -- event shapes; Random Starter species are now covered by the same
      -- provenance-based resolver above.
      local isYellowPikachu = (getGameVersion() == "YELLOW")
          and species == "PIKACHU"
          and (source == "starter"
              or (source == ""
                  and (loc == "PALLET_TOWN" or loc == "UNKNOWN")))

      if isStarter or isYellowPikachu then
          -- Nuzlocke must be active for tracking; but we still register
          -- even if the master toggle is off so the slot stays coherent.
          mod.exports.__beta26.registerStarterCatch(species, mon)
          return
      end

      -- Only enforce gifts/trades when Nuzlocke is active.
      if not active(game, nil) then return end

      local giftLookup  = mod.exports.__beta26.buildGiftLookup()
      local tradeLookup = mod.exports.__beta26.buildTradeLookup()

      -- Fallback/external acquisition events do not always pass through the
      -- native Commands.give_pokemon / Commands.trade wrappers. Prefer an
      -- explicit event source when supplied; only use species lookup as a
      -- compatibility fallback when source is absent so a normal acquisition
      -- cannot be reclassified merely because that species is also gift/trade
      -- eligible somewhere else in the game.
      local function sourceLookupMatches(lookup, kind)
          local expected = lookup[species]
          if expected == nil then return false end
          if loc == "UNKNOWN" then
              return mod.exports.__beta26.deterministicSourceFallback(kind, species)
          end
          return (routeKey(expected) or tostring(expected):upper()) == loc
      end
      local inferredGift = source == "" and sourceLookupMatches(giftLookup, "gift")
      local inferredTrade = source == "" and sourceLookupMatches(tradeLookup, "trade")
      local isGift = source == "gift" or source == "fossil"
          or source == "prize" or inferredGift
      local isTrade = source == "trade" or inferredTrade

      -- Wonderlocke is WIP. Wonder Trade transactions belong entirely to the
      -- provider mod for now: do not block them, remove the received Pokemon,
      -- consume an encounter slot, or write Wonderlocke provenance.
      if mod.exports.__beta26.wonderlockeWip
          and mod.exports.__beta26.isWonderTradeEvent(ev, source) then
          return
      end

      -- 2-3. Gift
      if isGift and not isTrade then
          local giftArea = loc ~= "UNKNOWN" and loc or giftLookup[species] or loc
          if mon and mon.nuzlockeTrackerRegistered == true then return end
          local denied = specialAcquisitionDenied(game, species, giftArea, "gift")
          if denied then
              -- Never delete a Pokemon here. pokemon.received is post-transaction
              -- in some engine/mod paths, so rollback would be unsafe. Native
              -- give_pokemon is rejected before mutation by the command wrapper.
              if mon then mon.nuzlockeInvalidAcquisition = denied end
              worldMechanic(game, "gift_post_denied:" .. tostring(species),
                  "This gift conflicts with your Nuzlocke rules.",
                  "Gift received through an external path.\nReview your rules before using it.",
                  "A mod bypassed the normal gift transaction gate.\nThe Pokemon was preserved instead of deleting data.",
                  true)
              return
          end
          mod.exports.__beta26.registerSpecialCatch(species, giftArea, "gift", mon, { consume = mod.exports.__beta26.specialAcquisitionConsumesArea("gift") })
          return
      end

      -- 4-5. Trade
      if isTrade then
          local tradeArea = loc ~= "UNKNOWN" and loc or tradeLookup[species] or loc
          if mon and mon.nuzlockeTrackerRegistered == true then return end
          local denied = specialAcquisitionDenied(game, species, tradeArea, "trade")
          if denied then
              -- Same safety rule as gifts: never attempt a destructive rollback
              -- after another mod/engine has already completed the exchange.
              if mon then mon.nuzlockeInvalidAcquisition = denied end
              worldMechanic(game, "trade_post_denied:" .. tostring(species),
                  "This trade conflicts with your Nuzlocke rules.",
                  "Trade completed through an external path.\nThe Pokemon was preserved instead of risking data loss.",
                  "A mod bypassed the normal trade gate.\nNo destructive rollback was attempted.",
                  true)
              return
          end
          mod.exports.__beta26.registerSpecialCatch(species, tradeArea, "trade", mon, { consume = mod.exports.__beta26.specialAcquisitionConsumesArea("trade") })
      end
  end)

  ---------------------------------------------------------------------
  -- CATCH RULE ENFORCEMENT
  ---------------------------------------------------------------------
  mod.exports.__beta26.pokemonFamily = function(game, species)
      if mod.exports.__beta26.getGlitchSpeciesInfo(game, species).isGlitch then
          return {}
      end
      local found, pending = {}, { species }
      local data = game and game.data and game.data.pokemon or {}
      while #pending > 0 do
          local id = table.remove(pending)
          if id and not found[id] then
              found[id] = true
              local def = data[id]
              for _, evo in ipairs((def and def.evolutions) or {}) do
                  if evo and evo.species then pending[#pending + 1] = evo.species end
              end
              for parent, parentDef in pairs(data) do
                  for _, evo in ipairs((parentDef and parentDef.evolutions) or {}) do
                      if evo and evo.species == id then
                          pending[#pending + 1] = parent
                      end
                  end
              end
          end
      end
      return found
  end

  mod.exports.__beta26.caughtSpeciesSet = function(game)
      local caught = {}

      -- Tracker history is authoritative for "previously caught", so a dead,
      -- boxed-out, released, or traded-away Pokemon still counts for Dupes.
      for area, entries in pairs(trackerLog()) do
          if area ~= "__LEGACY__" and type(entries) == "table" then
              for _, entry in ipairs(entries) do
                  local sp = type(entry) == "table"
                      and tostring(entry.species or ""):upper() or ""
                  if sp ~= "" then caught[sp] = true end
              end
          end
      end

      -- Current owned Pokemon are a safety net for imported/modded saves whose
      -- tracker reconstruction has not run yet.
      for _, mon in ipairs(Identity.allCurrentMons(game and game.save or {})) do
          local sp = type(mon) == "table"
              and tostring(mon.species or ""):upper() or ""
          -- A progression/completion catch is research-only and never became
          -- a legal Nuzlocke teammate, so merely existing in a Box must not
          -- make a later ordinary encounter a Dupes-Clause duplicate.
          if sp ~= "" and not (type(mon) == "table"
              and mon.nuzlockePcLocked == true) then caught[sp] = true end
      end

      return caught
  end

  mod.exports.__beta26.dupesMode = function()
      local value = mod.save:get("dupes_mode", defaultRuleValue("dupes_mode"))
      if type(value) == "boolean" then return value and 2 or 0 end
      return math.max(0, math.min(3, math.floor(tonumber(value) or 0)))
  end

  mod.exports.__beta26.isDuplicateSpecies = function(game, species)
      local mode = mod.exports.__beta26.dupesMode()
      if mode <= 0 then return false end

      -- Glitch identities are not stable evolution-family members. Treat each
      -- allowed glitch encounter independently instead of traversing missing or
      -- malformed evolution data.
      if mod.exports.__beta26.getGlitchSpeciesInfo(game, species).isGlitch then
          return false
      end

      species = tostring(species or ""):upper()
      if species == "" then return false end

      local caught = mod.exports.__beta26.caughtSpeciesSet(game)
      if mode == 1 then
          return caught[species] == true
      end

      if mode == 3 then
          -- SPLIT keeps ancestor/descendant lines mutually duplicate while
          -- allowing sibling branches after a genuine split. Example: an
          -- owned Vaporeon does not make Jolteon a duplicate, but Eevee and
          -- Vaporeon remain the same branch. Traversal consumes only the live
          -- merged/provider evolution rows reachable from the queried species;
          -- incomplete custom evolution metadata therefore fails open rather
          -- than inventing a family relationship.
          local function evolvesInto(fromSpecies, targetSpecies)
              fromSpecies = tostring(fromSpecies or ""):upper()
              targetSpecies = tostring(targetSpecies or ""):upper()
              if fromSpecies == "" or targetSpecies == "" then return false end
              if fromSpecies == targetSpecies then return true end
              local seen, pending = {}, { fromSpecies }
              while #pending > 0 do
                  local id = table.remove(pending)
                  if id and not seen[id] then
                      seen[id] = true
                      local facts = mod.exports.__beta26.getSpeciesFacts(game, id)
                      for _, evo in ipairs(type(facts) == "table"
                          and type(facts.evolutions) == "table" and facts.evolutions or {}) do
                          local nextId = evolutionTargetId(evo)
                          if nextId == targetSpecies then return true end
                          if nextId and not seen[nextId] then pending[#pending + 1] = nextId end
                      end
                  end
              end
              return false
          end
          for caughtSpecies in pairs(caught) do
              if evolvesInto(species, caughtSpecies)
                  or evolvesInto(caughtSpecies, species) then return true end
          end
          return false
      end

      local members = mod.exports.__beta26.pokemonFamily(game, species)
      for caughtSpecies in pairs(caught) do
          if members[caughtSpecies] == true then return true end
      end
      return false
  end

  -- Shared ordinary-clause conflict used both by the Ball legality check and
  -- by successful-catch accounting. A finite Shiny Clause allowance may only
  -- be spent when this exact helper says the catch genuinely needed an area,
  -- failed-state, or Dupes exception. This lives after mod.exports.__beta26.isDuplicateSpecies so
  -- the closure binds the actual local Dupes classifier rather than a global.
  mod.exports.__beta26.catchClauseConflict = function(game, battle, species)
      local key = areaKey(game, battle)
      local slotConflict = mod.exports.__beta26.encounterSlotConflict(
          game, key, true)
      if slotConflict ~= nil then return slotConflict end
      if mod.exports.__beta26.isDuplicateSpecies(game, species) then return "dupes" end
      return nil
  end

  ---------------------------------------------------------------------
  -- FAILED ENCOUNTER STATE
  -- A failed eligible wild encounter consumes the area's encounter slot.
  -- Dupes encounters do not consume the slot while Dupes Clause is ON.
  ---------------------------------------------------------------------
  mod.exports.__beta26.encounterStates = function()
      local states = mod.save:get("encounter_states")
      if type(states) ~= "table" then
          states = {}
          mod.save:set("encounter_states", states)
      end
      return states
  end

  getEncounterState = function(key)
      if not key then return nil end
      return mod.exports.__beta26.encounterStates()[key]
  end

  mod.exports.__beta26.markEncounterFailed = function(key, species, encounterType, sourceMapId,
      provenance)
      local policyGame = currentGame or mod.game
      if not mod.exports.__beta26.shouldEnforceNuzlocke(policyGame, nil) then return end
      if not key or mod.save:get("failed_encounter", true) ~= true then return end
      key = registerArea(key)
      if not isTrackedArea(key) then return end
      provenance = type(provenance) == "table" and provenance or {}
      local states = mod.exports.__beta26.encounterStates()

      -- 2.4.57: successful consumed-catch evidence is monotonic. A delayed
      -- battle-ended/provider callback must never downgrade an area that was
      -- already recorded CAUGHT into FAILED.
      local existing = states[key]
      if caughtAreas()[key] ~= nil
          or (type(existing) == "table" and existing.status == "CAUGHT") then
          return
      end
      local existingLog = trackerLog()[key]
      if type(existingLog) == "table" then
          for _, entry in ipairs(existingLog) do
              if type(entry) == "table" and entry.species
                  and entry.consumedArea ~= false then
                  return
              end
          end
      end
      local physical = routeKey(sourceMapId)
          or routeKey(provenance.encounterMapId) or key
      local record = {
          status = "FAILED", species = species,
          encounterType = encounterType or "wild", encounterMapId = physical,
          encounterMethod = provenance.encounterMethod,
          encounterTime = provenance.encounterTime,
          roamerSpecies = provenance.roamerSpecies,
          eggCreatedLocation = provenance.eggCreatedLocation,
          eggHatchLocation = provenance.eggHatchLocation,
      }
      states[key] = record
      mod.save:set("encounter_states", states)
      local ledger = mod.save:get("encounter_area_state_ledger", {})
      if type(ledger) ~= "table" then ledger = {} end
      local ledgerKey = mod.exports.__beta26.goldEncounterLedgerKey(
          currentGame or mod.game, physical, record) or physical
      ledger[ledgerKey] = record
      mod.save:set("encounter_area_state_ledger", ledger)
      mod.save:set("last_failed_encounter", {
          area = key, encounterMapId = physical, species = species,
          encounterType = record.encounterType,
          encounterMethod = record.encounterMethod,
          encounterTime = record.encounterTime,
          roamerSpecies = record.roamerSpecies,
      })
      if mod.exports.__beta26.RunHistory
          and type(mod.exports.__beta26.RunHistory.recordEncounterFailed) == "function" then
          pcall(mod.exports.__beta26.RunHistory.recordEncounterFailed,
              policyGame, {
                  area = key, species = species,
                  encounterType = record.encounterType,
                  encounterMethod = record.encounterMethod,
                  encounterTime = record.encounterTime,
                  roamerSpecies = record.roamerSpecies,
                  sourceMapId = physical,
                  dedupe = "encounter_failed:" .. tostring(key),
              })
      end
  end

  mod.exports.__beta26.markEncounterCaught = function(key, species, encounterType, sourceMapId,
      consumedArea, provenance)
      if not key then return end
      key = registerArea(key)
      if not isTrackedArea(key) then return end
      provenance = type(provenance) == "table" and provenance or {}
      local states = mod.exports.__beta26.encounterStates()
      local physical = routeKey(sourceMapId)
          or routeKey(provenance.encounterMapId) or key
      local record = {
          status = "CAUGHT", species = species,
          encounterType = encounterType or "wild", encounterMapId = physical,
          consumedArea = consumedArea ~= false,
          encounterMethod = provenance.encounterMethod,
          encounterTime = provenance.encounterTime,
          roamerSpecies = provenance.roamerSpecies,
          eggCreatedLocation = provenance.eggCreatedLocation,
          eggHatchLocation = provenance.eggHatchLocation,
      }
      states[key] = record
      mod.save:set("encounter_states", states)
      local ledger = mod.save:get("encounter_area_state_ledger", {})
      if type(ledger) ~= "table" then ledger = {} end
      local ledgerKey = mod.exports.__beta26.goldEncounterLedgerKey(
          currentGame or mod.game, physical, record) or physical
      ledger[ledgerKey] = record
      mod.save:set("encounter_area_state_ledger", ledger)
  end

  -- 2.4.57 CAPTURE LEDGER INTEGRITY
  -- Successful consumed-catch evidence is stronger than FAILED state. Keep
  -- tracker_log, caught_areas, encounter_states, and the physical state ledger
  -- mutually consistent without inventing catches from party/species guesses.
  mod.exports.__beta26.reconcileEncounterCaptureState = function()
      local log = trackerLog()
      local areas = caughtAreas()
      local states = mod.exports.__beta26.encounterStates()
      local ledger = mod.save:get("encounter_area_state_ledger", {})
      if type(ledger) ~= "table" then ledger = {} end
      local changed = false

      local function caughtRecord(key, species, source)
          local existing = states[key]
          if type(existing) == "table" and existing.status == "CAUGHT" then
              if existing.species == nil and species ~= nil then
                  existing.species = species
                  changed = true
              end
              return existing
          end
          local record = {
              status = "CAUGHT",
              species = species,
              encounterType = type(source) == "table"
                  and (source.encounterType or "wild") or "wild",
              encounterMapId = type(source) == "table"
                  and (routeKey(source.encounterMapId) or key) or key,
              consumedArea = true,
              encounterMethod = type(source) == "table"
                  and source.encounterMethod or nil,
              encounterTime = type(source) == "table"
                  and source.encounterTime or nil,
              roamerSpecies = type(source) == "table"
                  and source.roamerSpecies or nil,
              eggCreatedLocation = type(source) == "table"
                  and source.eggCreatedLocation or nil,
              eggHatchLocation = type(source) == "table"
                  and source.eggHatchLocation or nil,
              reconciledCapture = true,
          }
          states[key] = record
          changed = true
          return record
      end

      -- Tracker rows are strongest: they are written only after a successful
      -- acquisition. Exempt catches (consumedArea=false) intentionally do not
      -- claim the area's one-per-area slot.
      for key, catches in pairs(log) do
          if key ~= "__LEGACY__" and type(catches) == "table" then
              for _, entry in ipairs(catches) do
                  if type(entry) == "table" and entry.species
                      and entry.consumedArea ~= false then
                      if areas[key] == nil then
                          areas[key] = entry.species
                          changed = true
                      end
                      local record = caughtRecord(key, entry.species, entry)
                      local physical = routeKey(record.encounterMapId) or key
                      local ledgerKey =
                          mod.exports.__beta26.goldEncounterLedgerKey(
                              currentGame or mod.game, physical, record)
                          or physical
                      local old = ledger[ledgerKey]
                      if type(old) ~= "table" or old.status ~= "CAUGHT" then
                          ledger[ledgerKey] = record
                          changed = true
                      end
                      break
                  end
              end
          end
      end

      -- caught_areas is older successful-catch evidence used by legacy saves.
      -- It may repair a conflicting FAILED state, but it never creates tracker
      -- history and never guesses provenance beyond the logical area.
      for key, species in pairs(areas) do
          if key ~= "__LEGACY__" and species ~= nil then
              local state = states[key]
              if type(state) ~= "table" or state.status ~= "CAUGHT" then
                  local record = caughtRecord(key, species, state)
                  local physical = routeKey(record.encounterMapId) or key
                  local ledgerKey =
                      mod.exports.__beta26.goldEncounterLedgerKey(
                          currentGame or mod.game, physical, record)
                      or physical
                  local old = ledger[ledgerKey]
                  if type(old) ~= "table" or old.status ~= "CAUGHT" then
                      ledger[ledgerKey] = record
                      changed = true
                  end
              end
          end
      end

      if changed then
          mod.save:set("caught_areas", areas)
          mod.save:set("encounter_states", states)
          mod.save:set("encounter_area_state_ledger", ledger)
      end
      return changed
  end

  -- Rebuild the active encounter views from immutable physical-map
  -- provenance. This is called on load and immediately after either split
  -- selector changes. It never deletes catch rows: COMMON separates them and
  -- OFF groups them back under the parent while preserving every row.
  mod.exports.__beta26.reprojectEncounterAreas = function()
      -- Reconcile successful-catch evidence before any projection can choose
      -- a representative state for collapsed/split areas.
      pcall(mod.exports.__beta26.reconcileEncounterCaptureState)

      -- Legacy selector translation now runs in the coordinator's semantic
      -- phase. Projection has one job: deterministically rebuild logical views
      -- from preserved physical provenance without also mutating rule schema.
      local oldLog = trackerLog()
      local newLog = {}

      -- REVIEWED: split families can collapse multiple physical buckets into
      -- one logical area. Lua pairs() order is deliberately unspecified, so
      -- collect and sort the physical/source keys before projection. This
      -- makes the representative CAUGHT row/state stable across reloads and
      -- repeated split toggles while preserving each bucket's ipairs order.
      local function orderedKeys(tbl)
          local keys = {}
          for key in pairs(tbl or {}) do keys[#keys + 1] = key end
          table.sort(keys, function(a, b)
              local ar = routeKey(a) or tostring(a or "")
              local br = routeKey(b) or tostring(b or "")
              if ar == br then return tostring(a) < tostring(b) end
              return tostring(ar) < tostring(br)
          end)
          return keys
      end

      for _, oldKey in ipairs(orderedKeys(oldLog)) do
          local entries = oldLog[oldKey]
          if oldKey == "__LEGACY__" then
              newLog[oldKey] = entries
          elseif type(entries) == "table" then
              for _, entry in ipairs(entries) do
                  if type(entry) == "table" then
                      local physical = routeKey(entry.encounterMapId)
                      local normalizedOld = routeKey(oldKey)
                      if not physical then
                          physical = normalizedOld
                          if mod.exports.__beta26.splitFamilyFor(normalizedOld) then
                              entry.encounterMapId = normalizedOld
                          end
                      end
                      local base = mod.exports.__beta26.projectEncounterArea(
                          physical) or normalizedOld or oldKey
                      local target = mod.exports.__beta26.projectGoldEncounterArea(
                          currentGame or mod.game, base, entry) or base
                      newLog[target] = newLog[target] or {}
                      newLog[target][#newLog[target] + 1] = entry
                  end
              end
          else
              newLog[oldKey] = entries
          end
      end
      mod.save:set("tracker_log", newLog)

      local oldStates = mod.exports.__beta26.encounterStates()
      local stateLedger = mod.save:get("encounter_area_state_ledger", {})
      if type(stateLedger) ~= "table" then stateLedger = {} end
      for _, oldKey in ipairs(orderedKeys(oldStates)) do
          local state = oldStates[oldKey]
          if type(state) == "table" then
              local physical = routeKey(state.encounterMapId) or routeKey(oldKey)
              if physical then
                  local ledgerKey = mod.exports.__beta26.goldEncounterLedgerKey(
                      currentGame or mod.game, physical, state) or physical
                  if stateLedger[ledgerKey] == nil
                      or state.projectedFromSplits ~= true then
                      local copy = {}
                      for k, v in pairs(state) do copy[k] = v end
                      copy.encounterMapId = physical
                      copy.projectedFromSplits = nil
                      stateLedger[ledgerKey] = copy
                  end
              end
          end
      end

      local newStates = {}
      for _, ledgerKey in ipairs(orderedKeys(stateLedger)) do
          local state = stateLedger[ledgerKey]
          if type(state) == "table" then
              local physical = routeKey(state.encounterMapId) or routeKey(ledgerKey)
              local base = mod.exports.__beta26.projectEncounterArea(physical)
                  or physical
              local target = mod.exports.__beta26.projectGoldEncounterArea(
                  currentGame or mod.game, base, state) or base
              if target then
                  local existing = newStates[target]
                  local existingConsumes = existing and
                      (existing.status == "FAILED"
                          or existing.consumedArea ~= false)
                  local stateConsumes = state.status == "FAILED"
                      or state.consumedArea ~= false
                  if not existing or (not existingConsumes and stateConsumes)
                      or (existingConsumes == stateConsumes
                          and existing.status ~= "CAUGHT"
                          and state.status == "CAUGHT") then
                      local copy = {}
                      for k, v in pairs(state) do copy[k] = v end
                      copy.encounterMapId = routeKey(physical) or physical
                      copy.projectedFromSplits = target ~= copy.encounterMapId
                      newStates[target] = copy
                  end
              end
          end
      end
      mod.save:set("encounter_area_state_ledger", stateLedger)
      mod.save:set("encounter_states", newStates)

      local oldCaught = caughtAreas()
      local covered = {}
      for key in pairs(oldLog) do covered[key] = true end
      for key in pairs(oldStates) do covered[key] = true end
      local newCaught = {}
      for key, entries in pairs(newLog) do
          if key ~= "__LEGACY__" and type(entries) == "table" then
              for _, entry in ipairs(entries) do
                  if type(entry) == "table" and entry.species
                      and entry.consumedArea ~= false then
                      newCaught[key] = entry.species
                      break
                  end
              end
          end
      end
      for key, state in pairs(newStates) do
          if newCaught[key] == nil and type(state) == "table"
              and state.status == "CAUGHT" and state.species
              and state.consumedArea ~= false then
              newCaught[key] = state.species
          end
      end
      for oldKey, species in pairs(oldCaught) do
          if oldKey == "__LEGACY__" then
              newCaught[oldKey] = species
          elseif not covered[oldKey] then
              local target = mod.exports.__beta26.projectEncounterArea(oldKey)
                  or routeKey(oldKey) or oldKey
              if newCaught[target] == nil then newCaught[target] = species end
          end
      end
      mod.save:set("caught_areas", newCaught)

      local oldVisited = visitedAreas()
      local visitLedger = mod.save:get("encounter_visited_map_ids", {})
      if type(visitLedger) ~= "table" then visitLedger = {} end
      for key, value in pairs(oldVisited) do
          if value == true and visitLedger[key] == nil then
              local projectedParent = false
              for _, family in pairs(mod.exports.__beta26.encounterSplitAreas) do
                  if key == family.parent then
                      for member in pairs(family.members) do
                          if visitLedger[member] == true then
                              projectedParent = true
                              break
                          end
                      end
                  end
                  if projectedParent then break end
              end
              if not projectedParent then visitLedger[key] = true end
          end
      end
      local newVisited = {}
      for physical, value in pairs(visitLedger) do
          if value == true then
              local target = mod.exports.__beta26.projectEncounterArea(physical)
                  or routeKey(physical)
              if target then newVisited[target] = true end
          end
      end
      mod.save:set("encounter_visited_map_ids", visitLedger)
      mod.save:set("visited_areas", newVisited)

      -- Keep Catch Info and history aligned with the same live projection.
      -- The physical map field remains stable, while catchLocation is the
      -- current player-facing area name/key used throughout existing UI.
      for _, mon in ipairs(Identity.allCurrentMons(
          currentGame and currentGame.save or currentSave or {})) do
          if type(mon) == "table" then
              local physical = routeKey(mon.nuzlockeEncounterMapId)
              local oldLocation = routeKey(mon.catchLocation)
              if not physical
                  and mod.exports.__beta26.splitFamilyFor(oldLocation) then
                  physical = oldLocation
                  mon.nuzlockeEncounterMapId = physical
              end
              if physical then
                  local base = mod.exports.__beta26.projectEncounterArea(physical)
                      or mon.catchLocation
                  mon.catchLocation = mod.exports.__beta26.projectGoldEncounterArea(
                      currentGame or mod.game, base, mon) or base
              end
          end
      end
      local history = mod.save:get("nuzlocke_history", {})
      if type(history) == "table" then
          for _, row in ipairs(history) do
              if type(row) == "table" then
                  local physical = routeKey(row.encounterMapId)
                  local oldLocation = routeKey(row.catchLocation)
                  if not physical
                      and mod.exports.__beta26.splitFamilyFor(oldLocation) then
                      physical = oldLocation
                      row.encounterMapId = physical
                  end
                  if physical then
                      local base = mod.exports.__beta26.projectEncounterArea(physical)
                          or row.catchLocation
                      row.catchLocation = mod.exports.__beta26.projectGoldEncounterArea(
                          currentGame or mod.game, base, row) or base
                  end
              end
          end
          mod.save:set("nuzlocke_history", history)
      end
      local lastFailed = mod.save:get("last_failed_encounter", {})
      if type(lastFailed) == "table" then
          local physical = routeKey(lastFailed.encounterMapId)
          if physical then
              local base = mod.exports.__beta26.projectEncounterArea(physical)
                  or lastFailed.area
              lastFailed.area = mod.exports.__beta26.projectGoldEncounterArea(
                  currentGame or mod.game, base, lastFailed) or base
              mod.save:set("last_failed_encounter", lastFailed)
          end
      end
      mod.save:set("encounter_projection_signature",
          tostring(mod.exports.__beta26.routeSplitActive("route_2_split") and 1 or 0) .. ":"
          .. tostring(mod.exports.__beta26.routeSplitActive("route_10_split") and 1 or 0) .. ":"
          .. tostring(mod.exports.__beta26.routeSplitActive("route_20_split") and 1 or 0) .. ":"
          .. tostring(math.max(0, math.min(1, math.floor(tonumber(
              mod.save:get("mt_moon_splits", 0)) or 0)))) .. ":"
          .. tostring(mod.exports.__beta26.safariClauseMode()) .. ":"
          .. tostring(mod.save:get("gold_time_split", false) == true and 1 or 0) .. ":"
          .. tostring(mod.save:get("gold_headbutt_split", false) == true and 1 or 0) .. ":"
          .. tostring(mod.save:get("gold_roamer_clause", false) == true and 1 or 0) .. ":"
          .. tostring(math.max(0, math.min(2, math.floor(tonumber(
              mod.save:get("gold_bug_contest_mode", 0)) or 0))))
      )
      return true
  end

  mod.exports.__beta26.ensureEncounterProjection = function()
      local signature = tostring(mod.exports.__beta26.routeSplitActive("route_2_split") and 1 or 0) .. ":"
          .. tostring(mod.exports.__beta26.routeSplitActive("route_10_split") and 1 or 0) .. ":"
          .. tostring(mod.exports.__beta26.routeSplitActive("route_20_split") and 1 or 0) .. ":"
          .. tostring(math.max(0, math.min(1, math.floor(tonumber(
          mod.save:get("mt_moon_splits", 0)) or 0)))) .. ":"
          .. tostring(mod.exports.__beta26.safariClauseMode()) .. ":"
          .. tostring(mod.save:get("gold_time_split", false) == true and 1 or 0) .. ":"
          .. tostring(mod.save:get("gold_headbutt_split", false) == true and 1 or 0) .. ":"
          .. tostring(mod.save:get("gold_roamer_clause", false) == true and 1 or 0) .. ":"
          .. tostring(math.max(0, math.min(2, math.floor(tonumber(
              mod.save:get("gold_bug_contest_mode", 0)) or 0))))
      if mod.save:get("encounter_projection_signature", nil) ~= signature then
          return mod.exports.__beta26.reprojectEncounterAreas()
      end
      return false
  end

  mod.exports.__beta26.registerSaveUpgradeStep("projection",
      "encounter_area_projection", function()
          mod.exports.__beta26.reprojectEncounterAreas()
          return true
      end)
  -- game.ready remains a runtime synchronization seam, not a migration path:
  -- it handles title/new-game/adopted-save lifecycle cases after the canonical
  -- save-loaded upgrade pipeline has already done its ordered work.
  mod.events:on("game.ready", function()
      pcall(mod.exports.__beta26.reprojectEncounterAreas)
  end)

  -- Persist a self-consistent capture ledger. This does not create new catch
  -- history; it only makes already-recorded successful consumed catches
  -- monotonic across save/reload and provider/event ordering.
  mod.events:on("save.writing", function()
      pcall(mod.exports.__beta26.reconcileEncounterCaptureState)
  end)

  -- BETA.26 ENCOUNTER ARMING / SOFT START
  -- Keep this helper namespace on the existing beta export table instead of
  -- adding more long-lived locals to the main mod chunk. This is intentionally
  -- initialization-safe: the prior B5 feature batch caused the entire mod to
  -- disappear before title/start-menu hooks became usable on Blue and Gold.
  ---------------------------------------------------------------------
  mod.exports.__beta26.tableContainsOwnedBall = function(game, tbl, seen)
      if type(tbl) ~= "table" then return false end
      seen = seen or {}
      if seen[tbl] then return false end
      seen[tbl] = true
      for key, value in pairs(tbl) do
          if type(value) == "number" and value > 0 then
              local ok, result = pcall(ItemPolicy.isBall,
                  game and game.data, key, nil)
              if ok and result == true then
                  local okBlocked, blocked = pcall(ItemPolicy.ballUseBlocked,
                      game and game.data, key, nil, true)
                  if not okBlocked or blocked ~= true then return true end
              end
          elseif type(value) == "table"
              and mod.exports.__beta26.tableContainsOwnedBall(game, value, seen) then
              return true
          end
      end
      return false
  end

  mod.exports.__beta26.hasLegacyEncounterEvidence = function()
      -- Pallet Town's starter is established before the player owns Balls and
      -- MUST NOT arm Soft Start by itself. Only meaningful non-starter route
      -- history reconstructs an older save as already armed.
      -- Repair the old B7 Oak/Lab starter duplicate before using history as
      -- evidence that encounter rules should already be armed.
      mod.exports.__beta26.cleanupStarterDuplicate()

      local areas = mod.save:get("caught_areas", nil)
      if type(areas) == "table" then
          for key, value in pairs(areas) do
              if key ~= "PALLET_TOWN" and value ~= nil then
                  local k = tostring(key or ""):upper()
                  local sp = tostring(value or ""):upper()
                  local starter = sp == "BULBASAUR" or sp == "CHARMANDER"
                      or sp == "SQUIRTLE" or sp == "PIKACHU"
                  if not (starter and (k:find("OAK", 1, true)
                      or k:find("LAB", 1, true))) then
                      return true
                  end
              end
          end
      end
      local states = mod.save:get("encounter_states", nil)
      if type(states) == "table" then
          for key, state in pairs(states) do
              if key ~= "PALLET_TOWN" and type(state) == "table"
                  and (state.status == "FAILED" or state.status == "CAUGHT") then
                  return true
              end
          end
      end
      local log = mod.save:get("tracker_log", nil)
      if type(log) == "table" then
          for key, entries in pairs(log) do
              if key ~= "PALLET_TOWN" and key ~= "__LEGACY__"
                  and type(entries) == "table" and #entries > 0 then
                  local k = tostring(key or ""):upper()
                  local onlyStarter = true
                  for _, entry in ipairs(entries) do
                      local sp = tostring(entry and entry.species or ""):upper()
                      if sp ~= "BULBASAUR" and sp ~= "CHARMANDER"
                          and sp ~= "SQUIRTLE" and sp ~= "PIKACHU" then
                          onlyStarter = false
                          break
                      end
                  end
                  if not (onlyStarter and (k:find("OAK", 1, true)
                      or k:find("LAB", 1, true))) then
                      return true
                  end
              end
          end
      end
      return false
  end

  mod.exports.__beta26.clearPreArmEncounterState = function()
      -- Pre-Ball encounters are intentionally invisible to the route ledger.
      -- Clear only transient encounter-state rows; successful catch history and
      -- the starter tracker row live in separate tables and are preserved.
      mod.save:set("encounter_states", {})
  end

  mod.exports.__beta26.encounterRulesArmed = function(game)
      if not mod.exports.__beta26.canWriteNuzlockeSave(game) then return false end
      if mod.save:get("nuzlocke_encounters_armed", false) == true then return true end

      -- Compatibility for older saves: genuine route history means the run
      -- already passed the first-Ball boundary. A starter-only Pallet row does
      -- not count as evidence and leaves a fresh run unarmed.
      if mod.exports.__beta26.hasLegacyEncounterEvidence() then
          mod.save:set("nuzlocke_encounters_armed", true)
          return true
      end

      local save = game and game.save
      -- Only carried Balls count. Balls sitting in PC storage cannot be
      -- thrown yet, so pre-catch areas must remain free until withdrawn.
      if save and (mod.exports.__beta26.tableContainsOwnedBall(game, save.inventory)
          or mod.exports.__beta26.tableContainsOwnedBall(game, save.bag)
          or mod.exports.__beta26.tableContainsOwnedBall(game, save.pockets)) then
          mod.exports.__beta26.clearPreArmEncounterState()
          mod.save:set("nuzlocke_encounters_armed", true)
          local t1, t2, t3 = mod.exports.__beta26.worldRuleTriplet(
              game, "encounter_armed")
          worldMechanic(game, "encounter_armed", t1, t2, t3)
          return true
      end
      return false
  end

  mod.exports.__beta26.armEncounterRulesNow = function(game)
      if not mod.exports.__beta26.canWriteNuzlockeSave(game) then return false end
      if mod.save:get("nuzlocke_encounters_armed", false) ~= true then
          mod.exports.__beta26.clearPreArmEncounterState()
          mod.save:set("nuzlocke_encounters_armed", true)
      end
      return true
  end

  local activeWildEncounter = nil

  mod.exports.__beta26.isTrainerBattleForNuzlocke = function(battle)
      if not battle then return false end
      if battle.kind == "trainer" or battle.type == "trainer" then return true end
      if battle.trainerBattle == true or battle.isTrainerBattle == true then return true end
      if battle.trainer ~= nil or battle.opponentTrainer ~= nil then return true end
      if battle.opponent and type(battle.opponent) == "table" and battle.opponent.name then return true end
      return false
  end

  -- 2.6.43: semantic battle-role surface. Explicit/provider-owned role metadata
  -- wins over identity heuristics, letting dynamic trainer/League mods describe
  -- what a battle MEANS without Nuzlocke hard-coding their trainer IDs.
  mod.exports.__beta26.battleRole = function(battle)
      if type(battle) ~= "table" then return nil end
      local trainer = type(battle.trainer) == "table" and battle.trainer
          or type(battle.opponentTrainer) == "table" and battle.opponentTrainer
          or nil
      local raw = battle.nuzlockeBattleRole or battle.battleRole
          or battle.progressionRole or battle.nuzlockeProgressionRole
          or (trainer and (trainer.nuzlockeBattleRole or trainer.battleRole
              or trainer.progressionRole or trainer.nuzlockeProgressionRole))
      local role = tostring(raw or ""):lower():gsub("[%s%-]+", "_")
      local aliases = {
          rival="rival", gym="gym_leader", gymleader="gym_leader",
          gym_leader="gym_leader", elite="elite_four", elite4="elite_four",
          elite_four="elite_four", champion="champion",
          progression_boss="progression_boss", boss="progression_boss",
          trainer="trainer", ordinary="trainer",
      }
      return aliases[role]
  end

  -- Rival identity is deliberately behavioral and generation-neutral. Trainer
  -- IDs/classes are preferred, with the familiar default names retained as a
  -- compatibility fallback for engine builds that expose only display text.
  mod.exports.__beta26.isRivalBattle = function(battle)
      if type(battle) ~= "table" or not mod.exports.__beta26.isTrainerBattleForNuzlocke(battle) then
          return false
      end
      local trainer = type(battle.trainer) == "table" and battle.trainer
          or type(battle.opponentTrainer) == "table" and battle.opponentTrainer
          or nil
      if mod.exports.__beta26.battleRole(battle) == "rival" then return true end
      local fields = {
          tostring(battle.oppClass or ""),
          tostring(battle.trainerClass or ""),
          tostring(battle.opponentClass or ""),
          tostring(battle.trainerId or ""),
          tostring(battle.trainerID or ""),
          tostring(battle.opponentId or ""),
          tostring(battle.trainerName or ""),
          tostring(battle.opponentName or ""),
          tostring(trainer and trainer.class or ""),
          tostring(trainer and trainer.trainerClass or ""),
          tostring(trainer and trainer.id or ""),
          tostring(trainer and trainer.name or ""),
      }
      if battle.rival == true or battle.isRival == true
          or (trainer and (trainer.rival == true or trainer.isRival == true)) then
          return true
      end
      for _, value in ipairs(fields) do
          local compact = value:upper():gsub("[^A-Z0-9]", "")
          -- 2.6.40: do not classify arbitrary content trainers merely because
          -- their custom id contains the word RIVAL (for example quest-local
          -- STARTER_STORIES_*_RIVAL1 ids). Prefer canonical engine class/id
          -- shapes plus explicit provider flags above.
          if compact == "BLUE" or compact == "SILVER"
              or compact:match("^RIVAL%d*$")
              or compact:match("^OPPRIVAL%d*$")
              or compact:match("^TRAINERRIVAL%d*$") then
              return true
          end
      end
      return false
  end

  -- Avoid granting a newly-added option to a later Rival battle on an old
  -- save. Canonical opening locations and the shared level-5/zero-badge battle
  -- profile identify Red/Blue/Yellow and Gold without depending on mod names.
  mod.exports.__beta26.isOpeningRivalBattle = function(game, battle)
      if not mod.exports.__beta26.isRivalBattle(battle) then return false end
      local key = areaKey(game, battle)
      local area = tostring(key or ""):upper():gsub("[^A-Z0-9]", "")
      local openingArea = area:find("OAKSLAB", 1, true) ~= nil
          or area:find("PALLETTOWN", 1, true) ~= nil
          or area:find("ROUTE29", 1, true) ~= nil
          or area:find("CHERRYGROVE", 1, true) ~= nil

      local enemy = battle.enemy
      if type(enemy) == "table" and type(enemy.mon) == "table" then
          enemy = enemy.mon
      end
      local enemyLevel = type(enemy) == "table"
          and tonumber(enemy.level or enemy.lv) or nil
      local badges = currentBadgeCount(game and game.save)
      return openingArea or (badges == 0 and enemyLevel ~= nil and enemyLevel <= 6)
  end

  ---------------------------------------------------------------------
  -- GENERATION-NEUTRAL BATTLE CLASSIFIER
  --
  -- This is a read-only compatibility surface. It consolidates the battle
  -- shapes already understood by individual rules without making a rule
  -- decision or invoking another mod's callbacks. Consumers should prefer
  -- flags over `kind` when categories can overlap (a Rival is also a trainer;
  -- a scripted fixed encounter is also wild/catchable).
  ---------------------------------------------------------------------
  mod.exports.__beta26.classifyBattle = function(game, battle, species)
      local wrapper = type(battle) == "table" and battle or {}
      local core = type(wrapper.battle) == "table" and wrapper.battle or wrapper
      game = game or wrapper.game or core.game or currentGame or mod.game

      local source = tostring(core.encounterType or core.encounterSource
          or core.source or wrapper.encounterType or wrapper.encounterSource
          or wrapper.source or ""):lower()
      local trainer = mod.exports.__beta26.isTrainerBattleForNuzlocke(core)
      local tutorial = wrapper.tutorial == true or core.tutorial == true
          or wrapper.isTutorial == true or core.isTutorial == true
          or source == "tutorial" or source == "catch_tutorial"
      local demo = wrapper.demo == true or core.demo == true
      local ghost = wrapper.ghost == true or core.ghost == true
      local semanticRole = mod.exports.__beta26.battleRole(core)
      local rival = trainer and (semanticRole == "rival"
          or mod.exports.__beta26.isRivalBattle(core))
      local openingRival = rival
          and mod.exports.__beta26.isOpeningRivalBattle(game, core) or false
      local static = mod.exports.__beta26.isStaticEncounter(game, core)
      local roamer = core.nuzlockeRoamingEncounter == true
          or core.roamingEncounter == true or core.isRoamer == true
          or core.roamer == true or source == "roamer" or source == "roaming"
          or source:find("roam", 1, true) ~= nil
      local scripted = static or core.scriptedEncounter == true
          or core.isScriptedEncounter == true or core.storyEncounter == true
          or source == "script" or source == "scripted" or source == "event"
          or source == "fixed"

      local enemy = core.enemy or wrapper.enemy or core.wildMon
      if type(enemy) == "table" and type(enemy.mon) == "table" then
          enemy = enemy.mon
      end
      species = species or (type(enemy) == "table"
          and (enemy.species or enemy.id or enemy.name))
          or core.species or wrapper.species
      local speciesKey = mod.exports.__beta26.getGlitchSpeciesInfo(
          game, species).key

      local kindText = tostring(core.kind or core.type or ""):lower()
      local wild = not trainer and (core.wild == true or wrapper.wild == true
          or kindText == "wild" or source == "wild" or source == "grass"
          or source == "surf" or source == "fishing" or source == "overworld"
          or static or roamer or type(enemy) == "table")
      local overworld = core.overworldEncounter == true
          or core.overworld == true or core.isOverworld == true
          or source == "overworld"
      local externalProvider = core.nuzlockeEncounterProvider
          or core.encounterProvider or wrapper.nuzlockeEncounterProvider
          or wrapper.encounterProvider
      local externalVersion = core.nuzlockeEncounterProviderVersion
          or core.encounterProviderVersion
          or wrapper.nuzlockeEncounterProviderVersion
          or wrapper.encounterProviderVersion

      local flags = {
          tutorial = tutorial,
          demo = demo,
          ghost = ghost,
          trainer = trainer,
          rival = rival,
          gym_leader = semanticRole == "gym_leader",
          elite_four = semanticRole == "elite_four",
          champion = semanticRole == "champion",
          progression_boss = semanticRole == "progression_boss"
              or semanticRole == "gym_leader" or semanticRole == "elite_four"
              or semanticRole == "champion",
          opening_rival = openingRival,
          wild = wild,
          ordinary_wild = wild and not static and not roamer and not scripted,
          static = static,
          fixed = static,
          roaming = roamer,
          scripted = scripted,
          overworld = overworld,
          legendary = Identity.isLegendarySpecies(game, speciesKey),
          mythical = Identity.isMythicalSpecies(game, speciesKey),
          external = externalProvider ~= nil,
      }
      flags.excluded = tutorial or demo or ghost
      flags.catchable = wild and not trainer and not flags.excluded
      flags.unknown = not trainer and not wild and not flags.excluded

      local kind = "unknown"
      if tutorial then kind = "tutorial"
      elseif demo or ghost then kind = "excluded"
      elseif rival then kind = "rival"
      elseif trainer then kind = "trainer"
      elseif roamer then kind = "roaming"
      elseif static then kind = "static"
      elseif scripted then kind = "scripted"
      elseif wild then kind = "wild"
      end

      local trainerRecord = type(core.trainer) == "table" and core.trainer
          or type(core.opponentTrainer) == "table" and core.opponentTrainer
          or nil
      return {
          api = 1,
          kind = kind,
          role = semanticRole,
          flags = flags,
          generation = mod.exports.__beta26.runtimeIsGen2(game) and 2 or 1,
          area = areaKey(game, core),
          source = source ~= "" and source or nil,
          species = speciesKey,
          trainer = {
              id = core.trainerId or core.trainerID or core.opponentId
                  or (trainerRecord and trainerRecord.id),
              class = core.oppClass or core.trainerClass or core.opponentClass
                  or (trainerRecord and (trainerRecord.class
                      or trainerRecord.trainerClass)),
              name = core.trainerName or core.opponentName
                  or (trainerRecord and trainerRecord.name),
          },
          provider = externalProvider and {
              id = externalProvider,
              version = externalVersion,
          } or nil,
      }
  end

  mod.exports.__beta26.engineBattleSnapshot = function()
      local battle = mod.battle
      if type(battle) ~= "table" or type(battle.snapshot) ~= "function" then
          return nil, "mod.battle snapshot unavailable"
      end
      local ok, snapshot = pcall(battle.snapshot, battle)
      if not ok then return nil, tostring(snapshot) end
      if snapshot == nil then return nil end
      if type(snapshot) ~= "table" then
          return nil, "invalid mod.battle snapshot"
      end
      return snapshot
  end

  mod.exports.battle_classifier = {
      api = 1,
      build = mod.exports.__beta26.build,
      classify = function(game, battle, species)
          return mod.exports.__beta26.classifyBattle(game, battle, species)
      end,
      -- 0.1.98+ current-battle view. The engine returns detached records, so
      -- consumers can render/inspect them without mutating battle state.
      snapshot = function()
          return mod.exports.__beta26.engineBattleSnapshot()
      end,
  }

  mod.exports.__beta26.armFirstRivalForgiveness = function(game, battle)
      if not mod.exports.__beta26.isRivalBattle(battle) then return false end
      if mod.save:get("nuzlocke_first_rival_battle_seen", false) == true then
          return false
      end

      local opening = mod.exports.__beta26.isOpeningRivalBattle(game, battle)
      battle.nuzlockeFirstRivalBattle = opening == true

      -- A rival-shaped battle that is not the canonical opening encounter is
      -- rejected without consuming the durable one-shot. isOpeningRivalBattle
      -- already protects old saves from receiving mercy on later Rival fights;
      -- leaving the semaphore untouched also lets a rewound/reordered run reach
      -- the genuine opener later without having silently burned the feature.
      if not opening then return false end

      -- Once the actual opening Rival battle is reached, the slot is consumed
      -- regardless of whether the option is enabled or whether anybody faints.
      mod.save:set("nuzlocke_first_rival_battle_seen", true)

      local enabled = mod.save:get("first_rival_forgiveness", true) == true
      -- REVIEWED: nuzlocke_first_rival_battle_seen is the only durable
      -- one-shot state. Armed/triggered state is battle-local because no
      -- resume or status path consumes separate persisted telemetry.
      battle.nuzlockeRivalForgiveness = enabled
      return enabled
  end

  mod.exports.__beta26.isFirstRivalForgivenessActive = function(game, battle)
      return type(battle) == "table"
          and battle.nuzlockeFirstRivalBattle == true
          and battle.nuzlockeRivalForgiveness == true
          and mod.save:get("nuzlocke_enabled", true) ~= false
  end

    -- 2.4.20 Limited Shiny Clause. Historical boolean ON is interpreted as
    -- UNLIMITED so existing saves retain their prior behavior without a schema
    -- migration. The run counter records successful shiny exceptions only.
    mod.exports.__beta26.shinyClauseMode = function()
        local raw = mod.save:get("shiny_clause", defaultRuleValue("shiny_clause"))
        if type(raw) == "boolean" then raw = raw and 4 or 0 end
        return math.max(0, math.min(4, math.floor(tonumber(raw) or 0)))
    end

    mod.exports.__beta26.shinyClauseUsed = function()
        return math.max(0, math.floor(tonumber(
            mod.save:get("shiny_clause_used", 0)) or 0))
    end

    mod.exports.__beta26.shinyClauseAvailable = function()
        local mode = mod.exports.__beta26.shinyClauseMode()
        if mode == 4 then return true end
        return mode > 0 and mod.exports.__beta26.shinyClauseUsed() < mode
    end

    mod.exports.__beta26.consumeShinyClauseAllowance = function()
        local mode = mod.exports.__beta26.shinyClauseMode()
        if mode <= 0 then return false end
        if mode == 4 then return true end
        local used = mod.exports.__beta26.shinyClauseUsed()
        if used >= mode then return false end
        mod.save:set("shiny_clause_used", used + 1)
        return true
    end

    -- 2.4.85 Encounter Ball Limit. Stored value is a compact selector mode
    -- so ordinary A/LEFT/RIGHT cycling stays predictable while the displayed
    -- budgets can use the useful OFF/1/2/3/5/10 sequence.
    mod.exports.__beta26.encounterBallLimitValues = { [0]=0, [1]=1, [2]=2, [3]=3, [4]=5, [5]=10 }

    mod.exports.__beta26.encounterBallLimit = function()
        local mode = math.max(0, math.min(5, math.floor(tonumber(
            mod.save:get("encounter_ball_limit", 0)) or 0)))
        return mod.exports.__beta26.encounterBallLimitValues[mode] or 0
    end

    mod.exports.__beta26.encounterBallThrowsUsed = function(battle)
        return type(battle) == "table"
            and math.max(0, math.floor(tonumber(
                battle.nuzlockeEncounterBallThrowsUsed) or 0)) or 0
    end

    mod.exports.__beta26.encounterBallThrowAvailable = function(game, battle)
        local limit = mod.exports.__beta26.encounterBallLimit()
        if limit <= 0 or mod.save:get("nuzlocke_enabled", true) ~= true then
            return true, limit, mod.exports.__beta26.encounterBallThrowsUsed(battle)
        end
        local used = mod.exports.__beta26.encounterBallThrowsUsed(battle)
        return used < limit, limit, used
    end

    mod.exports.__beta26.consumeEncounterBallThrow = function(game, battle)
        local allowed, limit, used =
            mod.exports.__beta26.encounterBallThrowAvailable(game, battle)
        if not allowed then return false, limit, used end
        if limit > 0 and type(battle) == "table" then
            battle.nuzlockeEncounterBallThrowsUsed = used + 1
            return true, limit, used + 1
        end
        return true, limit, used
    end

    mod.exports.__beta26.encounterBallLimitMessage = function(limit)
        return Strings("Ball Limit reached! This encounter allows %d throw%s.",
            tonumber(limit) or 0, tonumber(limit) == 1 and "" or "s")
    end


  mod.exports.__beta26.beginWildEncounter = function(payload)
      if not payload then return end
      local battle = payload.battle or payload
      if not battle then return end
      if not currentGame then currentGame = payload.game end
      local game = payload.game or currentGame
      local classification = mod.exports.__beta26.classifyBattle(game, battle)
      if classification.flags.trainer or classification.flags.excluded then return end
      if not active(game, battle) then return end
      if not mod.exports.__beta26.encounterRulesArmed(game) then return end

      local key = areaKey(game, battle)
      if not key then return end
      local encounterMapId = battle and battle.nuzlockeEncounterMapId
          or mod.exports.__beta26.currentPhysicalArea(game,
              game and game.save and game.save.player
              and game.save.player.map)
      local species = battle.enemy and battle.enemy.mon and battle.enemy.mon.species
          or battle.enemy and battle.enemy.species
          or payload.species
      if species == nil or species == "" then return end
      local glitch = mod.exports.__beta26.getGlitchSpeciesInfo(game, species)
      local rawSpecies = species
      species = glitch.key

      -- 2.2.18: Failed Encounter eligibility must be derived from the same
      -- authoritative capture policy as an actual Ball throw. Otherwise an
      -- encounter forbidden by No Catching/species/BST/glitch/Solo rules can
      -- consume the area, and Shiny Clause can accidentally change that result.
      local denied = type(catchDeniedReason) == "function"
          and catchDeniedReason(game, battle, species) or nil
      if denied then
          battle.nuzlockeFreeEncounterReason = denied
          battle.nuzlockeEncounterEligible = false
          battle.nuzlockeEncounterWillSpendArea = false
          return
      end
      if battle.nuzlockeProgressionCatch == true then
          battle.nuzlockeFreeEncounterReason = "progression_catch"
          battle.nuzlockeEncounterEligible = false
          battle.nuzlockeEncounterWillSpendArea = false
          return
      end

      local shiny = enemyIsShiny(battle)
      local shinyClause = mod.exports.__beta26.shinyClauseAvailable()
      local town = key ~= nil and isTownArea(key, routeName(key)) or false
      local overworld = battle.overworldEncounter == true
          or battle.overworld == true
          or battle.isOverworld == true
          or battle.encounterType == "overworld"
          or battle.source == "overworld"
      local static = mod.exports.__beta26.isStaticEncounter(game, battle)

      if static and mod.exports.__beta26.ruleActive(
          game, "no_static_encounters", battle) then return end
      if overworld and not mod.exports.__beta26.ruleActive(game, "overworld_encounters", battle) then return end
      if town and not mod.save:get("town_catches", false) then return end
      if not mod.save:get("encounter_limit", defaultRuleValue("encounter_limit")) then return end
      if mod.save:get("failed_encounter", true) ~= true then return end
      if caughtAreas()[key] ~= nil then return end

      local existing = getEncounterState(key)
      if existing and (existing.status == "FAILED" or existing.status == "CAUGHT") then return end

      if mod.exports.__beta26.isDuplicateSpecies(game, species)
          and not (shiny and shinyClause) then
          -- Persist the eligibility decision on the battle itself. The failed-
          -- encounter finalizer must never reclassify this encounter after
          -- battle-side mutations or another provider callback changes state.
          battle.nuzlockeFreeEncounterReason = "dupes"
          battle.nuzlockeEncounterEligible = false
          battle.nuzlockeEncounterWillSpendArea = false
          return
      end
      battle.nuzlockeEncounterEligible = true
      battle.nuzlockeEncounterWillSpendArea = true
      battle.nuzlockeEncounterSpendArea = key

      local provider = activeCompatProvider("encounters", game, battle)
      local delegatedEncounter = externalRuleDelegation
          and externalRuleDelegation("random_encounter_tables", game) or nil
      if provider then
          rememberEncounterProvider(provider.id, provider.version)
      elseif delegatedEncounter then
          rememberEncounterProvider(delegatedEncounter.id, delegatedEncounter.version)
      end
      activeWildEncounter = {
          battle = battle, game = game, key = key, species = species,
          encounterMapId = encounterMapId,
          rawSpecies = glitch.isGlitch and rawSpecies or nil,
          glitch = glitch.isGlitch or nil,
          missingNo = glitch.missingNo or nil,
          encounterType = (battle.nuzlockeEncounterMethod == "roamer"
                  or battle.nuzlockeEncounterMethod == "headbutt"
                  or battle.nuzlockeEncounterMethod == "bug_contest")
              and battle.nuzlockeEncounterMethod
              or (static and "static"
                  or (overworld and "overworld" or (town and "town" or "wild"))),
          encounterMethod = battle.nuzlockeEncounterMethod or "wild",
          encounterTime = battle.nuzlockeEncounterTime,
          roamerSpecies = battle.nuzlockeRoamerSpecies,
          encounterSource = (provider or delegatedEncounter) and "provider" or "vanilla",
          encounterProvider = provider and provider.id
              or (delegatedEncounter and delegatedEncounter.id) or nil,
          encounterProviderVersion = provider and provider.version
              or (delegatedEncounter and delegatedEncounter.version) or nil,
          encounterContext = providerContext(provider, game, battle),
          resolved = false,
      }
  end

  -- 2.7.70: compatibility-only encounter-spend projection. The old built-in
  -- in-battle HUD/toggle was intentionally retired after it overlaid battle-owned
  -- presentation. External information surfaces may still query this read-only
  -- semantic projection; it never decides legality itself.
  mod.exports.__beta26.encounterSpendIndicator = function(targetBattle)
      if mod.save:get("encounter_limit", defaultRuleValue("encounter_limit")) ~= true then return nil end
      local b = targetBattle or (activeWildEncounter and activeWildEncounter.battle)
      if type(b) ~= "table" then return nil end
      local game = b.game or currentGame or mod.game
      local class = mod.exports.__beta26.classifyBattle(game, b)
      if class and class.flags and (class.flags.trainer or class.flags.excluded) then return nil end
      if not active(game, b) or not mod.exports.__beta26.encounterRulesArmed(game) then return nil end

      local conflict = b.nuzlockeClauseConflictChecked == true
          and b.nuzlockeClauseConflict or nil
      local mon = b.enemy and (b.enemy.mon or b.enemy) or nil
      local shiny = Identity.isShiny(mon)
      if conflict ~= nil and shiny and mod.exports.__beta26.shinyClauseAvailable() then
          return { active=true, state="shiny_free", area=areaKey(game,b),
              text=Strings("SHINY:FREE"), conflict=conflict }
      end
      if conflict == "dupes" or b.nuzlockeFreeEncounterReason == "dupes" then
          return { active=true, state="dupe_free", area=areaKey(game,b),
              text=Strings("DUPE:FREE"), conflict="dupes" }
      end
      if conflict == "caught" or conflict == "failed"
          or b.nuzlockeFreeEncounterReason == "area" then
          return { active=true, state="spent", area=areaKey(game,b),
              text=Strings("AREA:SPENT"), conflict=conflict or "caught" }
      end
      if b.nuzlockeFreeEncounterReason ~= nil then
          return { active=true, state="blocked", area=areaKey(game,b),
              text=Strings("NO CATCH"), reason=b.nuzlockeFreeEncounterReason }
      end
      return { active=true, state="counts", area=areaKey(game,b),
          text=Strings("AREA:COUNT") }
  end

  -- 2.8.41: read-only encounter provenance snapshot for Dev Mode and bug
  -- reports. It reports already-materialized state only and never assigns an
  -- area, consumes a slot, creates an identity, or queries Randomizer RNG.
  mod.exports.__beta26.activeEncounterProvenance = function(targetBattle)
      local pending = activeWildEncounter
      local battle = targetBattle or (pending and pending.battle)
      if type(battle) ~= "table" then
          return { active=false, state="none" }
      end
      local game = battle.game or (pending and pending.game) or currentGame or mod.game
      local mon = battle.enemy and (battle.enemy.mon or battle.enemy) or nil
      local key = (pending and pending.battle == battle and pending.key)
          or battle.nuzlockeEncounterAreaKey or areaKey(game, battle)
      local sourceMap = (pending and pending.battle == battle and pending.encounterMapId)
          or battle.nuzlockeEncounterMapId
          or (game and game.save and game.save.player and game.save.player.map)
      local indicator = mod.exports.__beta26.encounterSpendIndicator(battle)
      local caught = key and caughtAreas()[key] or nil
      local state = key and getEncounterState(key) or nil
      return {
          active=true, state=indicator and indicator.state or "observed",
          area=key, physical_area=sourceMap,
          species=mon and mon.species or (pending and pending.species),
          pokemon_id=mon and mon.nuzlockeId or nil,
          encounter_type=(pending and pending.battle == battle and pending.encounterType)
              or battle.encounterType or battle.nuzlockeEncounterMethod or "wild",
          encounter_method=(pending and pending.battle == battle and pending.encounterMethod)
              or battle.nuzlockeEncounterMethod,
          encounter_time=(pending and pending.battle == battle and pending.encounterTime)
              or battle.nuzlockeEncounterTime,
          source=(pending and pending.battle == battle and pending.encounterSource)
              or battle.nuzlockeEncounterSource or "vanilla",
          provider=(pending and pending.battle == battle and pending.encounterProvider)
              or battle.nuzlockeEncounterProvider or battle.encounterProvider,
          provider_version=(pending and pending.battle == battle
              and pending.encounterProviderVersion)
              or battle.nuzlockeEncounterProviderVersion or battle.encounterProviderVersion,
          eligible=battle.nuzlockeEncounterEligible,
          will_spend=battle.nuzlockeEncounterWillSpendArea,
          spend_area=battle.nuzlockeEncounterSpendArea,
          free_reason=battle.nuzlockeFreeEncounterReason,
          clause_conflict=battle.nuzlockeClauseConflict,
          caught_area=caught ~= nil,
          area_status=type(state) == "table" and state.status or nil,
          shiny=mon and Identity.isShiny(mon) or false,
          resolved=pending and pending.battle == battle and pending.resolved or nil,
      }
  end

  -- 2.7.70: no built-in encounter-spend battle HUD is installed. BattleState
  -- remains presentation-owner; the semantic encounterSpendIndicator() export
  -- above is retained only for compatible external information surfaces.

